function getWebsiteDefaultTemplate(v) {
  if (v && Array.isArray(v.customizationTemplates)) {
    const byId = v.defaultTemplateId
      ? v.customizationTemplates.find(t => t && t.id === v.defaultTemplateId)
      : null;
    if (byId && byId.customization) {
      return JSON.parse(JSON.stringify(byId));
    }
    const found = v.customizationTemplates.find(t => t && t.isDefault);
    if (found && found.customization) {
      return JSON.parse(JSON.stringify(found));
    }
  }
  try {
    const raw = localStorage.getItem(DEFAULT_TEMPLATE_LS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed.customization) {
        return parsed;
      }
    }
  } catch (e) {}
  return JSON.parse(JSON.stringify(FACTORY_DEFAULT_TEMPLATE));
}

function ensureCustomizationTemplates(v) {
  if (!v || typeof v !== 'object') return;
  if (!Array.isArray(v.customizationTemplates) || v.customizationTemplates.length === 0) {
    v.customizationTemplates = JSON.parse(JSON.stringify(BUILTIN_STUDIO_TEMPLATES));
  } else {
    // Strip legacy factory placeholder preset and deleted presets
    v.customizationTemplates = v.customizationTemplates.filter(t => t && t.id !== 'tpl_warm_gallery_default' && t.id !== 'tpl_swiss_editorial');
    if (v.customizationTemplates.length === 0) {
      v.customizationTemplates = JSON.parse(JSON.stringify(BUILTIN_STUDIO_TEMPLATES));
    }
  }

  // One-time migration: ensure the user's actual customized studio design is saved as the default & active preset
  v.customization = v.customization || {};
  if (!v.customization.v3PresetRestoreMigrated) {
    const studioPresetCopy = JSON.parse(JSON.stringify(FACTORY_DEFAULT_TEMPLATE));
    const existingIdx = v.customizationTemplates.findIndex(t => t && t.id === 'preset_studio_default');
    if (existingIdx >= 0) {
      v.customizationTemplates[existingIdx] = studioPresetCopy;
    } else {
      v.customizationTemplates.unshift(studioPresetCopy);
    }
    v.defaultTemplateId = 'preset_studio_default';
    v.customization = {
      ...JSON.parse(JSON.stringify(FACTORY_DEFAULT_TEMPLATE.customization)),
      worldTitles: v.customization.worldTitles || FACTORY_DEFAULT_TEMPLATE.customization.worldTitles,
      activeTemplateId: 'preset_studio_default',
      sleekV6Migrated: true,
      v23ConnectedStudioMigrated: true,
      v3PresetRestoreMigrated: true
    };
    try {
      localStorage.setItem(DEFAULT_TEMPLATE_LS_KEY, JSON.stringify(studioPresetCopy));
    } catch (e) {}
  }

  // Repair if preset_studio_default was accidentally overwritten by the old update-mode dialog
  const defaultPresetObj = v.customizationTemplates.find(t => t && t.id === 'preset_studio_default');
  if (defaultPresetObj && (defaultPresetObj.name === '6dryftugvjhb' || !defaultPresetObj.name)) {
    const cleanDefault = JSON.parse(JSON.stringify(FACTORY_DEFAULT_TEMPLATE));
    Object.assign(defaultPresetObj, cleanDefault);
    if (v.defaultTemplateId === 'preset_studio_default') {
      try {
        localStorage.setItem(DEFAULT_TEMPLATE_LS_KEY, JSON.stringify(defaultPresetObj));
      } catch (e) {}
    }
  }

  // Sync defaultTemplateId with localStorage or fallback to preset_studio_default
  if (!v.defaultTemplateId || v.defaultTemplateId === 'tpl_warm_gallery_default') {
    let storedDefId = null;
    try {
      const raw = localStorage.getItem(DEFAULT_TEMPLATE_LS_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && parsed.id && parsed.id !== 'tpl_warm_gallery_default') {
          storedDefId = parsed.id;
          if (!v.customizationTemplates.some(t => t && t.id === parsed.id)) {
            v.customizationTemplates.unshift(parsed);
          }
        }
      }
    } catch (e) {}
    v.defaultTemplateId = storedDefId
      || v.customizationTemplates.find(t => t && t.isDefault)?.id
      || v.customizationTemplates[0]?.id
      || 'preset_studio_default';
  }

  if (!v.customizationTemplates.some(t => t && t.id === v.defaultTemplateId)) {
    v.defaultTemplateId = v.customizationTemplates[0]?.id || 'preset_studio_default';
  }

  v.customizationTemplates.forEach(t => {
    if (t) t.isDefault = (t.id === v.defaultTemplateId);
  });

  if (!v.customization.activeTemplateId || v.customization.activeTemplateId === 'tpl_warm_gallery_default') {
    v.customization.activeTemplateId = v.defaultTemplateId;
  }
}

