function loadVault() {
  let loaded = null;
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (isValidV5Vault(parsed)) {
        loaded = parsed;
      }
    }
  } catch (e) {
    console.warn('Could not read local vault, using seed:', e);
  }
  if (!loaded) loaded = createSeedVault();

  // Restore dedicated keys so workspace preferences and renames are never lost
  try {
    const rawTitles = localStorage.getItem('ideal_custom_space_titles');
    if (rawTitles) {
      const parsed = JSON.parse(rawTitles);
      loaded.customSpaceTitles = { ...(loaded.customSpaceTitles || {}), ...parsed };
    }
  } catch (e) {}

  try {
    const rawCodes = localStorage.getItem('ideal_custom_space_codes');
    if (rawCodes) {
      const parsed = JSON.parse(rawCodes);
      loaded.customSpaceCodes = { ...(loaded.customSpaceCodes || {}), ...parsed };
    }
  } catch (e) {}

  try {
    const rawSections = localStorage.getItem('ideal_asset_sections');
    if (rawSections) {
      const parsed = JSON.parse(rawSections);
      loaded.assetSections = { ...(loaded.assetSections || {}), ...parsed };
      loaded.customization = loaded.customization || {};
      loaded.customization.assetSections = { ...(loaded.customization.assetSections || {}), ...parsed };
    }
  } catch (e) {}

  try {
    const rawPreviews = localStorage.getItem('ideal_gdrive_enclosing_previews');
    if (rawPreviews) {
      const parsed = JSON.parse(rawPreviews);
      loaded.enclosingPreviews = { ...(loaded.enclosingPreviews || {}), ...parsed };
      loaded.customization = loaded.customization || {};
      loaded.customization.enclosingPreviews = { ...(loaded.customization.enclosingPreviews || {}), ...parsed };
    }
  } catch (e) {}

  const result = ensureVaultSleekAndGDrive(loaded);
  ensureLightboxCleanWorkspace(result);
  try {
    localStorage.setItem(LS_KEY, JSON.stringify(result));
  } catch (e) {}
  return result;
}

let saveTimer = null;
function saveVault(statusMsg = 'SAVED') {
  try {
    localStorage.setItem(LS_KEY, JSON.stringify(vault));
  } catch (e) {
    console.error('Local save error:', e);
  }
  const syncText = document.getElementById('syncStatusText');
  const syncDot = document.getElementById('syncStatusDot');
  if (syncText) syncText.textContent = 'SYNCING…';
  if (syncDot) syncDot.style.background = 'var(--accent)';

  const shortStatus = (!statusMsg || statusMsg.length > 10) ? 'SAVED' : statusMsg;
  clearTimeout(saveTimer);
  saveTimer = setTimeout(async () => {
    try {
      await fetch('/api/vault', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(vault)
      });
      if (syncText) syncText.textContent = shortStatus;
      if (syncDot) syncDot.style.background = 'var(--ok)';
    } catch (err) {
      if (syncText) syncText.textContent = 'LOCAL';
    }
  }, 220);
}

async function fetchGDriveAssets(forceRefresh = false) {
  if (state.gdriveStats.loading) return;
  const now = Date.now();
  if (state.gdriveStats.loaded && !forceRefresh && (now - (state.gdriveStats.lastSyncTs || 0) < 4000)) return;
  state.gdriveStats.loading = true;
  try {
    const res = await fetch(`/api/gdrive-assets?force=${forceRefresh ? '1' : '0'}&_t=${now}`);
    if (res.ok) {
      let data = await res.json();
      if (data && Array.isArray(data.batches)) {
        if ((data.batches.length === 0 || !Array.isArray(data.enclosingFolders) || data.enclosingFolders.length === 0) && typeof window !== 'undefined' && window._IDEAL_GDRIVE_SEED) {
          data = window._IDEAL_GDRIVE_SEED;
        }
        if (data.batches.length === 0 && state.gdriveBatches && state.gdriveBatches.length > 0) {
          console.warn('[Assets] 0 batches returned; holding previous asset configuration intact.');
          state.gdriveStats.loading = false;
          return;
        }
        state.gdriveBatches = data.batches;

        let enclosing = [...(data.enclosingFolders || [])];

        // 1. Look for custom saved order in vault customization, localStorage, or gdriveSp.categories
        const gdriveSp = vault.spaces.find(s => s.id === 'gdrive_assets');
        let savedOrder = vault?.customization?.enclosingOrder;
        if (!Array.isArray(savedOrder) || savedOrder.length === 0) {
          try {
            const raw = localStorage.getItem('ideal_gdrive_enclosing_order');
            if (raw) savedOrder = JSON.parse(raw);
          } catch (e) {}
        }
        if (!Array.isArray(savedOrder) || savedOrder.length === 0) {
          if (gdriveSp && Array.isArray(gdriveSp.categories)) {
            savedOrder = gdriveSp.categories.filter(c => c !== 'All' && c !== 'All Asset Batches');
          }
        }

        if (Array.isArray(savedOrder) && savedOrder.length > 0) {
          const diskNames = new Set(enclosing.map(e => (e.name || '').toLowerCase()));
          savedOrder = savedOrder.map(name => {
            if (name === 'Color Palettes & Swatches' && diskNames.has('color palettes')) return 'Color Palettes';
            return name;
          }).filter(name => diskNames.has(String(name).toLowerCase()));
          if (vault?.customization) vault.customization.enclosingOrder = savedOrder;
          try {
            localStorage.setItem('ideal_gdrive_enclosing_order', JSON.stringify(savedOrder));
          } catch (e) {}

          const orderMap = new Map();
          savedOrder.forEach((name, idx) => orderMap.set(String(name).toLowerCase(), idx));
          enclosing.sort((a, b) => {
            const idxA = orderMap.has(String(a.name).toLowerCase()) ? orderMap.get(String(a.name).toLowerCase()) : 9999;
            const idxB = orderMap.has(String(b.name).toLowerCase()) ? orderMap.get(String(b.name).toLowerCase()) : 9999;
            return idxA - idxB;
          });
        }

        state.gdriveEnclosingFolders = enclosing;
        state.gdriveCategoryLinks = data.categoryLinks || {};
        state.gdriveStats = {
          totalBatches: data.totalBatches || data.batches.length,
          totalFiles: data.totalFiles || 0,
          driveRoot: data.driveRoot || data.gdriveRoot || '',
          loading: false,
          loaded: true,
          lastSyncTs: Date.now()
        };
        // Dynamically sync Assets & Vaults category filter tabs with real enclosing folders
        if (gdriveSp && state.gdriveEnclosingFolders.length > 0) {
          const encNames = state.gdriveEnclosingFolders.map(e => e.name);
          const firstTab = 'All';
          gdriveSp.categories = [firstTab, ...encNames];
          if (state.activeSpaceId === 'gdrive_assets') {
            if (state._savedNavCategory && gdriveSp.categories.includes(state._savedNavCategory)) {
              state.activeCategory = state._savedNavCategory;
              state._savedNavCategory = null;
              state.activeGDriveEnclosingFolder = state.activeCategory === 'All' ? null : state.activeCategory;
            } else if (!gdriveSp.categories.includes(state.activeCategory)) {
              state.activeCategory = firstTab;
              state.activeGDriveEnclosingFolder = null;
            }
          }
        }
        try {
          localStorage.setItem('ideal_gdrive_assets_cache', JSON.stringify({
            batches: state.gdriveBatches,
            enclosingFolders: state.gdriveEnclosingFolders,
            categoryLinks: state.gdriveCategoryLinks,
            totalBatches: state.gdriveStats.totalBatches,
            totalFiles: state.gdriveStats.totalFiles,
            driveRoot: state.gdriveStats.driveRoot
          }));
        } catch (e) {}
        renderSidebar();
        if (state.viewType === 'space' && state.activeSpaceId === 'gdrive_assets') {
          renderFilterActionRow();
          renderWorkspace();
        }
        return;
      }
    }
  } catch (e) {
    console.warn('Google Drive index fetch error:', e);
  }
  if ((!state.gdriveBatches || state.gdriveBatches.length === 0) && typeof window !== 'undefined' && window._IDEAL_GDRIVE_SEED) {
    const seed = window._IDEAL_GDRIVE_SEED;
    state.gdriveBatches = seed.batches || [];
    state.gdriveEnclosingFolders = seed.enclosingFolders || [];
    state.gdriveCategoryLinks = seed.categoryLinks || {};
    state.gdriveStats = {
      totalBatches: seed.totalBatches || state.gdriveBatches.length,
      totalFiles: seed.totalFiles || 0,
      driveRoot: seed.driveRoot || '',
      loading: false,
      loaded: true,
      lastSyncTs: Date.now()
    };
    renderSidebar();
    if (state.viewType === 'space' && state.activeSpaceId === 'gdrive_assets') {
      renderFilterActionRow();
      renderWorkspace();
    }
  }
  state.gdriveStats.loading = false;
}

function getActiveGDriveLaneInfo(catName) {
  const rootPath = state.gdriveStats?.driveRoot || '~/Library/CloudStorage/GoogleDrive/My Drive';
  const linksMap = state.gdriveCategoryLinks || {};
  const key = (!catName || catName.startsWith('All')) ? 'All' : catName;
  if (linksMap[key]) {
    return linksMap[key];
  }
  const matchingBatch = (state.gdriveBatches || []).find(b => key === 'All' || b.category === key);
  if (matchingBatch) {
    return {
      relPath: matchingBatch.relPath,
      label: `My Drive/${matchingBatch.relPath}`,
      localFolder: matchingBatch.localFolder,
      driveFolderUrl: matchingBatch.driveFolderUrl || 'https://drive.google.com/drive/folders/1hKoACYGUbGqAFEUJGv6Ocf5lqiy0-mIr'
    };
  }
  return {
    relPath: 'ASSETS',
    label: 'My Drive/ASSETS',
    localFolder: `${rootPath}/ASSETS`,
    driveFolderUrl: 'https://drive.google.com/drive/folders/1hKoACYGUbGqAFEUJGv6Ocf5lqiy0-mIr'
  };
}

async function syncFromServerOnBoot() {
  let localSaved = null;
  try {
    const rawLocal = localStorage.getItem('ideal_vault_v5');
    if (rawLocal) localSaved = JSON.parse(rawLocal);
  } catch (e) {}

  try {
    const res = await fetch('/api/vault');
    if (res.ok) {
      const resJson = await res.json();
      const serverVault = (resJson && resJson.vault) ? resJson.vault : resJson;
      if (isValidV5Vault(serverVault)) {
        // Never overwrite server items with seed vault URLs, and never overwrite server spaces with stale local cache!
        ensureCustomizationTemplates(serverVault);
        if (localSaved && localSaved.customization?.worldTitles) {
          serverVault.customization = serverVault.customization || {};
          serverVault.customization.worldTitles = {
            ...(serverVault.customization.worldTitles || {}),
            ...localSaved.customization.worldTitles
          };
        }
        if (localSaved && Array.isArray(localSaved.customization?.spacesOrder) && localSaved.customization.spacesOrder.length > 0 && !serverVault.customization?.spacesOrder) {
          serverVault.customization = serverVault.customization || {};
          serverVault.customization.spacesOrder = localSaved.customization.spacesOrder;
        }
        if (localSaved && Array.isArray(localSaved.projects)) {
          const serverProjIds = new Set((serverVault.projects || []).map(p => p.id));
          localSaved.projects.forEach(lp => {
            if (lp && lp.id && !serverProjIds.has(lp.id)) {
              serverVault.projects.push(lp);
            }
          });
        }
        if (localSaved && Array.isArray(localSaved.items)) {
          const serverItemIds = new Set((serverVault.items || []).map(i => i.id));
          localSaved.items.forEach(li => {
            if (!li || !li.id || serverItemIds.has(li.id)) return;
            if (li.parentType === 'space' && li.parentId === 'lightbox' && !localSaved.lightboxCleanV104) return;
            serverVault.items.push(li);
          });
        }
        if (localSaved && localSaved.lightboxCleanV104 && Array.isArray(localSaved.lightboxProjects)) {
          serverVault.lightboxCleanV104 = true;
          serverVault.lightboxProjects = Array.isArray(serverVault.lightboxProjects) ? serverVault.lightboxProjects : [];
          const sLbProjIds = new Set(serverVault.lightboxProjects.map(p => p && p.id));
          localSaved.lightboxProjects.forEach(lp => {
            if (lp && lp.id && !sLbProjIds.has(lp.id)) {
              serverVault.lightboxProjects.push(lp);
              sLbProjIds.add(lp.id);
            }
          });
        }
        if (localSaved && localSaved.toolDock && typeof localSaved.toolDock === 'object') {
          serverVault.toolDock = serverVault.toolDock || {};
          const sTd = serverVault.toolDock;
          const lTd = localSaved.toolDock;
          sTd.trash = Array.isArray(sTd.trash) ? sTd.trash : [];
          const trashIdSet = new Set(sTd.trash.map(x => x && x.id).filter(Boolean));
          if (Array.isArray(lTd.trash)) {
            lTd.trash.forEach(tr => {
              if (tr && tr.id && !trashIdSet.has(tr.id)) {
                sTd.trash.push(tr);
                trashIdSet.add(tr.id);
              }
            });
          }
          if (Array.isArray(lTd.launchpad)) {
            sTd.launchpad = Array.isArray(sTd.launchpad) ? sTd.launchpad.filter(t => t && !trashIdSet.has(t.id)) : [];
            const sLpIds = new Set(sTd.launchpad.map(t => t.id));
            lTd.launchpad.forEach(lt => {
              if (lt && lt.id && !trashIdSet.has(lt.id) && !sLpIds.has(lt.id)) {
                sTd.launchpad.push(lt);
                sLpIds.add(lt.id);
              }
            });
          }
          if (Array.isArray(lTd.rdLab)) {
            sTd.rdLab = Array.isArray(sTd.rdLab) ? sTd.rdLab.filter(r => r && !trashIdSet.has(r.id)) : [];
            const sRdIds = new Set(sTd.rdLab.map(r => r.id));
            lTd.rdLab.forEach(lr => {
              if (lr && lr.id && !trashIdSet.has(lr.id) && !sRdIds.has(lr.id)) {
                sTd.rdLab.push(lr);
                sRdIds.add(lr.id);
              }
            });
          }
          if (Array.isArray(lTd.usefulLinks)) {
            sTd.usefulLinks = Array.isArray(sTd.usefulLinks) ? sTd.usefulLinks.filter(u => u && !trashIdSet.has(u.id)) : [];
            const sUlIds = new Set(sTd.usefulLinks.map(u => u.id));
            lTd.usefulLinks.forEach(lu => {
              if (lu && lu.id && !trashIdSet.has(lu.id) && !sUlIds.has(lu.id)) {
                sTd.usefulLinks.push(lu);
                sUlIds.add(lu.id);
              }
            });
          }
        }
        if (localSaved && localSaved.customization?.v3PresetRestoreMigrated && Array.isArray(localSaved.customizationTemplates)) {
          serverVault.customizationTemplates = Array.isArray(serverVault.customizationTemplates) ? serverVault.customizationTemplates : [];
          const serverTplIds = new Set(serverVault.customizationTemplates.map(t => t && t.id));
          localSaved.customizationTemplates.forEach(lt => {
            if (lt && lt.id && lt.id !== 'tpl_warm_gallery_default' && !serverTplIds.has(lt.id)) {
              serverVault.customizationTemplates.push(lt);
            }
          });
        }
        if (localSaved && localSaved.customization?.v3PresetRestoreMigrated && localSaved.defaultTemplateId && !serverVault.defaultTemplateId) {
          serverVault.defaultTemplateId = localSaved.defaultTemplateId;
        }

        // Restore custom space titles (sidebar - disconnected from top bar headings)
        try {
          const rawTitles = localStorage.getItem('ideal_custom_space_titles');
          if (rawTitles) {
            const parsedTitles = JSON.parse(rawTitles);
            serverVault.customSpaceTitles = { ...(serverVault.customSpaceTitles || {}), ...parsedTitles };
            (serverVault.spaces || []).forEach(ss => {
              if (ss && parsedTitles[ss.id]) {
                ss.title = parsedTitles[ss.id];
              }
            });
          }
        } catch (e) {}

        // Restore custom top bar titles (disconnected from sidebar)
        try {
          const rawTopBarTitles = localStorage.getItem('ideal_custom_topbar_titles');
          if (rawTopBarTitles) {
            const parsedTbTitles = JSON.parse(rawTopBarTitles);
            serverVault.customTopBarTitles = { ...(serverVault.customTopBarTitles || {}), ...parsedTbTitles };
            (serverVault.spaces || []).forEach(ss => {
              if (ss && parsedTbTitles[ss.id]) {
                ss.heading = parsedTbTitles[ss.id];
              }
            });
          }
        } catch (e) {}

        try {
          const rawCodes = localStorage.getItem('ideal_custom_space_codes');
          if (rawCodes) {
            const parsedCodes = JSON.parse(rawCodes);
            serverVault.customSpaceCodes = { ...(serverVault.customSpaceCodes || {}), ...parsedCodes };
            (serverVault.spaces || []).forEach(ss => {
              if (ss && parsedCodes[ss.id]) {
                ss.code = parsedCodes[ss.id];
              }
            });
          }
        } catch (e) {}

        // Restore asset sections (Assets vs Vaults assignment)
        if (serverVault.assetSections && Object.keys(serverVault.assetSections).length > 0) {
          try {
            const rawSections = localStorage.getItem('ideal_asset_sections');
            if (rawSections) {
              const parsedSections = JSON.parse(rawSections);
              serverVault.assetSections = { ...serverVault.assetSections, ...parsedSections };
            }
            localStorage.setItem('ideal_asset_sections', JSON.stringify(serverVault.assetSections));
          } catch (e) {}
        } else {
          try {
            const rawSections = localStorage.getItem('ideal_asset_sections');
            if (rawSections) {
              serverVault.assetSections = JSON.parse(rawSections);
            }
          } catch (e) {}
        }
        serverVault.customization = serverVault.customization || {};
        serverVault.customization.assetSections = serverVault.assetSections;

        // Restore custom enclosing card previews
        if (serverVault.enclosingPreviews && Object.keys(serverVault.enclosingPreviews).length > 0) {
          try {
            const rawPreviews = localStorage.getItem('ideal_gdrive_enclosing_previews');
            if (rawPreviews) {
              const parsedPreviews = JSON.parse(rawPreviews);
              serverVault.enclosingPreviews = { ...serverVault.enclosingPreviews, ...parsedPreviews };
            }
            localStorage.setItem('ideal_gdrive_enclosing_previews', JSON.stringify(serverVault.enclosingPreviews));
          } catch (e) {}
        } else {
          try {
            const rawPreviews = localStorage.getItem('ideal_gdrive_enclosing_previews');
            if (rawPreviews) {
              serverVault.enclosingPreviews = JSON.parse(rawPreviews);
            }
          } catch (e) {}
        }
        serverVault.customization = serverVault.customization || {};
        serverVault.customization.enclosingPreviews = serverVault.enclosingPreviews;

        // Restore custom enclosing card order
        try {
          const rawOrder = localStorage.getItem('ideal_gdrive_enclosing_order');
          if (rawOrder) {
            const parsedOrder = JSON.parse(rawOrder);
            if (Array.isArray(parsedOrder) && parsedOrder.length > 0) {
              serverVault.enclosingOrder = parsedOrder;
              serverVault.customization = serverVault.customization || {};
              serverVault.customization.enclosingOrder = parsedOrder;
            }
          }
        } catch (e) {}

        vault = ensureVaultSleekAndGDrive(serverVault);
        ensureLightboxCleanWorkspace(vault);
        localStorage.setItem(LS_KEY, JSON.stringify(vault));
        hydrateLightboxLocalHandles(false);
        renderAll();
        fetch('/api/vault', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(vault)
        }).catch(() => {});
      } else {
        vault = createSeedVault();
        localStorage.setItem(LS_KEY, JSON.stringify(vault));
        await fetch('/api/vault', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(vault)
        });
      }
    }
  } catch (e) {
    // Offline fallback is already loaded
  }

  try {
    const fRes = await fetch('/api/finland-projects');
    if (fRes.ok) {
      const fData = await fRes.json();
      if (fData && Array.isArray(fData.projects)) {
        state.finlandProjects = fData.projects;
      }
    }
  } catch (e) {}

  if (state._pendingNavProject && Array.isArray(vault?.projects)) {
    const foundProj = vault.projects.find(p => p.id === state._pendingNavProject.activeProjectId);
    if (foundProj) {
      state.viewType = 'project';
      state.activeProjectId = foundProj.id;
      state.activeFolderId = state._pendingNavProject.activeFolderId || null;
      if (state._pendingNavProject.activeCategory) {
        state.activeCategory = state._pendingNavProject.activeCategory;
      }
    }
    state._pendingNavProject = null;
  }

  try {
    const cachedAssets = localStorage.getItem('ideal_gdrive_assets_cache');
    let parsed = null;
    if (cachedAssets) {
      try { parsed = JSON.parse(cachedAssets); } catch (e) {}
    }
    const hasSeedThumbs = typeof window !== 'undefined' && !!window._IDEAL_GDRIVE_SEED?.batches?.[0]?.examples?.[0]?.staticThumbUrl;
    const parsedHasThumbs = !!parsed?.batches?.[0]?.examples?.[0]?.staticThumbUrl;
    if ((!parsed || !Array.isArray(parsed.batches) || parsed.batches.length === 0 || !Array.isArray(parsed.enclosingFolders) || parsed.enclosingFolders.length === 0 || (hasSeedThumbs && !parsedHasThumbs)) && typeof window !== 'undefined' && window._IDEAL_GDRIVE_SEED) {
      parsed = window._IDEAL_GDRIVE_SEED;
    }
    if (parsed && Array.isArray(parsed.batches) && parsed.batches.length > 0) {
      state.gdriveBatches = parsed.batches;
      state.gdriveEnclosingFolders = parsed.enclosingFolders || [];
      state.gdriveCategoryLinks = parsed.categoryLinks || {};
      state.gdriveStats = {
        totalBatches: parsed.totalBatches || parsed.batches.length,
        totalFiles: parsed.totalFiles || 0,
        driveRoot: parsed.driveRoot || '',
        loading: false,
        loaded: true,
        lastSyncTs: 0
      };
    }
  } catch (e) {}

  fetchGDriveAssets(true);
  checkGmailStatusOnBoot();
  state.custSavedSnapshot = captureCustomizationSnapshot(vault);
  state.custDirty = false;
  applyCustomizationToDOM();
  renderAll();
}

/* ==========================================================================
   HELPERS: ACTIVE CONTAINER & UI SETTINGS
   ========================================================================== */
function getActiveContainer() {
  if (state.viewType === 'project') {
    const proj = vault.projects.find(p => p.id === state.activeProjectId);
    if (proj) {
      if (!proj.ui) {
        proj.ui = { layoutMode: 'wall', cardSize: 320, aspectRatio: '16 / 10.5', imageFit: 'cover', sortOrder: 'manual' };
      }
      return { type: 'project', obj: proj };
    }
  }
  const sp = vault.spaces.find(s => s.id === state.activeSpaceId) || vault.spaces[0];
  if (!sp.ui) {
    sp.ui = { layoutMode: 'wall', cardSize: 330, aspectRatio: '16 / 10.5', imageFit: 'cover', sortOrder: 'manual' };
  }
  return { type: 'space', obj: sp };
}

/* --- PAGE-SPECIFIC HUD SCALE & VIEW SIZING ENGINE --- */
function getContainerScaleContext(type, obj) {
  if (!obj) return { key: 'wall', step: 3, ui: {} };
  const ui = obj.ui = obj.ui || {};
  const isMovingForward = (type === 'space' && ['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(obj.id));
  const isGDrive = (type === 'space' && obj.id === 'gdrive_assets');
  const isToolDock = (type === 'space' && obj.id === 'tool_dock');
  const isLightbox = (type === 'space' && obj.id === 'lightbox');
  const mode = ui.layoutMode || (type === 'project' ? 'giant_wall' : 'wall');

  let key = 'wall';
  if (isGDrive) {
    key = 'gdrive';
  } else if (isLightbox) {
    key = 'lightbox';
  } else if (isToolDock) {
    key = 'tool_dock';
  } else if (isMovingForward) {
    key = 'moving_forward';
  } else if (mode === 'giant_wall') {
    key = 'giant_wall';
  } else if (mode === 'kanban') {
    key = 'kanban';
  } else if (mode === 'list') {
    key = 'list';
  } else {
    key = 'wall';
  }

  // Determine current step (1 to 5) per page & per mode
  ui.scaleStepByMode = ui.scaleStepByMode || {};
  let step = 3;
  if (typeof ui.scaleStepByMode[key] === 'number' && ui.scaleStepByMode[key] >= 1 && ui.scaleStepByMode[key] <= 5) {
    step = Math.round(ui.scaleStepByMode[key]);
  } else if (typeof ui.scaleStep === 'number' && ui.scaleStep >= 1 && ui.scaleStep <= 5) {
    step = Math.round(ui.scaleStep);
  } else if (key === 'gdrive' && typeof state.gdriveScaleStep === 'number' && state.gdriveScaleStep >= 1 && state.gdriveScaleStep <= 5) {
    step = state.gdriveScaleStep;
  } else if (key === 'tool_dock' && typeof state.toolDockScaleStep === 'number' && state.toolDockScaleStep >= 1 && state.toolDockScaleStep <= 5) {
    step = state.toolDockScaleStep;
  } else if (key === 'giant_wall') {
    const curZoom = (typeof ui.cameraZoom === 'number' && ui.cameraZoom > 0) ? ui.cameraZoom : (state.giantWallZoom || 1);
    const zooms = [0.5, 0.75, 1.0, 1.35, 1.8];
    let closestIdx = 2;
    let minDiff = 999;
    zooms.forEach((z, idx) => {
      const diff = Math.abs(z - curZoom);
      if (diff < minDiff) { minDiff = diff; closestIdx = idx; }
    });
    step = closestIdx + 1;
  } else if (key === 'wall') {
    if (typeof ui.cardSize === 'number' && ui.cardSize >= 150) {
      const DRAWER_SIZES = [200, 260, 320, 390, 480];
      let closestIdx = 2;
      let minDiff = 999;
      DRAWER_SIZES.forEach((s, idx) => {
        const diff = Math.abs(s - ui.cardSize);
        if (diff < minDiff) { minDiff = diff; closestIdx = idx; }
      });
      step = closestIdx + 1;
    }
  } else if (key === 'kanban') {
    if (typeof ui.columnWidth === 'number' && ui.columnWidth >= 180) {
      const COL_WIDTHS = [240, 280, 320, 380, 450];
      let closestIdx = 2;
      let minDiff = 999;
      COL_WIDTHS.forEach((w, idx) => {
        const diff = Math.abs(w - ui.columnWidth);
        if (diff < minDiff) { minDiff = diff; closestIdx = idx; }
      });
      step = closestIdx + 1;
    }
  }

  ui.scaleStep = step;
  ui.scaleStepByMode[key] = step;
  return { key, step, ui };
}

function applyContainerScale(type, obj, isInteractive = false) {
  if (!obj) return;
  const { key, step, ui } = getContainerScaleContext(type, obj);
  ui.scaleStep = step;
  ui.scaleStepByMode = ui.scaleStepByMode || {};
  ui.scaleStepByMode[key] = step;

  if (key === 'lightbox') {
    state.lightboxScaleStep = step;
    const LB_SIZES = [180, 215, 255, 310, 390];
    const sz = LB_SIZES[step - 1] || 255;
    ui.cardSize = sz;
    document.querySelectorAll('.lb-studio-grid, .lb-assets-grid').forEach(el => {
      el.dataset.scaleStep = String(step);
      el.style.setProperty('--lb-col-width', sz + 'px');
    });
    return;
  }

  if (key === 'gdrive') {
    state.gdriveScaleStep = step;
    const GDRIVE_ROOT_SNAP_SIZES = [160, 195, 230, 280, 360];
    const GDRIVE_SNAP_SIZES = [75, 100, 130, 165, 210];
    const rootW = GDRIVE_ROOT_SNAP_SIZES[step - 1];
    const snapW = GDRIVE_SNAP_SIZES[step - 1];
    state.gdriveSubfolderCardSize = snapW;
    ui.cardSize = snapW;

    document.querySelectorAll('#gridAssets, #gridVaults').forEach(el => {
      el.dataset.scaleStep = String(step);
      el.style.setProperty('--eagle-col-width', rootW + 'px');
    });
    document.querySelectorAll('.gdrive-subfolder-section .gdrive-files-grid, #creativeMainArea .gdrive-files-grid, .gdrive-creative-sections .gdrive-files-grid, .gdrive-files-grid:not(#gridAssets):not(#gridVaults)').forEach(el => {
      el.dataset.scaleStep = String(step);
      el.style.setProperty('--eagle-col-width', snapW + 'px');
    });
    return;
  }

  if (key === 'tool_dock') {
    state.toolDockScaleStep = step;
    const TOOL_DOCK_SIZES = [160, 200, 240, 290, 360];
    const sz = TOOL_DOCK_SIZES[step - 1];
    ui.cardSize = sz;
    applyToolDockScaleToDOM(null, sz);
    return;
  }

  if (key === 'giant_wall') {
    const GIANT_WALL_ZOOMS = [0.5, 0.75, 1.0, 1.35, 1.8];
    const cam = getActiveBoardCamera();
    if (isInteractive) {
      cam.zoom = GIANT_WALL_ZOOMS[step - 1];
      ui.cameraZoom = cam.zoom;
      applyActiveBoardCameraTransform();
    } else {
      if (typeof ui.cameraZoom === 'number' && ui.cameraZoom > 0) {
        cam.zoom = ui.cameraZoom;
      } else {
        cam.zoom = GIANT_WALL_ZOOMS[step - 1];
        ui.cameraZoom = cam.zoom;
      }
      applyActiveBoardCameraTransform();
    }
    return;
  }

  if (key === 'kanban') {
    const COL_WIDTHS = [240, 280, 320, 380, 450];
    const colW = COL_WIDTHS[step - 1];
    ui.columnWidth = colW;
    document.documentElement.style.setProperty('--kanban-col-width', colW + 'px');
    const ws = document.getElementById('workspace');
    if (ws) ws.style.setProperty('--kanban-col-width', colW + 'px');
    document.querySelectorAll('.kanban-board').forEach(el => {
      el.style.setProperty('grid-auto-columns', colW + 'px');
    });
    document.querySelectorAll('.kanban-col, .kanban-column, .milanote-column').forEach(el => {
      el.style.width = colW + 'px';
      el.style.minWidth = colW + 'px';
      el.style.maxWidth = colW + 'px';
    });
    return;
  }

  if (key === 'list') {
    const LIST_ROW_PADDINGS = ['4px 8px', '6px 10px', '8px 12px', '11px 14px', '14px 18px'];
    const LIST_THUMB_WS = [48, 64, 80, 100, 130];
    const LIST_THUMB_HS = [32, 44, 54, 68, 88];
    const LIST_FONT_SIZES = ['11px', '12px', '13px', '14.5px', '16px'];
    const pad = LIST_ROW_PADDINGS[step - 1];
    const tw = LIST_THUMB_WS[step - 1];
    const th = LIST_THUMB_HS[step - 1];
    const fsz = LIST_FONT_SIZES[step - 1];

    document.documentElement.style.setProperty('--list-row-pad', pad);
    document.documentElement.style.setProperty('--list-thumb-w', tw + 'px');
    document.documentElement.style.setProperty('--list-thumb-h', th + 'px');
    document.documentElement.style.setProperty('--list-thumb-sz', tw + 'px');
    document.documentElement.style.setProperty('--list-font-sz', fsz);

    const ws = document.getElementById('workspace');
    if (ws) {
      ws.style.setProperty('--list-row-pad', pad);
      ws.style.setProperty('--list-thumb-w', tw + 'px');
      ws.style.setProperty('--list-thumb-h', th + 'px');
      ws.style.setProperty('--list-font-sz', fsz);
    }

    document.querySelectorAll('.list-row-item').forEach(el => {
      el.style.padding = pad;
      el.style.fontSize = fsz;
      el.style.gridTemplateColumns = `${tw + 16}px minmax(140px, 1.2fr) minmax(180px, 2fr) minmax(100px, 140px) 130px`;
    });
    document.querySelectorAll('.list-thumb').forEach(el => {
      el.style.width = tw + 'px';
      el.style.height = th + 'px';
    });
    return;
  }

  if (key === 'moving_forward') {
    const MF_COL_WIDTHS = [200, 240, 280, 330, 400];
    const colW = MF_COL_WIDTHS[step - 1];
    ui.cardSize = colW;
    document.documentElement.style.setProperty('--mf-col-min-width', colW + 'px');
    const ws = document.getElementById('workspace');
    if (ws) ws.style.setProperty('--mf-col-min-width', colW + 'px');
    document.querySelectorAll('.mf-vertical-board').forEach(el => {
      el.style.setProperty('grid-template-columns', `repeat(auto-fill, minmax(${colW}px, 1fr))`);
    });
    document.querySelectorAll('.mf-row-cards .mf-lead-card').forEach(el => {
      el.style.setProperty('min-width', colW + 'px');
    });
    return;
  }

  // Default: wall
  const DRAWER_SIZES = [200, 260, 320, 390, 480];
  const sz = DRAWER_SIZES[step - 1];
  ui.cardSize = sz;
  document.documentElement.style.setProperty('--grid-size', sz + 'px');
  const ws = document.getElementById('workspace');
  if (ws) ws.style.setProperty('--grid-size', sz + 'px');

  applyProjectsGridCardSize(document.getElementById('projectsClearDrawersWall'), sz);
  const showcaseWall = document.getElementById('showcaseItemsWall');
  if (showcaseWall) {
    showcaseWall.style.setProperty('--grid-size', sz + 'px');
    showcaseWall.style.setProperty('grid-template-columns', `repeat(auto-fill, minmax(${sz}px, 1fr))`);
  }
  document.querySelectorAll('.clear-drawers-grid').forEach(el => {
    el.style.setProperty('--grid-size', sz + 'px');
    el.style.setProperty('grid-template-columns', `repeat(auto-fill, minmax(${sz}px, 1fr))`, 'important');
  });
  document.querySelectorAll('.cards-wall').forEach(el => {
    el.style.setProperty('--grid-size', sz + 'px');
    el.style.setProperty('grid-template-columns', `repeat(auto-fill, minmax(${sz}px, 1fr))`);
  });
  document.querySelectorAll('.clear-drawer-bento').forEach(el => {
    el.style.setProperty('grid-auto-rows', `${Math.round(sz * 0.25)}px`, 'important');
  });
  document.querySelectorAll('.clear-drawer-thumb:first-child').forEach(el => {
    el.style.setProperty('min-height', `${Math.round(sz * 0.5 + 6)}px`, 'important');
  });
}

function extractSpacesConfig(spaces = vault?.spaces) {
  const out = {};
  (spaces || []).forEach(sp => {
    if (!sp || !sp.id || sp.id === 'customize') return;
    out[sp.id] = {
      code: sp.code || FACTORY_DEFAULT_SPACES_CONFIG[sp.id]?.code || '',
      title: sp.title || FACTORY_DEFAULT_SPACES_CONFIG[sp.id]?.title || '',
      heading: sp.heading || sp.title || FACTORY_DEFAULT_SPACES_CONFIG[sp.id]?.heading || '',
      layoutMode: sp.ui?.layoutMode || FACTORY_DEFAULT_SPACES_CONFIG[sp.id]?.layoutMode || 'wall',
      aspectRatio: sp.ui?.aspectRatio || FACTORY_DEFAULT_SPACES_CONFIG[sp.id]?.aspectRatio || '16 / 10.5'
    };
  });
  return out;
}

function captureCustomizationSnapshot(v = vault) {
  if (!v) return '';
  const custCopy = { ...(v.customization || {}) };
  delete custCopy.worldTitles;
  delete custCopy.assetSections;
  delete custCopy.enclosingOrder;
  delete custCopy.enclosingPreviews;
  delete custCopy.topBarTitles;
  return JSON.stringify({
    customization: custCopy
  });
}

function restoreCustomizationSnapshot(snapStr) {
  if (!snapStr || !vault) return;
  try {
    const parsed = JSON.parse(snapStr);
    if (parsed.customization) {
      const preservedWorldTitles = vault.customWorldTitles || vault.customization?.worldTitles || {};
      const preservedAssetSections = vault.assetSections || vault.customization?.assetSections || {};
      const preservedEnclosingOrder = vault.enclosingOrder || vault.customization?.enclosingOrder || [];
      const preservedEnclosingPreviews = vault.enclosingPreviews || vault.customization?.enclosingPreviews || {};
      const preservedTopBarTitles = vault.customTopBarTitles || vault.customization?.topBarTitles || {};

      vault.customization = JSON.parse(JSON.stringify(parsed.customization));
      vault.customization.worldTitles = { ...preservedWorldTitles };
      vault.customization.assetSections = preservedAssetSections;
      vault.customization.enclosingOrder = preservedEnclosingOrder;
      vault.customization.enclosingPreviews = preservedEnclosingPreviews;
      vault.customization.topBarTitles = { ...preservedTopBarTitles };

      vault.customTopBarTitles = { ...preservedTopBarTitles };
      vault.assetSections = preservedAssetSections;
      vault.enclosingOrder = preservedEnclosingOrder;
      vault.enclosingPreviews = preservedEnclosingPreviews;
    }
    state.custDirty = false;
    applyCustomizationToDOM();
    renderAll();
  } catch (e) {}
}

function applyTemplateObjectToVault(tpl, v = vault) {
  if (!tpl || !v) return;
  const tc = JSON.parse(JSON.stringify(tpl.customization || FACTORY_DEFAULT_TEMPLATE.customization));

  // Keep user's custom section headlines permanently intact! Presets must NEVER overwrite them!
  const preservedWorldTitles = v.customWorldTitles || v.customization?.worldTitles || {};
  const preservedAssetSections = v.assetSections || v.customization?.assetSections || {};
  const preservedEnclosingOrder = v.enclosingOrder || v.customization?.enclosingOrder || [];
  const preservedEnclosingPreviews = v.enclosingPreviews || v.customization?.enclosingPreviews || {};
  const preservedTopBarTitles = v.customTopBarTitles || v.customization?.topBarTitles || {};

  tc.activeTemplateId = tpl.id;
  v.customization = {
    ...(v.customization || {}),
    ...tc,
    customColors: { ...(tc.customColors || FACTORY_DEFAULT_TEMPLATE.customization.customColors) },
    worldTitles: { ...preservedWorldTitles },
    assetSections: preservedAssetSections,
    enclosingOrder: preservedEnclosingOrder,
    enclosingPreviews: preservedEnclosingPreviews,
    topBarTitles: { ...preservedTopBarTitles },
    activeTemplateId: tpl.id
  };

  v.assetSections = preservedAssetSections;
  v.enclosingOrder = preservedEnclosingOrder;
  v.enclosingPreviews = preservedEnclosingPreviews;
  v.customTopBarTitles = { ...preservedTopBarTitles };

  // Do NOT touch sp.title or sp.heading from presets! Spaces titles belong to the user!
  const scMap = tpl.spacesConfig || FACTORY_DEFAULT_SPACES_CONFIG;
  if (Array.isArray(v.spaces)) {
    v.spaces.forEach(sp => {
      if (!sp || sp.id === 'customize') return;
      if (v.customSpaceTitles && v.customSpaceTitles[sp.id]) {
        sp.title = v.customSpaceTitles[sp.id];
      } else if (sp.title === 'Drive & PSD Assets' || sp.title === 'Google Drive & PSD Vault') {
        sp.title = 'Assets & Vaults';
      }
      if (v.customTopBarTitles && v.customTopBarTitles[sp.id]) {
        sp.heading = v.customTopBarTitles[sp.id];
      } else if (sp.id === 'lightbox') {
        sp.heading = 'The Lightbox — Curation, Comparison & Routing Hub';
      }
      if (v.customSpaceCodes && v.customSpaceCodes[sp.id]) {
        sp.code = v.customSpaceCodes[sp.id];
      }
      const sc = scMap[sp.id] || FACTORY_DEFAULT_SPACES_CONFIG[sp.id];
      if (sc) {
        sp.ui = sp.ui || {};
        if (sc.layoutMode) sp.ui.layoutMode = sc.layoutMode;
        if (sc.aspectRatio) sp.ui.aspectRatio = sc.aspectRatio;
      }
    });
    renumberSidebarSpaces(v.spaces);
  }
}

function setTemplateAsWebsiteDefault(tplId) {
  ensureCustomizationTemplates(vault);
  const found = vault.customizationTemplates.find(t => t.id === tplId);
  if (!found) return;
  vault.defaultTemplateId = found.id;
  vault.customizationTemplates.forEach(t => {
    if (t) t.isDefault = (t.id === found.id);
  });
  try {
    localStorage.setItem(DEFAULT_TEMPLATE_LS_KEY, JSON.stringify(found));
  } catch (e) {}

  applyTemplateObjectToVault(found, vault);

  state.custMode = 'idle';
  state.custPreviewingTemplateId = null;
  state.custEditingTemplateId = null;
  state.custSavedSnapshot = captureCustomizationSnapshot(vault);
  state.custDirty = false;

  saveVault(`★ DEFAULT PRESET: ${found.name.toUpperCase()}`);
  applyCustomizationToDOM();
  renderSidebar();
  renderHeaderAndToolbar();
  updateCustomizerDirtyState();
  if (state.viewType === 'space' && state.activeSpaceId === 'customize') {
    renderWorkspace();
  }
  showStatusToast(`★ Set as website default: ${found.name}`);
}

function updateCustomizerDirtyState() {
  if (!state.custSavedSnapshot) {
    state.custSavedSnapshot = captureCustomizationSnapshot(vault);
  }
  const currentSnap = captureCustomizationSnapshot(vault);
  state.custDirty = (currentSnap !== state.custSavedSnapshot);

  // If dirty and not yet in an explicit mode, enter edit mode on the active/default template
  if (state.custDirty && (!state.custMode || state.custMode === 'idle' || state.custMode === 'preview')) {
    state.custMode = 'edit';
    state.custEditingTemplateId = state.custPreviewingTemplateId || vault.customization?.activeTemplateId || vault.defaultTemplateId;
    state.custPreviewingTemplateId = null;
  }

  const bar = document.getElementById('custStickyBar');
  const badge = document.getElementById('custDirtyBadge');
  const discardBtn = document.getElementById('btnCustDiscard');
  const saveBtn = document.getElementById('btnCustSavePrimary');
  const activeNameEl = document.getElementById('custActiveTplName');

  ensureCustomizationTemplates(vault);
  const targetId = state.custEditingTemplateId || state.custPreviewingTemplateId || vault.customization?.activeTemplateId || vault.defaultTemplateId;
  const activeTpl = vault.customizationTemplates.find(t => t.id === targetId) || getWebsiteDefaultTemplate(vault);

  if (activeNameEl && activeTpl) {
    const isNew = state.custMode === 'create';
    activeNameEl.textContent = (isNew ? 'New Studio Preset' : activeTpl.name) + (state.custDirty ? ' *' : '');
  }
  if (bar) {
    bar.classList.toggle('is-dirty', state.custDirty);
  }
  if (badge) {
    if (state.custDirty) {
      badge.className = 'cust-dirty-pill dirty';
      badge.textContent = '● Unsaved Edits';
      badge.style.display = '';
    } else {
      badge.style.display = 'none';
    }
  }
  if (discardBtn) {
    discardBtn.style.display = state.custDirty ? '' : 'none';
  }
  if (saveBtn) {
    if (state.custMode === 'create') {
      saveBtn.textContent = 'Save as New Preset *';
    } else if (state.custMode === 'edit') {
      saveBtn.textContent = state.custDirty ? 'Save Changes *' : 'Save Changes';
    } else {
      saveBtn.textContent = state.custDirty ? 'Save Changes *' : 'Save as New Preset';
    }
  }
}

function showUnsavedCustDialog() {
  const dlg = document.getElementById('unsavedCustDialog');
  if (!dlg) return;

  const kickerEl = document.getElementById('unsavedCustKicker');
  const titleEl = document.getElementById('unsavedCustTitle');
  const msgEl = document.getElementById('unsavedCustMessage');
  const saveBtn = document.getElementById('btnUnsavedSaveLeave');

  const isCreatingNew = (state.custMode === 'create' || !state.custEditingTemplateId);
  let tplName = 'Preset';
  if (!isCreatingNew) {
    const tpl = (vault.customizationTemplates || []).find(t => t.id === state.custEditingTemplateId);
    if (tpl) tplName = tpl.name;
  }

  if (kickerEl) kickerEl.textContent = isCreatingNew ? 'UNSAVED NEW PRESET' : 'UNSAVED TEMPLATE EDITS';
  if (titleEl) titleEl.textContent = isCreatingNew ? 'Leave without saving new preset?' : `Save changes to "${tplName}"?`;
  if (msgEl) {
    msgEl.textContent = isCreatingNew
      ? 'You have unsaved changes to your new preset. Would you like to save it as a preset, discard it, or keep editing?'
      : `You made changes to "${tplName}". Would you like to save your changes, discard them, or keep editing?`;
  }
  if (saveBtn) {
    saveBtn.textContent = isCreatingNew ? 'Save New Preset & Leave' : 'Save Changes & Leave';
  }

  dlg.showModal();
}

function guardLeaveCustomize(onProceed) {
  if (state.viewType === 'space' && state.activeSpaceId === 'customize') {
    if (state.custDirty) {
      state.pendingLeaveAction = onProceed;
      showUnsavedCustDialog();
      return;
    }
    // If not dirty, but was previewing a preset (or not on the saved default)
    if (state.custMode === 'preview' || state.custPreviewingTemplateId) {
      const defTpl = getWebsiteDefaultTemplate(vault);
      applyTemplateObjectToVault(defTpl, vault);
      applyCustomizationToDOM();
      state.custPreviewingTemplateId = null;
      state.custMode = null;
      state.custEditingTemplateId = null;
    }
  }
  onProceed();
}

function saveChangesToActiveTemplate() {
  ensureCustomizationTemplates(vault);
  const targetId = state.custEditingTemplateId || vault.customization?.activeTemplateId || vault.defaultTemplateId;
  const tpl = vault.customizationTemplates.find(t => t.id === targetId);
  if (!tpl) {
    openSaveTemplateModal(null);
    return;
  }
  const custCopy = JSON.parse(JSON.stringify(vault.customization || {}));
  delete custCopy.activeTemplateId;
  tpl.customization = custCopy;
  tpl.updatedAt = Date.now();

  if (tpl.id === vault.defaultTemplateId || tpl.isDefault) {
    try {
      localStorage.setItem(DEFAULT_TEMPLATE_LS_KEY, JSON.stringify(tpl));
    } catch (e) {}
  }

  saveVault(`SAVED TEMPLATE: ${tpl.name.toUpperCase()}`);
  state.custSavedSnapshot = captureCustomizationSnapshot(vault);
  state.custDirty = false;
  state.custMode = 'idle';
  state.custEditingTemplateId = null;
  state.custPreviewingTemplateId = null;
  renderSidebar();
  renderHeaderAndToolbar();
  if (state.viewType === 'space' && state.activeSpaceId === 'customize') {
    renderWorkspace();
  }
  showStatusToast(`✓ Saved changes to: ${tpl.name}`);
}

function enterCreateNewTemplateMode() {
  if (state.custDirty) {
    const discardOk = confirm('You have unsaved edits. Discard them to create a new template?');
    if (!discardOk) return;
  }
  state.custMode = 'create';
  state.custEditingTemplateId = null;
  state.custPreviewingTemplateId = null;
  state.custSavedSnapshot = captureCustomizationSnapshot(vault);
  state.custDirty = false;
  renderWorkspace();
}

function startEditingTemplate(tplId) {
  ensureCustomizationTemplates(vault);
  const tpl = vault.customizationTemplates.find(t => t.id === tplId);
  if (!tpl) return;
  if (state.custDirty && state.custEditingTemplateId !== tpl.id) {
    const discardOk = confirm(`You have unsaved edits. Discard them to edit "${tpl.name}"?`);
    if (!discardOk) return;
  }
  state.custMode = 'edit';
  state.custEditingTemplateId = tpl.id;
  state.custPreviewingTemplateId = null;
  applyTemplateObjectToVault(tpl, vault);
  applyCustomizationToDOM();
  state.custSavedSnapshot = captureCustomizationSnapshot(vault);
  state.custDirty = false;
  renderWorkspace();
}

function openSaveTemplateModal(afterSaveCallback = null) {
  ensureCustomizationTemplates(vault);
  state.pendingSaveAfterCallback = typeof afterSaveCallback === 'function' ? afterSaveCallback : null;

  const dlg = document.getElementById('saveTemplateDialog');
  const nameIn = document.getElementById('saveTplNameInput');
  const defaultChk = document.getElementById('saveTplSetDefaultChk');

  if (!dlg || !nameIn || !defaultChk) return;

  const nextNum = (vault.customizationTemplates?.length || 1) + 1;
  nameIn.value = '';
  nameIn.placeholder = `e.g. Studio Preset ${nextNum}`;
  defaultChk.checked = false;

  dlg.showModal();
  setTimeout(() => {
    nameIn.focus();
  }, 30);
}

function commitSaveTemplateFromModal() {
  ensureCustomizationTemplates(vault);
  const dlg = document.getElementById('saveTemplateDialog');
  const nameIn = document.getElementById('saveTplNameInput');
  const defaultChk = document.getElementById('saveTplSetDefaultChk');

  const nextNum = (vault.customizationTemplates?.length || 1) + 1;
  const rawName = (nameIn?.value || '').trim() || `Studio Preset ${nextNum}`;
  const setAsDefault = Boolean(defaultChk?.checked);

  const custCopy = JSON.parse(JSON.stringify(vault.customization || {}));
  delete custCopy.activeTemplateId;

  const targetTpl = {
    id: 'preset_custom_' + Date.now(),
    name: rawName,
    builtIn: false,
    isDefault: false,
    customization: custCopy,
    createdAt: Date.now(),
    updatedAt: Date.now()
  };
  vault.customizationTemplates.push(targetTpl);

  vault.customization.activeTemplateId = targetTpl.id;

  if (setAsDefault) {
    vault.defaultTemplateId = targetTpl.id;
    vault.customizationTemplates.forEach(t => {
      if (t) t.isDefault = (t.id === targetTpl.id);
    });
    try {
      localStorage.setItem(DEFAULT_TEMPLATE_LS_KEY, JSON.stringify(targetTpl));
    } catch (e) {}
  }

  state.custSavedSnapshot = captureCustomizationSnapshot(vault);
  state.custDirty = false;
  state.custMode = 'idle';
  state.custEditingTemplateId = null;
  state.custPreviewingTemplateId = null;

  dlg?.close();
  saveVault(setAsDefault ? `SAVED & SET DEFAULT: ${targetTpl.name.toUpperCase()}` : `PRESET SAVED: ${targetTpl.name.toUpperCase()}`);
  applyCustomizationToDOM();
  showStatusToast(`✓ Saved preset: ${targetTpl.name}`);

  const cb = state.pendingSaveAfterCallback;
  state.pendingSaveAfterCallback = null;
  if (cb) {
    cb();
  } else {
    renderAll();
  }
}

function applyCustomizationToDOM() {
  const c = vault.customization || {};
  const root = document.documentElement;

  root.style.setProperty('--font-heading', c.fontHeading || "'Syne', sans-serif");
  // Keep --font-body unset on :root so top bar filter pills inherit --font-heading from body, while notes/descriptions use --font-typewriter
  root.style.removeProperty('--font-body');
  root.style.setProperty('--font-typewriter', c.fontBody || "'Inter', sans-serif");
  root.style.setProperty('--font-mono', c.fontMono || "'Space Mono', monospace");
  root.style.setProperty('--base-font-size', (c.baseFontSize || 12.5) + 'px');
  root.style.setProperty('--heading-scale', c.headingScale || 0.9);
  root.style.setProperty('--card-radius', (c.cardRadius ?? 5) + 'px');
  root.style.setProperty('--card-border-width', (c.cardBorderWidth ?? 0) + 'px');
  root.style.setProperty('--grid-gap', (c.gridGap ?? 28) + 'px');

  // Theme preset or custom palette
  const presetKey = c.themePreset || 'warm_gallery';
  const metaScheme = document.querySelector('meta[name="color-scheme"]');
  if (presetKey === 'custom' && c.customColors) {
    const cc = c.customColors;
    const bgHex = cc.bg || '#F6F4EF';
    const textHex = cc.text || '#181715';
    const isDarkCustom = /^#[0-3]/i.test(bgHex.trim());
    const modeStr = isDarkCustom ? 'dark' : 'light';
    root.style.colorScheme = modeStr;
    if (metaScheme) {
      metaScheme.content = modeStr;
      try { localStorage.setItem('color-scheme', modeStr); } catch (e) {}
    }
    root.style.setProperty('--bg', bgHex);
    root.style.setProperty('--surface', cc.surface || '#FAF8F5');
    root.style.setProperty('--surface-stage', cc.stage || '#E8E4DC');
    root.style.setProperty('--surface-pill', cc.surface || '#FFFFFF');
    root.style.setProperty('--text', textHex);
    root.style.setProperty('--accent', cc.accent || '#C84B31');
    root.style.setProperty('--border', `color-mix(in srgb, ${textHex} 11%, ${bgHex})`);
    root.style.setProperty('--border-strong', textHex);
    root.style.setProperty('--text-mid', `color-mix(in srgb, ${textHex} 62%, ${bgHex})`);
    root.style.setProperty('--text-faint', `color-mix(in srgb, ${textHex} 40%, ${bgHex})`);
  } else {
    const p = THEME_PRESETS[presetKey] || THEME_PRESETS.warm_gallery;
    root.style.colorScheme = p.mode || 'light';
    if (metaScheme) {
      metaScheme.content = p.mode;
      try { localStorage.setItem('color-scheme', p.mode); } catch (e) {}
    }
    root.style.setProperty('--bg', p.bg);
    root.style.setProperty('--surface', p.surface);
    root.style.setProperty('--surface-stage', p.stage);
    root.style.setProperty('--surface-pill', p.pill);
    root.style.setProperty('--border', p.border);
    root.style.setProperty('--border-strong', p.strong);
    root.style.setProperty('--text', p.text);
    root.style.setProperty('--text-mid', p.textMid);
    root.style.setProperty('--text-faint', p.textFaint);
    root.style.setProperty('--accent', p.accent);
  }

  // Card badge visibility classes
  document.body.classList.toggle('hide-index-badges', c.showIndexBadge === false);
  document.body.classList.toggle('hide-status-badges', c.showStatusBadge === false);
  document.body.classList.toggle('hide-count-badges', c.showCountBadge === false);
  document.body.classList.toggle('hide-card-tags', c.showCardTags === false);

  // Subbar title header styling (unified between Dashboard & Active Launchpad)
  const tone = c.subbarTitleTone || 'grayish';
  let subbarColor = 'var(--text-faint)';
  if (tone === 'mid') subbarColor = 'var(--text-mid)';
  else if (tone === 'ink') subbarColor = 'var(--text)';
  else if (tone === 'accent') subbarColor = 'var(--accent)';
  root.style.setProperty('--subbar-title-color', subbarColor);

  const subbarSize = c.subbarTitleSize || 'standard';
  if (subbarSize === 'compact') {
    root.style.setProperty('--subbar-title-size', '10px');
    root.style.setProperty('--subbar-title-spacing', '0.06em');
    root.style.setProperty('--subbar-height', '32px');
  } else if (subbarSize === 'editorial') {
    root.style.setProperty('--subbar-title-size', '12px');
    root.style.setProperty('--subbar-title-spacing', '0.12em');
    root.style.setProperty('--subbar-height', '40px');
  } else {
    root.style.setProperty('--subbar-title-size', '10.5px');
    root.style.setProperty('--subbar-title-spacing', '0.08em');
    root.style.setProperty('--subbar-height', '36px');
  }

  // Card border width
  root.style.setProperty('--card-border-width', (c.cardBorderWidth ?? 0) + 'px');

  // Card elevation / shadow
  const shadowMode = c.cardShadow || 'none';
  let shadowVal = 'none';
  if (shadowMode === 'soft') shadowVal = '0 8px 24px -6px rgba(0, 0, 0, 0.12)';
  else if (shadowMode === 'deep') shadowVal = '0 18px 40px -10px rgba(0, 0, 0, 0.28)';
  root.style.setProperty('--stage-shadow', shadowVal);

  // Stage pattern & hover motion
  document.body.dataset.stagePattern = c.stagePattern || 'none';
  document.body.dataset.hoverMotion = c.hoverMotion || 'lift';

  // Top bar unified appearance (Frosted glass / Solid studio / Minimal, Text tone, Elevation)
  document.body.dataset.topbarBg = c.topBarBg || 'glass';
  document.body.dataset.topbarTone = c.topBarTone || 'ink';
  document.body.dataset.topbarElevation = c.topBarElevation || 'whisper';

  // Per-section UI tokens & scale engine
  const { type, obj } = getActiveContainer();
  const ui = obj?.ui || {};
  const validCardSize = (typeof ui.cardSize === 'number' && ui.cardSize >= 150) ? ui.cardSize : 330;
  root.style.setProperty('--grid-size', validCardSize + 'px');
  root.style.setProperty('--stage-aspect', ui.aspectRatio || '16 / 10.5');
  root.style.setProperty('--stage-fit', c.stageFit || ui.imageFit || 'cover');

  applyContainerScale(type, obj, false);

  // Sync sidebar open/collapsed state (open on entry, pushable to the side)
  const appShell = document.getElementById('appShell');
  const drawer = document.getElementById('sidebarDrawer');
  const restoreEdge = document.getElementById('btnRestoreSidebarEdge');

  const isOpen = Boolean(state.sidebarOpen);
  if (appShell) appShell.classList.toggle('sidebar-open', isOpen);
  if (drawer) drawer.classList.toggle('open', isOpen);
  if (restoreEdge) restoreEdge.hidden = isOpen;
}

/* ==========================================================================
   SIDEBAR NAVIGATION & INLINE COPY CUSTOMIZATION
   ========================================================================== */
function toggleSidebar(forceOpen) {
  state.sidebarOpen = typeof forceOpen === 'boolean' ? forceOpen : !state.sidebarOpen;
  applyCustomizationToDOM();
  saveNavState();
}

function getInstagramAllItems() {
  return (vault.items || []).filter(it =>
    (it.parentType === 'space' && it.parentId === 'instagram') ||
    ((it.parentType === 'project' || (it.parentType === 'space' && it.parentId === 'incubator')) &&
      (it.igStatus === 'queued' || it.igStatus === 'published'))
  );
}

function isInstagramFolderMatch(it, activeFolderId) {
  const isIgFolder = Boolean(
    it.folderId &&
    (vault.items || []).some(f => f.id === it.folderId && f.kind === 'folder' && f.parentType === 'space' && f.parentId === 'instagram')
  );
  if (activeFolderId) {
    return it.folderId === activeFolderId;
  }
  if (it.parentType === 'space' && it.parentId === 'instagram') {
    return !it.folderId;
  }
  return !isIgFolder;
}

function matchesInstagramCategory(it, cat, isFirstAll) {
  if (!cat || isFirstAll || cat === 'All') return true;
  if (cat === 'IG Ready') {
    return it.igStatus === 'queued' || it.section === 'IG Ready' || /ready/i.test(it.status || '');
  }
  if (cat === 'IG Live') {
    return it.igStatus === 'published' || it.section === 'IG Live' || /live/i.test(it.status || '');
  }
  if (cat === 'Reels & Motion') {
    return (
      it.section === 'Reels & Motion' ||
      it.kind === 'video' ||
      /\.gif$/i.test(it.url || '') ||
      (it.tags || []).some(t => /reel|motion|video|loop|animation/i.test(t))
    );
  }
  if (cat === 'Highlights') {
    return (
      it.section === 'Highlights' ||
      it.section === 'Story Highlights' ||
      /highlight|story/i.test(it.status || '') ||
      (it.tags || []).some(t => /highlight|story/i.test(t))
    );
  }
  return it.section === cat;
}

function getSpaceCount(spaceId) {
  if (spaceId === 'projects') return vault.projects.length;
  if (spaceId === 'lightbox') {
    return getLightboxAssetsForActiveProject().length;
  }
  if (spaceId === 'gdrive_assets') return state.gdriveBatches.length || state.gdriveStats.totalBatches || 75;
  if (spaceId === 'tool_dock') {
    const lp = Array.isArray(vault.toolDock?.launchpad) ? vault.toolDock.launchpad : (vault.toolDock?.tools || []);
    return lp.length;
  }
  if (['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(spaceId)) {
    const cards = (vault.pitchEngine?.cards || []).filter(c => (c.spaceId || 'residencies') === spaceId).length;
    const notes = vault.items.filter(i => i.parentType === 'space' && i.parentId === spaceId).length;
    return cards + notes;
  }
  if (spaceId === 'gmail') {
    if (!state.gmail?.connected) return '✉';
    const unread = (state.gmail.messages || []).filter(m => m.unread).length;
    return unread > 0 ? unread : (state.gmail.totalInFolder || state.gmail.messages?.length || '✓');
  }
  return vault.items.filter(i => i.parentType === 'space' && i.parentId === spaceId).length;
}

function updateSidebarBoardJumpButton() {
  const jumpBtn = document.getElementById('btnOpenBoardSwitcher');
  const jumpLabel = document.getElementById('sidebarBoardJumpLabel');
  if (!jumpLabel) return;
  if (state.viewType === 'project') {
    const p = vault.projects.find(proj => proj.id === state.activeProjectId);
    jumpLabel.textContent = p ? p.title : 'Jump to Project';
    if (jumpBtn) jumpBtn.classList.add('is-in-project');
  } else {
    jumpLabel.textContent = 'Jump to Project';
    if (jumpBtn) jumpBtn.classList.remove('is-in-project');
  }
}

function getSpaceTopBarTitle(spaceId) {
  if (vault?.customTopBarTitles && typeof vault.customTopBarTitles[spaceId] === 'string' && vault.customTopBarTitles[spaceId].trim()) {
    return vault.customTopBarTitles[spaceId].trim();
  }
  if (vault?.customization?.topBarTitles && typeof vault.customization.topBarTitles[spaceId] === 'string' && vault.customization.topBarTitles[spaceId].trim()) {
    return vault.customization.topBarTitles[spaceId].trim();
  }
  try {
    const raw = localStorage.getItem('ideal_custom_topbar_titles');
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed[spaceId] === 'string' && parsed[spaceId].trim()) {
        vault.customTopBarTitles = vault.customTopBarTitles || {};
        vault.customTopBarTitles[spaceId] = parsed[spaceId].trim();
        return parsed[spaceId].trim();
      }
    }
  } catch (e) {}
  const sp = vault?.spaces?.find(s => s.id === spaceId);
  if (spaceId === 'lightbox') {
    return sp?.heading || 'The Lightbox — Curation, Comparison & Routing Hub';
  }
  return sp?.heading || sp?.title || '';
}

function setSpaceTopBarTitle(spaceId, title) {
  const clean = (title || '').trim();
  const sp = vault?.spaces?.find(s => s.id === spaceId);
  const fallback = (spaceId === 'lightbox') ? 'The Lightbox — Curation, Comparison & Routing Hub' : (sp?.title || '');
  const finalTitle = clean || fallback;
  if (sp) {
    sp.heading = finalTitle;
  }
  vault.customTopBarTitles = vault.customTopBarTitles || {};
  vault.customTopBarTitles[spaceId] = finalTitle;
  vault.customization = vault.customization || {};
  vault.customization.topBarTitles = vault.customization.topBarTitles || {};
  vault.customization.topBarTitles[spaceId] = finalTitle;
  try {
    localStorage.setItem('ideal_custom_topbar_titles', JSON.stringify(vault.customTopBarTitles));
  } catch (e) {}
  return finalTitle;
}

function renderSidebar() {
  const brandTitle = document.getElementById('sidebarBrandTitle') || document.getElementById('sidebarBrandName');
  const brandBadge = document.getElementById('sidebarBrandBadge');
  const tagline = document.getElementById('sidebarTagline');

  if (brandTitle) {
    brandTitle.textContent = vault.brand?.title || 'IDEAL';
    brandTitle.title = 'Click to return to Studio Projects • Double-click to rename';
  }
  if (brandBadge) brandBadge.textContent = vault.brand?.badge || 'STUDIO VAULT';
  if (tagline) tagline.textContent = vault.brand?.tagline || 'Visual Archive • Original Quality';

  vault.customization = vault.customization || {};
  vault.customization.worldTitles = vault.customization.worldTitles || {};
  renumberSidebarSpaces(vault.spaces);

  const nav = document.getElementById('sidebarNav');
  if (nav) {
    nav.innerHTML = '';
    let lastWorld = null;
    let draggedSpaceId = null;
    let draggedWorld = null;

    const clearDropIndicators = () => {
      nav.querySelectorAll('.sidebar-item-btn').forEach(el => {
        el.classList.remove('drop-before', 'drop-after');
      });
    };

    vault.spaces.forEach(sp => {
      const worldKey = sp.world || '';
      if (worldKey && worldKey !== lastWorld) {
        lastWorld = worldKey;
        if (worldKey === 'Customize') {
          const sep = document.createElement('div');
          sep.className = 'sidebar-world-sep';
          nav.appendChild(sep);
        } else {
          const hdr = document.createElement('div');
          hdr.className = 'sidebar-world-header';
          const customWorldTitle = vault.customWorldTitles?.[worldKey] || vault.customization?.worldTitles?.[worldKey] || worldKey;
          hdr.textContent = customWorldTitle;
          hdr.title = 'Double-click to rename headline';
          hdr.addEventListener('dblclick', (e) => {
            e.stopPropagation();
            promptInlineRename(hdr, customWorldTitle, (newVal) => {
              const trimmed = newVal.trim();
              if (trimmed) {
                vault.customization = vault.customization || {};
                vault.customization.worldTitles = vault.customization.worldTitles || {};
                vault.customWorldTitles = vault.customWorldTitles || {};
                vault.customization.worldTitles[worldKey] = trimmed;
                vault.customWorldTitles[worldKey] = trimmed;
                try {
                  localStorage.setItem('ideal_custom_world_titles', JSON.stringify(vault.customWorldTitles));
                } catch (e) {}
                saveVault('SAVED WORLD HEADER: ' + trimmed);
                renderSidebar();
              }
            });
          });
          nav.appendChild(hdr);
        }
      }

      const btn = document.createElement('button');
      btn.type = 'button';
      btn.dataset.spaceId = sp.id;
      btn.dataset.world = worldKey;
      btn.draggable = true;
      const isActive = state.viewType === 'space' && state.activeSpaceId === sp.id;
      btn.className = 'sidebar-item-btn' + (isActive ? ' active' : '');
      btn.title = 'Click to open • Double-click to rename • Drag to reorder';

      const isLabOrUtility =
        sp.id === 'customize' ||
        worldKey === 'II. Lab & Assets' ||
        ['gdrive_assets', 'tool_dock', 'gmail'].includes(sp.id);
      const showCountPill = !isLabOrUtility;
      const count = showCountPill ? getSpaceCount(sp.id) : '';

      btn.innerHTML = `
        <span class="sidebar-item-left">
          <span class="sidebar-code">${escapeHtml(sp.code)}</span>
          <span class="sidebar-label">${escapeHtml(sp.title)}</span>
        </span>
        ${showCountPill ? `<span class="sidebar-right-meta"><span class="sidebar-count-pill">${escapeHtml(String(count))}</span></span>` : ''}
      `;

      const triggerRenameSpace = (e) => {
        e.stopPropagation();
        const labelSpan = btn.querySelector('.sidebar-label');
        if (!labelSpan) return;
        btn.draggable = false;
        promptInlineRename(labelSpan, sp.title, (newVal) => {
          btn.draggable = true;
          const clean = (newVal || '').trim();
          if (clean) {
            sp.title = clean;
            vault.customSpaceTitles = vault.customSpaceTitles || {};
            vault.customSpaceTitles[sp.id] = clean;
            try {
              localStorage.setItem('ideal_custom_space_titles', JSON.stringify(vault.customSpaceTitles));
            } catch (e) {}
            saveVault('RENAMED TAB: ' + clean.toUpperCase());
            renderSidebar();
            renderHeaderAndToolbar();
            if (state.viewType === 'space' && state.activeSpaceId === 'customize') {
              renderWorkspace();
            }
            showStatusToast('✓ Renamed tab to: ' + clean);
          }
        });
        const activeInput = labelSpan.querySelector('.inline-rename-field');
        if (activeInput) {
          activeInput.addEventListener('blur', () => { btn.draggable = true; }, { once: true });
        }
      };

      btn.addEventListener('dblclick', (e) => {
        if (e.target.closest('.sidebar-code')) {
          e.stopPropagation();
          const codeSpan = btn.querySelector('.sidebar-code');
          btn.draggable = false;
          promptInlineRename(codeSpan, sp.code, (newVal) => {
            btn.draggable = true;
            const clean = (newVal || '').trim();
            if (clean) {
              sp.code = clean;
              vault.customSpaceCodes = vault.customSpaceCodes || {};
              vault.customSpaceCodes[sp.id] = clean;
              try {
                localStorage.setItem('ideal_custom_space_codes', JSON.stringify(vault.customSpaceCodes));
              } catch (e) {}
              saveVault('UPDATED CODE');
              renderSidebar();
              renderHeaderAndToolbar();
              if (state.viewType === 'space' && state.activeSpaceId === 'customize') {
                renderWorkspace();
              }
              showStatusToast('✓ Updated code to: ' + clean);
            }
          });
          const activeInput = codeSpan?.querySelector('.inline-rename-field');
          if (activeInput) {
            activeInput.addEventListener('blur', () => { btn.draggable = true; }, { once: true });
          }
          return;
        }
        triggerRenameSpace(e);
      });

      // Drag-and-drop reordering within section with automatic sequential renumbering
      btn.addEventListener('dragstart', (e) => {
        if (btn.querySelector('.inline-rename-field')) {
          e.preventDefault();
          return;
        }
        draggedSpaceId = sp.id;
        draggedWorld = worldKey;
        btn.classList.add('is-dragging');
        if (e.dataTransfer) {
          e.dataTransfer.effectAllowed = 'move';
          try { e.dataTransfer.setData('text/plain', sp.id); } catch (_) {}
        }
      });

      btn.addEventListener('dragover', (e) => {
        if (!draggedSpaceId || draggedSpaceId === sp.id) return;
        if (draggedWorld !== worldKey) return;
        e.preventDefault();
        if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
        clearDropIndicators();
        const rect = btn.getBoundingClientRect();
        const isAfter = (e.clientY - rect.top) > rect.height / 2;
        btn.classList.add(isAfter ? 'drop-after' : 'drop-before');
      });

      btn.addEventListener('dragleave', () => {
        btn.classList.remove('drop-before', 'drop-after');
      });

      btn.addEventListener('drop', (e) => {
        if (!draggedSpaceId || draggedSpaceId === sp.id || draggedWorld !== worldKey) return;
        e.preventDefault();
        const rect = btn.getBoundingClientRect();
        const insertAfter = (e.clientY - rect.top) > rect.height / 2;
        clearDropIndicators();

        const fromIdx = vault.spaces.findIndex(s => s.id === draggedSpaceId);
        if (fromIdx === -1) return;
        const [movedSp] = vault.spaces.splice(fromIdx, 1);
        let toIdx = vault.spaces.findIndex(s => s.id === sp.id);
        if (toIdx === -1) {
          vault.spaces.splice(fromIdx, 0, movedSp);
          return;
        }
        if (insertAfter) toIdx += 1;
        vault.spaces.splice(toIdx, 0, movedSp);

        renumberSidebarSpaces(vault.spaces);
        vault.customization = vault.customization || {};
        vault.customization.spacesOrder = vault.spaces.map(s => s.id);
        saveVault('REORDERED SIDEBAR');
        try {
          localStorage.setItem('ideal_gdrive_assets_cache', JSON.stringify({
            batches: state.gdriveBatches,
            enclosingFolders: state.gdriveEnclosingFolders,
            categoryLinks: state.gdriveCategoryLinks,
            totalBatches: state.gdriveStats.totalBatches,
            totalFiles: state.gdriveStats.totalFiles,
            driveRoot: state.gdriveStats.driveRoot
          }));
        } catch (e) {}
        renderSidebar();
        renderHeaderAndToolbar();
        if (state.viewType === 'space' && state.activeSpaceId === 'customize') {
          renderWorkspace();
        }
      });

      btn.addEventListener('dragend', () => {
        draggedSpaceId = null;
        draggedWorld = null;
        btn.classList.remove('is-dragging');
        clearDropIndicators();
      });

      btn.addEventListener('click', (e) => {
        if (e.target.closest('.inline-rename-field')) return;
        if (e.detail > 1) return;
        if (state.viewType === 'space' && state.activeSpaceId === sp.id) {
          if (sp.id === 'instagram' && state.activeFolderId) {
            state.activeFolderId = null;
            renderHeaderAndToolbar();
            renderFilterActionRow();
            renderWorkspace();
          }
          if (sp.id === 'gdrive_assets') {
            state.activeGDriveEnclosingFolder = null;
            state.activeGDriveBatchId = null;
            state.activeCategory = 'All';
            saveNavState();
            renderHeaderAndToolbar();
            renderFilterActionRow();
            renderWorkspace();
          }
          return;
        }
        guardLeaveCustomize(() => {
          if (sp.id === 'customize') {
            state.custSavedSnapshot = captureCustomizationSnapshot(vault);
            state.custDirty = false;
          }
          state.viewType = 'space';
          state.activeSpaceId = sp.id;
          state.activeProjectId = null;
          state.activeLeadId = null;
          if (sp.id === 'instagram') state.activeFolderId = null;
          if (sp.id === 'gdrive_assets') {
            state.activeGDriveBatchId = null;
            state.activeGDriveEnclosingFolder = null;
          }
          state.activeCategory = (sp.categories && sp.categories[0]) || 'All';
          state.sphereActiveIndex = 0;
          state.sphereLockedNodeId = null;
          state.sphereZoom = 1;
          state.spherePanX = 0;
          state.spherePanY = 0;
          applyCustomizationToDOM();
          nav.querySelectorAll('.sidebar-item-btn').forEach(b => {
            b.classList.toggle('active', b.dataset.spaceId === sp.id);
          });
          updateSidebarBoardJumpButton();
          renderHeaderAndToolbar();
          renderFilterActionRow();
          renderSectionDesignDrawer();
          renderWorkspace();
          renderCompareFloatingBar();
          saveNavState();
        });
      });

      nav.appendChild(btn);
    });
  }

  updateSidebarBoardJumpButton();
}

/* ==========================================================================
   INSTANT ⌘K PROJECT BOARD SWITCHER (SCALES TO 800+ BOARDS)
   ========================================================================== */
function openBoardSwitcherModal() {
  const dlg = document.getElementById('boardSwitcherDialog');
  const inp = document.getElementById('boardSwitcherInput');
  if (!dlg) return;
  const curIdx = state.viewType === 'project'
    ? getBoardSwitcherOrderedProjects().findIndex(e => e.proj.id === state.activeProjectId)
    : 0;
  state.boardSwitcherActiveIdx = curIdx >= 0 ? curIdx : 0;
  if (inp) inp.value = '';
  renderBoardSwitcherList('');
  if (!dlg.open) dlg.showModal();
  if (inp) {
    setTimeout(() => inp.focus(), 15);
  }
}

// ⌘K order: Open projects first, then Finished (canonical numbering across all views)
function getBoardSwitcherOrderedProjects() {
  const all = (vault.projects || []).map((proj, idx) => ({ proj, idx }));
  return [
    ...all.filter(e => e.proj.lifecycleState !== 'delivered'),
    ...all.filter(e => e.proj.lifecycleState === 'delivered')
  ];
}

function getProjectDisplayNumber(projOrId) {
  const id = typeof projOrId === 'string' ? projOrId : projOrId?.id;
  const ordered = getBoardSwitcherOrderedProjects();
  const pos = ordered.findIndex(e => e.proj.id === id);
  const num = pos >= 0 ? (pos + 1) : 1;
  return String(num).padStart(2, '0');
}

function renderBoardSwitcherList(rawQuery) {
  const listEl = document.getElementById('boardSwitcherList');
  const footerCountEl = document.getElementById('boardSwitcherFooterCount');
  const dlg = document.getElementById('boardSwitcherDialog');
  if (!listEl) return;
  const q = (rawQuery || '').trim().toLowerCase();

  const matches = [];
  getBoardSwitcherOrderedProjects().forEach(({ proj, idx }, orderPos) => {
    const numCode = String(orderPos + 1).padStart(2, '0');
    if (q) {
      const hay = `#${numCode} ${numCode} ${proj.title || ''} ${proj.category || ''} ${proj.subtitle || ''} ${proj.status || ''}`.toLowerCase();
      if (!hay.includes(q)) return;
    }
    const itemCount = (vault.items || []).filter(i => i.parentType === 'project' && i.parentId === proj.id).length;
    matches.push({ proj, idx, numCode, itemCount });
  });

  if (footerCountEl) {
    const total = vault.projects.length;
    footerCountEl.textContent = q
      ? `${matches.length} of ${total} Project Boards`
      : `${total} Project Board${total === 1 ? '' : 's'}`;
  }

  if (typeof state.boardSwitcherActiveIdx !== 'number' || state.boardSwitcherActiveIdx >= matches.length || state.boardSwitcherActiveIdx < 0) {
    state.boardSwitcherActiveIdx = 0;
  }

  const visible = matches.slice(0, 80);
  if (visible.length === 0) {
    listEl.innerHTML = `<div class="board-switcher-empty">No matching project boards found · Click <strong>+ Project Board</strong> to create one</div>`;
    return;
  }

  listEl.innerHTML = visible.map((m, vIdx) => {
    const isAct = vIdx === state.boardSwitcherActiveIdx;
    const isCur = state.viewType === 'project' && state.activeProjectId === m.proj.id;
    const catText = m.proj.category || 'Studio Board';
    return `
      <button type="button" role="option" aria-selected="${isAct ? 'true' : 'false'}" class="board-switcher-row ${isAct ? 'is-focused' : ''} ${isCur ? 'is-current' : ''}" data-proj-id="${escapeHtml(m.proj.id)}" data-row-idx="${vIdx}">
        <span class="bs-row-left">
          <span class="bs-code">${m.numCode}</span>
          <span class="bs-title">${escapeHtml(m.proj.title)}</span>
          ${isCur ? `<span class="bs-current-pill">Current</span>` : ''}
          ${m.proj.lifecycleState === 'delivered' ? `<span class="bs-current-pill bs-finished-pill">Finished</span>` : ''}
        </span>
        <span class="bs-row-right">
          <span class="bs-cat">${escapeHtml(catText)}</span>
          <span class="bs-count">${m.itemCount}</span>
        </span>
      </button>
    `;
  }).join('');

  listEl.querySelectorAll('.board-switcher-row').forEach(btn => {
    btn.addEventListener('pointerenter', () => {
      const idx = parseInt(btn.dataset.rowIdx, 10);
      if (!Number.isNaN(idx) && state.boardSwitcherActiveIdx !== idx) {
        state.boardSwitcherActiveIdx = idx;
        listEl.querySelectorAll('.board-switcher-row').forEach((r, i) => {
          r.classList.toggle('is-focused', i === idx);
          r.setAttribute('aria-selected', i === idx ? 'true' : 'false');
        });
      }
    });
    btn.addEventListener('click', () => {
      const pid = btn.dataset.projId;
      dlg?.close();
      openProjectBoard(pid);
    });
  });
}

const MILANOTE_GRID_SIZE = 24;

function snapCoord(val, disableSnap = false) {
  if (disableSnap || state.snapToGrid === false) return Math.round(val);
  return Math.round(val / MILANOTE_GRID_SIZE) * MILANOTE_GRID_SIZE;
}

function getActiveBoardCamera() {
  const { type, obj } = getActiveContainer();
  const ui = (obj && obj.ui) ? obj.ui : {};
  if (type === 'space' && obj && obj.id === 'projects') {
    if (typeof ui.cameraZoom !== 'number') ui.cameraZoom = state.overviewZoom || 1;
    if (typeof ui.cameraPanX !== 'number') ui.cameraPanX = state.overviewPanX || 0;
    if (typeof ui.cameraPanY !== 'number') ui.cameraPanY = state.overviewPanY || 0;
    return {
      get zoom() { return ui.cameraZoom; },
      set zoom(v) { ui.cameraZoom = v; state.overviewZoom = v; },
      get panX() { return ui.cameraPanX; },
      set panX(v) { ui.cameraPanX = v; state.overviewPanX = v; },
      get panY() { return ui.cameraPanY; },
      set panY(v) { ui.cameraPanY = v; state.overviewPanY = v; }
    };
  }
  if (typeof ui.cameraZoom !== 'number') ui.cameraZoom = (typeof state.giantWallZoom === 'number' && state.giantWallZoom > 0) ? state.giantWallZoom : 1;
  if (typeof ui.cameraPanX !== 'number') ui.cameraPanX = state.giantWallPanX || 0;
  if (typeof ui.cameraPanY !== 'number') ui.cameraPanY = state.giantWallPanY || 0;
  return {
    get zoom() { return ui.cameraZoom; },
    set zoom(v) { ui.cameraZoom = v; state.giantWallZoom = v; },
    get panX() { return ui.cameraPanX; },
    set panX(v) { ui.cameraPanX = v; state.giantWallPanX = v; },
    get panY() { return ui.cameraPanY; },
    set panY(v) { ui.cameraPanY = v; state.giantWallPanY = v; }
  };
}

let cameraSaveTimer = null;
function saveCameraStateDebounced() {
  clearTimeout(cameraSaveTimer);
  cameraSaveTimer = setTimeout(() => {
    saveVault('SAVED CAMERA');
  }, 400);
}

function applyActiveBoardCameraTransform() {
  const plane = document.getElementById('giantWallPlane');
  const cam = getActiveBoardCamera();
  if (plane) {
    plane.style.transform = `translate3d(${cam.panX.toFixed(1)}px, ${cam.panY.toFixed(1)}px, 0) scale(${cam.zoom.toFixed(3)})`;
  }
  const resetBtn = document.getElementById('btnResetWallCamera');
  if (resetBtn) {
    resetBtn.textContent = `${Math.round(cam.zoom * 100)}%`;
  }
  const { obj } = getActiveContainer();
  if (obj && obj.ui && obj.ui.layoutMode === 'giant_wall') {
    obj.ui.cameraZoom = cam.zoom;
    obj.ui.cameraPanX = cam.panX;
    obj.ui.cameraPanY = cam.panY;
    saveCameraStateDebounced();
  }
}

/* ==========================================================================
   SINGLE-ROW HEADER, FILTER PILLS & PER-SECTION UI DRAWER
   ========================================================================== */
function renderHeaderAndToolbar() {
  const { type, obj } = getActiveContainer();
  const ui = obj.ui || (obj.ui = {});
  const isMovingForward = (type === 'space' && ['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(obj.id));

  // Enforce strict Eagle-only on Drive & PSD Assets, Vertical/Horizontal only on Moving Forward, and remove Eagle/Vertical/Horizontal from other sections
  if (type === 'space' && obj.id === 'gdrive_assets') {
    ui.layoutMode = 'eagle';
  } else if (isMovingForward) {
    if (ui.layoutMode !== 'vertical' && ui.layoutMode !== 'horizontal') {
      ui.layoutMode = 'vertical';
    }
  } else if (ui.layoutMode === 'eagle' || ui.layoutMode === 'vertical' || ui.layoutMode === 'horizontal') {
    ui.layoutMode = (type === 'project') ? 'giant_wall' : 'wall';
  }

  const codeEl = document.getElementById('menuCurrentCode');
  const backBtn = document.getElementById('btnBackToProjects');
  if (typeof updateNavHistoryButtons === 'function') updateNavHistoryButtons();
  const crumbEl = document.getElementById('boardBreadcrumbTrail');
  const titleEl = document.getElementById('viewTitle');
  const mainStage = document.getElementById('mainStage');
  const railEl = document.getElementById('milanoteToolRail');
  const hudViewModeGroup = document.getElementById('hudViewModeGroup');
  const btnViewSphere = document.getElementById('btnViewSphere');

  if (type === 'project') {
    const codeStr = '#' + getProjectDisplayNumber(obj);
    if (codeEl) codeEl.textContent = codeStr;
    if (backBtn) backBtn.hidden = false;

    // Build folder breadcrumb chain if inside a nested Board / Folder
    const folderChain = [];
    let curFolderId = state.activeFolderId || null;
    const seen = new Set();
    while (curFolderId && !seen.has(curFolderId)) {
      seen.add(curFolderId);
      const fItem = vault.items.find(i => i.id === curFolderId);
      if (!fItem) break;
      folderChain.unshift(fItem);
      curFolderId = fItem.folderId || null;
    }

    if (crumbEl) {
      crumbEl.hidden = false;
      let html = `<button type="button" class="crumb-link" data-crumb-action="projects">Projects</button><span class="crumb-sep">/</span>`;
      if (folderChain.length > 0) {
        html += `<button type="button" class="crumb-link crumb-folder-drop" data-crumb-action="root-project" data-crumb-folder="" data-folder-drop="">${escapeHtml(obj.title)}</button><span class="crumb-sep">/</span>`;
        folderChain.slice(0, -1).forEach(f => {
          html += `<button type="button" class="crumb-link crumb-folder-drop" data-crumb-folder="${escapeHtml(f.id)}" data-folder-drop="${escapeHtml(f.id)}">${escapeHtml(f.title)}</button><span class="crumb-sep">/</span>`;
        });
      }
      crumbEl.innerHTML = html;
      crumbEl.querySelectorAll('.crumb-link').forEach(btn => {
        btn.addEventListener('click', () => {
          if (btn.dataset.crumbAction === 'projects') {
            state.activeFolderId = null;
            state.viewType = 'space';
            state.activeSpaceId = 'projects';
            state.activeProjectId = null;
            renderAll();
          } else if (btn.dataset.crumbAction === 'root-project') {
            state.activeFolderId = null;
            state.giantWallPanX = 0;
            state.giantWallPanY = 0;
            renderAll();
          } else if (btn.dataset.crumbFolder) {
            state.activeFolderId = btn.dataset.crumbFolder;
            state.giantWallPanX = 0;
            state.giantWallPanY = 0;
            renderAll();
          }
        });
      });
    }

    if (titleEl) {
      const activeFolder = folderChain.length > 0 ? folderChain[folderChain.length - 1] : null;
      titleEl.textContent = activeFolder ? activeFolder.title : obj.title;
    }
  } else if (type === 'space' && ['projects', 'incubator'].includes(obj.id) && state.activeFolderId) {
    const folderChain = [];
    let curFolderId = state.activeFolderId || null;
    const seen = new Set();
    while (curFolderId && !seen.has(curFolderId)) {
      seen.add(curFolderId);
      const fItem = vault.items.find(i => i.id === curFolderId);
      if (!fItem) break;
      folderChain.unshift(fItem);
      curFolderId = fItem.folderId || null;
    }

    if (folderChain.length === 0) {
      state.activeFolderId = null;
      const fallbackCode = obj.code || '01';
      if (codeEl) codeEl.textContent = fallbackCode;
      if (backBtn) backBtn.hidden = true;
      if (crumbEl) {
        crumbEl.hidden = true;
        crumbEl.innerHTML = '';
      }
      if (titleEl) {
        titleEl.textContent = obj.title;
        titleEl.style.cursor = '';
        titleEl.title = 'Click or double-click to rename';
        titleEl.classList.remove('active');
      }
    } else {
      const fallbackCode = obj.code || '01';
      if (codeEl) codeEl.textContent = fallbackCode;
      if (backBtn) backBtn.hidden = false;
      if (crumbEl) {
        crumbEl.hidden = false;
        let html = `<button type="button" class="crumb-link crumb-folder-drop" data-crumb-action="root-space" data-crumb-folder="" data-folder-drop="">${escapeHtml(obj.title)}</button><span class="crumb-sep">/</span>`;
        folderChain.slice(0, -1).forEach(f => {
          html += `<button type="button" class="crumb-link crumb-folder-drop" data-crumb-folder="${escapeHtml(f.id)}" data-folder-drop="${escapeHtml(f.id)}">${escapeHtml(f.title)}</button><span class="crumb-sep">/</span>`;
        });
        crumbEl.innerHTML = html;
        crumbEl.querySelectorAll('.crumb-link').forEach(btn => {
          btn.addEventListener('click', () => {
            if (btn.dataset.crumbAction === 'root-space') {
              state.activeFolderId = null;
              state.giantWallPanX = 0;
              state.giantWallPanY = 0;
              renderAll();
            } else if (btn.dataset.crumbFolder) {
              state.activeFolderId = btn.dataset.crumbFolder;
              state.giantWallPanX = 0;
              state.giantWallPanY = 0;
              renderAll();
            }
          });
        });
      }
      if (titleEl) {
        titleEl.textContent = folderChain[folderChain.length - 1].title;
      }
    }
  } else {
    state.activeFolderId = null;
    const fallbackCode = obj.code || '01';
    if (codeEl) codeEl.textContent = fallbackCode;
    if (backBtn) backBtn.hidden = true;
    if (crumbEl) {
      crumbEl.hidden = true;
      crumbEl.innerHTML = '';
    }
    if (titleEl) {
      if (type === 'space' && obj.id === 'gdrive_assets') {
        const gTitle = getSpaceTopBarTitle('gdrive_assets') || 'Assets & Vaults';
        titleEl.textContent = gTitle;
        titleEl.style.cursor = 'pointer';
        titleEl.title = 'Click to return to Assets & Vaults Dashboard';
        const isDashboardActive = !state.activeGDriveEnclosingFolder || state.activeCategory === 'All';
        titleEl.classList.toggle('active', isDashboardActive);
      } else if (type === 'space' && obj.id === 'lightbox') {
        const lbTitle = getSpaceTopBarTitle('lightbox');
        titleEl.textContent = lbTitle;
        titleEl.style.cursor = 'default';
        titleEl.title = lbTitle;
        titleEl.classList.remove('active');
      } else {
        const topTitle = (type === 'space') ? getSpaceTopBarTitle(obj.id) : obj.title;
        titleEl.textContent = topTitle;
        titleEl.style.cursor = '';
        titleEl.title = 'Click or double-click to rename';
        titleEl.classList.remove('active');
      }
    }
  }

  const mode = ui.layoutMode || (isMovingForward ? 'vertical' : 'wall');

  // Hide view switcher group on Lightbox, Drive & PSD Assets (Eagle-only), Tool Dock, Gmail, and Customize
  if (hudViewModeGroup) {
    hudViewModeGroup.hidden = (type === 'space' && ['lightbox', 'gdrive_assets', 'tool_dock', 'gmail', 'customize'].includes(obj.id));
  }

  // Show ONLY Vertical & Horizontal view buttons in Moving Forward; show standard view buttons elsewhere
  ['btnViewGiantWall', 'btnViewWall', 'btnViewList', 'btnViewKanban'].forEach(id => {
    const b = document.getElementById(id);
    if (b) {
      b.hidden = isMovingForward;
      b.classList.toggle('active', !isMovingForward && b.dataset.mode === mode);
    }
  });
  if (btnViewSphere) {
    btnViewSphere.hidden = true;
  }
  ['btnViewMfVertical', 'btnViewMfHorizontal'].forEach(id => {
    const b = document.getElementById(id);
    if (b) {
      b.hidden = !isMovingForward;
      b.classList.toggle('active', isMovingForward && b.dataset.mode === mode);
    }
  });

  // Milanote Creation Rail (on the Right): strictly locked on all Creative Studio spaces (Studio Projects, Idea Incubator, Project Boards)
  const showMilanoteRail = (
    type === 'project' ||
    (type === 'space' && ['projects', 'incubator'].includes(obj.id))
  );
  if (railEl) {
    railEl.hidden = !showMilanoteRail;
  }
  if (!showMilanoteRail) {
    const morePop = document.getElementById('milanoteMorePopover');
    if (morePop) morePop.hidden = true;
  }
  const appShellEl = document.getElementById('appShell');
  if (appShellEl) {
    appShellEl.classList.toggle('has-milanote-rail', showMilanoteRail);
  }

  const isSpatialBoard = (
    mode === 'sphere' ||
    (type === 'project' && (mode === 'wall' || mode === 'giant_wall')) ||
    (type === 'space' && (obj.id === 'projects' || obj.id === 'incubator') && (mode === 'wall' || mode === 'giant_wall' || mode === 'sphere')) ||
    mode === 'giant_wall'
  );
  if (mainStage) {
    mainStage.classList.toggle('is-canvas-mode', isSpatialBoard);
  }

  // Sync HUD Scale / Zoom Slider (5 Snappy Steps across supported views)
  const isGiantWall = (mode === 'giant_wall');
  const isCustomizeSpace = (type === 'space' && obj.id === 'customize');
  const hudDensityPill = document.getElementById('hudDensityPill');
  if (hudDensityPill) {
    hudDensityPill.hidden = isGiantWall || isCustomizeSpace;
  }
  const sizeSlider = document.getElementById('sizeSlider');
  if (sizeSlider) {
    sizeSlider.min = "1";
    sizeSlider.max = "5";
    sizeSlider.step = "1";
    const { step } = getContainerScaleContext(type, obj);
    sizeSlider.value = String(step);
  }

  // Hide + Upload / + Note / + Link on 04 Drive & PSD Assets; hide + Note / + Link on Lightbox
  const isGDriveAssets = (type === 'space' && obj.id === 'gdrive_assets');
  const isToolDockSpace = (type === 'space' && obj.id === 'tool_dock');
  const isLightboxSpace = (type === 'space' && obj.id === 'lightbox');
  const isStudioProjectsArea = (type === 'project' || (type === 'space' && obj.id === 'projects'));
  const btnToggleSidebar = document.getElementById('btnToggleSidebar');
  if (btnToggleSidebar) btnToggleSidebar.hidden = isGDriveAssets;
  document.body.classList.toggle('is-gdrive-space', isGDriveAssets);
  const hudUploadEl = document.getElementById('btnHudUpload');
  const hudActionsPill = document.querySelector('.hud-actions-pill');
  const hideHudUpload = isGDriveAssets || isToolDockSpace || isStudioProjectsArea || isCustomizeSpace || isLightboxSpace;
  if (hudUploadEl) hudUploadEl.hidden = hideHudUpload;
  if (hudActionsPill) hudActionsPill.hidden = hideHudUpload;
  const sidebarUploadEl = document.getElementById('btnSidebarUpload');
  if (sidebarUploadEl) sidebarUploadEl.hidden = isGDriveAssets || isToolDockSpace;
  ['btnHudNote', 'btnHudLink', 'btnSidebarQuickNote', 'btnSidebarQuickLink'].forEach(btnId => {
    const el = document.getElementById(btnId);
    if (el) el.hidden = isGDriveAssets || isLightboxSpace || (type === 'space' && obj.id === 'projects');
  });
  // Scope flag so Studio Projects (front page + boards) hides IG / Site status badges
  document.body.classList.toggle('in-studio-projects', isStudioProjectsArea);
  const hudNoteBtn = document.getElementById('btnHudNote');
  if (hudNoteBtn) {
    hudNoteBtn.textContent = isToolDockSpace ? '+ Add R&D / Wishlist Item' : '+ Sticky Note / Checklist';
  }
  const hudLinkBtn = document.getElementById('btnHudLink');
  if (hudLinkBtn) {
    hudLinkBtn.textContent = isToolDockSpace ? '+ Add Useful Link' : '+ Web Link / Local Path';
  }
  if (isGDriveAssets || isToolDockSpace || isLightboxSpace) {
    const compBar = document.getElementById('quickComposerBar');
    if (compBar) compBar.hidden = true;
  }

  // Sync IG Status Filter Pill (hidden on Studio Projects & Project Boards)
  const igFilterBar = document.getElementById('igStatusFilterBar');
  const showIgFilter = (
    type === 'space' && ['incubator'].includes(obj.id)
  );
  if (igFilterBar) {
    igFilterBar.hidden = !showIgFilter;
    if (!showIgFilter && state.igStatusFilter && state.igStatusFilter !== 'all') {
      state.igStatusFilter = 'all';
    }
    igFilterBar.querySelectorAll('.ig-filter-btn').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.igFilter === (state.igStatusFilter || 'all'));
    });
  }

  const btnSectionDesign = document.getElementById('btnSectionDesign');
  if (btnSectionDesign) btnSectionDesign.classList.toggle('active', state.sectionDrawerOpen);

  const btnTheme = document.getElementById('btnThemeToggle');
  if (btnTheme) {
    const preset = (vault.customization && vault.customization.themePreset) ? vault.customization.themePreset : 'warm_gallery';
    const isDark = preset.includes('dark') || preset.includes('oled');
    btnTheme.textContent = isDark ? '☀ Switch to Light Theme' : '☾ Switch to Dark Theme';
  }
}

function renderFilterActionRow() {
  const row = document.getElementById('filterActionRow');
  if (!row) return;

  const { type, obj } = getActiveContainer();

  // Hide filter bar on 09 Customize view
  if (type === 'space' && obj.id === 'customize') {
    row.innerHTML = '';
    row.style.display = 'none';
    return;
  }
  row.style.display = 'inline-flex';

  const isGDriveAssets = type === 'space' && obj.id === 'gdrive_assets';
  const isGmailSpace = type === 'space' && obj.id === 'gmail';
  const isLightboxSpace = type === 'space' && obj.id === 'lightbox';
  const isProjectsSpace = type === 'space' && obj.id === 'projects';
  const isProjectBoard = type === 'project';

  let list = type === 'project' ? (obj.sections = obj.sections || ['All']) : (obj.categories = obj.categories || ['All']);
  const LIGHTBOX_SHORT_LABELS = {
    'Portfolio Staging': 'The Website Room',
    'Instagram Board': 'The Instagram Room'
  };
  if (isLightboxSpace) {
    list = ['Portfolio Staging', 'Instagram Board'];
    obj.categories = list;
    if (!list.includes(state.lightboxFilter)) {
      state.lightboxFilter = 'Instagram Board';
    }
    state.activeCategory = state.lightboxFilter;
  }
  if (isGDriveAssets) {
    list = list.filter(c => c !== 'All' && c !== 'All Asset Batches');
  }
  if (!isGDriveAssets && !isLightboxSpace && !list.includes(state.activeCategory)) {
    state.activeCategory = list[0] || 'All';
  }

  const pillsHtml = list.map((cat, idx) => {
    const count = getCategoryCount(type, obj, cat, idx === 0);
    const isActive = isLightboxSpace ? (state.lightboxFilter === cat) : (state.activeCategory === cat);
    const shortCat = isLightboxSpace
      ? (LIGHTBOX_SHORT_LABELS[cat] || cat)
      : cat
          .replace(/^All\s+.*/, 'All')
          .replace('VJ & Club Visuals', 'VJ')
          .replace('3D & Motion', '3D')
          .replace('Graphic Design', 'Design');
    const canDeleteTab = idx > 0 && !isGDriveAssets && !isGmailSpace && !isLightboxSpace;
    const showCountSpan = isLightboxSpace ? (Number(count) > 0) : !(isGmailSpace && count === '');
    const ariaPressedAttr = isLightboxSpace ? ` aria-pressed="${isActive ? 'true' : 'false'}"` : '';
    return `
      <button type="button" class="filter-pill ${isActive ? 'active' : ''}" data-cat="${escapeHtml(cat)}"${ariaPressedAttr} title="${escapeHtml(cat)}${count !== '' ? ` (${count})` : ''} • Click to switch view">
        <span>${escapeHtml(shortCat)}</span>
        ${showCountSpan ? `<span class="filter-pill-count">${count}</span>` : ''}
        ${canDeleteTab ? `<span class="pill-del-btn" data-del-cat="${escapeHtml(cat)}" title="Delete tab (contents stay safe as Untagged)">×</span>` : ''}
      </button>
    `;
  }).join('');

  const openCount = isProjectsSpace ? vault.projects.filter(p => (p.lifecycleState || 'active') !== 'delivered').length : 0;
  const finishedCount = isProjectsSpace ? vault.projects.filter(p => p.lifecycleState === 'delivered').length : 0;
  const lcFilter = state.projectsLifecycleFilter || 'active';

  const lifecycleInlineHtml = isProjectsSpace ? `
    <div class="projects-lifecycle-switch" role="group" aria-label="Project Status Filter">
      <button type="button" class="lifecycle-seg-btn ${lcFilter !== 'delivered' ? 'active' : ''}" data-lc-mode="active" title="Show Open Projects">
        <span>Open</span>
        <span class="lifecycle-seg-count">${openCount}</span>
      </button>
      <button type="button" class="lifecycle-seg-btn ${lcFilter === 'delivered' ? 'active' : ''}" data-lc-mode="delivered" title="Show Finished Projects">
        <span>Finished</span>
        <span class="lifecycle-seg-count">${finishedCount}</span>
      </button>
    </div>
  ` : '';

  const gdriveLane = isGDriveAssets ? getActiveGDriveLaneInfo(state.activeCategory) : null;

  // Inside a Project Board: quick Category picker (3D / Design / Mixed Media / VJ…)
  let projectCategorySelectHtml = '';
  if (isProjectBoard) {
    const projSpace = vault.spaces.find(s => s.id === 'projects');
    const catOpts = ((projSpace && projSpace.categories) || []).slice(1).filter(Boolean);
    if (obj.category && !catOpts.includes(obj.category)) catOpts.push(obj.category);
    projectCategorySelectHtml = `
      <select class="project-category-select" id="selActiveProjectCategory" title="Project Category" aria-label="Project Category">
        ${catOpts.map(c => `<option value="${escapeHtml(c)}" ${c === obj.category ? 'selected' : ''}>${escapeHtml(c)}</option>`).join('')}
      </select>
    `;
  }
  const gdriveLaneControlsHtml = '';

  row.innerHTML = `
    <div class="pills-scroll-row" id="pillsContainer" style="display:inline-flex;align-items:center;gap:2px;">
      ${lifecycleInlineHtml}
      ${pillsHtml}
      ${(!isGDriveAssets && !isGmailSpace && !isLightboxSpace) ? `<button type="button" class="filter-pill" id="btnAddCategoryTab" title="Add Tab">+</button>` : ''}
      ${isProjectBoard ? `<span class="quiet-sep">·</span><button type="button" class="project-finish-toggle-btn ${obj.lifecycleState === 'delivered' ? 'is-finished' : ''}" id="btnDeliverActiveProjectBoard" title="${obj.lifecycleState === 'delivered' ? 'Finished — Click to move back to Open' : 'Mark project as Finished'}">${obj.lifecycleState === 'delivered' ? '✓ Finished' : 'Mark Finished'}</button>${projectCategorySelectHtml}<button type="button" class="filter-pill" id="btnDeleteActiveProjectBoard" title="Delete Project Board">×</button>` : ''}
      ${gdriveLaneControlsHtml}
    </div>
  `;

  row.querySelectorAll('.lifecycle-seg-btn[data-lc-mode]').forEach(lcBtn => {
    lcBtn.addEventListener('click', () => {
      const nextMode = lcBtn.dataset.lcMode || 'active';
      if (state.projectsLifecycleFilter !== nextMode) {
        state.projectsLifecycleFilter = nextMode;
        renderWorkspace();
        renderFilterActionRow();
      }
    });
  });

  document.getElementById('btnDeliverActiveProjectBoard')?.addEventListener('click', () => {
    deliverProjectAndSpawnShowcase(obj.id);
  });
  document.getElementById('selActiveProjectCategory')?.addEventListener('change', (e) => {
    const nextCat = e.target.value;
    if (!nextCat || nextCat === obj.category) return;
    const oldCat = obj.category;
    obj.category = nextCat;
    obj.tags = (obj.tags || []).filter(t => t !== oldCat);
    if (!obj.tags.includes(nextCat)) obj.tags.unshift(nextCat);
    obj.updatedAt = Date.now();
    saveVault('CATEGORY UPDATED');
  });
  document.getElementById('btnDeleteActiveProjectBoard')?.addEventListener('click', () => {
    requestDelete('project', obj.id, obj.title);
  });

  // Bind non-destructive tab delete (relabels contents as 'Untagged' without deleting any items)
  row.querySelectorAll('.pill-del-btn[data-del-cat]').forEach(delEl => {
    delEl.addEventListener('pointerdown', (e) => e.stopPropagation());
    delEl.addEventListener('dblclick', (e) => e.stopPropagation());
    delEl.addEventListener('click', (e) => {
      e.stopPropagation();
      const catName = delEl.dataset.delCat;
      if (!catName) return;
      const arr = type === 'project' ? (obj.sections = obj.sections || ['All']) : (obj.categories = obj.categories || ['All']);
      const tabIdx = arr.indexOf(catName);
      if (tabIdx <= 0) return; // Never remove the first "All" tab

      arr.splice(tabIdx, 1);
      let retaggedCount = 0;

      if (type === 'project') {
        vault.items.forEach(it => {
          if (it.parentType === 'project' && it.parentId === obj.id && it.section === catName) {
            it.section = 'Untagged';
            retaggedCount++;
          }
        });
      } else if (obj.id === 'projects') {
        vault.projects.forEach(p => {
          if (p.category === catName) {
            p.category = 'Untagged';
            retaggedCount++;
          }
        });
        vault.items.forEach(it => {
          if (it.parentType === 'space' && it.parentId === 'projects' && it.section === catName) {
            it.section = 'Untagged';
            retaggedCount++;
          }
        });
      } else if (obj.id === 'tool_dock') {
        const remainingCats = (obj.categories || []).filter(c => c !== 'All' && !c.startsWith('All ') && c !== catName);
        const fallbackCluster = remainingCats[0] || 'Active Launchpad';
        (vault.toolDock?.launchpad || []).forEach(t => {
          if (t.cluster === catName || t.category === catName) {
            t.cluster = fallbackCluster;
            if (t.category === catName) t.category = fallbackCluster;
            retaggedCount++;
          }
        });
        (vault.toolDock?.rdLab || []).forEach(r => {
          if (r.targetCluster === catName || r.category === catName) {
            r.targetCluster = fallbackCluster;
            if (r.category === catName) r.category = fallbackCluster;
            retaggedCount++;
          }
        });
        (vault.toolDock?.usefulLinks || []).forEach(l => {
          if (l.cluster === catName || l.category === catName) {
            l.cluster = fallbackCluster;
            if (l.category === catName) l.category = fallbackCluster;
            retaggedCount++;
          }
        });
        if (Array.isArray(vault.toolDock?.categories)) {
          vault.toolDock.categories = vault.toolDock.categories.filter(c => c !== catName);
        }
      } else if (['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(obj.id)) {
        (vault.pitchEngine?.cards || []).forEach(c => {
          if ((c.spaceId || 'residencies') === obj.id && (c.category === catName || c.type === catName)) {
            c.category = 'Untagged';
            if (c.type === catName) c.type = 'Untagged';
            retaggedCount++;
          }
        });
        vault.items.forEach(it => {
          if (it.parentType === 'space' && it.parentId === obj.id && it.section === catName) {
            it.section = 'Untagged';
            retaggedCount++;
          }
        });
      } else if (obj.id === 'instagram') {
        getInstagramAllItems().forEach(it => {
          if (it.section === catName || matchesInstagramCategory(it, catName, false)) {
            it.section = 'Untagged';
            if (catName === 'IG Ready' && it.igStatus === 'queued') it.igStatus = '';
            if (catName === 'IG Live' && it.igStatus === 'published') it.igStatus = '';
            retaggedCount++;
          }
        });
      } else {
        vault.items.forEach(it => {
          if (it.parentType === 'space' && it.parentId === obj.id && it.section === catName) {
            it.section = 'Untagged';
            retaggedCount++;
          }
        });
      }

      if (catName !== 'Untagged' && retaggedCount > 0 && !arr.includes('Untagged')) {
        arr.push('Untagged');
      }
      if (state.activeCategory === catName) {
        state.activeCategory = arr[0] || 'All';
      }
      saveVault('TAB REMOVED • ITEMS UNTAGGED');
      renderAll();
    });
  });

  // Bind filter pill clicks & double-click rename
  row.querySelectorAll('.filter-pill[data-cat]').forEach(btn => {
    const catName = btn.dataset.cat;
    btn.addEventListener('click', (e) => {
      if (e.target.closest('.pill-del-btn') || e.target.closest('.inline-rename-field')) return;
      state.activeCategory = catName;
      state._savedNavCategory = catName;
      state.activeLeadId = null;
      if (isGDriveAssets) {
        state.activeGDriveBatchId = null;
        state.activeGDriveEnclosingFolder = (catName === 'All' || catName === 'All Asset Batches') ? null : catName;
        state.eagleFormatFilter = 'all';
        renderWorkspace();
        renderFilterActionRow();
        return;
      }
      if (isGmailSpace) {
        switchGmailFolder(catName);
        return;
      }
      if (isLightboxSpace) {
        state.lightboxFilter = catName;
        row.querySelectorAll('.filter-pill[data-cat]').forEach(b => {
          const act = b.dataset.cat === catName;
          b.classList.toggle('active', act);
          b.setAttribute('aria-pressed', act ? 'true' : 'false');
        });
        try {
          btn.scrollIntoView({ block: 'nearest', inline: 'nearest', container: 'nearest' });
        } catch (_) {
          btn.scrollIntoView({ block: 'nearest', inline: 'nearest' });
        }
        renderWorkspace();
        saveNavState();
        return;
      }
      row.querySelectorAll('.filter-pill[data-cat]').forEach(b => {
        b.classList.toggle('active', b.dataset.cat === catName);
      });
      renderWorkspace();
      saveNavState();
    });
    if (!isGDriveAssets && !isGmailSpace && !isLightboxSpace) {
      btn.addEventListener('dblclick', (e) => {
        if (e.target.closest('.pill-del-btn')) return;
        e.stopPropagation();
        promptInlineRename(btn, catName, (newVal) => {
          const clean = newVal.trim();
          if (!clean || clean === catName) return;
          const arr = type === 'project' ? obj.sections : obj.categories;
          const i = arr.indexOf(catName);
          if (i !== -1) arr[i] = clean;
          if (type === 'project') {
            vault.items.forEach(it => {
              if (it.parentType === 'project' && it.parentId === obj.id && it.section === catName) it.section = clean;
            });
          } else if (obj.id === 'projects') {
            vault.projects.forEach(p => { if (p.category === catName) p.category = clean; });
            vault.items.forEach(it => {
              if (it.parentType === 'space' && it.parentId === 'projects' && it.section === catName) it.section = clean;
            });
          } else if (obj.id === 'tool_dock') {
            (vault.toolDock?.launchpad || []).forEach(t => { if (t.cluster === catName) t.cluster = clean; });
            (vault.toolDock?.rdLab || []).forEach(r => { if (r.targetCluster === catName) r.targetCluster = clean; });
            (vault.toolDock?.usefulLinks || []).forEach(l => { if (l.cluster === catName) l.cluster = clean; });
          } else if (['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(obj.id)) {
            (vault.pitchEngine?.cards || []).forEach(c => {
              if ((c.spaceId || 'residencies') === obj.id && (c.category === catName || c.type === catName)) {
                c.category = clean;
                if (c.type === catName) c.type = clean;
              }
            });
          } else if (obj.id === 'instagram') {
            getInstagramAllItems().forEach(it => {
              if (it.section === catName) it.section = clean;
            });
          } else {
            vault.items.forEach(it => {
              if (it.parentType === 'space' && it.parentId === obj.id && it.section === catName) it.section = clean;
            });
          }
          state.activeCategory = clean;
          saveVault();
          renderAll();
        });
      });
    }
  });

  // Add new tab button
  const addTabBtn = document.getElementById('btnAddCategoryTab');
  if (addTabBtn) {
    addTabBtn.addEventListener('click', () => {
      promptInlineRename(addTabBtn, 'New Tab', (newVal) => {
        const clean = newVal.trim();
        if (!clean || clean === 'New Tab') return;
        const arr = type === 'project' ? (obj.sections = obj.sections || ['All']) : (obj.categories = obj.categories || ['All']);
        if (!arr.includes(clean)) arr.push(clean);
        state.activeCategory = clean;
        saveVault();
        renderAll();
      });
    });
  }

  // Google Drive sync buttons (both HUD pill and top actions pill)
  const rescanBtn = row.querySelector('#btnRescanGDrive') || document.getElementById('btnRescanGDrive');
  if (rescanBtn) {
    rescanBtn.addEventListener('click', async (e) => {
      e.stopPropagation();
      rescanBtn.textContent = '↻ Syncing…';
      rescanBtn.style.opacity = '0.6';
      showStatusToast('Syncing with Google Drive…');
      await fetchGDriveAssets(true);
      rescanBtn.textContent = '↻ Sync';
      rescanBtn.style.opacity = '1';
      renderFilterActionRow();
      renderWorkspace();
      showStatusToast('Google Drive synced');
    });
  }
  const btnHudSync = document.getElementById('btnHudSync');
  if (btnHudSync) {
    btnHudSync.hidden = !isGDriveAssets;
    btnHudSync.onclick = async () => {
      btnHudSync.textContent = '↻ Syncing…';
      await fetchGDriveAssets(true);
      btnHudSync.textContent = '↻ Sync';
      renderWorkspace();
    };
  }

  // Action buttons
  const newProjBtn = document.getElementById('btnNewProjectMain');
  if (newProjBtn) newProjBtn.addEventListener('click', () => createAndOpenNewProjectBoard());

  const upBtn = document.getElementById('btnBarUpload');
  if (upBtn) upBtn.addEventListener('click', () => document.getElementById('globalFileInput')?.click());

  const noteBtn = document.getElementById('btnBarNote');
  if (noteBtn) noteBtn.addEventListener('click', () => openQuickComposer('note'));

  const linkBtn = document.getElementById('btnBarLink');
  if (linkBtn) linkBtn.addEventListener('click', () => openQuickComposer('link'));

  saveNavState();
}

function getCategoryCount(type, obj, cat, isFirstAll) {
  if (type === 'space' && obj.id === 'lightbox') {
    const items = getLightboxAssetsForActiveProject();
    if (cat === 'Instagram Board') return items.filter(i => isLightboxKeptInRoom(i, 'instagram')).length;
    if (cat === 'Portfolio Staging') return items.filter(i => isLightboxKeptInRoom(i, 'website')).length;
    return items.filter(i => !isLightboxHiddenInRoom(i, 'source')).length;
  }
  if (type === 'project') {
    const all = vault.items.filter(i => i.parentType === 'project' && i.parentId === obj.id && (i.folderId || null) === (state.activeFolderId || null));
    if (isFirstAll) return all.length;
    return all.filter(i => i.section === cat).length;
  }
  if (obj.id === 'projects') {
    if (state.activeFolderId) {
      const all = vault.items.filter(i => i.parentType === 'space' && i.parentId === 'projects' && (i.folderId || null) === state.activeFolderId);
      if (isFirstAll) return all.length;
      return all.filter(i => i.section === cat).length;
    }
    const lcFilter = state.projectsLifecycleFilter || 'active';
    const visibleProjs = vault.projects.filter(p => {
      const pState = p.lifecycleState || 'active';
      return lcFilter === 'delivered' ? pState === 'delivered' : pState !== 'delivered';
    });
    if (isFirstAll) return visibleProjs.length;
    return visibleProjs.filter(p => p.category === cat).length;
  }
  if (obj.id === 'gdrive_assets') {
    if (cat === 'All' || cat === 'All Asset Batches') return state.gdriveEnclosingFolders?.length || 8;
    const enc = (state.gdriveEnclosingFolders || []).find(e => e.name === cat);
    if (enc) return enc.subfolderCount || (enc.examples || []).length || 0;
    return state.gdriveBatches.filter(b => b.enclosingFolder === cat || b.category === cat).length;
  }
  if (obj.id === 'tool_dock') {
    const rawTools = Array.isArray(vault.toolDock?.launchpad) ? vault.toolDock.launchpad : (vault.toolDock?.tools || []);
    const clusterTools = rawTools.filter(t => t && !t.stapleOnly);
    if (isFirstAll) return clusterTools.length;
    return clusterTools.filter(t => (t.cluster || t.category) === cat).length;
  }
  if (['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(obj.id)) {
    const cards = (vault.pitchEngine?.cards || []).filter(c => (c.spaceId || 'residencies') === obj.id);
    if (isFirstAll) return cards.length;
    return cards.filter(c => (c.category || c.type || '') === cat).length;
  }
  if (obj.id === 'gmail') {
    if (state.gmail?.connected) {
      const counts = state.gmail.folderCounts || {};
      if (typeof counts[cat] === 'number') return counts[cat];
      if (state.gmail.folder === cat) {
        return state.gmail.totalInFolder || state.gmail.messages?.length || 0;
      }
    }
    return '';
  }
  const all = vault.items.filter(i => i.parentType === 'space' && i.parentId === obj.id);
  if (isFirstAll) return all.length;
  return all.filter(i => i.section === cat).length;
}

function renderSectionDesignDrawer() {
  const drawer = document.getElementById('sectionDesignDrawer');
  if (!drawer) return;
  if (!state.sectionDrawerOpen) {
    drawer.hidden = true;
    return;
  }
  drawer.hidden = false;

  const { type, obj } = getActiveContainer();
  const ui = obj.ui || {};
  const isProjectsSpace = (type === 'space' && (obj.id === 'projects' || obj.id === 'incubator'));
  const isGDrive = (type === 'space' && obj.id === 'gdrive_assets');
  const isToolDock = (type === 'space' && obj.id === 'tool_dock');
  const isMovingForward = (type === 'space' && ['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(obj.id));

  drawer.innerHTML = `
    <div class="design-drawer-group">
      <span class="kicker-mono" style="color:var(--text);">SECTION UI (${escapeHtml(obj.title)}):</span>
      <label class="kicker-mono">LAYOUT</label>
      <select id="secUiLayout" class="toolbar-select" style="border:1px solid var(--border);padding:4px 8px;border-radius:4px;background:var(--surface-pill);">
        ${isGDrive ? `<option value="eagle" selected>🦅 Eagle Dense Asset Browser</option>` : (isToolDock ? `<option value="wall" selected>⚡ Visual Launchpad &amp; 3-Lane Lab</option>` : (isMovingForward ? `
          <option value="vertical" ${ui.layoutMode !== 'horizontal' ? 'selected' : ''}>▤ Vertical Columns</option>
          <option value="horizontal" ${ui.layoutMode === 'horizontal' ? 'selected' : ''}>☰ Horizontal Rows</option>
        ` : `
          ${isProjectsSpace ? `<option value="sphere" ${ui.layoutMode === 'sphere' ? 'selected' : ''}>◎ 3D Sphere Stage</option>` : ''}
          <option value="giant_wall" ${ui.layoutMode === 'giant_wall' ? 'selected' : ''}>✥ Giant Wall (Freeform Spatial Board)</option>
          <option value="wall" ${ui.layoutMode === 'wall' ? 'selected' : ''}>⊞ Clear Drawers / Bento Grid</option>
          <option value="list" ${ui.layoutMode === 'list' ? 'selected' : ''}>☰ Visual List Rows</option>
          <option value="kanban" ${ui.layoutMode === 'kanban' ? 'selected' : ''}>▤ Category Columns</option>
        `))}
      </select>

      ${isToolDock ? `
      <label class="kicker-mono">SORT ORDER</label>
      <select id="secUiSortOrder" class="toolbar-select" style="border:1px solid var(--border);padding:4px 8px;border-radius:4px;background:var(--surface-pill);">
        <option value="manual" ${(!ui.sortOrder || ui.sortOrder === 'manual') ? 'selected' : ''}>↕ Manual (Drag to Reorder)</option>
        <option value="alpha" ${ui.sortOrder === 'alpha' ? 'selected' : ''}>Aa Alphabetical (A–Z)</option>
        <option value="newest" ${ui.sortOrder === 'newest' ? 'selected' : ''}>✦ Newest Added First</option>
      </select>
      ` : `
      <label class="kicker-mono">STAGE RATIO</label>
      <select id="secUiAspect" class="toolbar-select" style="border:1px solid var(--border);padding:4px 8px;border-radius:4px;background:var(--surface-pill);">
        <option value="16 / 10.5" ${ui.aspectRatio === '16 / 10.5' ? 'selected' : ''}>16:10 Studio Frame</option>
        <option value="4 / 3" ${ui.aspectRatio === '4 / 3' ? 'selected' : ''}>4:3 Classic</option>
        <option value="1 / 1" ${ui.aspectRatio === '1 / 1' ? 'selected' : ''}>1:1 Square Grid</option>
        <option value="4 / 5" ${ui.aspectRatio === '4 / 5' ? 'selected' : ''}>4:5 Instagram Portrait</option>
        <option value="9 / 16" ${ui.aspectRatio === '9 / 16' ? 'selected' : ''}>9:16 Vertical Reel</option>
      </select>

      <label class="kicker-mono">IMAGE FIT</label>
      <select id="secUiFit" class="toolbar-select" style="border:1px solid var(--border);padding:4px 8px;border-radius:4px;background:var(--surface-pill);">
        <option value="cover" ${ui.imageFit === 'cover' ? 'selected' : ''}>Fill Stage (Cover)</option>
        <option value="contain" ${ui.imageFit === 'contain' ? 'selected' : ''}>Show Whole Image (Contain)</option>
      </select>
      `}
    </div>

    <div class="design-drawer-group">
      <button type="button" class="outline-btn" id="btnOpenFullCustomizer">Open 11 Full Studio Customizer →</button>
      <button type="button" class="icon-chip" id="btnCloseSecDrawer" title="Close">✕</button>
    </div>
  `;

  drawer.querySelector('#secUiLayout')?.addEventListener('change', (e) => {
    obj.ui.layoutMode = e.target.value;
    saveVault();
    applyCustomizationToDOM();
    renderAll();
  });
  drawer.querySelector('#secUiSortOrder')?.addEventListener('change', (e) => {
    obj.ui = obj.ui || {};
    obj.ui.sortOrder = e.target.value;
    saveVault('UPDATED SORT ORDER');
    renderWorkspace();
  });
  drawer.querySelector('#secUiAspect')?.addEventListener('change', (e) => {
    obj.ui.aspectRatio = e.target.value;
    saveVault();
    applyCustomizationToDOM();
  });
  drawer.querySelector('#secUiFit')?.addEventListener('change', (e) => {
    obj.ui.imageFit = e.target.value;
    saveVault();
    applyCustomizationToDOM();
  });
  drawer.querySelector('#btnOpenFullCustomizer')?.addEventListener('click', () => {
    state.custSavedSnapshot = captureCustomizationSnapshot(vault);
    state.custDirty = false;
    state.viewType = 'space';
    state.activeSpaceId = 'customize';
    state.sectionDrawerOpen = false;
    renderAll();
  });
  drawer.querySelector('#btnCloseSecDrawer')?.addEventListener('click', () => {
    state.sectionDrawerOpen = false;
    renderHeaderAndToolbar();
    renderSectionDesignDrawer();
  });
}

/* ==========================================================================
   WORKSPACE RENDERING (SECTION-SPECIFIC VIEW ENGINES — MODULES 1–6)
   ========================================================================== */
function renderAll() {
  applyCustomizationToDOM();
  renderSidebar();
  renderHeaderAndToolbar();
  renderFilterActionRow();
  renderSectionDesignDrawer();
  renderWorkspace();
  renderCompareFloatingBar();
  saveNavState();
}

function renderWorkspace() {
  const ws = document.getElementById('workspace');
  if (!ws) return;

  saveNavState();

  const { type, obj } = getActiveContainer();

  if (type === 'space' && obj.id === 'customize') {
    renderCustomizeView(ws);
    return;
  }

  if (type === 'space' && obj.id === 'lightbox') {
    renderLightboxView(ws, obj);
    applyContainerScale(type, obj, false);
    if (state._pendingScrollTop > 0 && (vault.items || []).length > 0) {
      const targetTop = state._pendingScrollTop;
      state._pendingScrollTop = 0;
      requestAnimationFrame(() => { ws.scrollTop = targetTop; });
    }
    if (state._pendingCompareRestore && (vault.items || []).length > 0) {
      const pendingCmp = state._pendingCompareRestore;
      const matched = pendingCmp.selectedIds
        .map(id => vault.items.find(i => i.id === id))
        .filter(Boolean);
      state._pendingCompareRestore = null;
      if (matched.length > 0) {
        state.selectedCompareAssets = matched.map(it => ({
          id: it.id,
          title: it.title || 'Asset',
          url: it.url,
          kind: getLightboxMasterMediaKind(it),
          igStatus: it.igStatus || '',
          lightboxKeep: Boolean(it.lightboxKeep),
          vaultItemId: it.id,
          notes: it.notes || ''
        }));
        state.compareState.mode = pendingCmp.mode || 'stack';
        state.compareState.activeIndex = Math.min(Math.max(0, pendingCmp.activeIndex || 0), matched.length - 1);
        state.compareState.showGrid = Boolean(pendingCmp.showGrid);
        state.compareState.overlayMode = pendingCmp.overlayMode || 'none';
        state.compareState.diffBlend = Boolean(pendingCmp.diffBlend);
        state.compareState.showSpecs = Boolean(pendingCmp.showSpecs);
        state.compareState.diffColor = pendingCmp.diffColor || 'pink';
        state.compareState.diffGain = Number(pendingCmp.diffGain || 4);
        const cmpDlg = document.getElementById('compareDialog');
        if (cmpDlg) {
          renderCompareModal();
          if (!cmpDlg.open) cmpDlg.showModal();
          requestAnimationFrame(() => syncCompareOverlayBounds());
        }
      }
    }
    return;
  }

  if (type === 'space' && obj.id === 'tool_dock') {
    renderToolDockAndRdLab(ws, obj);
    return;
  }

  if (type === 'space' && obj.id === 'gmail') {
    renderGmailView(ws, obj);
    return;
  }

  if (type === 'space' && ['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(obj.id)) {
    renderOutreachPitchEngine(ws, obj);
    applyContainerScale(type, obj, false);
    return;
  }

  if (type === 'space' && obj.id === 'gdrive_assets') {
    renderGDriveAssetsView(ws, obj);
    applyContainerScale(type, obj, false);
    return;
  }

  if (type === 'space' && obj.id === 'projects' && !state.activeFolderId) {
    renderProjectsOverview(ws, obj);
    applyContainerScale(type, obj, false);
    return;
  }

  renderItemsCollection(ws, type, obj);
  applyContainerScale(type, obj, false);
}

/* ==========================================================================
   SOOT-INSPIRED TACTILE SPHERICAL BATCH STAGE & SPATIAL ZOOM HUD
   - Inner Sphere (0%–60% radius, Golden-Angle Phyllotaxis Spiral): Images, Videos, 3D Renders, PSDs
   - Outer Circle Layer (79% radius, Circumference Ring): Notes, Checklists, Links, Mac Paths, Audio
   - Proximity Fisheye Hover: Smoothly magnifies cluster under cursor + pops target file up to 2.35x
   - Spatial Zoom-In (Wheel/Pinch/Click): Spreads files spatially & displays Frosted-Glass Attached Note Card
   ========================================================================== */
function renderSphericalStage(ws, batches, stageConfig = {}) {
  if (!batches || batches.length === 0) {
    ws.innerHTML = `
      <div class="sphere-stage-viewport">
        <div style="text-align:center;padding:48px;">
          <div class="kicker-mono">EMPTY SPHERICAL STAGE</div>
          <p class="typewriter" style="font-size:12.5px;color:var(--text-mid);margin-top:6px;">Drop images, videos, notes, or links anywhere to form a spherical batch.</p>
        </div>
      </div>
    `;
    return;
  }

  // Clamp active sphere index
  if (typeof state.sphereActiveIndex !== 'number' || state.sphereActiveIndex < 0 || state.sphereActiveIndex >= batches.length) {
    state.sphereActiveIndex = 0;
  }

  const isMultiGrid = state.sphereViewStyle === 'grid' && batches.length > 1;
  const activeBatch = batches[state.sphereActiveIndex] || batches[0];

  const viewport = document.createElement('div');
  viewport.className = 'sphere-stage-viewport';

  if (isMultiGrid) {
    const multiGrid = document.createElement('div');
    multiGrid.className = 'spheres-multi-grid';
    batches.forEach((b, idx) => {
      const orbEl = buildSingleSphereOrb(b, idx, false, stageConfig);
      multiGrid.appendChild(orbEl);
    });
    viewport.appendChild(multiGrid);
  } else {
    // Constellation Hero Stage (Center Hero Sphere + Peripheral Satellite Spheres + Camera Zoom/Pan World)
    const cameraWorld = document.createElement('div');
    cameraWorld.className = 'sphere-camera-world';

    // Peripheral Satellite Spheres (like the surrounding clusters on spiral.soot.com)
    const satellitePositions = [
      { left: '8%', top: '22%' },
      { left: '92%', top: '22%' },
      { left: '8%', top: '71%' },
      { left: '92%', top: '70%' }
    ];

    let satSlot = 0;
    batches.forEach((b, idx) => {
      if (idx === state.sphereActiveIndex) return;
      if (satSlot >= satellitePositions.length) return;
      const pos = satellitePositions[satSlot++];
      const satEl = buildSatelliteSphereEl(b, idx, pos, stageConfig);
      cameraWorld.appendChild(satEl);
    });

    // Hero Center Sphere Orb
    const heroOrb = buildSingleSphereOrb(activeBatch, state.sphereActiveIndex, true, stageConfig);
    cameraWorld.appendChild(heroOrb);
    viewport.appendChild(cameraWorld);

    // Apply current zoom & pan transform
    const updateCameraTransform = () => {
      const z = state.sphereZoom || 1;
      const px = state.spherePanX || 0;
      const py = state.spherePanY || 0;
      cameraWorld.style.transform = `translate3d(${px.toFixed(1)}px, ${py.toFixed(1)}px, 0) scale(${z.toFixed(3)})`;
      viewport.classList.toggle('is-zoomed-in', z > 1.12);
      const zoomBtn = viewport.querySelector('#sphereZoomPctBtn');
      if (zoomBtn) zoomBtn.textContent = `${Math.round(z * 100)}%`;

      // Update mini-map radar viewport box
      const radarVp = viewport.querySelector('#minimapRadarViewport');
      if (radarVp) {
        const wPct = Math.min(100, Math.max(22, 64 / z));
        const hPct = Math.min(100, Math.max(22, 64 / z));
        const cx = 50 - (px / 18);
        const cy = 50 - (py / 18);
        radarVp.style.width = `${wPct.toFixed(1)}%`;
        radarVp.style.height = `${hPct.toFixed(1)}%`;
        radarVp.style.left = `${Math.max(4, Math.min(96 - wPct, cx - wPct / 2)).toFixed(1)}%`;
        radarVp.style.top = `${Math.max(4, Math.min(96 - hPct, cy - hPct / 2)).toFixed(1)}%`;
      }

      // Trigger spatial spread update inside hero orb when zoomed in
      if (heroOrb._updateSpatialPositions) {
        heroOrb._updateSpatialPositions();
      }
    };

    // Wheel / Trackpad Pinch Zoom & Pan on Stage
    viewport.addEventListener('wheel', (e) => {
      if (e.target.closest('.spatial-attached-hud') || e.target.closest('.sphere-stage-switcher-bar')) {
        return;
      }
      e.preventDefault();
      const zoomFactor = e.ctrlKey ? -e.deltaY * 0.012 : -e.deltaY * 0.0022;
      const nextZoom = Math.min(3.5, Math.max(0.75, (state.sphereZoom || 1) + zoomFactor));
      state.sphereZoom = nextZoom;
      if (nextZoom <= 1.04) {
        state.spherePanX *= 0.82;
        state.spherePanY *= 0.82;
      }
      updateCameraTransform();
    }, { passive: false });

    // Click-and-drag panning on stage background using Pointer Capture (no global window listener leak)
    let isPanning = false;
    let panStartX = 0;
    let panStartY = 0;
    let origPanX = 0;
    let origPanY = 0;

    viewport.addEventListener('pointerdown', (e) => {
      if (
        e.button !== 0 ||
        e.target.closest('.sphere-node') ||
        e.target.closest('.spatial-attached-hud') ||
        e.target.closest('.sphere-bottom-capsule') ||
        e.target.closest('.sphere-stage-switcher-bar') ||
        e.target.closest('.satellite-sphere')
      ) {
        return;
      }
      isPanning = true;
      panStartX = e.clientX;
      panStartY = e.clientY;
      origPanX = state.spherePanX || 0;
      origPanY = state.spherePanY || 0;
      try { viewport.setPointerCapture(e.pointerId); } catch (_) {}
    });

    viewport.addEventListener('pointermove', (e) => {
      if (!isPanning) return;
      const dx = e.clientX - panStartX;
      const dy = e.clientY - panStartY;
      state.spherePanX = origPanX + dx;
      state.spherePanY = origPanY + dy;
      updateCameraTransform();
    });

    const endSpherePan = (e) => {
      if (!isPanning) return;
      isPanning = false;
      try { viewport.releasePointerCapture(e.pointerId); } catch (_) {}
    };
    viewport.addEventListener('pointerup', endSpherePan);
    viewport.addEventListener('pointercancel', endSpherePan);

    // Clicking empty background unlocks focused node if clicked without dragging
    viewport.addEventListener('click', (e) => {
      if (
        !e.target.closest('.sphere-node') &&
        !e.target.closest('.spatial-attached-hud') &&
        !e.target.closest('.sphere-stage-switcher-bar') &&
        state.sphereLockedNodeId
      ) {
        state.sphereLockedNodeId = null;
        if (heroOrb._refreshAttachedHud) heroOrb._refreshAttachedHud(null);
        if (heroOrb._updateSpatialPositions) heroOrb._updateSpatialPositions();
      }
    });

    viewport._updateCameraTransform = updateCameraTransform;
    requestAnimationFrame(updateCameraTransform);
  }

  // Bottom Floating Sphere Switcher Strip + Clean Zoom Controls
  const switcherBar = document.createElement('div');
  switcherBar.className = 'sphere-stage-switcher-bar';

  if (batches.length > 1) {
    const viewToggleBtn = document.createElement('button');
    viewToggleBtn.type = 'button';
    viewToggleBtn.className = `sphere-switch-pill ${isMultiGrid ? 'active' : ''}`;
    viewToggleBtn.title = isMultiGrid ? 'Switch to Hero Sphere + Satellites Constellation' : 'Show All Spheres Side-by-Side';
    viewToggleBtn.innerHTML = isMultiGrid ? `◎ Hero Sphere` : `⊞ All Spheres (${batches.length})`;
    viewToggleBtn.addEventListener('click', () => {
      state.sphereViewStyle = isMultiGrid ? 'constellation' : 'grid';
      state.sphereZoom = 1;
      state.spherePanX = 0;
      state.spherePanY = 0;
      renderWorkspace();
    });
    switcherBar.appendChild(viewToggleBtn);
  }

  batches.slice(0, 12).forEach((b, idx) => {
    const pill = document.createElement('button');
    pill.type = 'button';
    pill.className = `sphere-switch-pill ${!isMultiGrid && idx === state.sphereActiveIndex ? 'active' : ''}`;
    const totalCount = (b.visualNodes?.length || 0) + (b.outerNodes?.length || 0);
    pill.innerHTML = `
      <span class="pill-dot"></span>
      <span>${escapeHtml(b.code || ('#' + String(idx + 1).padStart(2, '0')))} ${escapeHtml(b.title.length > 22 ? b.title.slice(0, 22) + '…' : b.title)}</span>
      <span style="opacity:0.62;">(${totalCount})</span>
    `;
    pill.addEventListener('click', () => {
      state.sphereActiveIndex = idx;
      state.sphereViewStyle = 'constellation';
      state.sphereLockedNodeId = null;
      state.sphereZoom = 1;
      state.spherePanX = 0;
      state.spherePanY = 0;
      renderWorkspace();
    });
    switcherBar.appendChild(pill);
  });

  if (!isMultiGrid) {
    const zoomCluster = document.createElement('div');
    zoomCluster.style.cssText = 'display:inline-flex;align-items:center;gap:4px;margin-left:8px;padding-left:8px;border-left:1px solid var(--border);';
    zoomCluster.innerHTML = `
      <button type="button" class="sphere-switch-pill" id="btnSphereZoomOut" title="Zoom Out">−</button>
      <button type="button" class="sphere-switch-pill" id="sphereZoomPctBtn" title="Toggle Zoom">${Math.round((state.sphereZoom || 1) * 100)}%</button>
      <button type="button" class="sphere-switch-pill" id="btnSphereZoomIn" title="Zoom In">+</button>
      <button type="button" class="sphere-switch-pill" id="btnSphereZoomReset" title="Reset Camera">Reset</button>
    `;
    zoomCluster.querySelector('#btnSphereZoomOut')?.addEventListener('click', () => {
      state.sphereZoom = Math.max(0.75, (state.sphereZoom || 1) - 0.3);
      if (state.sphereZoom <= 1.05) { state.spherePanX = 0; state.spherePanY = 0; }
      viewport._updateCameraTransform?.();
    });
    zoomCluster.querySelector('#btnSphereZoomIn')?.addEventListener('click', () => {
      state.sphereZoom = Math.min(3.5, (state.sphereZoom || 1) + 0.35);
      viewport._updateCameraTransform?.();
    });
    zoomCluster.querySelector('#sphereZoomPctBtn')?.addEventListener('click', () => {
      if ((state.sphereZoom || 1) > 1.3) {
        state.sphereZoom = 1;
        state.spherePanX = 0;
        state.spherePanY = 0;
      } else {
        state.sphereZoom = 1.75;
      }
      viewport._updateCameraTransform?.();
    });
    zoomCluster.querySelector('#btnSphereZoomReset')?.addEventListener('click', () => {
      state.sphereZoom = 1;
      state.spherePanX = 0;
      state.spherePanY = 0;
      state.sphereLockedNodeId = null;
      const heroOrb = viewport.querySelector('.spherical-batch-orb');
      heroOrb?._refreshAttachedHud?.(null);
      viewport._updateCameraTransform?.();
    });
    switcherBar.appendChild(zoomCluster);
  }

  viewport.appendChild(switcherBar);

  ws.innerHTML = '';
  ws.appendChild(viewport);
}

function buildSatelliteSphereEl(batch, idx, pos, stageConfig) {
  const sat = document.createElement('div');
  sat.className = 'satellite-sphere';
  sat.style.left = pos.left;
  sat.style.top = pos.top;
  sat.title = `Click to bring "${batch.title}" to Center Sphere Stage`;

  const visuals = (batch.visualNodes || []).slice(0, 16);

  const goldenAngle = 2.399963229728653;
  const total = Math.max(1, visuals.length);
  const maxSatRadius = total <= 3 ? 18 : (total <= 7 ? 24 : 31);

  const thumbsHtml = visuals.map((v, i) => {
    const rPct = total === 1 ? 0 : Math.sqrt((i + 0.42) / total) * maxSatRadius;
    const theta = i * goldenAngle;
    const xPct = 50 + Math.cos(theta) * rPct;
    const yPct = 50 + Math.sin(theta) * rPct;
    return `
      <div class="sat-mini-thumb" style="left:${xPct.toFixed(1)}%;top:${yPct.toFixed(1)}%;">
        <img src="${escapeHtml(v.thumbSrc || v.url)}" alt="" loading="lazy">
      </div>
    `;
  }).join('');

  const totalFiles = (batch.visualNodes?.length || 0) + (batch.outerNodes?.length || 0);
  sat.innerHTML = `
    ${thumbsHtml}
    <div class="satellite-sphere-label" data-editable-title="1" title="Double-click to rename">${escapeHtml(batch.code || ('#' + String(idx + 1).padStart(2, '0')))} ${escapeHtml(batch.title.slice(0, 18))} (${totalFiles})</div>
  `;

  const satLbl = sat.querySelector('.satellite-sphere-label');
  satLbl?.addEventListener('dblclick', (e) => {
    e.stopPropagation();
    promptInlineRename(satLbl, batch.title, (newVal) => {
      if (newVal.trim() && batch.onRename) {
        batch.onRename(newVal.trim());
      }
    });
  });

  sat.addEventListener('click', (e) => {
    if (e.target.closest('.inline-rename-field')) return;
    e.stopPropagation();
    state.sphereActiveIndex = idx;
    state.sphereLockedNodeId = null;
    state.sphereZoom = 1;
    state.spherePanX = 0;
    state.spherePanY = 0;
    renderWorkspace();
  });

  return sat;
}

function buildSingleSphereOrb(batch, idx, isHeroStage, stageConfig = {}) {
  const orb = document.createElement('div');
  orb.className = 'spherical-batch-orb';
  if (!isHeroStage) {
    orb.style.setProperty('--sphere-diameter', '490px');
  }

  const visualNodes = batch.visualNodes || [];
  const outerNodes = batch.outerNodes || [];
  const totalCount = batch.totalCountOverride || (visualNodes.length + outerNodes.length);

  orb.innerHTML = `
    <div class="sphere-inner-divider-ring" title="Inner Core: Visual Files • Outer Ring: Notes, Links & Checklists"></div>

    <!-- BOTTOM SCULPTED CAPSULE: Batch Title, Count & Open Board Action -->
    <div class="sphere-bottom-capsule" title="Click title to rename • Click Open Board to enter">
      <span class="capsule-kicker">${escapeHtml(batch.code || ('#' + String(idx + 1).padStart(2, '0')))} · ${totalCount} items</span>
      <span class="capsule-title-row" style="display:inline-flex;align-items:center;gap:6px;">
        <span class="capsule-title" data-editable-title="1" title="Click to rename">${escapeHtml(batch.title)}</span>
        ${batch.onRename ? `<button type="button" class="capsule-edit-pen" title="Rename title">✎</button>` : ''}
      </span>
      <span class="capsule-sub" style="display:inline-flex;align-items:center;gap:8px;">
        <span>${visualNodes.length} visuals · ${outerNodes.length} notes/links</span>
        ${batch.onTurnIntoProject ? `<button type="button" class="btn-sphere-batch-proj" style="background:var(--accent);color:#FFF;border:none;border-radius:999px;padding:2px 10px;font-size:10px;font-weight:700;cursor:pointer;">✨ Turn into Project</button>` : ''}
        ${(batch.onPrimaryOpen || batch.onPrimaryAction) ? `<button type="button" class="btn-sphere-open-board" style="background:var(--text);color:var(--bg);border:none;border-radius:999px;padding:2px 9px;font-size:10px;font-weight:600;cursor:pointer;">Open Board →</button>` : ''}
      </span>
    </div>

    <!-- NODES LAYER (Inner Visual Spiral + Outer Note/Link Ring) -->
    <div class="sphere-nodes-container" style="position:absolute;inset:0;pointer-events:none;"></div>

    <!-- ATTACHED FROSTED-GLASS FILE NOTE & LINK HUD (Positioned beside focused file) -->
    <div class="spatial-attached-hud" hidden></div>
  `;

  const nodesContainer = orb.querySelector('.sphere-nodes-container');
  const attachedHud = orb.querySelector('.spatial-attached-hud');
  const allPlacedNodes = [];

  // 1. Place ONLY the real visual files (1:1 — never duplicate/clone uploaded files)
  const displayVisualNodes = visualNodes.slice(0, 60);
  const totalVisuals = Math.max(1, displayVisualNodes.length);

  // Adaptive tile size & spiral radius based on how many real files are in this batch
  if (totalVisuals <= 4) {
    orb.style.setProperty('--node-w-land', '114px');
    orb.style.setProperty('--node-h-land', '82px');
    orb.style.setProperty('--node-w-sq', '96px');
    orb.style.setProperty('--node-h-sq', '96px');
    orb.style.setProperty('--node-w-port', '82px');
    orb.style.setProperty('--node-h-port', '112px');
  } else if (totalVisuals <= 10) {
    orb.style.setProperty('--node-w-land', '78px');
    orb.style.setProperty('--node-h-land', '56px');
    orb.style.setProperty('--node-w-sq', '66px');
    orb.style.setProperty('--node-h-sq', '66px');
    orb.style.setProperty('--node-w-port', '56px');
    orb.style.setProperty('--node-h-port', '76px');
  } else if (totalVisuals <= 20) {
    orb.style.setProperty('--node-w-land', '56px');
    orb.style.setProperty('--node-h-land', '40px');
    orb.style.setProperty('--node-w-sq', '48px');
    orb.style.setProperty('--node-h-sq', '48px');
    orb.style.setProperty('--node-w-port', '40px');
    orb.style.setProperty('--node-h-port', '54px');
  }

  const goldenAngle = 2.399963229728653; // 137.508 degrees in radians
  const maxInnerRadiusPct = totalVisuals === 1 ? 0 : (totalVisuals <= 4 ? 17.5 : (totalVisuals <= 10 ? 24.5 : (totalVisuals <= 20 ? 28.5 : 31.8)));
  const spiralSlots = [];

  for (let i = 0; i < displayVisualNodes.length; i++) {
    const normR = totalVisuals === 1 ? 0 : Math.sqrt((i + 0.45) / totalVisuals);
    const rPct = normR * maxInnerRadiusPct;
    const theta = i * goldenAngle;
    const xPct = 50 + Math.cos(theta) * rPct;
    const yPct = 50 + Math.sin(theta) * rPct;
    spiralSlots.push({ xPct, yPct, rPct });
  }

  const aspectClasses = ['shape-landscape', 'shape-square', 'shape-portrait', 'shape-landscape', 'shape-portrait', 'shape-square'];

  displayVisualNodes.forEach((vn, i) => {
    const slot = spiralSlots[i] || { xPct: 50, yPct: 50 };
    const baseXPct = slot.xPct;
    const baseYPct = slot.yPct;

    const nodeEl = document.createElement('div');
    const shapeCls = vn.shapeClass || aspectClasses[i % aspectClasses.length];
    const isSel = isAssetCompareSelected(vn.id);
    const igStat = vn.igStatus || vn.vaultItem?.igStatus || '';
    nodeEl.className = `sphere-node is-visual-node ${shapeCls} ${isSel ? 'is-compare-selected' : ''}`;
    nodeEl.style.pointerEvents = 'auto';
    nodeEl.style.left = `${baseXPct.toFixed(2)}%`;
    nodeEl.style.top = `${baseYPct.toFixed(2)}%`;
    nodeEl.dataset.nodeId = vn.id;

    const isLcp = idx === 0 && i === 0;
    const prioAttr = isLcp ? 'fetchpriority="high"' : 'loading="lazy" decoding="async"';
    const hasAttachedNote = Boolean((vn.notes || '').trim());

    const igBadgeHtml = igStat === 'published'
      ? `<span class="ig-status-badge is-published" title="Published (IG Live) — Click to cycle status">● IG LIVE</span>`
      : (igStat === 'queued'
          ? `<span class="ig-status-badge is-queued" title="Queued (IG Ready / Next Up) — Click to cycle status">◈ IG READY</span>`
          : '');

    const igQuickBtnHtml = vn.vaultItem ? `
      <button type="button" class="node-ig-quick-btn ${igStat === 'published' ? 'is-published' : (igStat === 'queued' ? 'is-queued' : '')}" title="1-Click Toggle IG Status (WIP → IG Ready → IG Live)">
        ${igStat === 'published' ? '●' : '◈'}
      </button>
    ` : '';

    const selectChkHtml = `
      <button type="button" class="asset-select-check ${isSel ? 'is-selected' : ''}" title="Select to Compare (1:1 Layer Stack / Split View)">✓</button>
    `;

    if (vn.kind === 'video' && vn.url) {
      nodeEl.innerHTML = `
        <video src="${escapeHtml(vn.url)}#t=0.1" preload="metadata" muted loop playsinline></video>
        <span class="node-kind-badge">▶ VID</span>
        ${selectChkHtml}
        ${igQuickBtnHtml}
        ${igBadgeHtml}
        ${hasAttachedNote ? `<span class="node-note-dot" title="Has attached note"></span>` : ''}
      `;
    } else {
      nodeEl.innerHTML = `
        <img src="${escapeHtml(vn.thumbSrc || vn.url)}" data-fallback="${escapeHtml(vn.fallbackSrc || '')}" alt="${escapeHtml(vn.title)}" ${prioAttr}>
        ${vn.badge ? `<span class="node-kind-badge">${escapeHtml(vn.badge)}</span>` : ''}
        ${selectChkHtml}
        ${igQuickBtnHtml}
        ${igBadgeHtml}
        ${hasAttachedNote ? `<span class="node-note-dot" title="Has attached note"></span>` : ''}
      `;
      const imgEl = nodeEl.querySelector('img');
      imgEl?.addEventListener('error', () => {
        const fb = imgEl.dataset.fallback;
        if (fb && imgEl.src !== fb && !imgEl.dataset.triedFb) {
          imgEl.dataset.triedFb = '1';
          imgEl.src = fb;
        }
      });
    }

    // Bind Compare multi-select checkbox on sphere node
    nodeEl.querySelector('.asset-select-check')?.addEventListener('click', (e) => {
      e.stopPropagation();
      toggleCompareSelect({
        id: vn.id,
        title: vn.title || 'Visual',
        url: vn.url || vn.thumbSrc,
        kind: vn.kind || 'image',
        igStatus: vn.vaultItem?.igStatus || vn.igStatus || '',
        vaultItemId: vn.vaultItem?.id || null,
        notes: vn.notes || ''
      });
    });

    // Bind 1-click IG status toggle & badge click on sphere node
    nodeEl.querySelector('.node-ig-quick-btn')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (vn.vaultItem) cycleItemIgStatus(vn.vaultItem.id);
    });
    nodeEl.querySelector('.ig-status-badge')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (vn.vaultItem) cycleItemIgStatus(vn.vaultItem.id);
    });

    nodesContainer.appendChild(nodeEl);
    allPlacedNodes.push({
      id: vn.id,
      data: vn,
      el: nodeEl,
      layer: 'inner',
      baseXPct,
      baseYPct,
      curXPct: baseXPct,
      curYPct: baseYPct
    });
  });

  // 2. Place OUTER CIRCLE LAYER Notes, Checklists, Web Links, Mac Paths & Audio along safe diagonal arcs (never colliding with top/bottom/left/right controls)
  const outerRingRadiusPct = 42.2;
  const safeOuterAnglesDeg = [-148, -44, 146, 44, -126, -62, 124, 62, -162, 162];
  outerNodes.slice(0, 10).forEach((on, i) => {
    const deg = safeOuterAnglesDeg[i % safeOuterAnglesDeg.length];
    const theta = (deg * Math.PI) / 180;

    const baseXPct = 50 + Math.cos(theta) * outerRingRadiusPct;
    const baseYPct = 50 + Math.sin(theta) * outerRingRadiusPct;

    const nodeEl = document.createElement('div');
    nodeEl.className = 'sphere-node is-outer-node';
    nodeEl.style.pointerEvents = 'auto';
    nodeEl.style.left = `${baseXPct.toFixed(2)}%`;
    nodeEl.style.top = `${baseYPct.toFixed(2)}%`;
    nodeEl.dataset.nodeId = on.id;

    let iconSym = '📝';
    let subTag = 'NOTE';
    if (on.kind === 'checklist' || (on.notes || '').includes('[ ]') || (on.notes || '').includes('[x]')) {
      iconSym = '☑';
      const done = ((on.notes || '').match(/\[x\]/gi) || []).length;
      const all = done + ((on.notes || '').match(/\[ \]/g) || []).length;
      subTag = `${done}/${all}`;
    } else if (on.kind === 'link' || on.link) {
      const isMacPath = (on.link || '').startsWith('~') || (on.link || '').startsWith('/');
      iconSym = isMacPath ? '📁' : '🌐';
      subTag = isMacPath ? 'MAC' : 'URL';
    } else if (on.kind === 'audio') {
      iconSym = '🔊';
      subTag = 'WAV';
    }

    const shortLabel = (on.title || 'Note').length > 16 ? (on.title || 'Note').slice(0, 16) + '…' : (on.title || 'Note');

    nodeEl.innerHTML = `
      <span class="outer-node-icon">${iconSym}</span>
      <span class="outer-node-label">${escapeHtml(shortLabel)}</span>
      <span class="outer-node-sub">${escapeHtml(subTag)}</span>
    `;

    nodesContainer.appendChild(nodeEl);
    allPlacedNodes.push({
      id: on.id,
      data: on,
      el: nodeEl,
      layer: 'outer',
      baseXPct,
      baseYPct,
      curXPct: baseXPct,
      curYPct: baseYPct
    });
  });

  // Helper: Render & Position the Frosted-Glass Attached Note Card + Link Pill beside the focused node (Screenshot 5!)
  const refreshAttachedHud = (targetNodeData) => {
    if (!targetNodeData) {
      attachedHud.hidden = true;
      attachedHud.innerHTML = '';
      allPlacedNodes.forEach(p => p.el.classList.remove('is-locked-focus'));
      return;
    }

    const placed = allPlacedNodes.find(p => p.id === targetNodeData.id);
    if (!placed) {
      attachedHud.hidden = true;
      return;
    }

    allPlacedNodes.forEach(p => p.el.classList.toggle('is-locked-focus', p.id === targetNodeData.id));

    // Position HUD right alongside the focused file (to the right if file is on left/center, or to the left if near right edge)
    const xPct = placed.curXPct;
    const yPct = placed.curYPct;
    const placeOnLeft = xPct > 64;
    const hudLeftPct = placeOnLeft ? Math.max(4, xPct - 36) : Math.min(68, xPct + 6.5);
    const hudTopPct = Math.max(8, Math.min(78, yPct - 6));

    attachedHud.style.left = `${hudLeftPct.toFixed(1)}%`;
    attachedHud.style.top = `${hudTopPct.toFixed(1)}%`;
    attachedHud.hidden = false;

    // Resolve note text (either from vault item or custom Google Drive note dictionary)
    const rawNote = getAttachedNoteForNode(targetNodeData);
    const hasChecklist = rawNote.includes('[ ]') || rawNote.includes('[x]') || rawNote.includes('[X]');

    // Resolve link / domain label for bottom frosted pill
    let linkLabel = '';
    if (targetNodeData.link) {
      if (targetNodeData.link.startsWith('~') || targetNodeData.link.startsWith('/')) {
        const parts = targetNodeData.link.split('/').filter(Boolean);
        linkLabel = parts.slice(-2).join('/');
      } else {
        linkLabel = targetNodeData.link.replace(/^https?:\/\/(www\.)?/, '').split('/')[0];
      }
    } else if (targetNodeData.localPath) {
      const parts = targetNodeData.localPath.split('/').filter(Boolean);
      linkLabel = 'My Drive/' + parts.slice(-2).join('/');
    } else if (targetNodeData.section) {
      linkLabel = `${batch.title.slice(0, 18)} · ${targetNodeData.section}`;
    }

    const noteBodyHtml = hasChecklist
      ? `<div class="spatial-note-checklist">${renderChecklistHtml(rawNote)}</div>`
      : `
        <div
          class="spatial-note-body"
          contenteditable="true"
          spellcheck="false"
          data-placeholder="Click here to write a note or [ ] task attached to this file..."
          title="Click to edit note directly on this file"
        >${escapeHtml(rawNote)}</div>
      `;

    const curIgStat = targetNodeData.vaultItem?.igStatus || targetNodeData.igStatus || '';
    const isCmpSelected = isAssetCompareSelected(targetNodeData.id);

    attachedHud.innerHTML = `
      <!-- TOP FROSTED-GLASS NOTE CARD (Matches Screenshot 5) -->
      <div class="spatial-note-card">
        <div class="spatial-note-title" contenteditable="${targetNodeData.vaultItem ? 'true' : 'false'}" spellcheck="false" title="File Title">${escapeHtml(targetNodeData.title)}</div>
        ${noteBodyHtml}
      </div>

      <!-- BOTTOM FROSTED-GLASS LINK & ACTION PILL (Matches Screenshot 5) -->
      <div class="spatial-link-pill-row">
        ${targetNodeData.url ? `
          <button type="button" class="spatial-link-pill" id="btnHudSelectCompare" style="${isCmpSelected ? 'background:#111110;color:#FFF;' : ''}" title="Select this file for 1:1 Layer Stack / Split Comparison">
            <span>${isCmpSelected ? '✓ Selected' : '+ Compare'}</span>
          </button>
        ` : ''}
        ${targetNodeData.vaultItem && targetNodeData.url ? `
          <button type="button" class="spatial-link-pill" id="btnHudIgQueued" style="${curIgStat === 'queued' ? 'background:#D97706;color:#FFF;' : ''}" title="Flag as Queued (IG Ready / Next Up)">
            <span>◈ IG Ready</span>
          </button>
          <button type="button" class="spatial-link-pill" id="btnHudIgPublished" hidden style="${curIgStat === 'published' ? 'background:#10B981;color:#FFF;' : ''}" title="Flag as Published (IG Live)">
            <span>● IG Live</span>
          </button>
        ` : ''}
        ${(targetNodeData.link || targetNodeData.localPath) ? `
          <button type="button" class="spatial-link-pill" id="btnHudOpenLink" title="Open Link or Reveal in macOS Finder">
            <span class="pill-arrow">↗</span>
            <span>${escapeHtml(linkLabel || 'Open Reference')}</span>
          </button>
        ` : ''}
        ${targetNodeData.url ? `
          <a href="${escapeHtml(targetNodeData.url)}" download class="spatial-link-pill" title="Download Uncompressed Original File">
            <span class="pill-arrow">↓</span>
            <span>Original</span>
          </a>
        ` : ''}
        <button type="button" class="spatial-link-pill" id="btnHudAddChecklist" title="Append a [ ] checkbox task to this file's note">
          <span>+ [ ] Task</span>
        </button>
        ${targetNodeData.vaultItem ? `
          <button type="button" class="spatial-link-pill" id="btnHudFullInspect" title="Open Full Studio Inspector Modal">
            <span>⤢ Inspect</span>
          </button>
        ` : ''}
      </div>
    `;

    // Inline note editing directly inside the frosted-glass card!
    const noteBodyEl = attachedHud.querySelector('.spatial-note-body');
    if (noteBodyEl) {
      noteBodyEl.addEventListener('click', (e) => e.stopPropagation());
      noteBodyEl.addEventListener('keydown', (e) => {
        e.stopPropagation();
        if (e.key === 'Escape') noteBodyEl.blur();
      });
      noteBodyEl.addEventListener('blur', () => {
        const updatedText = noteBodyEl.innerText.trim();
        saveAttachedNoteForNode(targetNodeData, updatedText);
      });
    }

    // Inline title editing
    const titleEl = attachedHud.querySelector('.spatial-note-title');
    if (titleEl && targetNodeData.vaultItem) {
      titleEl.addEventListener('click', (e) => e.stopPropagation());
      titleEl.addEventListener('keydown', (e) => {
        e.stopPropagation();
        if (e.key === 'Enter') { e.preventDefault(); titleEl.blur(); }
      });
      titleEl.addEventListener('blur', () => {
        const newT = titleEl.innerText.trim();
        if (newT && targetNodeData.vaultItem) {
          targetNodeData.vaultItem.title = newT;
          targetNodeData.title = newT;
          saveVault('SAVED FILE TITLE');
        }
      });
    }

    // Interactive checkboxes inside the frosted-glass note card
    attachedHud.querySelectorAll('.chk-row input[type="checkbox"]').forEach(chk => {
      chk.addEventListener('click', (e) => {
        e.stopPropagation();
        const lineIdx = parseInt(chk.dataset.line, 10);
        if (targetNodeData.vaultItem) {
          toggleChecklistLine(targetNodeData.vaultItem.id, lineIdx);
          targetNodeData.notes = targetNodeData.vaultItem.notes;
          refreshAttachedHud(targetNodeData);
        }
      });
    });

    // + [ ] Task button appends a checkbox line to this file's attached note
    attachedHud.querySelector('#btnHudAddChecklist')?.addEventListener('click', (e) => {
      e.stopPropagation();
      const cur = getAttachedNoteForNode(targetNodeData);
      const next = (cur ? cur + '\n' : '') + '[ ] Follow-up studio step';
      saveAttachedNoteForNode(targetNodeData, next);
      refreshAttachedHud(targetNodeData);
    });

    // Open Link or Reveal in Finder button
    attachedHud.querySelector('#btnHudOpenLink')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (targetNodeData.localPath) {
        openUrlOrMacPath(targetNodeData.localPath);
      } else if (targetNodeData.link) {
        openUrlOrMacPath(targetNodeData.link);
      }
    });

    // Full Inspect modal button
    attachedHud.querySelector('#btnHudFullInspect')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (targetNodeData.vaultItem) {
        openItemInspector(targetNodeData.vaultItem.id);
      }
    });

    // Compare select toggle inside HUD
    attachedHud.querySelector('#btnHudSelectCompare')?.addEventListener('click', (e) => {
      e.stopPropagation();
      toggleCompareSelect({
        id: targetNodeData.id,
        title: targetNodeData.title || 'Visual',
        url: targetNodeData.url || targetNodeData.thumbSrc,
        kind: targetNodeData.kind || 'image',
        igStatus: targetNodeData.vaultItem?.igStatus || targetNodeData.igStatus || '',
        vaultItemId: targetNodeData.vaultItem?.id || null,
        notes: targetNodeData.notes || ''
      });
    });

    // 1-Click IG Ready & IG Live pills inside HUD
    attachedHud.querySelector('#btnHudIgQueued')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (targetNodeData.vaultItem) {
        const next = targetNodeData.vaultItem.igStatus === 'queued' ? '' : 'queued';
        setItemIgStatus(targetNodeData.vaultItem.id, next);
      }
    });

    attachedHud.querySelector('#btnHudIgPublished')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (targetNodeData.vaultItem) {
        const next = targetNodeData.vaultItem.igStatus === 'published' ? '' : 'published';
        setItemIgStatus(targetNodeData.vaultItem.id, next);
      }
    });
  };

  orb._refreshAttachedHud = refreshAttachedHud;

  // Spatial Spread + Proximity Fisheye Magnification Engine
  let pointerXPct = null;
  let pointerYPct = null;

  const updateSpatialPositions = () => {
    const zoom = isHeroStage ? (state.sphereZoom || 1) : 1;
    // As you zoom in past 1.0x, spread the files spatially outward so they breathe across the canvas like Screenshot 5
    const zoomSpread = 1 + Math.max(0, zoom - 1) * 0.58;

    let closestNode = null;
    let minDist = Infinity;

    if (pointerXPct !== null && pointerYPct !== null) {
      allPlacedNodes.forEach(n => {
        const sx = 50 + (n.baseXPct - 50) * zoomSpread;
        const sy = 50 + (n.baseYPct - 50) * zoomSpread;
        const d = Math.hypot(pointerXPct - sx, pointerYPct - sy);
        if (d < minDist) {
          minDist = d;
          closestNode = n;
        }
      });
    }

    const fisheyeRadiusPct = 25; // ~162px on a 650px sphere

    allPlacedNodes.forEach(n => {
      const spreadX = 50 + (n.baseXPct - 50) * zoomSpread;
      const spreadY = 50 + (n.baseYPct - 50) * zoomSpread;

      let tx = spreadX;
      let ty = spreadY;
      let scale = 1;
      let zIdx = n.layer === 'outer' ? 28 : 20;

      // Locked focus node stays prominently enlarged
      const isLocked = state.sphereLockedNodeId === n.id;

      if (pointerXPct !== null && pointerYPct !== null) {
        const dx = spreadX - pointerXPct;
        const dy = spreadY - pointerYPct;
        const dist = Math.hypot(dx, dy);

        if (dist < fisheyeRadiusPct) {
          const factor = 1 - (dist / fisheyeRadiusPct); // 0..1
          const eased = factor * factor * (3 - 2 * factor);

          if (n === closestNode && dist < 11.5) {
            // The exact file under your cursor pops up dramatically
            scale = n.layer === 'outer' ? 1.32 : 2.32;
            zIdx = 145;
          } else {
            // Neighboring batch files enlarge and push gently outward so nothing is hidden
            scale = 1 + eased * (n.layer === 'outer' ? 0.22 : 0.78);
            const pushPct = eased * 3.8;
            const angle = Math.atan2(dy, dx);
            tx += Math.cos(angle) * pushPct;
            ty += Math.sin(angle) * pushPct;
            zIdx = Math.round(45 + eased * 60);
          }
        }
      }

      if (isLocked) {
        scale = Math.max(scale, n.layer === 'outer' ? 1.28 : 1.95);
        zIdx = Math.max(zIdx, 138);
      }

      n.curXPct = tx;
      n.curYPct = ty;
      n.el.style.left = `${tx.toFixed(2)}%`;
      n.el.style.top = `${ty.toFixed(2)}%`;
      n.el.style.scale = scale.toFixed(3);
      n.el.style.zIndex = String(zIdx);
      n.el.classList.toggle('is-hovered-hero', n === closestNode && minDist < 11.5);
    });

    // Update attached HUD position if locked or if hovering while zoomed in
    if (state.sphereLockedNodeId) {
      const lockedData = allPlacedNodes.find(p => p.id === state.sphereLockedNodeId)?.data;
      if (lockedData && !attachedHud.contains(document.activeElement)) {
        refreshAttachedHud(lockedData);
      }
    } else if (closestNode && minDist < 10.5) {
      refreshAttachedHud(closestNode.data);
    } else if (!attachedHud.matches(':hover') && !attachedHud.contains(document.activeElement)) {
      refreshAttachedHud(null);
    }
  };

  orb._updateSpatialPositions = updateSpatialPositions;

  // Mousemove over the sphere drives the real-time proximity fisheye lens
  orb.addEventListener('mousemove', (e) => {
    if (e.target.closest('.spatial-attached-hud')) return;
    const rect = orb.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    pointerXPct = ((e.clientX - rect.left) / rect.width) * 100;
    pointerYPct = ((e.clientY - rect.top) / rect.height) * 100;
    updateSpatialPositions();
  });

  orb.addEventListener('mouseleave', () => {
    pointerXPct = null;
    pointerYPct = null;
    updateSpatialPositions();
  });

  // Node click behavior:
  // - Single click locks focus onto that file, zooms in smoothly if not yet zoomed so you see its attached note & link pill clearly!
  // - Clicking an already-focused file (or Double-clicking) opens the full Inspector / Finder / Link.
  allPlacedNodes.forEach(placed => {
    placed.el.addEventListener('click', (e) => {
      e.stopPropagation();

      // If this orb is in the multi-grid view, switch to Hero Constellation focused on this file
      if (!isHeroStage) {
        state.sphereActiveIndex = idx;
        state.sphereViewStyle = 'constellation';
        state.sphereLockedNodeId = placed.id;
        state.sphereZoom = 1.85;
        renderWorkspace();
        return;
      }

      if (state.sphereLockedNodeId === placed.id) {
        // Second click on the already-focused node opens full view or reveals in Finder
        if (placed.data.vaultItem) {
          openItemInspector(placed.data.vaultItem.id);
        } else if (placed.data.localPath) {
          openUrlOrMacPath(placed.data.localPath);
        } else if (placed.data.link) {
          openUrlOrMacPath(placed.data.link);
        }
        return;
      }

      state.sphereLockedNodeId = placed.id;
      if ((state.sphereZoom || 1) < 1.45) {
        state.sphereZoom = 1.75;
      }
      // Gently center camera toward the clicked node when zoomed in
      state.spherePanX = (50 - placed.baseXPct) * 3.2;
      state.spherePanY = (50 - placed.baseYPct) * 3.2;

      const viewport = orb.closest('.sphere-stage-viewport');
      if (viewport && viewport._updateCameraTransform) {
        viewport._updateCameraTransform();
      } else {
        updateSpatialPositions();
      }
      refreshAttachedHud(placed.data);
    });
  });

  const capTitleEl = orb.querySelector('.capsule-title');
  const capPenBtn = orb.querySelector('.capsule-edit-pen');
  const triggerCapsuleRename = (e) => {
    e.stopPropagation();
    if (!batch.onRename || !capTitleEl) return;
    promptInlineRename(capTitleEl, batch.title, (newVal) => {
      if (newVal.trim()) batch.onRename(newVal.trim());
    });
  };
  capPenBtn?.addEventListener('click', triggerCapsuleRename);
  capTitleEl?.addEventListener('click', triggerCapsuleRename);

  orb.querySelector('.btn-sphere-batch-proj')?.addEventListener('click', (e) => {
    e.stopPropagation();
    if (typeof batch.onTurnIntoProject === 'function') batch.onTurnIntoProject();
  });

  orb.querySelector('.btn-sphere-open-board')?.addEventListener('click', (e) => {
    e.stopPropagation();
    if (batch.onPrimaryOpen) batch.onPrimaryOpen();
    else if (batch.onPrimaryAction) batch.onPrimaryAction();
  });

  orb.querySelector('.sphere-bottom-capsule')?.addEventListener('click', (e) => {
    if (e.target.closest('.inline-rename-field') || e.target.closest('.capsule-edit-pen') || e.target.closest('.capsule-title')) return;
    e.stopPropagation();
    if (batch.onPrimaryOpen) batch.onPrimaryOpen();
    else if (batch.onPrimaryAction) batch.onPrimaryAction();
  });

  // If a node is already locked on boot/render, show its attached note HUD
  if (isHeroStage && state.sphereLockedNodeId) {
    const locked = allPlacedNodes.find(p => p.id === state.sphereLockedNodeId);
    if (locked) {
      requestAnimationFrame(() => refreshAttachedHud(locked.data));
    }
  }

  return orb;
}

function getAttachedNoteForNode(nodeData) {
  if (!nodeData) return '';
  if (nodeData.vaultItem) {
    return nodeData.vaultItem.notes || '';
  }
  if (nodeData.isGDrive && nodeData.localPath) {
    vault.gdriveNotes = vault.gdriveNotes || {};
    return vault.gdriveNotes[nodeData.localPath] || nodeData.notes || '';
  }
  return nodeData.notes || '';
}

function saveAttachedNoteForNode(nodeData, newNoteText) {
  if (!nodeData) return;
  nodeData.notes = newNoteText;
  if (nodeData.vaultItem) {
    nodeData.vaultItem.notes = newNoteText;
    saveVault('SAVED ATTACHED FILE NOTE');
  } else if (nodeData.isGDrive && nodeData.localPath) {
    vault.gdriveNotes = vault.gdriveNotes || {};
    vault.gdriveNotes[nodeData.localPath] = newNoteText;
    saveVault('SAVED NOTE ON DRIVE ASSET');
  }
}

function convertItemsToSphereLayerNodes(items) {
  const visualNodes = [];
  const outerNodes = [];
  (items || []).forEach(it => {
    const isVisual = Boolean(it.url && it.kind !== 'audio');
    if (isVisual) {
      visualNodes.push({
        id: it.id,
        kind: it.kind || 'image',
        title: it.title || 'Studio Visual',
        url: it.url,
        thumbSrc: it.url,
        notes: it.notes || '',
        link: it.link || '',
        section: it.section || '',
        igStatus: it.igStatus || '',
        badge: it.kind === 'video' ? '▶ VID' : '',
        vaultItem: it
      });
    } else {
      outerNodes.push({
        id: it.id,
        kind: it.kind || 'note',
        title: it.title || 'Studio Note',
        url: it.url || '',
        notes: it.notes || '',
        link: it.link || '',
        section: it.section || '',
        vaultItem: it
      });
    }
  });
  return { visualNodes, outerNodes };
}

/* --------------------------------------------------------------------------
   02 GOOGLE DRIVE, PSD ASSETS & ARCHIVE (Eagle-Style Visual Browser)
   -------------------------------------------------------------------------- */
function matchesGDriveFormatFilter(extStr, fmt) {
  if (!fmt || fmt === 'all') return true;
  const e = String(extStr || '').replace('.', '').toUpperCase();
  if (fmt === 'PSD') return e === 'PSD' || e === 'PSB';
  if (fmt === 'AI') return e === 'AI' || e === 'EPS';
  if (fmt === 'INDD') return e === 'INDD' || e === 'INDT' || e === 'IDML';
  if (fmt === 'IMG') return ['PNG', 'JPG', 'JPEG', 'WEBP', 'TIF', 'TIFF', 'SVG', 'PDF'].includes(e);
  if (fmt === 'MOTION') return ['GIF', 'MP4', 'MOV', 'WEBM'].includes(e);
  if (fmt === '3D') return ['OBJ', 'FBX', 'GLB', 'GLTF', 'C4D', 'BLEND', 'STL'].includes(e);
  return true;
}

function getClientAssetSpecimenSvg(name, ext, cat) {
  const cleanBase = (name || 'Untitled Asset').replace(/\.[^/.]+$/, '').replace(/[-_]/g, ' ').slice(0, 24);
  const safeTitle = escapeHtml(cleanBase);
  let rawExt = ((ext || 'FILE').replace('.', '').toUpperCase() || 'FILE').slice(0, 7);
  if (rawExt === 'FILE' && name && name.includes('.')) {
    rawExt = name.split('.').pop().toUpperCase().slice(0, 7);
  }
  const safeExt = escapeHtml(rawExt);

  let badgeBg = 'rgba(255, 255, 255, 0.08)';
  let badgeBorder = 'rgba(255, 255, 255, 0.16)';
  let badgeColor = '#D4CFC4';
  let badgeText = safeExt;
  let iconSvg = '';

  if (['OTF', 'TTF', 'WOFF', 'WOFF2'].includes(rawExt)) {
    badgeText = `TYPEFACE · ${safeExt}`;
    badgeBg = 'rgba(237, 234, 227, 0.08)';
    badgeBorder = 'rgba(237, 234, 227, 0.16)';
    badgeColor = '#D4CFC4';
    iconSvg = `
      <text x="150" y="135" text-anchor="middle" dominant-baseline="central" fill="#F0ECE1" font-family="Georgia, serif" font-size="64" font-weight="400">Ag</text>
      <line x1="60" y1="168" x2="240" y2="168" stroke="rgba(255,255,255,0.08)" stroke-width="1"/>
      <text x="150" y="184" text-anchor="middle" fill="#8E8B82" font-family="monospace" font-size="8.5" letter-spacing="1.5">A B C D E F G</text>
    `;
  } else if (['PSD', 'PSB'].includes(rawExt)) {
    badgeText = `PHOTOSHOP · ${safeExt}`;
    badgeBg = 'rgba(49, 168, 255, 0.12)';
    badgeBorder = 'rgba(49, 168, 255, 0.3)';
    badgeColor = '#31A8FF';
    iconSvg = `
      <g transform="translate(105, 88)">
        <rect x="0" y="0" width="90" height="80" rx="6" fill="#141412" stroke="rgba(49,168,255,0.3)" stroke-width="1.5"/>
        <text x="45" y="46" text-anchor="middle" dominant-baseline="central" fill="#31A8FF" font-family="-apple-system, sans-serif" font-size="28" font-weight="700">Ps</text>
      </g>
    `;
  } else if (['AI', 'EPS'].includes(rawExt)) {
    badgeText = `VECTOR · ${safeExt}`;
    badgeBg = 'rgba(255, 154, 0, 0.12)';
    badgeBorder = 'rgba(255, 154, 0, 0.3)';
    badgeColor = '#FFA629';
    iconSvg = `
      <g transform="translate(105, 88)">
        <rect x="0" y="0" width="90" height="80" rx="6" fill="#141412" stroke="rgba(255,154,0,0.3)" stroke-width="1.5"/>
        <text x="45" y="46" text-anchor="middle" dominant-baseline="central" fill="#FFA629" font-family="-apple-system, sans-serif" font-size="28" font-weight="700">Ai</text>
      </g>
    `;
  } else if (['INDD', 'INDT', 'IDML'].includes(rawExt)) {
    badgeText = `INDESIGN · ${safeExt}`;
    badgeBg = 'rgba(209, 46, 102, 0.14)';
    badgeBorder = 'rgba(209, 46, 102, 0.35)';
    badgeColor = '#FF4B8B';
    iconSvg = `
      <g transform="translate(105, 88)">
        <rect x="0" y="0" width="90" height="80" rx="6" fill="#141412" stroke="rgba(209,46,102,0.35)" stroke-width="1.5"/>
        <text x="45" y="46" text-anchor="middle" dominant-baseline="central" fill="#FF4B8B" font-family="-apple-system, sans-serif" font-size="28" font-weight="700">Id</text>
      </g>
    `;
  } else {
    badgeText = safeExt;
    iconSvg = `
      <g transform="translate(115, 92)">
        <rect x="0" y="0" width="70" height="70" rx="6" fill="#141412" stroke="rgba(255,255,255,0.14)" stroke-width="1.2"/>
        <text x="35" y="38" text-anchor="middle" dominant-baseline="central" fill="#D4CFC4" font-family="monospace" font-size="15" font-weight="600">${safeExt.slice(0, 4)}</text>
      </g>
    `;
  }

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 260" width="100%" height="100%">
    <rect width="300" height="260" fill="#10100E"/>
    <g transform="translate(16, 20)">
      <rect x="0" y="0" width="${badgeText.length * 7.5 + 16}" height="22" rx="3" fill="${badgeBg}" stroke="${badgeBorder}" stroke-width="1"/>
      <text x="${(badgeText.length * 7.5 + 16) / 2}" y="14" text-anchor="middle" fill="${badgeColor}" font-family="-apple-system, sans-serif" font-size="9" font-weight="600" letter-spacing="0.8">${badgeText}</text>
    </g>
    ${iconSvg}
    <g transform="translate(150, 222)">
      <text x="0" y="0" text-anchor="middle" fill="#EDEDE9" font-family="-apple-system, sans-serif" font-size="11" font-weight="500">${safeTitle}</text>
    </g>
  </svg>`;

  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

function getGDriveAssetThumbSrc(fileOrEx) {
  if (!fileOrEx) return '';
  const sid = fileOrEx.sid ? String(fileOrEx.sid) : '';
  const manifestThumb = (sid && window._IDEAL_ASSET_THUMBS_MANIFEST && window._IDEAL_ASSET_THUMBS_MANIFEST[sid]) ? window._IDEAL_ASSET_THUMBS_MANIFEST[sid] : null;
  const staticThumb = fileOrEx.staticThumbUrl || manifestThumb;

  const isStaticWeb = typeof window !== 'undefined' && (window.location.hostname.includes('github.io') || window.location.protocol === 'file:');
  if (isStaticWeb) {
    if (staticThumb) return staticThumb;
    return getClientAssetSpecimenSvg(fileOrEx.name, fileOrEx.ext, fileOrEx.category);
  }
  // On localhost/server, PREFER staticThumb or manifestThumb first so we NEVER hit server or disk!
  return staticThumb || fileOrEx.thumbUrl || getClientAssetSpecimenSvg(fileOrEx.name, fileOrEx.ext, fileOrEx.category);
}

function getGDriveAssetFallbackSrc(fileOrEx) {
  if (!fileOrEx) return '';
  const sid = fileOrEx.sid ? String(fileOrEx.sid) : '';
  const manifestThumb = (sid && window._IDEAL_ASSET_THUMBS_MANIFEST && window._IDEAL_ASSET_THUMBS_MANIFEST[sid]) ? window._IDEAL_ASSET_THUMBS_MANIFEST[sid] : null;
  const staticThumb = fileOrEx.staticThumbUrl || manifestThumb;
  if (staticThumb) return staticThumb;
  return getClientAssetSpecimenSvg(fileOrEx.name, fileOrEx.ext, fileOrEx.category);
}

function getEnclosingFolderSection(folderName) {
  const customMap = vault?.assetSections || vault?.customization?.assetSections || {};
  if (customMap[folderName]) {
    return customMap[folderName]; // 'assets' or 'vaults'
  }
  try {
    const raw = localStorage.getItem('ideal_asset_sections');
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed[folderName]) {
        vault.assetSections = vault.assetSections || {};
        vault.assetSections[folderName] = parsed[folderName];
        return parsed[folderName];
      }
    }
  } catch (e) {}

  const lower = String(folderName || '').toLowerCase().trim();
  if (
    lower.includes('vault') ||
    lower.includes('reference') ||
    lower.includes('inspo') ||
    lower.includes('logo') ||
    lower.includes('לוגו') ||
    lower.includes('palette') ||
    lower.includes('swatch') ||
    lower.includes('color') ||
    lower.includes('צבע') ||
    lower.includes('client') ||
    lower.includes('archive') ||
    lower.includes('brand')
  ) {
    return 'vaults';
  }
  return 'assets';
}

function setEnclosingFolderSection(folderName, targetSec) {
  if (!folderName) return;
  vault.assetSections = vault.assetSections || {};
  vault.assetSections[folderName] = targetSec;
  vault.customization = vault.customization || {};
  vault.customization.assetSections = vault.assetSections;
  try {
    localStorage.setItem('ideal_asset_sections', JSON.stringify(vault.assetSections));
  } catch (e) {}
  saveVault(`MOVED "${folderName}" TO ${targetSec.toUpperCase()}`);
}

function renderGDriveAssetsView(ws, spaceObj) {
  if (!state.gdriveStats.loaded && !state.gdriveStats.loading) {
    try {
    const cachedAssets = localStorage.getItem('ideal_gdrive_assets_cache');
    let parsed = null;
    if (cachedAssets) {
      try { parsed = JSON.parse(cachedAssets); } catch (e) {}
    }
    const hasSeedThumbs = typeof window !== 'undefined' && !!window._IDEAL_GDRIVE_SEED?.batches?.[0]?.examples?.[0]?.staticThumbUrl;
    const parsedHasThumbs = !!parsed?.batches?.[0]?.examples?.[0]?.staticThumbUrl;
    if ((!parsed || !Array.isArray(parsed.batches) || parsed.batches.length === 0 || !Array.isArray(parsed.enclosingFolders) || parsed.enclosingFolders.length === 0 || (hasSeedThumbs && !parsedHasThumbs)) && typeof window !== 'undefined' && window._IDEAL_GDRIVE_SEED) {
      parsed = window._IDEAL_GDRIVE_SEED;
    }
    if (parsed && Array.isArray(parsed.batches) && parsed.batches.length > 0) {
      state.gdriveBatches = parsed.batches;
      state.gdriveEnclosingFolders = parsed.enclosingFolders || [];
      state.gdriveCategoryLinks = parsed.categoryLinks || {};
      state.gdriveStats = {
        totalBatches: parsed.totalBatches || parsed.batches.length,
        totalFiles: parsed.totalFiles || 0,
        driveRoot: parsed.driveRoot || '',
        loading: false,
        loaded: true,
        lastSyncTs: 0
      };
    }
  } catch (e) {}

  fetchGDriveAssets(true);
  }
  if (state.gdriveStats.loading && state.gdriveBatches.length === 0) {
    ws.innerHTML = `
      <div style="padding:80px 0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;">
        <div class="ideal-subtle-loader-bar"></div>
      </div>
    `;
    return;
  }

  // Level 2: Inside a specific subfolder drill-down
  if (state.activeGDriveBatchId) {
    const targetBatch = state.gdriveBatches.find(b => b.id === state.activeGDriveBatchId);
    if (targetBatch) {
      renderGDriveFolderDrillDown(ws, targetBatch, spaceObj);
      return;
    } else {
      state.activeGDriveBatchId = null;
    }
  }

  // Level 1: Inside an enclosing folder (e.g. MOCKUPS, TEXTURES, ELEMENTS, etc.)
  const activeEncName = state.activeGDriveEnclosingFolder || (state.activeCategory && state.activeCategory !== 'All' && state.activeCategory !== 'All Asset Batches' ? state.activeCategory : null);
  if (activeEncName) {
    let encObj = (state.gdriveEnclosingFolders || []).find(e => (e.name || '').toLowerCase() === activeEncName.toLowerCase());
    if (!encObj) {
      const matching = (state.gdriveBatches || []).filter(b => {
        const bEnc = (b.enclosingFolder || '').toLowerCase();
        const bRel = (b.relPath || '').toLowerCase();
        return bEnc === activeEncName.toLowerCase() || bRel.startsWith(`assets/${activeEncName.toLowerCase()}/`);
      });
      if (matching.length > 0) {
        encObj = {
          name: matching[0].enclosingFolder || activeEncName,
          subfolderCount: matching.length,
          totalCount: matching.reduce((acc, b) => acc + (b.totalCount || 0), 0),
          driveFolderUrl: matching[0].driveFolderUrl || '',
          localFolder: `${state.gdriveStats?.driveRoot || '~/Library/CloudStorage/GoogleDrive/My Drive'}/ASSETS/${matching[0].enclosingFolder || activeEncName}`,
          examples: matching.flatMap(b => b.examples || []).slice(0, 10)
        };
      }
    }
    if (encObj) {
      renderGDriveEnclosingFolderView(ws, encObj, spaceObj);
      return;
    }
  }

  // Level 0: Front Page showing the enclosing folders in ASSETS divided into Assets & Vaults
  renderGDriveRootEnclosingView(ws, spaceObj);
}

function renderGDriveRootEnclosingView(ws, spaceObj) {
  const GDRIVE_ROOT_SNAP_SIZES = [160, 195, 230, 280, 360];
  const step = Math.max(1, Math.min(5, spaceObj?.ui?.scaleStep || state.gdriveScaleStep || 3));
  state.gdriveScaleStep = step;
  if (spaceObj) {
    spaceObj.ui = spaceObj.ui || {};
    spaceObj.ui.scaleStep = step;
  }
  const colWidth = GDRIVE_ROOT_SNAP_SIZES[step - 1] || 230;

  const topSizeSlider = document.getElementById('sizeSlider');
  if (topSizeSlider) {
    topSizeSlider.min = "1";
    topSizeSlider.max = "5";
    topSizeSlider.step = "1";
    topSizeSlider.value = String(step);
  }
  const currentTab = state.gdriveDashboardViewMode || 'default';
  const searchQ = (state.searchQuery || '').trim().toLowerCase();

  let enclosingList = [...(state.gdriveEnclosingFolders || [])];

  if (enclosingList.length === 0 && state.gdriveBatches && state.gdriveBatches.length > 0) {
    const encMap = new Map();
    state.gdriveBatches.forEach(b => {
      const name = b.enclosingFolder || 'ASSETS';
      if (!encMap.has(name)) {
        encMap.set(name, {
          id: `enc_${name.toLowerCase()}`,
          name,
          subfolderCount: 0,
          totalCount: 0,
          driveFolderUrl: b.driveFolderUrl || '',
          localFolder: `${state.gdriveStats?.driveRoot || '~/Library/CloudStorage/GoogleDrive/My Drive'}/ASSETS/${name}`,
          examples: []
        });
      }
      const item = encMap.get(name);
      item.subfolderCount++;
      item.totalCount += (b.totalCount || 0);
      if (item.examples.length < 8 && Array.isArray(b.examples)) {
        item.examples.push(...b.examples.slice(0, 8 - item.examples.length));
      }
    });
    enclosingList = Array.from(encMap.values());
    state.gdriveEnclosingFolders = enclosingList;
  }

  if (searchQ) {
    enclosingList = enclosingList.filter(enc => {
      const nameMatch = enc.name.toLowerCase().includes(searchQ);
      const exMatch = (enc.examples || []).some(ex => (ex.name || '').toLowerCase().includes(searchQ));
      const subMatch = state.gdriveBatches.some(b => b.enclosingFolder === enc.name && (b.title || '').toLowerCase().includes(searchQ));
      return nameMatch || exMatch || subMatch;
    });
  }

  // Partition into two UI sections: Assets & Vaults (100% interface division, zero disk impact)
  let assetsList = enclosingList.filter(enc => getEnclosingFolderSection(enc.name) === 'assets');
  let vaultsList = enclosingList.filter(enc => getEnclosingFolderSection(enc.name) === 'vaults');

  const sortSectionList = (list) => {
    if (currentTab === 'alpha') {
      list.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    } else if (currentTab === 'size') {
      list.sort((a, b) => (b.totalCount || 0) - (a.totalCount || 0));
    } else {
      let savedEnclosingOrder = vault?.customization?.enclosingOrder;
      if (!Array.isArray(savedEnclosingOrder) || savedEnclosingOrder.length === 0) {
        try {
          const raw = localStorage.getItem('ideal_gdrive_enclosing_order');
          if (raw) savedEnclosingOrder = JSON.parse(raw);
        } catch (e) {}
      }
      if (Array.isArray(savedEnclosingOrder) && savedEnclosingOrder.length > 0) {
        const orderMap = new Map();
        savedEnclosingOrder.forEach((name, idx) => orderMap.set(String(name).toLowerCase(), idx));
        list.sort((a, b) => {
          const idxA = orderMap.has(String(a.name).toLowerCase()) ? orderMap.get(String(a.name).toLowerCase()) : 9999;
          const idxB = orderMap.has(String(b.name).toLowerCase()) ? orderMap.get(String(b.name).toLowerCase()) : 9999;
          return idxA - idxB;
        });
      }
    }
  };

  sortSectionList(assetsList);
  sortSectionList(vaultsList);

  // Keep top bar categories in exact sync with dashboard card order
  const syncedEnclosing = [...assetsList, ...vaultsList];
  if (syncedEnclosing.length > 0) {
    state.gdriveEnclosingFolders = syncedEnclosing;
    const gdriveSp = spaceObj || vault.spaces.find(s => s.id === 'gdrive_assets');
    if (gdriveSp) {
      const desiredTabs = ['All', ...syncedEnclosing.map(e => e.name)];
      if (JSON.stringify(gdriveSp.categories) !== JSON.stringify(desiredTabs)) {
        gdriveSp.categories = desiredTabs;
        renderFilterActionRow();
      }
    }
  }

  const assetsLane = getActiveGDriveLaneInfo('All');
  const totalAssetsFiles = (state.gdriveStats?.totalFiles) || state.gdriveBatches.reduce((acc, b) => acc + (b.totalCount || 0), 0);

  // Set current eagle asset list to all examples across enclosing folders so Spacebar Quick Look navigation works
  const allExamples = [];
  [...assetsList, ...vaultsList].forEach(enc => {
    (enc.examples || []).forEach((ex, idx) => {
      const extUpper = (ex.ext || '').replace('.', '').toUpperCase();
      allExamples.push({
        id: `${enc.id}_ex_${ex.sid || idx}`,
        title: ex.name,
        rawName: ex.name,
        category: enc.name,
        ext: extUpper,
        cid: ex.cid,
        kind: ['MP4', 'MOV', 'WEBM'].includes(extUpper) ? 'video' : 'image',
        thumbSrc: getGDriveAssetThumbSrc(ex),
        fallbackSrc: getGDriveAssetFallbackSrc(ex),
        driveEmbedUrl: ex.driveEmbedUrl,
        driveDownloadUrl: ex.driveDownloadUrl,
        localPath: ex.localPath,
        driveWebUrl: ex.driveWebUrl || enc.driveFolderUrl,
        sizeLabel: ex.sizeLabel || extUpper
      });
    });
  });
  state.currentEagleAssetList = allExamples;

  const showAssetsSection = (currentTab !== 'vaults');
  const showVaultsSection = (currentTab !== 'assets');
  const showDivider = (showAssetsSection && showVaultsSection);

  ws.innerHTML = `
    <div class="eagle-browser-shell">
      <div class="minimal-inline-subbar">
        <div class="subbar-group">
          <span class="quiet-subbar-title subbar-title-unified">Dashboard</span>
        </div>

        <span class="quiet-sep">·</span>

        <div class="subbar-group">
          <button type="button" class="quiet-subbar-link ${currentTab === 'default' ? 'active' : ''}" data-root-tab="default" title="Default order">Default</button>
          <button type="button" class="quiet-subbar-link ${currentTab === 'assets' ? 'active' : ''}" data-root-tab="assets" title="Show Assets only">Assets</button>
          <button type="button" class="quiet-subbar-link ${currentTab === 'vaults' ? 'active' : ''}" data-root-tab="vaults" title="Show Vaults only">Vaults</button>
          <button type="button" class="quiet-subbar-link ${currentTab === 'alpha' ? 'active' : ''}" data-root-tab="alpha" title="Sort A–Z">A–Z</button>
          <button type="button" class="quiet-subbar-link ${currentTab === 'size' ? 'active' : ''}" data-root-tab="size" title="Sort by Size">Size</button>
        </div>

        <div class="subbar-group quiet-subbar-actions" style="margin-left:auto;gap:8px;display:inline-flex;align-items:center;">
          <a href="${escapeHtml(assetsLane.driveFolderUrl)}" target="_blank" rel="noopener" class="quiet-subbar-link quiet-subbar-action-link" title="Show ASSETS in Google Drive">Show in Drive</a>
          <span class="quiet-subbar-sep">|</span>
          <button type="button" class="quiet-subbar-link quiet-subbar-action-link" id="btnAssetsFinder" title="Open ASSETS folder in Finder">Show in Finder</button>
        </div>
      </div>

      <div id="gdriveRootStage" style="display:flex;flex-direction:column;gap:16px;padding-bottom:50px;">
        ${showAssetsSection ? `
        <!-- SECTION 1: ASSETS -->
        <section class="asset-dashboard-section" data-section-name="assets">
          <div class="asset-section-header">
            <div class="asset-section-title-wrap">
              <h3 class="asset-section-title">Assets</h3>
              <span class="asset-section-count">${assetsList.length} ${assetsList.length === 1 ? 'folder' : 'folders'}</span>
            </div>
            <div class="asset-section-actions">
              <button type="button" class="btn-add-folder" data-target-section="assets" title="Add new Asset folder in Google Drive">+ Add Folder</button>
            </div>
          </div>
          <div class="gdrive-files-grid is-uniform" id="gridAssets" data-section="assets" style="--eagle-col-width: ${colWidth}px;"></div>
        </section>
        ` : ''}

        ${showDivider ? `<div class="asset-section-divider"></div>` : ''}

        ${showVaultsSection ? `
        <!-- SECTION 2: VAULTS -->
        <section class="asset-dashboard-section" data-section-name="vaults">
          <div class="asset-section-header">
            <div class="asset-section-title-wrap">
              <h3 class="asset-section-title">Vaults</h3>
              <span class="asset-section-count">${vaultsList.length} ${vaultsList.length === 1 ? 'folder' : 'folders'}</span>
            </div>
            <div class="asset-section-actions">
              <button type="button" class="btn-add-folder" data-target-section="vaults" title="Add new Vault folder in Google Drive">+ Add Folder</button>
            </div>
          </div>
          <div class="gdrive-files-grid is-uniform" id="gridVaults" data-section="vaults" style="--eagle-col-width: ${colWidth}px;"></div>
        </section>
        ` : ''}
      </div>
    </div>
  `;

  ws.querySelectorAll('[data-root-tab]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.gdriveDashboardViewMode = btn.dataset.rootTab;
      renderWorkspace();
    });
  });

  ws.querySelector('#btnAssetsFinder')?.addEventListener('click', () => {
    revealItemInFinder(assetsLane.localFolder);
  });

  const gridAssets = ws.querySelector('#gridAssets');
  const gridVaults = ws.querySelector('#gridVaults');
  const currentScaleStep = state.gdriveScaleStep || 3;
  if (gridAssets) gridAssets.dataset.scaleStep = String(currentScaleStep);
  if (gridVaults) gridVaults.dataset.scaleStep = String(currentScaleStep);

  if (assetsList.length === 0 && gridAssets) {
    gridAssets.innerHTML = `<div style="grid-column: 1 / -1; padding: 18px 14px; text-align: center; color: var(--text-faint); font-size: 11px; font-family: var(--font-mono); background: color-mix(in srgb, var(--text) 2%, transparent); border-radius: 8px;">No folders in Assets. Drag folders here or click + Add Folder.</div>`;
  } else if (gridAssets) {
    assetsList.forEach((enc, idx) => gridAssets.appendChild(buildGDriveEnclosingCardEl(enc, idx)));
  }

  if (vaultsList.length === 0 && gridVaults) {
    gridVaults.innerHTML = `<div style="grid-column: 1 / -1; padding: 18px 14px; text-align: center; color: var(--text-faint); font-size: 11px; font-family: var(--font-mono); background: color-mix(in srgb, var(--text) 2%, transparent); border-radius: 8px;">No folders in Vaults. Drag folders here or click + Add Folder.</div>`;
  } else if (gridVaults) {
    vaultsList.forEach((enc, idx) => gridVaults.appendChild(buildGDriveEnclosingCardEl(enc, idx)));
  }

  // Bind + Add Folder buttons
  ws.querySelectorAll('.btn-add-folder').forEach(btn => {
    btn.addEventListener('click', async (e) => {
      e.stopPropagation();
      const targetSec = btn.dataset.targetSection;
      const label = targetSec === 'assets' ? 'Assets' : 'Vaults';
      const folderName = prompt(`Create new folder in ${label}:`);
      if (!folderName || !folderName.trim()) return;
      const cleanName = folderName.trim();

      try {
        const res = await fetch('/api/gdrive/create-folder', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ parentPath: assetsLane.localFolder, folderName: cleanName })
        });
        const data = await res.json();
        if (!res.ok || !data.ok) {
          alert(data.error || 'Failed to create folder');
          return;
        }

        setEnclosingFolderSection(cleanName, targetSec);

        const currentOrder = vault.customization.enclosingOrder || state.gdriveEnclosingFolders.map(x => x.name);
        if (!currentOrder.includes(cleanName)) {
          currentOrder.push(cleanName);
          vault.customization.enclosingOrder = currentOrder;
          localStorage.setItem('ideal_gdrive_enclosing_order', JSON.stringify(currentOrder));
        }

        saveVault(`CREATED FOLDER "${cleanName}"`);
        showStatusToast(`Created "${cleanName}" in ${label}`);
        await fetchGDriveAssets(true);
        renderFilterActionRow();
        renderWorkspace();
      } catch (err) {
        alert('Create folder error: ' + err.message);
      }
    });
  });

  // Enable dragging cards directly into an empty or populated section grid (100% UI only, zero disk change)
  [gridAssets, gridVaults].forEach(grid => {
    if (!grid) return;
    const secEl = grid.closest('.asset-dashboard-section');
    grid.addEventListener('dragover', (e) => {
      if (!e.dataTransfer.types.includes('application/x-ideal-enclosing')) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      secEl?.classList.add('is-drag-over-section');
    });
    grid.addEventListener('dragleave', (e) => {
      if (!grid.contains(e.relatedTarget)) {
        secEl?.classList.remove('is-drag-over-section');
      }
    });
    grid.addEventListener('drop', (e) => {
      secEl?.classList.remove('is-drag-over-section');
      if (e.target.closest('.gdrive-enclosing-card')) return;
      const sourceName = e.dataTransfer.getData('application/x-ideal-enclosing');
      if (!sourceName) return;
      e.preventDefault();
      e.stopPropagation();

      const targetSec = grid.dataset.section;
      setEnclosingFolderSection(sourceName, targetSec);

      const currentList = [...(state.gdriveEnclosingFolders || [])];
      const srcIdx = currentList.findIndex(x => x.name === sourceName);
      if (srcIdx !== -1) {
        const [item] = currentList.splice(srcIdx, 1);
        let lastIdx = -1;
        currentList.forEach((x, idx) => {
          if (getEnclosingFolderSection(x.name) === targetSec) lastIdx = idx;
        });
        if (lastIdx !== -1) {
          currentList.splice(lastIdx + 1, 0, item);
        } else {
          currentList.push(item);
        }
        state.gdriveEnclosingFolders = currentList;
        const newNamesOrder = currentList.map(x => x.name);
        localStorage.setItem('ideal_gdrive_enclosing_order', JSON.stringify(newNamesOrder));
        vault.customization.enclosingOrder = newNamesOrder;
        const gdriveSp = vault.spaces.find(s => s.id === 'gdrive_assets');
        if (gdriveSp) {
          gdriveSp.categories = ['All', ...newNamesOrder];
        }
        saveVault(`MOVED "${sourceName}" TO ${targetSec.toUpperCase()}`);
        renderFilterActionRow();
        renderWorkspace();
        showStatusToast(`Moved "${sourceName}" to ${targetSec === 'assets' ? 'Assets' : 'Vaults'}`);
      }
    });
  });
}

function showStatusToast(message) {
  let toast = document.getElementById('idealGlobalToast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'idealGlobalToast';
    toast.style.cssText = `
      position: fixed;
      bottom: 24px;
      right: 24px;
      background: rgba(18, 18, 17, 0.94);
      color: #f5f4f0;
      border: 1px solid rgba(255, 255, 255, 0.16);
      padding: 9px 16px;
      border-radius: 8px;
      font-family: var(--font-mono);
      font-size: 11px;
      font-weight: 600;
      z-index: 99999;
      box-shadow: 0 8px 24px rgba(0,0,0,0.4);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      pointer-events: none;
      transition: opacity 0.2s ease, transform 0.2s ease;
      opacity: 0;
      transform: translateY(8px);
    `;
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.style.opacity = '1';
  toast.style.transform = 'translateY(0)';
  clearTimeout(toast._hideTimer);
  toast._hideTimer = setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(8px)';
  }, 2500);
}

async function renameGDriveItemOnDisk(itemPath, newName, isFolder = false) {
  if (!itemPath || !newName) return null;
  const clean = newName.trim();
  let finalName = clean;
  if (!isFolder && itemPath.includes('.')) {
    const ext = '.' + itemPath.split('.').pop();
    if (ext && !clean.toLowerCase().endsWith(ext.toLowerCase())) {
      finalName = clean + ext;
    }
  }
  try {
    const res = await fetch('/api/gdrive/rename', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ oldPath: itemPath, newName: finalName })
    });
    const data = await res.json();
    if (!res.ok || !data.ok) {
      alert(data.error || 'Failed to rename item');
      return null;
    }
    showStatusToast(`Renamed ${isFolder ? 'folder' : 'file'} to "${finalName}"`);
    await fetchGDriveAssets(true);
    return data.newPath;
  } catch (err) {
    alert('Rename error: ' + err.message);
    return null;
  }
}

async function moveGDriveItemOnDisk(sourcePath, targetFolderPath) {
  if (!sourcePath || !targetFolderPath) return false;
  try {
    const res = await fetch('/api/gdrive/move', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sourcePath, targetFolderPath })
    });
    const data = await res.json();
    if (!res.ok || !data.ok) {
      alert(data.error || 'Failed to move item');
      return false;
    }
    const fileName = sourcePath.split('/').pop();
    const folderName = targetFolderPath.split('/').pop();
    showStatusToast(`Moved "${fileName}" to "${folderName}"`);
    await fetchGDriveAssets(true);
    return true;
  } catch (err) {
    alert('Move error: ' + err.message);
    return false;
  }
}

async function createGDriveSubfolderOnDisk(parentPath, folderName) {
  if (!parentPath || !folderName) return null;
  try {
    const res = await fetch('/api/gdrive/create-folder', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ parentPath, folderName })
    });
    const data = await res.json();
    if (!res.ok || !data.ok) {
      alert(data.error || 'Failed to create folder');
      return null;
    }
    showStatusToast(`Created folder "${folderName}"`);
    return data.folderPath;
  } catch (err) {
    alert('Create folder error: ' + err.message);
    return null;
  }
}

function renderGDriveEnclosingFolderView(ws, encObj, spaceObj) {
  // Live background refresh to immediately reflect Finder/Drive renames and moves
  const now = Date.now();
  if (now - (state.gdriveStats.lastSyncTs || 0) > 1000 && !state.gdriveStats.loading) {
    fetchGDriveAssets(true).then(() => {
      const currentActiveEnc = state.activeGDriveEnclosingFolder || (state.activeCategory && state.activeCategory !== 'All' && state.activeCategory !== 'All Asset Batches' ? state.activeCategory : null);
      if (currentActiveEnc && currentActiveEnc.toLowerCase() === (encObj.name || '').toLowerCase()) {
        renderWorkspace();
      }
    }).catch(() => {});
  }

  const fmt = state.eagleFormatFilter || 'all';
  const sortBy = state.gdriveDrillSort || 'default';
  const GDRIVE_SNAP_SIZES = [75, 100, 130, 165, 210];
  const step = Math.max(1, Math.min(5, spaceObj?.ui?.scaleStep || state.gdriveScaleStep || 3));
  state.gdriveScaleStep = step;
  if (spaceObj) {
    spaceObj.ui = spaceObj.ui || {};
    spaceObj.ui.scaleStep = step;
  }
  const colWidth = GDRIVE_SNAP_SIZES[step - 1] || 130;
  state.gdriveSubfolderCardSize = colWidth;
  const searchQ = (state.searchQuery || '').trim().toLowerCase();

  // Helper to cleanly strip redundant enclosing folder prefixes ("Mockups — ", "MOCKUPS - ", etc.)
  function formatCleanSubfolderTitle(rawTitle) {
    if (!rawTitle) return '';
    let t = rawTitle;
    const encName = encObj.name || '';
    const encEscaped = encName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const patterns = [
      new RegExp(`^${encEscaped}\\s*[—\\-–:/]\\s*`, 'i'),
      /^(mockups|textures|elements|fonts|unsorted|halloween madness)\s*[—\\-–:/]\s*/i
    ];
    for (const pat of patterns) {
      t = t.replace(pat, '');
    }
    return t.trim() || rawTitle;
  }

  // Clean up any existing window scroll spy listener from prior render
  if (window._gdriveScrollSpyCleaner) {
    window._gdriveScrollSpyCleaner();
    window._gdriveScrollSpyCleaner = null;
  }

  // Sync the top HUD slider: snappy 5 stages, default 3 (130px) right in the middle
  const topSizeSlider = document.getElementById('sizeSlider');
  if (topSizeSlider) {
    topSizeSlider.min = "1";
    topSizeSlider.max = "5";
    topSizeSlider.step = "1";
    topSizeSlider.value = String(step);
  }

  // Find all batches belonging to this enclosing folder
  const targetEncName = (encObj.name || '').toLowerCase();
  const matchingBatches = state.gdriveBatches.filter(b => {
    const bEnc = (b.enclosingFolder || '').toLowerCase();
    const bCat = (b.category || '').toLowerCase();
    const bRel = (b.relPath || '').toLowerCase();
    return bEnc === targetEncName || bCat === targetEncName || bRel.startsWith(`assets/${targetEncName}/`) || bRel.includes(`/${targetEncName}/`);
  });

  // Load custom user arrangement if saved
  const subfolderOrderKey = `ideal_gdrive_subfolder_order_${encObj.name}`;
  let savedSubfolderOrder = [];
  try {
    const rawOrder = localStorage.getItem(subfolderOrderKey);
    if (rawOrder) savedSubfolderOrder = JSON.parse(rawOrder);
  } catch (e) {}

  let filteredBatches = matchingBatches.filter(b => {
    if (fmt !== 'all') {
      const typesMatch = (b.fileTypes || []).some(t => matchesGDriveFormatFilter(t, fmt));
      const exMatch = (b.examples || []).some(ex => matchesGDriveFormatFilter(ex.ext, fmt));
      if (!typesMatch && !exMatch) return false;
    }
    if (searchQ) {
      const hay = `${b.title} ${b.relPath} ${b.category} ${(b.fileTypes || []).join(' ')}`.toLowerCase();
      if (!hay.includes(searchQ)) return false;
    }
    return true;
  });

  if (sortBy === 'alpha') {
    filteredBatches.sort((a, b) => (a.title || '').localeCompare(b.title || ''));
  } else if (sortBy === 'size') {
    filteredBatches.sort((a, b) => (b.totalBytes || b.totalCount || 0) - (a.totalBytes || a.totalCount || 0));
  } else if (sortBy === 'type') {
    filteredBatches.sort((a, b) => ((a.fileTypes && a.fileTypes[0]) || '').localeCompare((b.fileTypes && b.fileTypes[0]) || ''));
  } else if (Array.isArray(savedSubfolderOrder) && savedSubfolderOrder.length > 0) {
    const orderMap = new Map();
    savedSubfolderOrder.forEach((id, idx) => orderMap.set(id, idx));
    filteredBatches.forEach((b, origIdx) => { b._origIndex = origIdx; });
    filteredBatches.sort((a, b) => {
      const getPos = (item) => {
        if (orderMap.has(item.id)) return orderMap.get(item.id);
        if (orderMap.has(item.relPath)) return orderMap.get(item.relPath);
        if (orderMap.has(item.title)) return orderMap.get(item.title);
        return item._origIndex ?? 9999;
      };
      return getPos(a) - getPos(b);
    });
  }

  // Flatten all files for Quick Look sequence
  let allFilesForNav = [];
  filteredBatches.forEach(b => {
    (b.examples || []).forEach((ex, idx) => {
      const ext = (ex.ext || '').replace('.', '').toUpperCase() || 'FILE';
      if (fmt !== 'all' && !matchesGDriveFormatFilter(ext, fmt)) return;
      allFilesForNav.push({
        id: `${b.id}_ex_${ex.sid || idx}`,
        title: ex.name,
        rawName: ex.name,
        category: b.title,
        batchId: b.id,
        ext,
        cid: ex.cid,
        kind: ['MP4', 'MOV', 'WEBM'].includes(ext) ? 'video' : 'image',
        thumbSrc: getGDriveAssetThumbSrc(ex),
        fallbackSrc: getGDriveAssetFallbackSrc(ex),
        driveEmbedUrl: ex.driveEmbedUrl,
        driveDownloadUrl: ex.driveDownloadUrl,
        localPath: ex.localPath,
        driveWebUrl: ex.driveWebUrl || ex.driveUrl || b.driveFolderUrl,
        size: ex.size || 0,
        sizeLabel: ex.sizeLabel || ext,
        notes: `My Drive/${b.relPath}`
      });
    });
  });
  state.currentEagleAssetList = allFilesForNav;

  const totalFilesCount = matchingBatches.reduce((acc, b) => acc + (b.totalCount || (b.examples || []).length || 0), 0);

  ws.innerHTML = `
    <div class="eagle-browser-shell">
      <div class="gdrive-creative-shell">
        <div class="gdrive-creative-main">
          <!-- Enclosing Folder Bar (connected at top with right sidebar, redundant Drive/Finder buttons removed) -->
          <div class="gdrive-folder-drill-bar">
            <div class="gdrive-drill-top-row">
              <div class="gdrive-drill-left">
                <div class="gdrive-drill-title-wrap">
                  <h3 class="gdrive-drill-title">${escapeHtml(encObj.name)}</h3>
                  <span class="gdrive-drill-sub">${matchingBatches.length} subfolders · ${totalFilesCount} files</span>
                </div>
              </div>
            </div>

            <div class="gdrive-drill-bottom-row">
              <div class="subbar-group">
                <button type="button" class="quiet-subbar-link ${fmt === 'all' ? 'active' : ''}" data-enc-fmt="all">All</button>
                <button type="button" class="quiet-subbar-link ${fmt === 'PSD' ? 'active' : ''}" data-enc-fmt="PSD">PSD</button>
                <button type="button" class="quiet-subbar-link ${fmt === 'AI' ? 'active' : ''}" data-enc-fmt="AI">AI</button>
                <button type="button" class="quiet-subbar-link ${fmt === 'INDD' ? 'active' : ''}" data-enc-fmt="INDD">INDD</button>
                <button type="button" class="quiet-subbar-link ${fmt === 'IMG' ? 'active' : ''}" data-enc-fmt="IMG">Image</button>
                <button type="button" class="quiet-subbar-link ${fmt === 'MOTION' ? 'active' : ''}" data-enc-fmt="MOTION">Motion</button>
                <button type="button" class="quiet-subbar-link ${fmt === '3D' ? 'active' : ''}" data-enc-fmt="3D">3D</button>
              </div>

              <span class="quiet-sep">·</span>

              <div class="subbar-group">
                <button type="button" class="quiet-subbar-link ${sortBy === 'default' ? 'active' : ''}" data-enc-sort="default" title="Default order">Default</button>
                <button type="button" class="quiet-subbar-link ${sortBy === 'alpha' ? 'active' : ''}" data-enc-sort="alpha" title="Sort A–Z">A–Z</button>
                <button type="button" class="quiet-subbar-link ${sortBy === 'size' ? 'active' : ''}" data-enc-sort="size" title="Sort by total files">Size</button>
              </div>
            </div>
          </div>

          <div class="gdrive-creative-sections" id="creativeMainArea">
            ${filteredBatches.length === 0 ? `
              <div style="padding:48px 24px;text-align:center;background:var(--surface);border:1px solid var(--border);border-radius:14px;">
                <div class="kicker-mono">NO SUBFOLDERS MATCH THIS FILTER</div>
                <p class="typewriter" style="font-size:12px;color:var(--text-mid);margin-top:6px;">Switch format back to All to view all ${matchingBatches.length} subfolders in ${escapeHtml(encObj.name)}.</p>
              </div>
            ` : ''}
          </div>
        </div>

        <aside class="gdrive-creative-sidebar" id="creativeRightSidebar">
          <div class="gdrive-sidebar-meta-row">
            <div class="gdrive-sidebar-label-wrap">
              <span class="gdrive-sidebar-section-label">Subfolders</span>
              <span class="gdrive-sidebar-total-badge">${matchingBatches.length}</span>
            </div>
            <button type="button" class="gdrive-sidebar-add-pill" id="btnSidebarAddSubfolder" title="Create new subfolder on Google Drive">+ Add</button>
          </div>

          <div class="gdrive-sidebar-list" id="sidebarSubfoldersList"></div>

          <div class="gdrive-sidebar-nav-footer">
            <button type="button" class="gdrive-sidebar-jump-link" id="btnSidebarJumpUp" title="Scroll back to top of subfolders">
              <span class="jump-arrow">↑</span>
              <span>Jump to Top</span>
            </button>
          </div>
        </aside>
      </div>
    </div>
  `;

  ws.querySelector('#btnSidebarJumpUp')?.addEventListener('click', (e) => {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: 'smooth' });
    document.documentElement.scrollTo({ top: 0, behavior: 'smooth' });
    document.body.scrollTo({ top: 0, behavior: 'smooth' });
  });



  ws.querySelectorAll('[data-enc-fmt]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.eagleFormatFilter = btn.dataset.encFmt;
      saveNavState();
      renderWorkspace();
    });
  });

  ws.querySelectorAll('[data-enc-sort]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.gdriveDrillSort = btn.dataset.encSort;
      renderWorkspace();
    });
  });

  const mainArea = ws.querySelector('#creativeMainArea');
  const sidebarList = ws.querySelector('#sidebarSubfoldersList');

  // Handle + Add subfolder in right sidebar
  ws.querySelector('#btnSidebarAddSubfolder')?.addEventListener('click', (e) => {
    promptInlineRename(e.currentTarget, 'New Subfolder', async (newVal) => {
      const cleanName = newVal.trim();
      if (!cleanName) return;
      const createdPath = await createGDriveSubfolderOnDisk(encObj.localFolder, cleanName);
      if (createdPath) {
        const newBatchId = 'gdb_' + Date.now();
        state.gdriveBatches.unshift({
          id: newBatchId,
          title: cleanName,
          category: encObj.name,
          enclosingFolder: encObj.name,
          relPath: `${encObj.relPath}/${cleanName}`,
          localFolder: createdPath,
          driveFolderUrl: encObj.driveFolderUrl,
          totalCount: 0,
          fileTypes: [],
          examples: []
        });
        encObj.subfolderCount = (encObj.subfolderCount || 0) + 1;
        renderWorkspace();
      }
    });
  });

  // Subfolder scrolling helper: smooth scroll with sticky header clearance (no jumping or flickering)
  let isProgrammaticScrolling = false;
  let unlockScrollSpyTimer = null;
  let scrollSpyRaf = null;

  function scrollToSubfolderSection(batchId) {
    const secEl = document.getElementById(`sec_batch_${batchId}`);
    if (!secEl) return;

    isProgrammaticScrolling = true;
    clearTimeout(unlockScrollSpyTimer);

    sidebarList?.querySelectorAll('.gdrive-sidebar-item').forEach(el => {
      el.classList.toggle('active', el.dataset.batchId === batchId);
    });

    const headerOffset = 100;
    const rect = secEl.getBoundingClientRect();
    const targetY = window.pageYOffset + rect.top - headerOffset;

    window.scrollTo({
      top: Math.max(0, targetY),
      behavior: 'smooth'
    });

    unlockScrollSpyTimer = setTimeout(() => {
      isProgrammaticScrolling = false;
    }, 600);
  }

  // Populate Right Sidebar and Main Sections
  filteredBatches.forEach(batch => {
    const cleanTitle = formatCleanSubfolderTitle(batch.title);
    const batchRawFiles = batch.examples || [];
    let batchFiles = batchRawFiles.filter(f => {
      if (fmt !== 'all' && !matchesGDriveFormatFilter(f.ext, fmt)) return false;
      if (searchQ) {
        const hay = `${f.name || ''} ${f.ext || ''}`.toLowerCase();
        if (!hay.includes(searchQ)) return false;
      }
      return true;
    });

    // 1. Right Sidebar Item (Clean Title: no redundant enclosing folder name, draggable to reorder)
    if (sidebarList) {
      const sideItem = document.createElement('div');
      sideItem.className = 'gdrive-sidebar-item';
      sideItem.dataset.batchId = batch.id;
      sideItem.draggable = true;
      sideItem.title = `${cleanTitle} · ${batchFiles.length} files · Drag to reorder · Drop file here to move`;
      sideItem.innerHTML = `
        <span class="gdrive-sidebar-item-name">${escapeHtml(cleanTitle)}</span>
        <span class="gdrive-sidebar-item-count">${batchFiles.length}</span>
      `;

      sideItem.addEventListener('click', (e) => {
        e.preventDefault();
        scrollToSubfolderSection(batch.id);
      });

      sideItem.addEventListener('dragstart', (e) => {
        e.stopPropagation();
        window._idealActiveDraggedBatchId = batch.id;
        sideItem.classList.add('is-folder-dragging');
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('application/ideal-subfolder-reorder', batch.id);
        e.dataTransfer.setData('text/plain', batch.id);
      });

      sideItem.addEventListener('dragend', () => {
        window._idealActiveDraggedBatchId = null;
        sideItem.classList.remove('is-folder-dragging');
        sidebarList.querySelectorAll('.gdrive-sidebar-item').forEach(el => {
          el.classList.remove('is-reorder-target-top', 'is-reorder-target-bottom', 'is-file-drag-over', 'is-drag-over');
        });
      });

      // Allow inline renaming of subfolder directly from right sidebar on double click
      sideItem.addEventListener('dblclick', (e) => {
        e.stopPropagation();
        const nameSpan = sideItem.querySelector('.gdrive-sidebar-item-name') || sideItem.querySelector('.gdrive-sidebar-name');
        promptInlineRename(nameSpan, cleanTitle, async (newVal) => {
          const clean = newVal.trim();
          if (!clean || clean === cleanTitle) return;
          const newPath = await renameGDriveItemOnDisk(batch.localFolder, clean, true);
          if (newPath) {
            const oldId = batch.id;
            const oldRel = batch.relPath;
            const finalFolderName = newPath.split('/').pop();
            const newRel = `${encObj.relPath}/${finalFolderName}`;
            batch.title = finalFolderName;
            batch.localFolder = newPath;
            batch.relPath = newRel;
            (batch.examples || []).forEach(f => {
              if (f.localPath) f.localPath = `${newPath}/${f.name}`;
            });
            try {
              const rawOrder = localStorage.getItem(subfolderOrderKey);
              if (rawOrder) {
                let orderArr = JSON.parse(rawOrder);
                orderArr = orderArr.map(k => (k === oldId || k === oldRel || k === cleanTitle) ? (batch.id || newRel) : k);
                localStorage.setItem(subfolderOrderKey, JSON.stringify(orderArr));
              }
            } catch (err) {}
            renderWorkspace();
          }
        });
      });

      // Drag and drop target on sidebar item: handles both subfolder reordering and file moving
      sideItem.addEventListener('dragover', (e) => {
        e.preventDefault();
        const isReorder = Boolean(window._idealActiveDraggedBatchId);
        if (isReorder) {
          e.dataTransfer.dropEffect = 'move';
          const rect = sideItem.getBoundingClientRect();
          const relY = e.clientY - rect.top;
          const isTop = relY < rect.height / 2;
          sideItem.classList.toggle('is-reorder-target-top', isTop);
          sideItem.classList.toggle('is-reorder-target-bottom', !isTop);
        } else {
          e.dataTransfer.dropEffect = 'move';
          sideItem.classList.add('is-file-drag-over');
        }
      });

      sideItem.addEventListener('dragleave', () => {
        sideItem.classList.remove('is-file-drag-over', 'is-drag-over', 'is-reorder-target-top', 'is-reorder-target-bottom');
      });

      sideItem.addEventListener('drop', async (e) => {
        e.preventDefault();
        e.stopPropagation();
        const isReorder = Boolean(window._idealActiveDraggedBatchId);
        const draggedBatchId = window._idealActiveDraggedBatchId || e.dataTransfer.getData('application/ideal-subfolder-reorder') || e.dataTransfer.getData('text/plain');
        const isTop = sideItem.classList.contains('is-reorder-target-top');
        sideItem.classList.remove('is-file-drag-over', 'is-drag-over', 'is-reorder-target-top', 'is-reorder-target-bottom');
        window._idealActiveDraggedBatchId = null;

        if (isReorder) {
          if (!draggedBatchId || draggedBatchId === batch.id) return;

          const currentOrder = filteredBatches.map(b => b.id);
          const fromIdx = currentOrder.indexOf(draggedBatchId);
          if (fromIdx < 0) return;
          currentOrder.splice(fromIdx, 1);
          let toIdx = currentOrder.indexOf(batch.id);
          if (!isTop) toIdx++;
          currentOrder.splice(toIdx, 0, draggedBatchId);

          try {
            localStorage.setItem(subfolderOrderKey, JSON.stringify(currentOrder));
          } catch (err) {}
          state.gdriveDrillSort = 'default';
          renderWorkspace();
          showStatusToast('Subfolder order saved');
          return;
        }

        try {
          const raw = window._idealActiveDraggedFilePayload || e.dataTransfer.getData('application/json') || e.dataTransfer.getData('text/plain');
          window._idealActiveDraggedFilePayload = null;
          if (!raw) return;
          const dragData = JSON.parse(raw);
          if (dragData.sourcePath && dragData.batchId !== batch.id) {
            await handleFileMove(dragData, batch);
          }
        } catch (err) {}
      });

      sidebarList.appendChild(sideItem);
    }

    // 2. Main Section for this subfolder
    if (mainArea) {
      const section = document.createElement('section');
      section.className = 'gdrive-subfolder-section';
      section.id = `sec_batch_${batch.id}`;
      section.dataset.batchId = batch.id;

      section.innerHTML = `
        <div class="gdrive-subfolder-sec-header">
          <div class="gdrive-subfolder-sec-title-wrap">
            <h4 class="gdrive-subfolder-sec-title" title="Click to rename subfolder in Google Drive">
              <span>${escapeHtml(cleanTitle)}</span>
            </h4>
            <span class="gdrive-subfolder-sec-count">${batchFiles.length} ${batchFiles.length === 1 ? 'file' : 'files'}</span>
          </div>

          <div class="gdrive-subfolder-sec-actions">
            <a href="${escapeHtml(batch.driveFolderUrl)}" target="_blank" rel="noopener" class="gdrive-pill-btn" title="Show folder in Google Drive">Show in Drive</a>
            <button type="button" class="gdrive-pill-btn btn-sec-finder" title="Show folder in Finder">Show in Finder</button>
          </div>
        </div>

        <div class="gdrive-files-grid is-uniform" data-scale-step="${state.gdriveScaleStep || 3}" style="--eagle-col-width:${colWidth}px;"></div>
      `;

      // Subfolder Rename via Header click
      const secTitleEl = section.querySelector('.gdrive-subfolder-sec-title');
      secTitleEl?.addEventListener('click', (e) => {
        e.stopPropagation();
        promptInlineRename(secTitleEl.querySelector('span'), cleanTitle, async (newVal) => {
          const clean = newVal.trim();
          if (!clean || clean === cleanTitle) return;
          const newPath = await renameGDriveItemOnDisk(batch.localFolder, clean, true);
          if (newPath) {
            const oldId = batch.id;
            const oldRel = batch.relPath;
            const finalFolderName = newPath.split('/').pop();
            const newRel = `${encObj.relPath}/${finalFolderName}`;
            batch.title = finalFolderName;
            batch.localFolder = newPath;
            batch.relPath = newRel;
            (batch.examples || []).forEach(f => {
              if (f.localPath) f.localPath = `${newPath}/${f.name}`;
            });
            try {
              const rawOrder = localStorage.getItem(subfolderOrderKey);
              if (rawOrder) {
                let orderArr = JSON.parse(rawOrder);
                orderArr = orderArr.map(k => (k === oldId || k === oldRel || k === cleanTitle) ? (batch.id || newRel) : k);
                localStorage.setItem(subfolderOrderKey, JSON.stringify(orderArr));
              }
            } catch (err) {}
            renderWorkspace();
          }
        });
      });

      section.querySelector('.btn-sec-finder')?.addEventListener('click', () => {
        revealItemInFinder(batch.localFolder);
      });


      // Render File Cards inside Section Grid
      const gridEl = section.querySelector('.gdrive-files-grid');
      batchFiles.forEach((file, fIdx) => {
        const ext = (file.ext || '').replace('.', '').toUpperCase() || 'FILE';
        const fileId = `${batch.id}_file_${file.sid || fIdx}`;
        const assetObj = {
          id: fileId,
          title: file.name,
          rawName: file.name,
          category: batch.title,
          batchId: batch.id,
          ext,
          cid: file.cid,
          kind: ['MP4', 'MOV', 'WEBM'].includes(ext) ? 'video' : 'image',
          thumbSrc: getGDriveAssetThumbSrc(file),
          fallbackSrc: getGDriveAssetFallbackSrc(file),
          driveEmbedUrl: file.driveEmbedUrl,
          driveDownloadUrl: file.driveDownloadUrl,
          localPath: file.localPath,
          driveWebUrl: file.driveWebUrl || file.driveUrl || batch.driveFolderUrl,
          size: file.size || 0,
          sizeLabel: file.sizeLabel || ext,
          notes: `My Drive/${batch.relPath}`
        };

        const card = document.createElement('article');
        card.className = 'gdrive-file-card gdrive-draggable-card';
        card.setAttribute('draggable', 'true');
        card.style.cursor = 'pointer';

        const prioAttr = fIdx < 6 ? 'fetchpriority="high"' : 'loading="lazy" decoding="async"';
        const mediaHtml = `<img src="${escapeHtml(assetObj.thumbSrc)}" data-fallback="${escapeHtml(assetObj.fallbackSrc)}" alt="${escapeHtml(assetObj.title)}" ${prioAttr}>`;

        card.innerHTML = `
          <div class="gdrive-file-stage" title="Click to preview · Spacebar Quick-Look · Drag to move">
            ${mediaHtml}
            <span class="gdrive-ext-tag">${escapeHtml(assetObj.ext)}</span>
            <div class="gdrive-card-hover-actions">
              ${assetObj.driveWebUrl ? `<a href="${escapeHtml(assetObj.driveWebUrl)}" target="_blank" rel="noopener" class="gdrive-pill-btn" title="Show file in Google Drive">Drive</a>` : ''}
              <button type="button" class="gdrive-pill-btn btn-file-finder" title="Show file in Finder">Finder</button>
            </div>
          </div>
          <div class="gdrive-file-body">
            <div class="gdrive-file-title" data-file-title="1" title="Click or double-click to rename file in Google Drive">
              <span>${escapeHtml(assetObj.title)}</span>
            </div>
            <div class="gdrive-file-sub">
              <span>${escapeHtml(assetObj.sizeLabel)}</span>
            </div>
          </div>
        `;

        const imgEl = card.querySelector('img');
        if (imgEl) {
          imgEl.addEventListener('error', () => {
            const fb = imgEl.dataset.fallback;
            if (fb && imgEl.src !== fb && !imgEl.dataset.triedFb) {
              imgEl.dataset.triedFb = '1';
              imgEl.src = fb;
            } else if (!imgEl.dataset.triedSvg) {
              imgEl.dataset.triedSvg = '1';
              imgEl.src = getClientAssetSpecimenSvg(assetObj.title, assetObj.ext, assetObj.category);
            }
          });
        }

        // Inline Rename of File on Title Click
        const titleSpan = card.querySelector('.gdrive-file-title span');
        titleSpan?.addEventListener('click', (e) => {
          e.stopPropagation();
          promptInlineRename(titleSpan, file.name, async (newVal) => {
            const clean = newVal.trim();
            if (!clean || clean === file.name) return;
            const newPath = await renameGDriveItemOnDisk(file.localPath, clean, false);
            if (newPath) {
              const finalFileName = newPath.split('/').pop();
              file.name = finalFileName;
              file.title = finalFileName;
              file.localPath = newPath;
              assetObj.title = finalFileName;
              assetObj.rawName = finalFileName;
              assetObj.localPath = newPath;
              titleSpan.textContent = finalFileName;
              const navMatch = (state.currentEagleAssetList || []).find(x => x.id === assetObj.id);
              if (navMatch) {
                navMatch.title = finalFileName;
                navMatch.rawName = finalFileName;
                navMatch.localPath = newPath;
              }
              renderWorkspace();
            }
          });
        });

        // Quick Look Hover
        card.addEventListener('mouseenter', () => {
          state.hoveredAssetForQuickLook = assetObj;
        });
        card.addEventListener('mouseleave', () => {
          if (state.hoveredAssetForQuickLook && state.hoveredAssetForQuickLook.id === assetObj.id) {
            state.hoveredAssetForQuickLook = null;
          }
        });

        // Click to Open Quick Look
        card.addEventListener('click', (e) => {
          if (e.target.closest('a') || e.target.closest('button') || e.target.closest('.inline-rename-field')) return;
          openSpacebarPreview(assetObj);
        });

        card.querySelector('.btn-file-finder')?.addEventListener('click', (e) => {
          e.stopPropagation();
          if (assetObj.localPath) revealItemInFinder(assetObj.localPath);
        });

        // Drag Start & Drag End on Card
        card.addEventListener('dragstart', (e) => {
          card.classList.add('is-dragging');
          const payload = JSON.stringify({
            sid: file.sid,
            sourcePath: file.localPath,
            fileName: file.name,
            batchId: batch.id,
            enclosingFolder: encObj.name
          });
          window._idealActiveDraggedFilePayload = payload;
          e.dataTransfer.setData('application/json', payload);
          e.dataTransfer.setData('text/plain', payload);
          e.dataTransfer.effectAllowed = 'move';
        });

        card.addEventListener('dragend', () => {
          card.classList.remove('is-dragging');
          window._idealActiveDraggedFilePayload = null;
        });

        gridEl.appendChild(card);
      });

      if (batchFiles.length === 0) {
        const emptyZone = document.createElement('div');
        emptyZone.className = 'gdrive-empty-folder-zone';
        emptyZone.innerHTML = `<span class="kicker-mono" style="opacity:0.45;font-size:10px;">EMPTY SUBFOLDER</span>`;
        section.appendChild(emptyZone);
      }

      mainArea.appendChild(section);
    }
  });

  // Rock-solid scroll spy: smoothly updates right sidebar without jittering during clicks
  function updateScrollSpy() {
    if (isProgrammaticScrolling || !sidebarList) return;
    const sections = Array.from(mainArea.querySelectorAll('.gdrive-subfolder-section'));
    if (!sections.length) return;

    const isAtBottom = (window.innerHeight + window.pageYOffset) >= (document.documentElement.scrollHeight - 70);
    let activeBatchId = null;

    if (isAtBottom) {
      activeBatchId = sections[sections.length - 1].dataset.batchId;
    } else {
      const topThreshold = 140;
      for (let i = 0; i < sections.length; i++) {
        const sec = sections[i];
        const rect = sec.getBoundingClientRect();
        if (rect.top <= topThreshold && rect.bottom > topThreshold) {
          activeBatchId = sec.dataset.batchId;
          break;
        }
      }
      if (!activeBatchId && sections[0].getBoundingClientRect().top > topThreshold) {
        activeBatchId = sections[0].dataset.batchId;
      }
    }

    if (activeBatchId) {
      sidebarList.querySelectorAll('.gdrive-sidebar-item').forEach(item => {
        const shouldBeActive = item.dataset.batchId === activeBatchId;
        item.classList.toggle('active', shouldBeActive);
      });
    }
  }

  const handleWindowScroll = () => {
    if (scrollSpyRaf) cancelAnimationFrame(scrollSpyRaf);
    scrollSpyRaf = requestAnimationFrame(updateScrollSpy);
  };

  window.addEventListener('scroll', handleWindowScroll, { passive: true });
  window._gdriveScrollSpyCleaner = () => {
    window.removeEventListener('scroll', handleWindowScroll);
    if (scrollSpyRaf) cancelAnimationFrame(scrollSpyRaf);
    clearTimeout(unlockScrollSpyTimer);
  };

  // Helper to move file across batches and sync Google Drive
  async function handleFileMove(dragData, targetBatch) {
    if (!dragData.sourcePath || !targetBatch.localFolder) return;
    const ok = await moveGDriveItemOnDisk(dragData.sourcePath, targetBatch.localFolder);
    if (ok) {
      // Find source batch in state
      const srcBatch = state.gdriveBatches.find(b => b.id === dragData.batchId);
      if (srcBatch && srcBatch.examples) {
        const fileIdx = srcBatch.examples.findIndex(f => (f.localPath && f.localPath === dragData.sourcePath) || (f.sid && String(f.sid) === String(dragData.sid)));
        if (fileIdx !== -1) {
          const [movedFile] = srcBatch.examples.splice(fileIdx, 1);
          srcBatch.totalCount = Math.max(0, (srcBatch.totalCount || 1) - 1);
          // Update target batch
          movedFile.localPath = `${targetBatch.localFolder}/${movedFile.name}`;
          movedFile.relPath = `${targetBatch.relPath}/${movedFile.name}`;
          targetBatch.examples = targetBatch.examples || [];
          targetBatch.examples.unshift(movedFile);
          targetBatch.totalCount = (targetBatch.totalCount || 0) + 1;
        }
      }
      renderWorkspace();
      showStatusToast(`Moved ${dragData.fileName || 'file'} to ${formatCleanSubfolderTitle(targetBatch.title)}`);
    }
  }
}

function renderGDriveFolderDrillDown(ws, batch, spaceObj) {
  const fmt = state.eagleFormatFilter || 'all';
  const disp = state.eagleDisplayStyle === 'uniform' ? 'uniform' : 'masonry';
  const sortBy = state.gdriveDrillSort || 'default';
  const colWidth = Math.max(160, Math.min(460, spaceObj?.ui?.cardSize || 235));
  const batchTitle = batch.title;
  const searchQ = (state.searchQuery || '').trim().toLowerCase();

  const rawFiles = batch.examples || [];
  let filteredFiles = rawFiles.filter((f, idx) => {
    if (fmt !== 'all' && !matchesGDriveFormatFilter(f.ext, fmt)) return false;
    if (searchQ) {
      const hay = `${f.name || ''} ${f.ext || ''} ${f.relPath || ''}`.toLowerCase();
      if (!hay.includes(searchQ)) return false;
    }
    return true;
  });

  if (sortBy === 'alpha') {
    filteredFiles = [...filteredFiles].sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  } else if (sortBy === 'size') {
    filteredFiles = [...filteredFiles].sort((a, b) => (b.size || 0) - (a.size || 0));
  } else if (sortBy === 'type') {
    filteredFiles = [...filteredFiles].sort((a, b) => (a.ext || '').localeCompare(b.ext || '') || (a.name || '').localeCompare(b.name || ''));
  }

  // Build standard asset objects for Quick Look / Spacebar navigation
  const folderAssetList = filteredFiles.map((ex, idx) => {
    const ext = (ex.ext || '').replace('.', '').toUpperCase() || 'FILE';
    const fileId = `${batch.id}_drill_${ex.sid || idx}`;
    return {
      id: fileId,
      rawFile: ex,
      title: ex.name,
      rawName: ex.name,
      category: batchTitle,
      batchId: batch.id,
      ext,
      cid: ex.cid,
      kind: ['MP4', 'MOV', 'WEBM'].includes(ext) ? 'video' : 'image',
      thumbSrc: getGDriveAssetThumbSrc(ex),
      fallbackSrc: getGDriveAssetFallbackSrc(ex),
      cloudThumbUrl: ex.cloudThumbUrl,
      driveHighResUrl: ex.driveHighResUrl,
      driveDownloadUrl: ex.driveDownloadUrl,
      driveEmbedUrl: ex.driveEmbedUrl,
      driveWebUrl: ex.driveWebUrl || ex.driveUrl || batch.driveFolderUrl,
      localPath: ex.localPath,
      size: ex.size || 0,
      sizeLabel: ex.sizeLabel || ext,
      notes: `My Drive/${batch.relPath}`
    };
  });

  state.currentEagleAssetList = folderAssetList;

  ws.innerHTML = `
    <div class="eagle-browser-shell">
      <div class="gdrive-folder-drill-bar">
        <div class="gdrive-drill-top-row">
          <div class="gdrive-drill-left">
            <button type="button" class="gdrive-pill-btn" id="btnBackToBatches" title="Back to ${escapeHtml(batch.enclosingFolder || 'ASSETS')}">← Back to ${escapeHtml(batch.enclosingFolder || 'ASSETS')}</button>
            <div class="gdrive-drill-title-wrap">
              <h3 class="gdrive-drill-title">${escapeHtml(batchTitle)}</h3>
              <span class="gdrive-drill-sub">My Drive/${escapeHtml(batch.relPath)} · ${filteredFiles.length} ${filteredFiles.length === 1 ? 'file' : 'files'}${batch.totalBytes ? ' · ' + formatBytes(batch.totalBytes) : ''}</span>
            </div>
          </div>

          <div class="gdrive-drill-actions">
            <a href="${escapeHtml(batch.driveFolderUrl)}" target="_blank" rel="noopener" class="gdrive-pill-btn" title="Show folder in Google Drive">Show in Drive</a>
            <button type="button" class="gdrive-pill-btn" id="btnDrillShowFolderFinder" title="Show folder in Finder (marked in location, not opened)">Show in Finder</button>
          </div>
        </div>

        <div class="gdrive-drill-bottom-row">
          <div class="subbar-group">
            <button type="button" class="quiet-subbar-link ${fmt === 'all' ? 'active' : ''}" data-drill-fmt="all">All</button>
            <button type="button" class="quiet-subbar-link ${fmt === 'PSD' ? 'active' : ''}" data-drill-fmt="PSD">PSD</button>
            <button type="button" class="quiet-subbar-link ${fmt === 'AI' ? 'active' : ''}" data-drill-fmt="AI">AI</button>
            <button type="button" class="quiet-subbar-link ${fmt === 'INDD' ? 'active' : ''}" data-drill-fmt="INDD">INDD</button>
            <button type="button" class="quiet-subbar-link ${fmt === 'IMG' ? 'active' : ''}" data-drill-fmt="IMG">Image</button>
            <button type="button" class="quiet-subbar-link ${fmt === 'MOTION' ? 'active' : ''}" data-drill-fmt="MOTION">Motion</button>
            <button type="button" class="quiet-subbar-link ${fmt === '3D' ? 'active' : ''}" data-drill-fmt="3D">3D</button>
          </div>

          <span class="quiet-sep">·</span>

          <div class="subbar-group">
            <button type="button" class="quiet-subbar-link ${sortBy === 'default' ? 'active' : ''}" data-drill-sort="default" title="Default order">Default</button>
            <button type="button" class="quiet-subbar-link ${sortBy === 'alpha' ? 'active' : ''}" data-drill-sort="alpha" title="Sort A–Z">A–Z</button>
            <button type="button" class="quiet-subbar-link ${sortBy === 'size' ? 'active' : ''}" data-drill-sort="size" title="Sort by file size (largest first)">Size</button>
            <button type="button" class="quiet-subbar-link ${sortBy === 'type' ? 'active' : ''}" data-drill-sort="type" title="Sort by file type">Type</button>
          </div>

          <span class="quiet-sep">·</span>

          <div class="subbar-group" style="margin-left:auto;">
            <button type="button" class="quiet-subbar-link ${disp === 'masonry' ? 'active' : ''}" data-drill-disp="masonry">Masonry</button>
            <button type="button" class="quiet-subbar-link ${disp === 'uniform' ? 'active' : ''}" data-drill-disp="uniform">Grid</button>
          </div>
        </div>
      </div>

      <div id="gdriveDrillStage"></div>
    </div>
  `;

  ws.querySelector('#btnBackToBatches')?.addEventListener('click', () => {
    state.activeGDriveBatchId = null;
    state.activeGDriveEnclosingFolder = batch.enclosingFolder || null;
    if (batch.enclosingFolder) {
      state.activeCategory = batch.enclosingFolder;
    } else {
      state.activeCategory = 'All';
    }
    saveNavState();
    renderFilterActionRow();
    renderWorkspace();
  });

  ws.querySelector('#btnDrillShowFolderFinder')?.addEventListener('click', () => {
    revealItemInFinder(batch.localFolder);
  });

  ws.querySelectorAll('[data-drill-fmt]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.eagleFormatFilter = btn.dataset.drillFmt;
      saveNavState();
      renderWorkspace();
    });
  });

  ws.querySelectorAll('[data-drill-sort]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.gdriveDrillSort = btn.dataset.drillSort;
      renderWorkspace();
    });
  });

  ws.querySelectorAll('[data-drill-disp]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.eagleDisplayStyle = btn.dataset.drillDisp;
      saveNavState();
      renderWorkspace();
    });
  });

  const stage = ws.querySelector('#gdriveDrillStage');
  if (!stage) return;

  if (filteredFiles.length === 0) {
    stage.innerHTML = `
      <div style="padding:48px 24px;text-align:center;background:var(--surface);border:1px solid var(--border);border-radius:14px;">
        <div class="kicker-mono">NO FILES IN THIS FOLDER MATCH THIS FILTER</div>
        <p class="typewriter" style="font-size:12px;color:var(--text-mid);margin-top:6px;">Clear the search box or switch the format filter back to All to view all ${batch.totalCount} files in this folder.</p>
      </div>
    `;
    return;
  }

  const gridEl = document.createElement('div');
  gridEl.className = `gdrive-files-grid ${disp === 'uniform' ? 'is-uniform' : 'is-masonry'}`;
  gridEl.style.setProperty('--eagle-col-width', `${colWidth}px`);

  folderAssetList.forEach((file, idx) => {
    const card = document.createElement('article');
    card.className = 'gdrive-file-card';
    card.style.cursor = 'pointer';

    const prioAttr = idx < 6 ? 'fetchpriority="high"' : 'loading="lazy" decoding="async"';
    const mediaHtml = `<img src="${escapeHtml(file.thumbSrc)}" data-fallback="${escapeHtml(file.fallbackSrc)}" alt="${escapeHtml(file.title)}" ${prioAttr}>`;

    card.innerHTML = `
      <div class="gdrive-file-stage" title="Click to preview · Spacebar Quick-Look">
        ${mediaHtml}
        <span class="gdrive-ext-tag">${escapeHtml(file.ext)}</span>
      </div>
      <div class="gdrive-file-body">
        <div class="gdrive-file-title">${escapeHtml(file.title)}</div>
        <div class="gdrive-file-sub">
          <span>${escapeHtml(file.sizeLabel)}</span>
        </div>
        <div class="gdrive-file-actions">
          <a href="${escapeHtml(file.driveWebUrl)}" target="_blank" rel="noopener" class="gdrive-pill-btn" title="Show file in Google Drive">Show in Drive</a>
          <button type="button" class="gdrive-pill-btn btn-file-finder" title="Show file in Finder (marked in location, not opened)">Show in Finder</button>
        </div>
      </div>
    `;

    const imgEl = card.querySelector('img');
    if (imgEl) {
      imgEl.addEventListener('error', () => {
        const fb = imgEl.dataset.fallback;
        if (fb && imgEl.src !== fb && !imgEl.dataset.triedFb) {
          imgEl.dataset.triedFb = '1';
          imgEl.src = fb;
        } else if (!imgEl.dataset.triedSvg) {
          imgEl.dataset.triedSvg = '1';
          imgEl.src = getClientAssetSpecimenSvg(file.title, file.ext, file.category);
        }
      });
    }

    card.addEventListener('mouseenter', () => {
      state.hoveredAssetForQuickLook = file;
    });
    card.addEventListener('mouseleave', () => {
      if (state.hoveredAssetForQuickLook && state.hoveredAssetForQuickLook.id === file.id) {
        state.hoveredAssetForQuickLook = null;
      }
    });

    card.addEventListener('click', (e) => {
      if (e.target.closest('a') || e.target.closest('button')) return;
      openSpacebarPreview(file);
    });

    card.querySelector('.btn-file-finder')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (file.localPath) revealItemInFinder(file.localPath);
    });

    gridEl.appendChild(card);
  });

  stage.appendChild(gridEl);
}

function renderEagleAssetBrowser(ws, driveBatches, spaceObj) {
  const scope = state.eagleScopeMode === 'files' ? 'files' : 'batches';
  state.eagleScopeMode = scope;
  const disp = state.eagleDisplayStyle === 'uniform' ? 'uniform' : 'masonry';
  state.eagleDisplayStyle = disp;
  const fmt = state.eagleFormatFilter || 'all';
  const sortBy = state.gdriveDrillSort || 'default';
  const colWidth = Math.max(160, Math.min(460, spaceObj?.ui?.cardSize || 235));
  const searchQ = (state.searchQuery || '').trim().toLowerCase();

  vault.gdriveTitles = vault.gdriveTitles || {};
  vault.gdriveBatchTitles = vault.gdriveBatchTitles || {};

  // Filter batches by active format so format pills work in both Batches and Files views
  let filteredBatches = fmt === 'all'
    ? [...driveBatches]
    : driveBatches.filter(b => {
        const typesMatch = (b.fileTypes || []).some(t => matchesGDriveFormatFilter(t, fmt));
        const exMatch = (b.examples || []).some(ex => matchesGDriveFormatFilter(ex.ext, fmt));
        return typesMatch || exMatch;
      });

  if (sortBy === 'alpha') {
    filteredBatches.sort((a, b) => (a.title || '').localeCompare(b.title || ''));
  } else if (sortBy === 'size') {
    filteredBatches.sort((a, b) => (b.totalBytes || b.totalCount || 0) - (a.totalBytes || a.totalCount || 0));
  } else if (sortBy === 'type') {
    filteredBatches.sort((a, b) => ((a.fileTypes && a.fileTypes[0]) || '').localeCompare((b.fileTypes && b.fileTypes[0]) || ''));
  }

  // Build individual asset items strictly from Google Drive batches
  let allFiles = [];
  filteredBatches.forEach(b => {
    (b.examples || []).forEach((ex, idx) => {
      const ext = (ex.ext || '').replace('.', '').toUpperCase() || 'FILE';
      if (fmt !== 'all' && !matchesGDriveFormatFilter(ext, fmt)) return;
      const fileId = `${b.id}_ex_${ex.sid || idx}`;
      if (searchQ) {
        const hay = `${ex.name || ''} ${ext} ${b.title || ''} ${b.relPath || ''}`.toLowerCase();
        if (!hay.includes(searchQ)) return;
      }
      allFiles.push({
        id: fileId,
        vaultItemId: null,
        title: ex.name,
        rawName: ex.name,
        category: b.title,
        batchId: b.id,
        ext,
        cid: ex.cid,
        kind: ['MP4', 'MOV', 'WEBM'].includes(ext) ? 'video' : 'image',
        thumbSrc: getGDriveAssetThumbSrc(ex),
        fallbackSrc: getGDriveAssetFallbackSrc(ex),
        cloudThumbUrl: ex.cloudThumbUrl,
        driveHighResUrl: ex.driveHighResUrl,
        driveDownloadUrl: ex.driveDownloadUrl,
        driveEmbedUrl: ex.driveEmbedUrl,
        localPath: ex.localPath,
        driveWebUrl: ex.driveWebUrl || ex.driveUrl || b.driveFolderUrl,
        size: ex.size || 0,
        sizeLabel: ex.sizeLabel || ext,
        notes: `My Drive/${b.relPath}`
      });
    });
  });

  if (sortBy === 'alpha') {
    allFiles = [...allFiles].sort((a, b) => (a.title || '').localeCompare(b.title || ''));
  } else if (sortBy === 'size') {
    allFiles = [...allFiles].sort((a, b) => (b.size || 0) - (a.size || 0));
  } else if (sortBy === 'type') {
    allFiles = [...allFiles].sort((a, b) => (a.ext || '').localeCompare(b.ext || '') || (a.title || '').localeCompare(b.title || ''));
  }

  const activeLane = getActiveGDriveLaneInfo(state.activeCategory);

  ws.innerHTML = `
    <div class="eagle-browser-shell">
      <div class="minimal-inline-subbar">
        <div class="subbar-group">
          <button type="button" class="quiet-subbar-link ${scope === 'batches' ? 'active' : ''}" data-eagle-scope="batches">Batches <span>${filteredBatches.length}</span></button>
          <button type="button" class="quiet-subbar-link ${scope === 'files' ? 'active' : ''}" data-eagle-scope="files">Files <span>${allFiles.length}</span></button>
        </div>

        <span class="quiet-sep">·</span>

        <div class="subbar-group">
          <button type="button" class="quiet-subbar-link ${fmt === 'all' ? 'active' : ''}" data-eagle-fmt="all">All</button>
          <button type="button" class="quiet-subbar-link ${fmt === 'PSD' ? 'active' : ''}" data-eagle-fmt="PSD">PSD</button>
          <button type="button" class="quiet-subbar-link ${fmt === 'AI' ? 'active' : ''}" data-eagle-fmt="AI">AI</button>
          <button type="button" class="quiet-subbar-link ${fmt === 'INDD' ? 'active' : ''}" data-eagle-fmt="INDD">INDD</button>
          <button type="button" class="quiet-subbar-link ${fmt === 'IMG' ? 'active' : ''}" data-eagle-fmt="IMG">Image</button>
          <button type="button" class="quiet-subbar-link ${fmt === 'MOTION' ? 'active' : ''}" data-eagle-fmt="MOTION">Motion</button>
          <button type="button" class="quiet-subbar-link ${fmt === '3D' ? 'active' : ''}" data-eagle-fmt="3D">3D</button>
        </div>

        <span class="quiet-sep">·</span>

        <div class="subbar-group">
          <button type="button" class="quiet-subbar-link ${sortBy === 'default' ? 'active' : ''}" data-eagle-sort="default" title="Default order">Default</button>
          <button type="button" class="quiet-subbar-link ${sortBy === 'alpha' ? 'active' : ''}" data-eagle-sort="alpha" title="Sort A–Z">A–Z</button>
          <button type="button" class="quiet-subbar-link ${sortBy === 'size' ? 'active' : ''}" data-eagle-sort="size" title="Sort by size (largest first)">Size</button>
          <button type="button" class="quiet-subbar-link ${sortBy === 'type' ? 'active' : ''}" data-eagle-sort="type" title="Sort by file type">Type</button>
        </div>

        <span class="quiet-sep">·</span>

        <div class="subbar-group" style="gap:6px;">
          <span class="kicker-mono" style="opacity:0.72;">${escapeHtml(activeLane.label)}</span>
        </div>

        ${scope === 'files' ? `
        <div class="subbar-group" style="margin-left:auto;">
          <button type="button" class="quiet-subbar-link ${disp === 'masonry' ? 'active' : ''}" data-eagle-disp="masonry">Masonry</button>
          <button type="button" class="quiet-subbar-link ${disp === 'uniform' ? 'active' : ''}" data-eagle-disp="uniform">Grid</button>
        </div>
        ` : ''}
      </div>

      <div id="eagleMainStage"></div>
    </div>
  `;

  ws.querySelectorAll('[data-eagle-scope]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.eagleScopeMode = btn.dataset.eagleScope;
      saveNavState();
      renderWorkspace();
    });
  });

  ws.querySelectorAll('[data-eagle-fmt]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.eagleFormatFilter = btn.dataset.eagleFmt;
      saveNavState();
      renderWorkspace();
    });
  });

  ws.querySelectorAll('[data-eagle-sort]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.gdriveDrillSort = btn.dataset.eagleSort;
      renderWorkspace();
    });
  });

  ws.querySelectorAll('[data-eagle-disp]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.eagleDisplayStyle = btn.dataset.eagleDisp;
      saveNavState();
      renderWorkspace();
    });
  });

  const stage = ws.querySelector('#eagleMainStage');
  if (!stage) return;

  state.currentEagleAssetList = allFiles;

  if (scope === 'batches') {
    if (filteredBatches.length === 0) {
      stage.innerHTML = `
        <div style="padding:48px 24px;text-align:center;background:var(--surface);border:1px solid var(--border);border-radius:14px;">
          <div class="kicker-mono">NO GOOGLE DRIVE BATCHES MATCH THIS FILTER</div>
          <p class="typewriter" style="font-size:12px;color:var(--text-mid);margin-top:6px;">Switch the format filter back to All to view all batches in this Drive lane.</p>
        </div>
      `;
      return;
    }
    stage.innerHTML = `<div class="gdrive-files-grid is-uniform" id="eagleBatchesGrid" style="--eagle-col-width:${colWidth}px;"></div>`;
    const grid = stage.querySelector('#eagleBatchesGrid');
    filteredBatches.forEach((b, idx) => grid.appendChild(buildGDriveBatchCardEl(b, idx)));
    return;
  }

  if (allFiles.length === 0) {
    stage.innerHTML = `
      <div style="padding:48px 24px;text-align:center;background:var(--surface);border:1px solid var(--border);border-radius:14px;">
        <div class="kicker-mono">NO MATCHING GOOGLE DRIVE FILES IN THIS FILTER</div>
        <p class="typewriter" style="font-size:12px;color:var(--text-mid);margin-top:6px;">Switch the format filter back to All to see all files in this Drive lane.</p>
      </div>
    `;
    return;
  }

  const gridEl = document.createElement('div');
  gridEl.className = `gdrive-files-grid ${disp === 'uniform' ? 'is-uniform' : 'is-masonry'}`;
  gridEl.style.setProperty('--eagle-col-width', `${colWidth}px`);

  allFiles.forEach((file, idx) => {
    const tile = document.createElement('article');
    tile.className = 'gdrive-file-card';
    tile.style.cursor = 'pointer';

    const prioAttr = idx < 8 ? 'fetchpriority="high"' : 'loading="lazy" decoding="async"';
    const mediaHtml = `<img src="${escapeHtml(file.thumbSrc)}" data-fallback="${escapeHtml(file.fallbackSrc)}" alt="${escapeHtml(file.title)}" ${prioAttr}>`;

    tile.innerHTML = `
      <div class="gdrive-file-stage" title="Click to preview · Spacebar Quick-Look · Cmd+Click for Google Drive">
        ${mediaHtml}
        <span class="gdrive-ext-tag">${escapeHtml(file.ext)}</span>
      </div>
      <div class="gdrive-file-body">
        <div class="gdrive-file-title">${escapeHtml(file.title)}</div>
        <div class="gdrive-file-sub">
          <span>${escapeHtml(file.sizeLabel)}</span>
        </div>
        <div class="gdrive-file-actions">
          ${file.driveWebUrl ? `<a href="${escapeHtml(file.driveWebUrl)}" target="_blank" rel="noopener" class="gdrive-pill-btn" title="Show file in Google Drive">Show in Drive</a>` : ''}
          <button type="button" class="gdrive-pill-btn btn-tile-finder" title="Show file in Finder (marked in location, not opened)">Show in Finder</button>
        </div>
      </div>
    `;

    const imgEl = tile.querySelector('img');
    if (imgEl) {
      imgEl.addEventListener('error', () => {
        const fb = imgEl.dataset.fallback;
        if (fb && imgEl.src !== fb && !imgEl.dataset.triedFb) {
          imgEl.dataset.triedFb = '1';
          imgEl.src = fb;
        } else if (!imgEl.dataset.triedSvg) {
          imgEl.dataset.triedSvg = '1';
          imgEl.src = getClientAssetSpecimenSvg(file.title, file.ext, file.category);
        }
      });
    }

    tile.addEventListener('mouseenter', () => {
      state.hoveredAssetForQuickLook = file;
    });
    tile.addEventListener('mouseleave', () => {
      if (state.hoveredAssetForQuickLook && state.hoveredAssetForQuickLook.id === file.id) {
        state.hoveredAssetForQuickLook = null;
      }
    });

    tile.addEventListener('click', (e) => {
      if (e.target.closest('a') || e.target.closest('button')) return;
      if ((e.metaKey || e.shiftKey) && file.driveWebUrl) {
        window.open(file.driveWebUrl, '_blank', 'noopener');
      } else {
        openSpacebarPreview(file);
      }
    });

    tile.querySelector('.btn-tile-finder')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (file.localPath) revealItemInFinder(file.localPath);
    });

    gridEl.appendChild(tile);
  });

  stage.appendChild(gridEl);
}

function ensureVaultItemForAsset(asset, defaultParentType = 'space', defaultParentId = 'incubator') {
  if (!asset) return null;
  if (asset.vaultItemId) {
    const existing = vault.items.find(i => i.id === asset.vaultItemId);
    if (existing) return existing;
  }
  const byUrl = vault.items.find(i => i.url && (i.url === asset.thumbSrc || i.url === asset.url));
  if (byUrl) {
    asset.vaultItemId = byUrl.id;
    return byUrl;
  }
  const newItem = {
    id: uid('item'),
    parentType: defaultParentType,
    parentId: defaultParentId,
    title: asset.title || 'Studio Asset',
    kind: asset.kind === 'video' ? 'video' : 'image',
    section: defaultParentType === 'space' && defaultParentId === 'incubator' ? 'Hatching Up' : 'WIP',
    status: 'Asset',
    url: asset.thumbSrc || asset.url || '',
    link: asset.driveWebUrl || '',
    localPath: asset.localPath || '',
    notes: asset.notes || `Imported from ${asset.category || 'Drive & PSD Assets'}`,
    tags: [asset.ext || 'ASSET', asset.category || 'Drive'].filter(Boolean),
    wallX: 336 + ((vault.items.length % 3) * 312),
    wallY: 144 + ((Math.floor(vault.items.length / 3) % 3) * 312),
    wallW: 264,
    createdAt: Date.now()
  };
  vault.items.unshift(newItem);
  asset.vaultItemId = newItem.id;
  return newItem;
}

function sendDriveAssetToStudio(asset) {
  if (!asset) return;
  let picker = document.getElementById('sendAssetToStudioDialog');
  if (!picker) {
    picker = document.createElement('dialog');
    picker.id = 'sendAssetToStudioDialog';
    picker.className = 'modal-dialog';
    picker.setAttribute('closedby', 'any');
    document.body.appendChild(picker);
  }
  const projOptions = (vault.projects || []).map(p =>
    `<button type="button" class="outline-btn" data-dest-type="project" data-dest-id="${escapeHtml(p.id)}" style="justify-content:flex-start;padding:8px 12px;text-align:left;width:100%;">
      <span class="kicker-mono" style="min-width:32px;">${escapeHtml(p.code || '')}</span>
      <span style="font-weight:600;color:var(--text);">${escapeHtml(p.title)}</span>
      <span style="margin-left:auto;font-size:10px;color:var(--text-dim);">${escapeHtml(p.category || '')}</span>
    </button>`
  ).join('');

  picker.innerHTML = `
    <div class="modal-shell" style="max-width:440px;">
      <header class="modal-header">
        <div>
          <span class="kicker-mono">CONNECT LAB &amp; ASSETS → CREATIVE STUDIO</span>
          <h3 class="modal-title" style="font-size:15px;">Send "${escapeHtml(asset.title || 'Asset')}" To Board</h3>
        </div>
        <button type="button" class="icon-close-btn" id="btnCloseSendStudio">✕</button>
      </header>
      <div style="padding:14px 18px;display:flex;flex-direction:column;gap:8px;max-height:65vh;overflow-y:auto;">
        <button type="button" class="solid-btn" data-dest-type="space" data-dest-id="incubator" style="justify-content:space-between;padding:10px 14px;width:100%;">
          <span>02 · Incubator (Hatching Up / WIP Board)</span>
          <span>Send →</span>
        </button>
        <div class="kicker-mono" style="margin-top:6px;">OR SEND TO A STUDIO PROJECT (01):</div>
        ${projOptions}
      </div>
    </div>
  `;

  picker.querySelector('#btnCloseSendStudio')?.addEventListener('click', () => picker.close());
  picker.querySelectorAll('[data-dest-type]').forEach(btn => {
    btn.addEventListener('click', () => {
      const destType = btn.dataset.destType;
      const destId = btn.dataset.destId;
      const destItems = vault.items.filter(i => i.parentType === destType && i.parentId === destId && !i.folderId);
      const col = destItems.length % 3;
      const row = Math.floor(destItems.length / 3);
      const created = {
        id: uid('item'),
        parentType: destType,
        parentId: destId,
        title: asset.title || 'Studio Asset',
        kind: 'image',
        section: destType === 'space' ? 'Hatching Up' : 'References',
        status: 'Asset',
        url: asset.thumbSrc || asset.url || '',
        link: asset.driveWebUrl || '',
        localPath: asset.localPath || '',
        notes: asset.notes || `Pinned from Drive & PSD Assets (${asset.category || 'Asset'})`,
        tags: [asset.ext || 'ASSET', asset.category || 'Drive'].filter(Boolean),
        wallX: 336 + col * 312,
        wallY: 144 + row * 312,
        wallW: 264,
        createdAt: Date.now()
      };
      vault.items.unshift(created);
      saveVault('SENT ASSET TO STUDIO');
      picker.close();
      renderSidebar();
    });
  });

  if (!picker.open) picker.showModal();
}

function openSpacebarPreview(asset) {
  if (!asset) return;
  state.currentQuickLookAsset = asset;
  const dlg = document.getElementById('spacebarPreviewDialog');
  const stage = document.getElementById('spacebarPreviewStage') || document.getElementById('spacebarPreviewMediaStage');
  const badgeEl = document.getElementById('spacebarPreviewBadge');
  const titleEl = document.getElementById('spacebarPreviewTitle');
  const btnQueued = document.getElementById('btnQuickLookQueued');
  const btnPublished = document.getElementById('btnQuickLookPublished');
  const btnWebsite = document.getElementById('btnQuickLookWebsite');
  const btnPinToBoard = document.getElementById('btnQuickLookPinToBoard');
  const btnFinder = document.getElementById('btnQuickLookFinder');
  const btnInspect = document.getElementById('btnQuickLookInspect');
  const btnClose = document.getElementById('btnCloseSpacebarPreview');
  if (!dlg || !stage) return;

  const isGDrivePage = state.viewType === 'space' && state.activeSpaceId === 'gdrive_assets';
  const fullPreviewUrl = asset.previewUrl || (asset.thumbSrc ? `${asset.thumbSrc}&preview=1` : (asset.thumbSrc || asset.url || ''));
  const thumbPreviewUrl = asset.thumbSrc || asset.url || '';
  const fallbackThumb = asset.fallbackSrc || asset.thumbSrc || '';

  if (isGDrivePage) {
    if (asset.kind === 'video' && asset.driveEmbedUrl) {
      stage.innerHTML = `<iframe src="${escapeHtml(asset.driveEmbedUrl)}" class="gdrive-embed-frame" allow="autoplay" allowfullscreen></iframe>`;
    } else {
      stage.innerHTML = `
        <div style="position:relative;display:flex;align-items:center;justify-content:center;max-width:90vw;max-height:80vh;">
          <img id="spacebarPreviewMainImg" src="${escapeHtml(thumbPreviewUrl)}" alt="${escapeHtml(asset.title || '')}" style="max-width:90vw;max-height:80vh;min-width:min(720px, 86vw);min-height:min(480px, 65vh);object-fit:contain;border-radius:8px;box-shadow:0 24px 70px rgba(0,0,0,0.65);transition:opacity 0.2s ease;">
        </div>
      `;
      if (fullPreviewUrl && fullPreviewUrl !== thumbPreviewUrl) {
        const highRes = new Image();
        highRes.src = fullPreviewUrl;
        highRes.onload = () => {
          const targetImg = document.getElementById('spacebarPreviewMainImg');
          if (targetImg && highRes.src) {
            targetImg.src = highRes.src;
          }
        };
      }
    }
  } else if (asset.driveEmbedUrl) {
    stage.innerHTML = `<iframe src="${escapeHtml(asset.driveEmbedUrl)}" class="gdrive-embed-frame" allow="autoplay" allowfullscreen></iframe>`;
  } else if (asset.kind === 'video') {
    stage.innerHTML = `<video src="${escapeHtml(thumbPreviewUrl)}" controls autoplay loop playsinline></video>`;
  } else {
    stage.innerHTML = `<img src="${escapeHtml(fullPreviewUrl)}" data-fallback="${escapeHtml(thumbPreviewUrl)}" alt="${escapeHtml(asset.title || '')}" style="max-height:80vh;max-width:92vw;object-fit:contain;border-radius:6px;box-shadow:0 8px 30px rgba(0,0,0,0.35);">`;
    const previewImg = stage.querySelector('img');
    if (previewImg) {
      previewImg.addEventListener('error', () => {
        const fb = previewImg.dataset.fallback;
        if (fb && previewImg.src !== fb && !previewImg.dataset.triedFb) {
          previewImg.dataset.triedFb = '1';
          previewImg.src = fb;
        }
      });
    }
  }

  if (badgeEl) {
    badgeEl.textContent = `${asset.category || asset.ext || 'STUDIO ASSET'}${asset.sizeLabel ? ' · ' + asset.sizeLabel : ''}`;
  }

  if (titleEl) {
    titleEl.textContent = asset.title || 'Asset Preview';
    if (isGDrivePage) {
      delete titleEl.dataset.editableTitle;
      titleEl.title = asset.title || 'Asset Preview';
      titleEl.onclick = null;
    } else {
      titleEl.dataset.editableTitle = '1';
      titleEl.title = 'Click to rename asset title';
      titleEl.onclick = (e) => {
        e.stopPropagation();
        promptInlineRename(titleEl, asset.title || 'Asset', (newVal) => {
          if (!newVal.trim()) return;
          const clean = newVal.trim();
          asset.title = clean;
          if (asset.vaultItemId) {
            const it = vault.items.find(i => i.id === asset.vaultItemId);
            if (it) it.title = clean;
          } else if (asset.id) {
            vault.gdriveTitles = vault.gdriveTitles || {};
            vault.gdriveTitles[asset.id] = clean;
            if (asset.localPath) vault.gdriveTitles[asset.localPath] = clean;
          }
          saveVault('RENAMED ASSET');
          renderWorkspace();
        });
      };
    }
  }

  // On Drive & PSD Assets page, show ONLY Prev/Next + Show in Drive + Show in Finder + Close
  if (btnQueued) btnQueued.hidden = isGDrivePage;
  if (btnPublished) btnPublished.hidden = isGDrivePage;
  if (btnWebsite) btnWebsite.hidden = isGDrivePage;
  if (btnInspect) btnInspect.hidden = isGDrivePage;
  if (btnPinToBoard) btnPinToBoard.hidden = isGDrivePage;

  const btnDownload = document.getElementById('btnQuickLookDownload');
  if (btnDownload) btnDownload.hidden = true;
  const btnToggleEmbed = document.getElementById('btnQuickLookEmbedToggle');
  if (btnToggleEmbed) btnToggleEmbed.hidden = true;

  // Prev / Next navigation buttons inside preview popup
  let btnPrev = document.getElementById('btnQuickLookPrev');
  let btnNext = document.getElementById('btnQuickLookNext');
  if (!btnPrev && btnFinder && btnFinder.parentElement) {
    btnPrev = document.createElement('button');
    btnPrev.type = 'button';
    btnPrev.id = 'btnQuickLookPrev';
    btnPrev.className = 'cmp-chip-btn';
    btnPrev.textContent = '← Prev';
    btnPrev.title = 'Previous file (Left Arrow)';
    btnFinder.insertAdjacentElement('beforebegin', btnPrev);
  }
  if (!btnNext && btnFinder && btnFinder.parentElement) {
    btnNext = document.createElement('button');
    btnNext.type = 'button';
    btnNext.id = 'btnQuickLookNext';
    btnNext.className = 'cmp-chip-btn';
    btnNext.textContent = 'Next →';
    btnNext.title = 'Next file (Right Arrow)';
    btnFinder.insertAdjacentElement('beforebegin', btnNext);
  }
  const navList = state.currentEagleAssetList || [];
  const hasMultiple = navList.length > 1;
  if (btnPrev) {
    btnPrev.hidden = !hasMultiple;
    btnPrev.onclick = () => {
      const curIdx = navList.findIndex(x => x.id === state.currentQuickLookAsset?.id || (x.localPath && x.localPath === state.currentQuickLookAsset?.localPath));
      if (curIdx !== -1) {
        openSpacebarPreview(navList[(curIdx - 1 + navList.length) % navList.length]);
      } else if (navList.length > 0) {
        openSpacebarPreview(navList[0]);
      }
    };
  }
  if (btnNext) {
    btnNext.hidden = !hasMultiple;
    btnNext.onclick = () => {
      const curIdx = navList.findIndex(x => x.id === state.currentQuickLookAsset?.id || (x.localPath && x.localPath === state.currentQuickLookAsset?.localPath));
      if (curIdx !== -1) {
        openSpacebarPreview(navList[(curIdx + 1) % navList.length]);
      } else if (navList.length > 0) {
        openSpacebarPreview(navList[0]);
      }
    };
  }

  // Ensure a direct "Show in Drive" button is available alongside "Show in Finder"
  let btnDriveWeb = document.getElementById('btnQuickLookDriveWeb');
  if (!btnDriveWeb && btnFinder && btnFinder.parentElement) {
    btnDriveWeb = document.createElement('a');
    btnDriveWeb.id = 'btnQuickLookDriveWeb';
    btnDriveWeb.className = 'cmp-chip-btn';
    btnDriveWeb.target = '_blank';
    btnDriveWeb.rel = 'noopener';
    btnDriveWeb.style.cssText = 'text-decoration:none;';
    btnFinder.insertAdjacentElement('beforebegin', btnDriveWeb);
  }
  if (btnDriveWeb) {
    const webUrl = asset.driveWebUrl || asset.driveUrl || '';
    btnDriveWeb.hidden = !webUrl;
    btnDriveWeb.textContent = isGDrivePage ? 'Show in Drive' : 'Drive ↗';
    if (webUrl) {
      btnDriveWeb.href = webUrl;
      btnDriveWeb.title = 'Show file in Google Drive';
    }
  }

  if (btnFinder) {
    btnFinder.hidden = isGDrivePage ? !asset.localPath : false;
    btnFinder.textContent = isGDrivePage ? 'Show in Finder' : 'Finder ↗';
    btnFinder.title = isGDrivePage ? 'Show file in Finder (marked in location, not opened)' : 'Reveal in Finder / Open Link';
    btnFinder.onclick = () => {
      if (asset.localPath) {
        revealItemInFinder(asset.localPath);
      } else if (asset.driveWebUrl) {
        window.open(asset.driveWebUrl, '_blank', 'noopener');
      } else if (asset.url) {
        openUrlOrMacPath(asset.url);
      }
    };
  }

  const syncQuickLookStatusButtons = () => {
    if (isGDrivePage) return;
    const vItem = asset.vaultItemId ? vault.items.find(i => i.id === asset.vaultItemId) : null;
    const st = vItem ? (vItem.igStatus || '') : (asset.igStatus || '');
    btnQueued?.classList.toggle('active', st === 'queued');
    btnPublished?.classList.toggle('active', st === 'published');
    btnWebsite?.classList.toggle('active', st === 'website');
  };
  syncQuickLookStatusButtons();

  const toggleAssetStatus = (targetStatus) => {
    if (isGDrivePage) return;
    const vItem = ensureVaultItemForAsset(asset);
    if (!vItem) return;
    vItem.igStatus = vItem.igStatus === targetStatus ? '' : targetStatus;
    asset.igStatus = vItem.igStatus;
    saveVault(vItem.igStatus === 'queued' ? 'MARKED IG READY' : (vItem.igStatus === 'published' ? 'MARKED IG LIVE' : (vItem.igStatus === 'website' ? 'STAGED FOR WEBSITE' : 'CLEARED TAG')));
    syncQuickLookStatusButtons();
    renderSidebar();
    renderWorkspace();
  };

  if (btnQueued) btnQueued.onclick = () => toggleAssetStatus('queued');
  if (btnPublished) btnPublished.onclick = () => toggleAssetStatus('published');
  if (btnWebsite) btnWebsite.onclick = () => toggleAssetStatus('website');
  if (btnPinToBoard) btnPinToBoard.onclick = () => sendDriveAssetToStudio(asset);

  if (btnInspect) {
    btnInspect.onclick = () => {
      const vItem = ensureVaultItemForAsset(asset);
      dlg.close();
      if (vItem) openItemInspector(vItem.id);
    };
  }

  if (btnClose) {
    btnClose.onclick = () => dlg.close();
  }

  if (!dlg._hasKeyNavListener) {
    dlg._hasKeyNavListener = true;
    dlg.addEventListener('keydown', (e) => {
      if (e.target.closest('input, textarea')) return;
      const list = state.currentEagleAssetList || [];
      if ((e.key === 'ArrowRight' || e.key === 'ArrowLeft') && list.length > 1 && state.currentQuickLookAsset) {
        e.preventDefault();
        const curIdx = list.findIndex(x => x.id === state.currentQuickLookAsset.id || (x.localPath && x.localPath === state.currentQuickLookAsset.localPath));
        if (curIdx !== -1) {
          const nextIdx = (curIdx + (e.key === 'ArrowRight' ? 1 : -1) + list.length) % list.length;
          openSpacebarPreview(list[nextIdx]);
        } else if (list.length > 0) {
          openSpacebarPreview(list[0]);
        }
      } else if (e.code === 'Space') {
        e.preventDefault();
        dlg.close();
      }
    });
  }

  if (!dlg.open) dlg.showModal();
}

function buildGDriveEnclosingCardEl(enc, idx) {
  const card = document.createElement('article');
  card.className = 'gdrive-file-card gdrive-enclosing-card';
  card.dataset.enclosing = enc.name;
  card.style.cursor = 'pointer';
  card.setAttribute('draggable', 'true');

  card.addEventListener('dragstart', (e) => {
    e.dataTransfer.setData('application/x-ideal-enclosing', enc.name);
    e.dataTransfer.effectAllowed = 'move';
    card.classList.add('is-dragging');
  });
  card.addEventListener('dragend', () => {
    card.classList.remove('is-dragging');
    document.querySelectorAll('.gdrive-enclosing-card').forEach(c => c.classList.remove('is-drag-over-left', 'is-drag-over-right'));
  });
  card.addEventListener('dragover', (e) => {
    if (!e.dataTransfer.types.includes('application/x-ideal-enclosing')) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    const rect = card.getBoundingClientRect();
    const isLeft = e.clientX < (rect.left + rect.width / 2);
    card.classList.toggle('is-drag-over-left', isLeft);
    card.classList.toggle('is-drag-over-right', !isLeft);
  });
  card.addEventListener('dragleave', () => {
    card.classList.remove('is-drag-over-left', 'is-drag-over-right');
  });
  card.addEventListener('drop', (e) => {
    card.classList.remove('is-drag-over-left', 'is-drag-over-right');
    const sourceName = e.dataTransfer.getData('application/x-ideal-enclosing');
    if (!sourceName || sourceName === enc.name) return;
    e.preventDefault();
    e.stopPropagation();

    const rect = card.getBoundingClientRect();
    const insertBefore = e.clientX < (rect.left + rect.width / 2);

    const targetSec = getEnclosingFolderSection(enc.name);
    setEnclosingFolderSection(sourceName, targetSec);

    const currentList = [...(state.gdriveEnclosingFolders || [])];
    const srcIdx = currentList.findIndex(x => x.name === sourceName);
    if (srcIdx === -1) return;
    const [removed] = currentList.splice(srcIdx, 1);
    let targetIdx = currentList.findIndex(x => x.name === enc.name);
    if (targetIdx === -1) targetIdx = currentList.length;
    if (!insertBefore) targetIdx++;
    currentList.splice(targetIdx, 0, removed);
    state.gdriveEnclosingFolders = currentList;

    const newNamesOrder = currentList.map(x => x.name);
    localStorage.setItem('ideal_gdrive_enclosing_order', JSON.stringify(newNamesOrder));
    vault.customization.enclosingOrder = newNamesOrder;

    const gdriveSp = vault.spaces.find(s => s.id === 'gdrive_assets');
    if (gdriveSp) {
      gdriveSp.categories = ['All', ...newNamesOrder];
    }
    saveVault('REORDER ASSETS & VAULTS');
    renderFilterActionRow();
    renderWorkspace();
    showStatusToast(`Moved "${sourceName}" to ${targetSec === 'assets' ? 'Assets' : 'Vaults'}`);
  });

  let customPreviews = vault?.enclosingPreviews?.[enc.name] || vault?.customization?.enclosingPreviews?.[enc.name];
  if (!Array.isArray(customPreviews) || customPreviews.length === 0) {
    try {
      const raw = localStorage.getItem('ideal_gdrive_enclosing_previews');
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed[enc.name]) && parsed[enc.name].length > 0) {
          customPreviews = parsed[enc.name];
        }
      }
    } catch (e) {}
  }
  const rawExList = (Array.isArray(customPreviews) && customPreviews.length > 0)
    ? customPreviews
    : (enc.examples || []);
  const visibleFour = rawExList.slice(0, 4);

  const tilesHtml = visibleFour.map((ex, tIdx) => {
    const primarySrc = getGDriveAssetThumbSrc(ex);
    const fallbackSrc = getGDriveAssetFallbackSrc(ex);
    const extBadge = (ex.ext || '').replace('.', '').toUpperCase() || 'FILE';
    const isLcpImg = idx === 0 && tIdx === 0;
    const priorityAttr = isLcpImg ? 'fetchpriority="high"' : 'loading="lazy" decoding="async"';
    const driveUrl = ex.driveWebUrl || ex.driveUrl || enc.driveFolderUrl || '';

    return `
      <div class="gdrive-preview-tile" data-local-path="${escapeHtml(ex.localPath || '')}" data-drive-url="${escapeHtml(driveUrl)}" title="${escapeHtml(ex.name)}${ex.sizeLabel ? ` (${escapeHtml(ex.sizeLabel)})` : ''} • Click to open • Spacebar Quick-Look">
        <img src="${escapeHtml(primarySrc)}" data-fallback="${escapeHtml(fallbackSrc)}" alt="${escapeHtml(ex.name)}" ${priorityAttr} draggable="false">
      </div>
    `;
  }).join('');

  const countLabel = `${enc.subfolderCount} ${enc.subfolderCount === 1 ? 'folder' : 'folders'}`;

  card.innerHTML = `
    <button type="button" class="btn-pick-previews" data-enclosing="${escapeHtml(enc.name)}" title="Pick preview images for ${escapeHtml(enc.name)}">
      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
        <path d="M17 3a2.828 2.828 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5L17 3z"/>
      </svg>
    </button>
    <div class="gdrive-file-stage" title="Click to view subfolders in ${escapeHtml(enc.name)} (${countLabel})">
      <div class="gdrive-four-grid count-${visibleFour.length}">
        ${tilesHtml}
      </div>
    </div>
    <div class="gdrive-file-body">
      <div class="gdrive-file-info-row">
        <div class="gdrive-file-title" title="${escapeHtml(enc.name)}">${escapeHtml(enc.name)}</div>
        <div class="gdrive-file-sub"><span>${countLabel}</span></div>
      </div>
    </div>
  `;

  card.querySelectorAll('.gdrive-preview-tile img').forEach(img => {
    img.addEventListener('error', () => {
      const fb = img.dataset.fallback;
      if (fb && img.src !== fb && !img.dataset.triedFallback) {
        img.dataset.triedFallback = '1';
        img.src = fb;
      } else if (!img.dataset.triedSvg) {
        img.dataset.triedSvg = '1';
        img.src = getClientAssetSpecimenSvg(img.alt || 'Asset', 'FILE', enc.name);
      }
    });
  });

  const openThisEnclosing = () => {
    state.activeGDriveEnclosingFolder = enc.name;
    state.activeCategory = enc.name;
    saveNavState();
    renderFilterActionRow();
    renderWorkspace();
  };

  card.querySelectorAll('.gdrive-preview-tile').forEach((tile, tIdx) => {
    const ex = visibleFour[tIdx];
    const localPath = tile.dataset.localPath;
    const driveUrl = tile.dataset.driveUrl || enc.driveFolderUrl || '';
    const extUpper = (ex?.ext || '').replace('.', '').toUpperCase();
    const previewAssetObj = ex ? {
      id: `${enc.id}_ex_${ex.sid || tIdx}`,
      title: ex.name,
      rawName: ex.name,
      category: enc.name,
      ext: extUpper,
      cid: ex.cid,
      kind: ['MP4', 'MOV', 'WEBM'].includes(extUpper) ? 'video' : 'image',
      thumbSrc: getGDriveAssetThumbSrc(ex),
      fallbackSrc: getGDriveAssetFallbackSrc(ex),
      driveEmbedUrl: ex.driveEmbedUrl,
      driveDownloadUrl: ex.driveDownloadUrl,
      localPath,
      driveWebUrl: driveUrl,
      sizeLabel: ex.sizeLabel || extUpper
    } : null;

    tile.addEventListener('mouseenter', () => {
      if (previewAssetObj) state.hoveredAssetForQuickLook = previewAssetObj;
    });
    tile.addEventListener('mouseleave', () => {
      if (previewAssetObj && state.hoveredAssetForQuickLook && state.hoveredAssetForQuickLook.id === previewAssetObj.id) {
        state.hoveredAssetForQuickLook = null;
      }
    });
    tile.addEventListener('click', (e) => {
      e.stopPropagation();
      if ((e.metaKey || e.shiftKey) && driveUrl) {
        window.open(driveUrl, '_blank', 'noopener');
        return;
      }
      openThisEnclosing();
    });
  });

  card.addEventListener('click', (e) => {
    if (e.target.closest('a') || e.target.closest('button')) return;
    openThisEnclosing();
  });

  card.querySelector('.btn-pick-previews')?.addEventListener('click', (e) => {
    e.stopPropagation();
    openEnclosingPreviewPicker(enc);
  });

  return card;
}

function openEnclosingPreviewPicker(enc) {
  const dlg = document.getElementById('enclosingPreviewPickerDialog');
  if (!dlg) return;

  const targetEncName = (enc.name || '').toLowerCase();
  const matchingBatches = (state.gdriveBatches || []).filter(b => {
    const bEnc = (b.enclosingFolder || '').toLowerCase();
    const bCat = (b.category || '').toLowerCase();
    const bRel = (b.relPath || '').toLowerCase();
    return bEnc === targetEncName || bCat === targetEncName || bRel.startsWith(`assets/${targetEncName}/`) || bRel.includes(`/${targetEncName}/`);
  });

  // Collect all unique candidates from batches
  const candidates = [];
  const seenPaths = new Set();
  matchingBatches.forEach(b => {
    (b.examples || []).forEach(ex => {
      const key = ex.localPath || ex.thumbUrl || ex.name;
      if (!seenPaths.has(key)) {
        seenPaths.add(key);
        candidates.push({ ...ex, batchTitle: b.title });
      }
    });
  });

  if (candidates.length === 0) {
    (enc.examples || []).forEach(ex => {
      const key = ex.localPath || ex.thumbUrl || ex.name;
      if (!seenPaths.has(key)) {
        seenPaths.add(key);
        candidates.push(ex);
      }
    });
  }

  // Load currently saved custom previews or default to the current 4
  let currentSaved = vault?.enclosingPreviews?.[enc.name] || vault?.customization?.enclosingPreviews?.[enc.name];
  if (!Array.isArray(currentSaved) || currentSaved.length === 0) {
    try {
      const raw = localStorage.getItem('ideal_gdrive_enclosing_previews');
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed[enc.name])) currentSaved = parsed[enc.name];
      }
    } catch (e) {}
  }
  if (!Array.isArray(currentSaved) || currentSaved.length === 0) {
    currentSaved = (enc.examples || []).slice(0, 4);
  }

  let selected = [...currentSaved];

  const headingEl = document.getElementById('previewPickerHeading');
  const subEl = document.getElementById('previewPickerSub');
  const counterEl = document.getElementById('previewPickerCounter');
  const gridEl = document.getElementById('previewPickerGrid');

  if (headingEl) headingEl.textContent = `Pick 4 Preview Images — ${enc.name}`;
  if (subEl) subEl.textContent = `Click any image to select or deselect. The 4 chosen images will display on the ${enc.name} card.`;

  const getKey = (item) => item?.localPath || item?.thumbUrl || item?.name || '';

  const updateGridUI = () => {
    if (counterEl) counterEl.textContent = `${selected.length} / 4 Selected`;
    gridEl.querySelectorAll('.preview-picker-item').forEach(itemEl => {
      const itemKey = itemEl.dataset.key;
      const idx = selected.findIndex(s => getKey(s) === itemKey);
      const isSel = idx !== -1;
      itemEl.classList.toggle('is-selected', isSel);
      let badge = itemEl.querySelector('.preview-picker-badge');
      if (isSel) {
        if (!badge) {
          badge = document.createElement('span');
          badge.className = 'preview-picker-badge';
          itemEl.appendChild(badge);
        }
        badge.textContent = String(idx + 1);
      } else if (badge) {
        badge.remove();
      }
    });
  };

  gridEl.innerHTML = candidates.map(cand => {
    const key = getKey(cand);
    const thumb = getGDriveAssetThumbSrc(cand);
    const fallback = getGDriveAssetFallbackSrc(cand);
    return `
      <div class="preview-picker-item" data-key="${escapeHtml(key)}" title="${escapeHtml(cand.name || '')}">
        <img src="${escapeHtml(thumb)}" data-fallback="${escapeHtml(fallback)}" alt="${escapeHtml(cand.name || '')}" loading="lazy">
      </div>
    `;
  }).join('');

  gridEl.querySelectorAll('.preview-picker-item img').forEach(img => {
    img.addEventListener('error', () => {
      const fb = img.dataset.fallback;
      if (fb && img.src !== fb && !img.dataset.triedFb) {
        img.dataset.triedFb = '1';
        img.src = fb;
      } else if (!img.dataset.triedSvg) {
        img.dataset.triedSvg = '1';
        img.src = getClientAssetSpecimenSvg(img.alt || 'Asset', 'FILE');
      }
    });
  });

  gridEl.querySelectorAll('.preview-picker-item').forEach(itemEl => {
    itemEl.addEventListener('click', () => {
      const itemKey = itemEl.dataset.key;
      const existingIdx = selected.findIndex(s => getKey(s) === itemKey);
      if (existingIdx !== -1) {
        selected.splice(existingIdx, 1);
      } else {
        const candObj = candidates.find(c => getKey(c) === itemKey);
        if (candObj) {
          if (selected.length >= 4) {
            selected[3] = candObj;
          } else {
            selected.push(candObj);
          }
        }
      }
      updateGridUI();
    });
  });

  updateGridUI();

  const btnSave = document.getElementById('btnSavePreviewPicker');
  const btnReset = document.getElementById('btnResetPreviewPicker');
  const btnCancel = document.getElementById('btnCancelPreviewPicker');
  const btnClose = document.getElementById('btnClosePreviewPicker');

  const cleanup = () => {
    dlg.close();
  };

  btnSave.onclick = () => {
    vault.enclosingPreviews = vault.enclosingPreviews || {};
    vault.enclosingPreviews[enc.name] = selected;
    vault.customization = vault.customization || {};
    vault.customization.enclosingPreviews = vault.enclosingPreviews;

    try {
      localStorage.setItem('ideal_gdrive_enclosing_previews', JSON.stringify(vault.enclosingPreviews));
    } catch (e) {}

    saveVault(`SET CARD PREVIEWS FOR ${enc.name}`);
    showStatusToast(`Updated ${enc.name} preview images`);
    cleanup();
    renderWorkspace();
  };

  btnReset.onclick = () => {
    vault.enclosingPreviews = vault.enclosingPreviews || {};
    delete vault.enclosingPreviews[enc.name];
    vault.customization = vault.customization || {};
    vault.customization.enclosingPreviews = vault.enclosingPreviews;
    try {
      localStorage.setItem('ideal_gdrive_enclosing_previews', JSON.stringify(vault.enclosingPreviews));
    } catch (e) {}
    saveVault(`RESET CARD PREVIEWS FOR ${enc.name}`);
    showStatusToast(`Reset ${enc.name} preview images to default`);
    cleanup();
    renderWorkspace();
  };

  btnCancel.onclick = cleanup;
  btnClose.onclick = cleanup;

  dlg.showModal();
}

function buildGDriveBatchCardEl(batch, idx) {
  const card = document.createElement('article');
  card.className = 'gdrive-file-card';
  card.dataset.id = batch.id;
  card.style.cursor = 'pointer';
  const batchTitle = batch.title;

  const fmt = state.eagleFormatFilter || 'all';
  const rawExList = batch.examples || [];
  const exList = fmt === 'all'
    ? rawExList
    : [
        ...rawExList.filter(ex => matchesGDriveFormatFilter(ex.ext, fmt)),
        ...rawExList.filter(ex => !matchesGDriveFormatFilter(ex.ext, fmt))
      ];
  const offset = state.gdriveOffsets[batch.id] || 0;
  const visibleSix = [];
  if (exList.length > 0) {
    const count = Math.min(6, exList.length);
    for (let i = 0; i < count; i++) {
      visibleSix.push(exList[(offset + i) % exList.length]);
    }
  }

  const tilesHtml = visibleSix.map((ex, tIdx) => {
    const primarySrc = getGDriveAssetThumbSrc(ex);
    const fallbackSrc = getGDriveAssetFallbackSrc(ex);
    const extBadge = (ex.ext || '').replace('.', '').toUpperCase() || 'FILE';
    const isLcpImg = idx === 0 && tIdx === 0;
    const priorityAttr = isLcpImg ? 'fetchpriority="high"' : 'loading="lazy" decoding="async"';
    const driveUrl = ex.driveWebUrl || ex.driveUrl || batch.driveFolderUrl || '';

    return `
      <div class="gdrive-preview-tile" data-local-path="${escapeHtml(ex.localPath)}" data-drive-url="${escapeHtml(driveUrl)}" title="${escapeHtml(ex.name)}${ex.sizeLabel ? ` (${escapeHtml(ex.sizeLabel)})` : ''} • Click to open folder • Spacebar Quick-Look">
        <img src="${escapeHtml(primarySrc)}" data-fallback="${escapeHtml(fallbackSrc)}" alt="${escapeHtml(ex.name)}" ${priorityAttr}>
        <span class="gdrive-ext-tag">${escapeHtml(extBadge)}</span>
      </div>
    `;
  }).join('');

  const countLabel = `${batch.totalCount} ${batch.totalCount === 1 ? 'file' : 'files'}`;

  card.innerHTML = `
    <div class="gdrive-file-stage" title="Click to open ${escapeHtml(batchTitle)} (${countLabel})">
      <div class="gdrive-six-grid count-${visibleSix.length}">
        ${tilesHtml}
      </div>
    </div>
    <div class="gdrive-file-body">
      <div class="gdrive-file-title">${escapeHtml(batchTitle)}</div>
      <div class="gdrive-file-sub">
        <span>${countLabel}</span>
      </div>
      <div class="gdrive-file-actions">
        <a href="${escapeHtml(batch.driveFolderUrl)}" target="_blank" rel="noopener" class="gdrive-pill-btn" title="Show folder in Google Drive">Show in Drive</a>
        <button type="button" class="gdrive-pill-btn btn-finder-folder" title="Show folder in Finder (marked in location, not opened)">Show in Finder</button>
      </div>
    </div>
  `;

  card.querySelectorAll('.gdrive-preview-tile img').forEach(img => {
    img.addEventListener('error', () => {
      const fb = img.dataset.fallback;
      if (fb && img.src !== fb && !img.dataset.triedFallback) {
        img.dataset.triedFallback = '1';
        img.src = fb;
      } else if (!img.dataset.triedSvg) {
        img.dataset.triedSvg = '1';
        img.src = getClientAssetSpecimenSvg(img.alt || 'Asset', 'FILE', enc.name);
      }
    });
  });

  const openThisFolder = () => {
    state.activeGDriveBatchId = batch.id;
    saveNavState();
    renderFilterActionRow();
    renderWorkspace();
  };

  card.querySelectorAll('.gdrive-preview-tile').forEach((tile, tIdx) => {
    const ex = visibleSix[tIdx];
    const localPath = tile.dataset.localPath;
    const driveUrl = tile.dataset.driveUrl || batch.driveFolderUrl || '';
    const extUpper = (ex?.ext || '').replace('.', '').toUpperCase();
    const previewAssetObj = ex ? {
      id: `${batch.id}_ex_${ex.sid || tIdx}`,
      title: ex.name,
      rawName: ex.name,
      category: batchTitle,
      batchId: batch.id,
      ext: extUpper,
      cid: ex.cid,
      kind: ['MP4', 'MOV', 'WEBM'].includes(extUpper) ? 'video' : 'image',
      thumbSrc: getGDriveAssetThumbSrc(ex),
      fallbackSrc: getGDriveAssetFallbackSrc(ex),
      driveEmbedUrl: ex.driveEmbedUrl,
      driveDownloadUrl: ex.driveDownloadUrl,
      localPath,
      driveWebUrl: driveUrl,
      sizeLabel: ex.sizeLabel || extUpper
    } : null;

    tile.addEventListener('mouseenter', () => {
      if (previewAssetObj) state.hoveredAssetForQuickLook = previewAssetObj;
    });
    tile.addEventListener('mouseleave', () => {
      if (previewAssetObj && state.hoveredAssetForQuickLook && state.hoveredAssetForQuickLook.id === previewAssetObj.id) {
        state.hoveredAssetForQuickLook = null;
      }
    });
    tile.addEventListener('click', (e) => {
      e.stopPropagation();
      if ((e.metaKey || e.shiftKey) && driveUrl) {
        window.open(driveUrl, '_blank', 'noopener');
        return;
      }
      openThisFolder();
    });
  });

  card.addEventListener('click', (e) => {
    if (e.target.closest('a') || e.target.closest('button')) return;
    openThisFolder();
  });

  card.querySelector('.btn-finder-folder')?.addEventListener('click', (e) => {
    e.stopPropagation();
    revealItemInFinder(batch.localFolder);
  });

  return card;
}

async function revealItemInFinder(localPath) {
  if (!localPath) return;
  try {
    await fetch('/api/reveal', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ localPath, revealOnly: true })
    });
  } catch (e) {}
}

async function revealFolderInFinder(folderPath) {
  if (!folderPath) return;
  try {
    await fetch('/api/reveal', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ localPath: folderPath, revealOnly: true })
    });
  } catch (e) {}
}

/* --------------------------------------------------------------------------
   SHARED SPATIAL CAMERA ENGINE (Zoom, Pan, 24px Snap Grid, Tidy)
   + PURE VECTOR CONNECTOR LINES & ENCLOSING SPHERE CONTAINERS
   -------------------------------------------------------------------------- */
function deleteItemDirectly(itemId) {
  if (!itemId) return;
  const it = vault.items.find(x => x.id === itemId);
  if (it) {
    requestDelete('item', it.id, it.title || (it.kind ? it.kind.toUpperCase() : 'Board Item'));
    return;
  }
  const proj = vault.projects.find(p => p.id === itemId);
  if (proj) {
    requestDelete('project', proj.id, proj.title || 'Project Board');
  }
}

function buildSpatialConnectorEl(it, isOverview = false) {
  const pin = document.createElement('div');
  pin.className = 'wall-pin-item is-line-pin';
  pin.dataset.itemId = it.id;
  pin.dataset.id = it.id;
  pin.dataset.itemKind = 'line';

  const updateConnectorCoords = () => {
    const lx1 = typeof it.lineX1 === 'number' ? it.lineX1 : (it.wallX || 264);
    const ly1 = typeof it.lineY1 === 'number' ? it.lineY1 : (it.wallY || 108);
    const lx2 = typeof it.lineX2 === 'number' ? it.lineX2 : (lx1 + (it.wallW || 240));
    const ly2 = typeof it.lineY2 === 'number' ? it.lineY2 : ly1;
    it.lineX1 = lx1;
    it.lineY1 = ly1;
    it.lineX2 = lx2;
    it.lineY2 = ly2;

    const pad = 24;
    const minX = Math.min(lx1, lx2) - pad;
    const minY = Math.min(ly1, ly2) - pad;
    const maxX = Math.max(lx1, lx2) + pad;
    const maxY = Math.max(ly1, ly2) + pad;
    const lineW = Math.max(48, maxX - minX);
    const lineH = Math.max(48, maxY - minY);

    pin.style.left = `${minX}px`;
    pin.style.top = `${minY}px`;
    pin.style.width = `${lineW}px`;
    pin.style.height = `${lineH}px`;

    const pX1 = lx1 - minX;
    const pY1 = ly1 - minY;
    const pX2 = lx2 - minX;
    const pY2 = ly2 - minY;
    const midX = (pX1 + pX2) / 2;
    const midY = (pY1 + pY2) / 2;

    pin.innerHTML = `
      <div class="mn-connector-wrap">
        <svg class="mn-connector-svg" viewBox="0 0 ${lineW} ${lineH}">
          <defs>
            <marker id="arrow_${it.id}" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto">
              <path d="M0,0 L0,6 L7,3 z" fill="var(--text)" />
            </marker>
          </defs>
          <line x1="${pX1}" y1="${pY1}" x2="${pX2}" y2="${pY2}" stroke="transparent" stroke-width="26" stroke-linecap="round" style="cursor:grab;pointer-events:stroke;"></line>
          <line class="mn-connector-path" x1="${pX1}" y1="${pY1}" x2="${pX2}" y2="${pY2}" marker-end="url(#arrow_${it.id})"></line>
        </svg>
        <div class="line-handle line-handle-start" data-handle="start" style="left:${pX1}px;top:${pY1}px;" title="Drag to move connector start"></div>
        <div class="line-handle line-handle-end" data-handle="end" style="left:${pX2}px;top:${pY2}px;" title="Drag arrow tip"></div>
        <button type="button" class="line-delete-btn" style="left:${midX}px;top:${midY}px;" title="Delete connector line">✕</button>
      </div>
    `;

    pin.querySelector('.line-delete-btn')?.addEventListener('click', (e) => {
      e.stopPropagation();
      deleteItemDirectly(it.id);
    });

    const hStart = pin.querySelector('.line-handle-start');
    const hEnd = pin.querySelector('.line-handle-end');

    const bindEndpoint = (handleEl, isStart) => {
      handleEl.addEventListener('pointerdown', (ev) => {
        if (ev.button !== 0) return;
        ev.stopPropagation();
        handleEl.classList.add('is-dragging');
        try { handleEl.setPointerCapture(ev.pointerId); } catch (_) {}
        const origPtX = isStart ? it.lineX1 : it.lineX2;
        const origPtY = isStart ? it.lineY1 : it.lineY2;
        const startEvX = ev.clientX;
        const startEvY = ev.clientY;
        const cam = getActiveBoardCamera();

        const onMove = (mev) => {
          const dx = (mev.clientX - startEvX) / (cam.zoom || 1);
          const dy = (mev.clientY - startEvY) / (cam.zoom || 1);
          const newX = snapCoord(origPtX + dx, mev.altKey);
          const newY = snapCoord(origPtY + dy, mev.altKey);
          if (isStart) {
            it.lineX1 = newX;
            it.lineY1 = newY;
          } else {
            it.lineX2 = newX;
            it.lineY2 = newY;
          }
          it.wallX = Math.min(it.lineX1, it.lineX2);
          it.wallY = Math.min(it.lineY1, it.lineY2);
          it.wallW = Math.abs(it.lineX2 - it.lineX1);
          updateConnectorCoords();
        };

        const onUp = () => {
          handleEl.classList.remove('is-dragging');
          handleEl.removeEventListener('pointermove', onMove);
          handleEl.removeEventListener('lostpointercapture', onUp);
          saveVault('CONNECTOR LINE MOVED');
        };

        handleEl.addEventListener('pointermove', onMove);
        handleEl.addEventListener('lostpointercapture', onUp);
      });
    };

    if (hStart) bindEndpoint(hStart, true);
    if (hEnd) bindEndpoint(hEnd, false);
  };

  updateConnectorCoords();

  // Allow dragging the entire connector line
  pin.addEventListener('pointerdown', (e) => {
    if (e.button !== 0 || e.target.closest('.line-handle') || e.target.closest('.line-delete-btn')) return;
    e.stopPropagation();
    try { pin.setPointerCapture(e.pointerId); } catch (_) {}
    const startX = e.clientX;
    const startY = e.clientY;
    const origX1 = it.lineX1;
    const origY1 = it.lineY1;
    const origX2 = it.lineX2;
    const origY2 = it.lineY2;
    const cam = getActiveBoardCamera();

    const onMove = (ev) => {
      const dx = (ev.clientX - startX) / (cam.zoom || 1);
      const dy = (ev.clientY - startY) / (cam.zoom || 1);
      it.lineX1 = snapCoord(origX1 + dx, ev.altKey);
      it.lineY1 = snapCoord(origY1 + dy, ev.altKey);
      it.lineX2 = snapCoord(origX2 + dx, ev.altKey);
      it.lineY2 = snapCoord(origY2 + dy, ev.altKey);
      it.wallX = Math.min(it.lineX1, it.lineX2);
      it.wallY = Math.min(it.lineY1, it.lineY2);
      it.wallW = Math.abs(it.lineX2 - it.lineX1);
      updateConnectorCoords();
    };

    const onUp = () => {
      pin.removeEventListener('pointermove', onMove);
      pin.removeEventListener('lostpointercapture', onUp);
      saveVault('CONNECTOR MOVED');
    };

    pin.addEventListener('pointermove', onMove);
    pin.addEventListener('lostpointercapture', onUp);
  });

  return pin;
}

function buildSphereContainerEl(it) {
  const pin = document.createElement('div');
  pin.className = 'wall-pin-item is-sphere-container-pin';
  pin.dataset.itemId = it.id;
  pin.dataset.id = it.id;
  pin.dataset.itemKind = 'sphere';

  const w = it.wallW || 520;
  const h = it.wallH || 520;
  pin.style.left = `${it.wallX || 264}px`;
  pin.style.top = `${it.wallY || 108}px`;
  pin.style.width = `${w}px`;
  pin.style.height = `${h}px`;

  const childItems = vault.items.filter(c => c.sphereId === it.id);

  pin.innerHTML = `
    <div class="mn-sphere-container" data-sphere-id="${escapeHtml(it.id)}">
      <button type="button" class="pin-quick-delete-btn" title="Delete Sphere container">✕</button>
      <div class="mn-sphere-items-layer">
        ${childItems.length ? childItems.map((c, i) => {
          const total = childItems.length;
          const goldenAngle = 2.39996;
          const radiusPct = total === 1 ? 0 : Math.min(38, 12 + Math.sqrt(i + 1) * (26 / Math.sqrt(total)));
          const theta = i * goldenAngle;
          const cxPct = 50 + Math.cos(theta) * radiusPct;
          const cyPct = 50 + Math.sin(theta) * radiusPct;
          const isVisual = Boolean(c.url && c.kind !== 'audio');
          return `
            <div class="mn-sphere-child-node" data-child-id="${escapeHtml(c.id)}" style="left:${cxPct.toFixed(1)}%;top:${cyPct.toFixed(1)}%;width:74px;height:74px;" title="${escapeHtml(c.title || 'Enclosed item')}">
              ${isVisual ? `<img src="${escapeHtml(c.url)}" alt="" draggable="false">` : `<div style="padding:6px;font-size:10px;font-family:var(--font-mono);line-height:1.2;overflow:hidden;height:100%;color:var(--text);">${escapeHtml(c.title || c.notes || 'Note')}</div>`}
              <button type="button" class="child-eject-btn" data-eject-id="${escapeHtml(c.id)}" title="Pop out of sphere onto board">↗</button>
            </div>
          `;
        }).join('') : `
          <div class="mn-sphere-empty-prompt">
            <div style="font-size:24px;margin-bottom:4px;">◎</div>
            <strong style="font-size:12px;font-family:var(--font-mono);display:block;margin-bottom:2px;">ENCLOSING SPHERE</strong>
            <span style="font-size:11px;">Drop photos, notes or sketches here to arrange them in a sphere</span>
          </div>
        `}
      </div>
      <div class="mn-sphere-capsule">
        <span class="mn-sphere-title" contenteditable="true" spellcheck="false">${escapeHtml(it.title || 'Sphere Batch')}</span>
        <span class="mn-sphere-count-pill">${childItems.length} items</span>
        ${childItems.length > 0 ? `<button type="button" class="btn-sphere-turn-proj">✨ Turn into Project</button>` : ''}
      </div>
      <div class="wall-resize-handle" title="Drag corner to resize"></div>
    </div>
  `;

  pin.querySelector('.pin-quick-delete-btn')?.addEventListener('click', (e) => {
    e.stopPropagation();
    childItems.forEach(c => { delete c.sphereId; });
    deleteItemDirectly(it.id);
  });

  const titleEl = pin.querySelector('.mn-sphere-title');
  titleEl?.addEventListener('pointerdown', (e) => e.stopPropagation());
  titleEl?.addEventListener('blur', () => {
    it.title = (titleEl.textContent || '').trim() || 'Sphere Batch';
    saveVault('SPHERE RENAMED');
  });

  pin.querySelector('.btn-sphere-turn-proj')?.addEventListener('click', (e) => {
    e.stopPropagation();
    state.batchSelectedIds = new Set(childItems.map(c => c.id));
    openBatchToProjectDialog();
  });

  pin.querySelectorAll('.child-eject-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const child = vault.items.find(x => x.id === btn.dataset.ejectId);
      if (child) {
        delete child.sphereId;
        child.wallX = (it.wallX || 264) + (it.wallW || 520) + 24;
        child.wallY = it.wallY || 108;
        saveVault('POPPED OUT OF SPHERE');
        renderWorkspace();
        showStatusToast('↗ Item popped out of sphere');
      }
    });
  });

  pin.querySelectorAll('.mn-sphere-child-node').forEach(node => {
    node.addEventListener('click', (e) => {
      if (e.target.closest('.child-eject-btn')) return;
      e.stopPropagation();
      openItemInspector(node.dataset.childId);
    });
  });

  // Dragging the entire sphere container
  pin.addEventListener('pointerdown', (e) => {
    if (e.button !== 0 || e.target.closest('button') || e.target.closest('.mn-sphere-child-node') || e.target.closest('.wall-resize-handle') || e.target.closest('.mn-sphere-title')) return;
    e.stopPropagation();
    try { pin.setPointerCapture(e.pointerId); } catch (_) {}
    const startX = e.clientX;
    const startY = e.clientY;
    const origX = it.wallX || 264;
    const origY = it.wallY || 108;
    const cam = getActiveBoardCamera();

    const onMove = (ev) => {
      const dx = (ev.clientX - startX) / (cam.zoom || 1);
      const dy = (ev.clientY - startY) / (cam.zoom || 1);
      it.wallX = snapCoord(origX + dx, ev.altKey);
      it.wallY = snapCoord(origY + dy, ev.altKey);
      pin.style.left = `${it.wallX}px`;
      pin.style.top = `${it.wallY}px`;
    };

    const onUp = () => {
      pin.removeEventListener('pointermove', onMove);
      pin.removeEventListener('lostpointercapture', onUp);
      saveVault('SPHERE CONTAINER MOVED');
    };

    pin.addEventListener('pointermove', onMove);
    pin.addEventListener('lostpointercapture', onUp);
  });

  // Resizing the sphere container
  const rHandle = pin.querySelector('.wall-resize-handle');
  rHandle?.addEventListener('pointerdown', (e) => {
    e.stopPropagation();
    try { rHandle.setPointerCapture(e.pointerId); } catch (_) {}
    const startX = e.clientX;
    const startW = it.wallW || 520;
    const cam = getActiveBoardCamera();

    const onRMove = (ev) => {
      const dw = (ev.clientX - startX) / (cam.zoom || 1);
      const nextSize = Math.max(340, Math.min(1200, snapCoord(startW + dw, ev.altKey)));
      it.wallW = nextSize;
      it.wallH = nextSize;
      pin.style.width = `${nextSize}px`;
      pin.style.height = `${nextSize}px`;
    };

    const onRUp = () => {
      rHandle.removeEventListener('pointermove', onRMove);
      rHandle.removeEventListener('lostpointercapture', onRUp);
      saveVault('SPHERE RESIZED');
      renderWorkspace();
    };

    rHandle.addEventListener('pointermove', onRMove);
    rHandle.addEventListener('lostpointercapture', onRUp);
  });

  return pin;
}

function renderBatchActionBar(stage, plane) {
  let bar = document.getElementById('wallBatchActionBar');
  const count = (state.batchSelectedIds && state.batchSelectedIds.size) || 0;
  if (count === 0) {
    if (bar) bar.remove();
    return;
  }

  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'wallBatchActionBar';
    bar.className = 'wall-batch-action-bar';
    stage.appendChild(bar);
  }

  const selectedIds = Array.from(state.batchSelectedIds || []);
  const hasBoardItems = selectedIds.some(id => vault.items.some(it => it.id === id));
  const isInsideProjBoard = state.viewType === 'project';

  bar.innerHTML = `
    <span class="batch-count-pill">${count} item${count === 1 ? '' : 's'} selected</span>
    ${hasBoardItems ? `<button type="button" class="btn-batch-enclose-folder" id="btnBatchEncloseFolder" title="Group selected items into a See-Through Folder">📁 Group in Folder</button>` : ''}
    ${hasBoardItems ? `<button type="button" class="btn-batch-to-project" id="btnBatchToProject">${isInsideProjBoard ? '✨ Split to New Project' : '✨ Turn into Project'}</button>` : ''}
    ${hasBoardItems ? `<button type="button" class="btn-batch-enclose-sphere" id="btnBatchEncloseSphere" title="Wrap items inside an Enclosing Sphere">◎ Enclose in Sphere</button>` : ''}
    ${hasBoardItems && count >= 2 ? `<button type="button" class="btn-batch-connect" id="btnBatchConnect" title="Connect items with arrow">⤹ Connect</button>` : ''}
    <button type="button" class="btn-batch-delete-all" id="btnBatchDeleteAll" title="Delete selected items">🗑 Delete</button>
    <button type="button" class="btn-batch-clear" id="btnBatchClear" title="Deselect">✕</button>
  `;

  bar.querySelector('#btnBatchClear')?.addEventListener('click', () => {
    state.batchSelectedIds.clear();
    plane?.querySelectorAll('.is-batch-selected').forEach(el => el.classList.remove('is-batch-selected'));
    bar.remove();
  });

  bar.querySelector('#btnBatchConnect')?.addEventListener('click', () => {
    connectBatchSelectedItems();
  });

  bar.querySelector('#btnBatchEncloseFolder')?.addEventListener('click', () => {
    encloseSelectedItemsInFolder();
  });

  bar.querySelector('#btnBatchToProject')?.addEventListener('click', () => {
    openBatchToProjectDialog();
  });

  bar.querySelector('#btnBatchEncloseSphere')?.addEventListener('click', () => {
    encloseSelectedItemsInSphere();
  });

  bar.querySelector('#btnBatchDeleteAll')?.addEventListener('click', () => {
    const ids = Array.from(state.batchSelectedIds || []);
    if (ids.length === 0) return;
    if (ids.length === 1) {
      deleteItemDirectly(ids[0]);
      return;
    }
    requestDelete('batch_items', ids, `${ids.length} selected items`);
  });
}

function encloseSelectedItemsInFolder() {
  const ids = Array.from(state.batchSelectedIds || []);
  if (ids.length === 0) return;
  const items = ids.map(id => vault.items.find(x => x.id === id && x.kind !== 'folder')).filter(Boolean);
  if (items.length === 0) return;

  let minX = Infinity, minY = Infinity;
  items.forEach(c => {
    minX = Math.min(minX, c.wallX || 264);
    minY = Math.min(minY, c.wallY || 108);
  });

  const { type, obj } = getActiveContainer();
  const folderItem = {
    id: 'item_' + uid(),
    parentType: type,
    parentId: obj.id,
    folderId: state.activeFolderId || null,
    title: 'New Folder',
    kind: 'folder',
    section: (state.activeCategory && !state.activeCategory.startsWith('All')) ? state.activeCategory : 'All',
    status: 'Folder',
    notes: '',
    tags: ['Folder'],
    wallX: snapCoord(isFinite(minX) ? minX : 264),
    wallY: snapCoord(isFinite(minY) ? minY : 108),
    wallW: 280,
    createdAt: Date.now()
  };

  items.forEach(c => {
    c.parentType = type;
    c.parentId = obj.id;
    c.folderId = folderItem.id;
    delete c.columnId;
    delete c.sphereId;
  });

  vault.items.unshift(folderItem);
  state.batchSelectedIds.clear();
  saveVault(`GROUPED ${items.length} ITEMS IN FOLDER`);
  renderAll();
  showStatusToast(`📁 Grouped ${items.length} items into folder`);
}

function encloseSelectedItemsInSphere() {
  const ids = Array.from(state.batchSelectedIds || []);
  if (ids.length === 0) return;
  const items = ids.map(id => vault.items.find(x => x.id === id)).filter(Boolean);
  if (items.length === 0) return;

  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  items.forEach(c => {
    minX = Math.min(minX, c.wallX || 264);
    minY = Math.min(minY, c.wallY || 108);
    maxX = Math.max(maxX, (c.wallX || 264) + (c.wallW || 240));
    maxY = Math.max(maxY, (c.wallY || 108) + 180);
  });

  const sphereSize = Math.max(480, Math.max(maxX - minX, maxY - minY) + 80);
  const sphereCenterX = (minX + maxX) / 2 - sphereSize / 2;
  const sphereCenterY = (minY + maxY) / 2 - sphereSize / 2;

  const { type, obj } = getActiveContainer();
  const sphereContainer = {
    id: 'item_' + uid(),
    parentType: type,
    parentId: obj.id,
    folderId: state.activeFolderId || null,
    title: 'Sphere Batch',
    kind: 'sphere',
    section: 'All',
    status: 'Active',
    wallX: snapCoord(sphereCenterX),
    wallY: snapCoord(sphereCenterY),
    wallW: sphereSize,
    wallH: sphereSize,
    createdAt: Date.now()
  };

  items.forEach(c => {
    c.sphereId = sphereContainer.id;
  });

  vault.items.push(sphereContainer);
  state.batchSelectedIds.clear();
  saveVault(`ENCLOSED ${items.length} ITEMS IN SPHERE`);
  renderWorkspace();
  showStatusToast(`◎ Enclosed ${items.length} items in Sphere`);
}

// Global Keyboard Backspace / Delete support (always confirms before moving to trash)
window.addEventListener('keydown', (e) => {
  if (e.key !== 'Backspace' && e.key !== 'Delete') return;
  if (e.target.closest('input, textarea, [contenteditable="true"]')) return;
  if (document.querySelector('dialog[open]')) return;

  if (state.batchSelectedIds && state.batchSelectedIds.size > 0) {
    e.preventDefault();
    const ids = Array.from(state.batchSelectedIds);
    if (ids.length === 1) {
      deleteItemDirectly(ids[0]);
      return;
    }
    requestDelete('batch_items', ids, `${ids.length} selected items`);
  }
});

function connectBatchSelectedItems() {
  const selectedIds = Array.from(state.batchSelectedIds || []);
  if (selectedIds.length < 2) return;

  const items = selectedIds.map(id => vault.items.find(x => x.id === id)).filter(Boolean);
  if (items.length < 2) return;

  items.sort((a, b) => (a.wallX || 0) - (b.wallX || 0));
  const itA = items[0];
  const itB = items[1];

  const { type, obj } = getActiveContainer();
  const ax = (itA.wallX || 264) + (itA.wallW || 240);
  const ay = (itA.wallY || 108) + 50;
  const bx = itB.wallX || 560;
  const by = (itB.wallY || 108) + 50;

  const connector = {
    id: 'item_' + uid(),
    parentType: type,
    parentId: obj.id,
    folderId: state.activeFolderId || null,
    title: '',
    kind: 'line',
    section: 'Notes',
    status: 'Active',
    url: '',
    link: '',
    notes: '',
    tags: [],
    lineX1: ax,
    lineY1: ay,
    lineX2: bx,
    lineY2: by,
    wallX: Math.min(ax, bx),
    wallY: Math.min(ay, by),
    wallW: Math.max(36, Math.abs(bx - ax)),
    createdAt: Date.now()
  };

  vault.items.push(connector);
  state.batchSelectedIds.clear();
  saveVault('CONNECTED ITEMS WITH LINE');
  renderWorkspace();
  showStatusToast('⤹ Connected items with line');
}

function findNextOpenProjectClusterSpot() {
  const existingProjs = (vault.projects || []).filter(p => (p.lifecycleState || 'active') !== 'delivered');
  const existingLoose = (vault.items || []).filter(i => i.parentType === 'space' && i.parentId === 'projects' && !i.folderId && !i.columnId);
  for (let step = 0; step < 60; step++) {
    const col = step % 3;
    const row = Math.floor(step / 3);
    const candX = snapCoord(264 + col * 384);
    const candY = snapCoord(108 + row * 336);
    const projHit = existingProjs.some(p => Math.abs((p.boardX ?? 264) - candX) < 220 && Math.abs((p.boardY ?? 108) - candY) < 200);
    const itemHit = existingLoose.some(it => Math.abs((it.wallX ?? 264) - candX) < 220 && Math.abs((it.wallY ?? 108) - candY) < 200);
    if (!projHit && !itemHit) return { x: candX, y: candY };
  }
  const n = existingProjs.length;
  return { x: snapCoord(264 + (n % 3) * 384), y: snapCoord(108 + Math.floor(n / 3) * 336) };
}

function openBatchToProjectDialog() {
  const dlg = document.getElementById('batchProjectDialog');
  if (!dlg) return;
  const count = (state.batchSelectedIds && state.batchSelectedIds.size) || 0;
  if (count === 0) return;

  const descEl = document.getElementById('batchProjectDesc');
  if (descEl) descEl.textContent = `Bundle ${count} selected item${count === 1 ? '' : 's'} into a dedicated Studio Project Board.`;

  const nameInput = document.getElementById('batchProjectNameInput');
  if (nameInput) {
    nameInput.value = 'New Project Batch';
    setTimeout(() => { nameInput.focus(); nameInput.select(); }, 50);
  }

  const cancelBtn = document.getElementById('btnCancelBatchProject');
  const confirmBtn = document.getElementById('btnConfirmBatchProject');

  const onCancel = () => {
    dlg.close();
    cleanup();
  };

  const onConfirm = () => {
    const title = (nameInput?.value || '').trim() || 'Untitled Project';
    const catSelect = document.getElementById('batchProjectCategorySelect');
    const cat = catSelect?.value || '3D & Motion';

    // 1. Create the new project in vault.projects
    const projSpot = findNextOpenProjectClusterSpot();
    const newProj = {
      id: 'proj_' + uid(),
      title,
      status: '🔥 In Progress',
      category: cat,
      subtitle: 'Project Board',
      sections: ['All', 'WIP', 'References', 'Notes'],
      tags: [cat, 'Studio', 'Batch'],
      finlandLinked: false,
      boardX: projSpot.x,
      boardY: projSpot.y,
      boardW: 360,
      wallX: projSpot.x,
      wallY: projSpot.y,
      wallW: 360,
      ui: { layoutMode: 'giant_wall', cardSize: 280, sortOrder: 'manual' },
      createdAt: Date.now(),
      updatedAt: Date.now()
    };

    vault.projects.unshift(newProj);

    // 2. Reassign all selected items to this new project
    let movedCount = 0;
    Array.from(state.batchSelectedIds).forEach((id, idx) => {
      const it = vault.items.find(x => x.id === id);
      if (it) {
        it.parentType = 'project';
        it.parentId = newProj.id;
        delete it.folderId;
        delete it.columnId;
        const col = idx % 3;
        const row = Math.floor(idx / 3);
        it.wallX = 264 + col * 312;
        it.wallY = 108 + row * 312;
        movedCount++;
      }
    });

    state.batchSelectedIds.clear();
    saveVault(`CREATED PROJECT "${title}" FROM BATCH (${movedCount} ITEMS)`);
    dlg.close();
    cleanup();

    // 3. Open the new project board directly!
    openProjectBoard(newProj.id);
    showStatusToast(`✨ Created Project "${title}" with ${movedCount} items!`);
  };

  function cleanup() {
    cancelBtn?.removeEventListener('click', onCancel);
    confirmBtn?.removeEventListener('click', onConfirm);
  }

  cancelBtn?.addEventListener('click', onCancel);
  confirmBtn?.addEventListener('click', onConfirm);

  dlg.showModal();
}

function bindSpatialStageCamera(stage, plane, onTidy) {
  if (!stage || !plane) return;
  applyActiveBoardCameraTransform();

  const cam = getActiveBoardCamera();

  document.getElementById('btnWallZoomIn')?.addEventListener('click', () => {
    cam.zoom = Math.min(3.5, +(cam.zoom * 1.18).toFixed(3));
    applyActiveBoardCameraTransform();
  });

  document.getElementById('btnWallZoomOut')?.addEventListener('click', () => {
    cam.zoom = Math.max(0.25, +(cam.zoom / 1.18).toFixed(3));
    applyActiveBoardCameraTransform();
  });

  document.getElementById('btnResetWallCamera')?.addEventListener('click', () => {
    cam.zoom = 1;
    cam.panX = 0;
    cam.panY = 0;
    applyActiveBoardCameraTransform();
  });

  document.getElementById('btnToggleGridSnap')?.addEventListener('click', (e) => {
    state.snapToGrid = state.snapToGrid === false ? true : false;
    e.currentTarget.classList.toggle('is-active', state.snapToGrid !== false);
    e.currentTarget.textContent = state.snapToGrid !== false ? '⊞ Snap: ON' : '⊞ Snap: OFF';
  });

  document.getElementById('btnAutoArrangeWall')?.addEventListener('click', () => {
    if (typeof onTidy === 'function') onTidy();
  });

  // Trackpad two-finger pan & pinch/Cmd/Alt wheel zoom anchored to cursor
  stage.addEventListener('wheel', (e) => {
    // Allow internal scrolling inside a large note or table if cursor is over a scrollable child without modifier
    if (!e.ctrlKey && !e.metaKey && !e.altKey) {
      const scrollChild = e.target.closest('.mn-inline-note-editor, .mn-table-wrap');
      if (scrollChild && scrollChild.scrollHeight > scrollChild.clientHeight) {
        return;
      }
    }
    e.preventDefault();
    if (e.ctrlKey || e.metaKey || e.altKey) {
      const rect = stage.getBoundingClientRect();
      const cursorX = e.clientX - rect.left;
      const cursorY = e.clientY - rect.top;
      const prevZoom = cam.zoom || 1;
      const factor = Math.exp(-e.deltaY * 0.0045);
      const nextZoom = Math.min(3.5, Math.max(0.25, prevZoom * factor));
      const worldX = (cursorX - cam.panX) / prevZoom;
      const worldY = (cursorY - cam.panY) / prevZoom;
      cam.zoom = nextZoom;
      cam.panX = cursorX - worldX * nextZoom;
      cam.panY = cursorY - worldY * nextZoom;
    } else {
      cam.panX -= e.deltaX;
      cam.panY -= e.deltaY;
    }
    applyActiveBoardCameraTransform();
  }, { passive: false });

  // Background pan via pointerdown + setPointerCapture on empty canvas (or middle mouse / Spacebar)
  // Shift + Left Drag -> Bounding Box (Marquee) Selection
  stage.addEventListener('pointerdown', (e) => {
    const isMiddle = e.button === 1;
    const isLeft = e.button === 0;
    const isEmptyCanvas = (e.target === stage || e.target === plane || e.target.id === 'giantWallStage' || e.target.id === 'giantWallPlane');
    if (!isEmptyCanvas && !isMiddle) return;
    if (!isLeft && !isMiddle) return;

    // Shift + Left Drag on Empty Canvas -> Bounding Box (Marquee) Selection
    if (isLeft && e.shiftKey) {
      e.preventDefault();
      try { stage.setPointerCapture(e.pointerId); } catch (_) {}

      const startClientX = e.clientX;
      const startClientY = e.clientY;
      const stageRect = stage.getBoundingClientRect();
      const startWorldX = (startClientX - stageRect.left - (cam.panX || 0)) / (cam.zoom || 1);
      const startWorldY = (startClientY - stageRect.top - (cam.panY || 0)) / (cam.zoom || 1);

      let marqueeEl = null;
      let didMarquee = false;

      const onMarqueeMove = (ev) => {
        const curClientX = ev.clientX;
        const curClientY = ev.clientY;
        const dist = Math.hypot(curClientX - startClientX, curClientY - startClientY);
        if (dist < 6) return;

        if (!didMarquee) {
          didMarquee = true;
          marqueeEl = document.createElement('div');
          marqueeEl.className = 'wall-marquee-box';
          plane.appendChild(marqueeEl);
        }

        const curWorldX = (curClientX - stageRect.left - (cam.panX || 0)) / (cam.zoom || 1);
        const curWorldY = (curClientY - stageRect.top - (cam.panY || 0)) / (cam.zoom || 1);

        const mMinX = Math.min(startWorldX, curWorldX);
        const mMinY = Math.min(startWorldY, curWorldY);
        const mMaxX = Math.max(startWorldX, curWorldX);
        const mMaxY = Math.max(startWorldY, curWorldY);

        marqueeEl.style.left = `${mMinX}px`;
        marqueeEl.style.top = `${mMinY}px`;
        marqueeEl.style.width = `${mMaxX - mMinX}px`;
        marqueeEl.style.height = `${mMaxY - mMinY}px`;

        state.batchSelectedIds = state.batchSelectedIds || new Set();
        state.batchSelectedIds.clear();

        const selectableEls = plane.querySelectorAll('.wall-pin-item, .studio-card, .clear-drawer-card');
        selectableEls.forEach(el => {
          const itemLeft = parseFloat(el.style.left) || el.offsetLeft || 0;
          const itemTop = parseFloat(el.style.top) || el.offsetTop || 0;
          const itemWidth = parseFloat(el.style.width) || el.offsetWidth || 260;
          const itemHeight = parseFloat(el.style.height) || el.offsetHeight || 180;
          const itemRight = itemLeft + itemWidth;
          const itemBottom = itemTop + itemHeight;

          const intersects = !(itemRight < mMinX || itemLeft > mMaxX || itemBottom < mMinY || itemTop > mMaxY);
          if (intersects) {
            el.classList.add('is-batch-selected');
            const itId = el.dataset.itemId || el.dataset.id;
            if (itId) state.batchSelectedIds.add(itId);
          } else {
            el.classList.remove('is-batch-selected');
          }
        });
      };

      const onMarqueeUp = () => {
        stage.removeEventListener('pointermove', onMarqueeMove);
        stage.removeEventListener('lostpointercapture', onMarqueeUp);
        if (marqueeEl) {
          marqueeEl.remove();
          marqueeEl = null;
        }
        try { stage.releasePointerCapture(e.pointerId); } catch (_) {}

        if (!didMarquee) {
          state.batchSelectedIds = state.batchSelectedIds || new Set();
          state.batchSelectedIds.clear();
          plane.querySelectorAll('.is-batch-selected').forEach(el => el.classList.remove('is-batch-selected'));
          renderBatchActionBar(stage, plane);
          return;
        }

        renderBatchActionBar(stage, plane);
      };

      stage.addEventListener('pointermove', onMarqueeMove);
      stage.addEventListener('lostpointercapture', onMarqueeUp);
      return;
    }

    // Default: Grab and Move Canvas
    const activeEl = document.activeElement;
    if (activeEl && (activeEl.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(activeEl.tagName))) {
      activeEl.blur();
    }
    e.preventDefault();
    try { stage.setPointerCapture(e.pointerId); } catch (_) {}
    stage.classList.add('is-panning');
    const startX = e.clientX;
    const startY = e.clientY;
    const origX = cam.panX || 0;
    const origY = cam.panY || 0;
    let didMove = false;

    const onMove = (ev) => {
      const dx = ev.clientX - startX;
      const dy = ev.clientY - startY;
      if (!didMove && Math.hypot(dx, dy) > 3) {
        didMove = true;
      }
      cam.panX = origX + dx;
      cam.panY = origY + dy;
      applyActiveBoardCameraTransform();
    };

    const onStop = () => {
      stage.classList.remove('is-panning');
      stage.removeEventListener('pointermove', onMove);
      stage.removeEventListener('lostpointercapture', onStop);
      try { stage.releasePointerCapture(e.pointerId); } catch (_) {}

      // If user clicked empty space without dragging, clear any active batch selection
      if (!didMove && state.batchSelectedIds && state.batchSelectedIds.size > 0) {
        state.batchSelectedIds.clear();
        plane.querySelectorAll('.is-batch-selected').forEach(el => el.classList.remove('is-batch-selected'));
        renderBatchActionBar(stage, plane);
      }
    };

    stage.addEventListener('pointermove', onMove);
    stage.addEventListener('lostpointercapture', onStop);
  });
}

/* --------------------------------------------------------------------------
   01 STUDIO PROJECTS OVERVIEW ("Clear Drawers" on Spatial Milanote Board)
   -------------------------------------------------------------------------- */
function renderProjectsOverview(ws, spaceObj) {
  const ui = spaceObj.ui || {};
  let mode = ui.layoutMode || 'giant_wall';
  if (mode === 'sphere') {
    mode = 'giant_wall';
    ui.layoutMode = 'giant_wall';
  }
  const sortOrder = ui.sortOrder || 'manual';
  const firstCat = (spaceObj.categories && spaceObj.categories[0]) || 'All Disciplines';
  const lifecycleFilter = state.projectsLifecycleFilter || 'active';

  let list = vault.projects.filter(p => {
    const pState = p.lifecycleState || 'active';
    if (lifecycleFilter === 'active' && pState === 'delivered') return false;
    if (lifecycleFilter === 'delivered' && pState !== 'delivered') return false;
    if (state.activeCategory && state.activeCategory !== firstCat && p.category !== state.activeCategory) {
      return false;
    }
    if (state.igStatusFilter && state.igStatusFilter !== 'all') {
      const hasMatchingIgItem = vault.items.some(i => i.parentType === 'project' && i.parentId === p.id && i.igStatus === state.igStatusFilter);
      if (!hasMatchingIgItem) return false;
    }
    if (state.searchQuery) {
      const q = state.searchQuery.toLowerCase();
      const hay = `${p.title} ${p.subtitle} ${p.status} ${(p.tags || []).join(' ')}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  const looseOverviewItems = vault.items.filter(i => {
    if (lifecycleFilter === 'delivered') return false;
    if (i.parentType !== 'space' || i.parentId !== 'projects' || i.folderId || i.columnId) return false;
    if (mode !== 'sphere' && state.activeCategory && state.activeCategory !== firstCat && i.section !== state.activeCategory) return false;
    if (state.igStatusFilter && state.igStatusFilter !== 'all' && i.igStatus !== state.igStatusFilter) return false;
    if (state.searchQuery) {
      const q = state.searchQuery.toLowerCase();
      const hay = `${i.title || ''} ${i.notes || ''} ${i.status || ''} ${(i.tags || []).join(' ')} ${i.link || ''}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  if (sortOrder === 'updated') {
    list = [...list].sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  } else if (sortOrder === 'newest') {
    list = [...list].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
  } else if (sortOrder === 'alpha') {
    list = [...list].sort((a, b) => (a.title || '').localeCompare(b.title || ''));
  }

  if (mode === 'sphere') {
    const allProjItems = [];
    looseOverviewItems.forEach(it => allProjItems.push({ ...it, _projTitle: 'Studio Canvas' }));
    list.forEach(proj => {
      const pItems = vault.items.filter(i => i.parentType === 'project' && i.parentId === proj.id);
      pItems.forEach(it => allProjItems.push({ ...it, _projTitle: proj.title }));
    });
    const allSphere = convertItemsToSphereLayerNodes(allProjItems);
    const sphereBatches = [
      {
        id: 'all_projects_sphere',
        code: '00',
        title: spaceObj.heading || spaceObj.title || 'All Studio Projects',
        subtitle: `${list.length} Project Boards · ${allProjItems.length} Total Elements`,
        category: 'Creative Studio',
        status: 'Unified 3D Constellation',
        visualNodes: allSphere.visualNodes,
        outerNodes: allSphere.outerNodes,
        totalCount: allProjItems.length,
        primaryActionLabel: 'Spatial Wall →',
        onPrimaryOpen: () => {
          spaceObj.ui = spaceObj.ui || {};
          spaceObj.ui.layoutMode = 'giant_wall';
          saveVault();
          renderAll();
        },
        onRightTopAction: () => {
          spaceObj.ui = spaceObj.ui || {};
          spaceObj.ui.layoutMode = 'giant_wall';
          saveVault();
          renderAll();
        },
        onRightBottomAction: () => createAndOpenNewProjectBoard(),
        onRename: (newTitle) => {
          spaceObj.title = newTitle;
          spaceObj.heading = newTitle;
          saveVault('RENAMED SECTION');
          renderAll();
        }
      },
      ...list.map((proj) => {
        const pItems = vault.items.filter(i => i.parentType === 'project' && i.parentId === proj.id);
        const { visualNodes, outerNodes } = convertItemsToSphereLayerNodes(pItems);
        return {
          id: proj.id,
          code: '#' + getProjectDisplayNumber(proj),
          title: proj.title,
          subtitle: proj.subtitle || proj.category || 'Studio Project',
          category: proj.category || 'Studio',
          status: proj.status || '',
          visualNodes,
          outerNodes,
          totalCount: pItems.length,
          primaryActionLabel: 'Open Board →',
          onPrimaryAction: () => openProjectBoard(proj.id),
          onPrimaryOpen: () => openProjectBoard(proj.id),
          onRightTopAction: () => openProjectBoard(proj.id),
          secondaryActionLabel: 'Edit',
          onSecondaryAction: () => openProjectModal(proj.id),
          onRightBottomAction: () => openProjectModal(proj.id),
          onRename: (newTitle) => {
            proj.title = newTitle;
            saveVault('RENAMED PROJECT');
            renderAll();
          }
        };
      })
    ];
    renderSphericalStage(ws, sphereBatches, { isProjectsOverview: true });
    return;
  }

  const appendFloatingNewProjectHud = () => {
    const hud = document.createElement('div');
    hud.className = 'giant-wall-hud';
    hud.innerHTML = `<button type="button" class="floating-new-project-fab" id="btnFloatingNewProject" title="Create New Project Board">+ New Project</button>`;
    hud.querySelector('#btnFloatingNewProject')?.addEventListener('click', () => createAndOpenNewProjectBoard());
    ws.appendChild(hud);
    appendProjectsEmptyState();
  };

  // Friendly message when the current Open / Finished + category view has no projects
  function appendProjectsEmptyState() {
    if (list.length > 0 || looseOverviewItems.length > 0) return;
    const isCatFiltered = state.activeCategory && state.activeCategory !== firstCat;
    const catLabel = isCatFiltered ? ` in ${state.activeCategory}` : '';
    const msg = state.searchQuery
      ? `No projects match “${state.searchQuery}”`
      : (lifecycleFilter === 'delivered' ? `No finished projects${catLabel} yet` : `No open projects${catLabel} yet`);
    const empty = document.createElement('div');
    empty.className = 'projects-empty-state';
    empty.textContent = msg;
    const targetStage = ws.querySelector('#giantWallStage') || ws;
    targetStage.appendChild(empty);
  }

  if (mode === 'list') {
    ws.innerHTML = `<div class="visual-list-table" id="projListTable"></div>`;
    const table = ws.querySelector('#projListTable');
    list.forEach((proj) => {
      const items = vault.items.filter(i => i.parentType === 'project' && i.parentId === proj.id);
      const mediaItem = items.find(i => i.url);
      const isDelivered = proj.lifecycleState === 'delivered';
      const numCode = getProjectDisplayNumber(proj);
      const row = document.createElement('div');
      row.className = 'list-row-item';
      row.style.cursor = 'pointer';
      row.innerHTML = `
        <div class="list-thumb">${mediaItem ? `<img src="${escapeHtml(mediaItem.url)}" alt="">` : `<span class="kicker-mono">${numCode}</span>`}</div>
        <div>
          <div class="card-title" data-editable-title="1" title="Click to rename project">${escapeHtml(proj.title)}</div>
          <span class="kicker-mono">${items.length} ${items.length === 1 ? 'item' : 'items'} · ${escapeHtml(proj.category || 'Studio')}${proj.status ? ` · ${escapeHtml(proj.status)}` : ''}</span>
        </div>
        <div class="card-desc">${escapeHtml(proj.subtitle || '')}</div>
        <div class="card-tags-row">${(proj.tags || []).slice(0, 3).map(t => `<span class="tag-chip">${escapeHtml(t)}</span>`).join('')}</div>
        <div class="card-footer-actions" style="justify-content:flex-end;">
          <button type="button" class="quiet-action-link btn-finish" title="${isDelivered ? 'Move back to Open' : 'Mark project as Finished'}">${isDelivered ? '↺ Reopen' : '✓ Finish'}</button>
          <button type="button" class="quiet-action-link btn-edit" title="Customize Project Settings">⚙</button>
          <button type="button" class="quiet-action-link danger btn-del" title="Delete project">×</button>
        </div>
      `;
      row.querySelector('.card-title').addEventListener('click', (e) => {
        e.stopPropagation();
        promptInlineRename(e.currentTarget, proj.title, (val) => {
          proj.title = val;
          proj.updatedAt = Date.now();
          saveVault('RENAMED PROJECT');
          renderAll();
        });
      });
      row.querySelector('.btn-finish').addEventListener('click', (e) => {
        e.stopPropagation();
        deliverProjectAndSpawnShowcase(proj.id);
      });
      row.querySelector('.btn-edit').addEventListener('click', (e) => {
        e.stopPropagation();
        openProjectModal(proj.id);
      });
      row.querySelector('.btn-del').addEventListener('click', (e) => {
        e.stopPropagation();
        requestDelete('project', proj.id, proj.title);
      });
      row.addEventListener('click', (e) => {
        if (e.target.closest('button') || e.target.closest('[data-editable-title]')) return;
        openProjectBoard(proj.id);
      });
      table.appendChild(row);
    });
    looseOverviewItems.forEach((it) => {
      const row = document.createElement('div');
      row.className = 'list-row-item';
      row.innerHTML = `
        <div class="list-thumb">${it.url && it.kind !== 'audio' ? `<img src="${escapeHtml(it.url)}" alt="">` : `<span class="kicker-mono">${escapeHtml((it.kind || 'ITEM').toUpperCase())}</span>`}</div>
        <div>
          <div class="card-title" data-editable-title="1" title="Click to rename item">${escapeHtml(it.title)}</div>
          <span class="kicker-mono">${escapeHtml(it.status || it.section || 'Overview')}</span>
        </div>
        <div class="card-desc">${escapeHtml(it.notes || it.link || '')}</div>
        <div class="card-tags-row">${(it.tags || []).slice(0, 2).map(t => `<span class="tag-chip">${escapeHtml(t)}</span>`).join('')}</div>
        <div class="card-footer-actions" style="justify-content:flex-end;">
          <button type="button" class="quiet-action-link btn-promote-proj" title="Move into a Project Board">↗ Project</button>
          <button type="button" class="quiet-action-link btn-inspect">Inspect</button>
          <button type="button" class="quiet-action-link danger btn-del" title="Delete item">×</button>
        </div>
      `;
      row.querySelector('.list-thumb').addEventListener('click', () => openItemInspector(it.id));
      row.querySelector('.card-title').addEventListener('click', (e) => {
        e.stopPropagation();
        promptInlineRename(e.currentTarget, it.title, (val) => {
          it.title = val;
          saveVault('RENAMED ITEM');
          renderAll();
        });
      });
      row.querySelector('.btn-promote-proj')?.addEventListener('click', (e) => {
        e.stopPropagation();
        promoteIncubatorItemToProject(it.id);
      });
      row.querySelector('.btn-inspect').addEventListener('click', () => openItemInspector(it.id));
      row.querySelector('.btn-del').addEventListener('click', () => requestDelete('item', it.id, it.title));
      table.appendChild(row);
    });
    appendFloatingNewProjectHud();
    return;
  }

  if (mode === 'kanban') {
    const cols = [...(spaceObj.categories || []).slice(1)];
    if (list.some(p => p.category === 'Untagged') && !cols.includes('Untagged')) {
      cols.push('Untagged');
    }
    ws.innerHTML = `<div class="kanban-board" id="projKanban"></div>`;
    const kb = ws.querySelector('#projKanban');
    cols.forEach((cat, cIdx) => {
      const colProjs = list.filter(p => p.category === cat);
      const colLoose = looseOverviewItems.filter(it => it.section === cat || (cIdx === 0 && !cols.includes(it.section)));
      const colEl = document.createElement('div');
      colEl.className = 'kanban-col';
      colEl.innerHTML = `
        <div class="kanban-col-header">
          <span class="kanban-col-title" data-editable-title="1" title="Click to rename column">${escapeHtml(cat)}</span>
          <span class="sidebar-count-pill">${colProjs.length + colLoose.length}</span>
        </div>
        <div class="kanban-cards" style="display:flex;flex-direction:column;gap:24px;"></div>
      `;
      colEl.querySelector('.kanban-col-title')?.addEventListener('click', (e) => {
        e.stopPropagation();
        promptInlineRename(e.currentTarget, cat, (val) => {
          const catIdx = (spaceObj.categories || []).indexOf(cat);
          if (catIdx !== -1) spaceObj.categories[catIdx] = val;
          vault.projects.forEach(p => { if (p.category === cat) p.category = val; });
          saveVault('RENAMED COLUMN');
          renderAll();
        });
      });
      const container = colEl.querySelector('.kanban-cards');
      colProjs.forEach((proj, idx) => {
        container.appendChild(buildClearDrawerProjectEl(proj, idx, false));
      });
      colLoose.forEach((it, idx) => {
        container.appendChild(buildItemCardEl(it, idx));
      });
      kb.appendChild(colEl);
    });
    appendFloatingNewProjectHud();
    return;
  }

  if (mode === 'giant_wall') {
    renderProjectsSpatialBoard(ws, list, looseOverviewItems);
    appendProjectsEmptyState();
    return;
  }

  // Mode 'wall' (⊞): Clean, responsive auto-arranged Clear Drawers Grid (never overlaps sidebar or HUD)
  ws.innerHTML = `<div class="clear-drawers-grid" id="projectsClearDrawersWall"></div>`;
  const wallGrid = ws.querySelector('#projectsClearDrawersWall');
  applyProjectsGridCardSize(wallGrid, ui.cardSize);
  list.forEach((proj, idx) => {
    wallGrid?.appendChild(buildClearDrawerProjectEl(proj, idx, false));
  });
  looseOverviewItems.forEach((it, idx) => {
    wallGrid?.appendChild(buildItemCardEl(it, idx));
  });
  appendFloatingNewProjectHud();
}

function applyProjectsGridCardSize(gridEl, rawSize) {
  if (!gridEl) return;
  const size = Math.max(180, Math.min(520, parseInt(rawSize, 10) || 330));
  gridEl.style.setProperty('grid-template-columns', `repeat(auto-fill, minmax(${size}px, 1fr))`, 'important');
}

function buildSpatialPinEl(it, parentType, parentObj, idx = 0) {
  if (typeof it.wallX !== 'number' || Number.isNaN(it.wallX) || typeof it.wallY !== 'number' || Number.isNaN(it.wallY)) {
    const col = idx % 3;
    const row = Math.floor(idx / 3);
    it.wallX = 264 + col * 312;
    it.wallY = 108 + row * 312;
  }

  const isFolder = it.kind === 'folder';
  const isColumn = it.kind === 'column';
  const isHeading = it.kind === 'heading';
  const isColor = it.kind === 'color';
  const isLine = it.kind === 'line';
  const isVisual = Boolean(it.url && it.kind !== 'audio' && !isFolder);
  const isTodo = it.kind === 'todo' || it.kind === 'checklist' || ((it.notes || '').includes('[ ]') || (it.notes || '').includes('[x]'));
  const isSticky = !isVisual && !isFolder && !isColumn && (it.kind === 'note' || it.kind === 'comment' || isTodo);
  const isCmp = isAssetCompareSelected(it.id);
  const isBatchSel = Boolean(state.batchSelectedIds && state.batchSelectedIds.has(it.id));
  const igStat = it.igStatus || '';

  const defaultW = isFolder ? 280 : (isColumn ? 288 : (isHeading ? 360 : (isColor ? 192 : (isVisual ? 264 : 264))));
  const w = it.wallW || defaultW;

  const pin = document.createElement('div');
  pin.className = [
    'wall-pin-item',
    isVisual ? 'is-visual-pin' : '',
    isSticky ? 'is-sticky-note' : '',
    isFolder ? 'is-folder-pin is-see-through-folder' : '',
    isColumn ? 'is-column-pin' : '',
    isHeading ? 'is-heading-pin' : '',
    isColor ? 'is-color-pin' : '',
    isLine ? 'is-line-pin' : '',
    isCmp ? 'is-compare-selected' : '',
    isBatchSel ? 'is-batch-selected' : ''
  ].filter(Boolean).join(' ');

  pin.dataset.itemId = it.id;
  pin.dataset.itemKind = it.kind || 'note';
  pin.style.left = `${it.wallX}px`;
  pin.style.top = `${it.wallY}px`;
  pin.style.width = `${w}px`;
  if (it.wallH) pin.style.height = `${it.wallH}px`;

  const igBadge = igStat === 'published'
    ? `<span class="ig-status-badge is-published">● IG LIVE</span>`
    : (igStat === 'queued'
        ? `<span class="ig-status-badge is-queued">◈ IG READY</span>`
        : (igStat === 'website' ? `<span class="ig-status-badge" style="background:rgba(59,130,246,0.92);color:#FFF;">🌐 ON SITE</span>` : ''));

  if (isFolder) {
    const childItems = (parentType === 'space' && parentObj && parentObj.id === 'instagram')
      ? vault.items.filter(c => c.folderId === it.id)
      : vault.items.filter(c => c.parentType === parentType && (!parentObj || c.parentId === parentObj.id) && c.folderId === it.id);
    pin.innerHTML = `
      <div class="mn-folder-card">
        <div class="mn-folder-header" style="display:flex;align-items:center;justify-content:space-between;padding:10px 12px 6px;gap:8px;">
          <div style="display:flex;align-items:center;gap:6px;min-width:0;flex:1;">
            <span style="font-size:15px;line-height:1;">📁</span>
            <span class="mn-folder-title" contenteditable="true" spellcheck="false" style="font-weight:600;font-size:13px;outline:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(it.title || 'Untitled Folder')}</span>
          </div>
          <span class="mn-folder-count" style="font-size:10px;font-family:var(--font-mono);color:var(--text-dim);white-space:nowrap;">${childItems.length} items</span>
        </div>

        <div class="mn-folder-see-through-grid">
          ${childItems.length ? childItems.map(c => `
            <div class="mn-folder-see-through-item" data-child-id="${escapeHtml(c.id)}" title="${escapeHtml(c.title || 'Item')} (Click to inspect)">
              ${c.url && c.kind !== 'audio' ? `<img src="${escapeHtml(c.url)}" alt="" draggable="false">` : `<div style="padding:6px;font-size:10px;font-family:var(--font-mono);overflow:hidden;height:100%;color:var(--text);">${escapeHtml(c.title || c.notes || 'Note')}</div>`}
              <div class="see-through-item-actions" style="position:absolute;top:2px;right:2px;display:flex;gap:2px;">
                ${c.url ? `<a href="${escapeHtml(c.url)}" download class="hover-act-btn" style="padding:1px 4px;font-size:9px;background:rgba(0,0,0,0.7);color:#fff;border-radius:3px;text-decoration:none;" title="Download original" onclick="event.stopPropagation()">⬇</a>` : ''}
                <button type="button" class="child-eject-btn hover-act-btn" data-eject-id="${escapeHtml(c.id)}" style="padding:1px 4px;font-size:9px;background:rgba(0,0,0,0.7);color:#fff;border-radius:3px;" title="Pop out onto board">↗</button>
              </div>
            </div>
          `).join('') : `
            <div style="grid-column:1/-1;text-align:center;padding:16px 8px;font-size:11px;color:var(--text-dim);">
              Drop files, images, or notes here to batch them
            </div>
          `}
        </div>

        <div class="mn-folder-notes-area" style="padding:6px 12px 10px;border-top:1px solid color-mix(in srgb, var(--text) 10%, transparent);">
          <div class="mn-note-editable" contenteditable="true" spellcheck="false" data-placeholder="Add notes / highlights to this folder…">${escapeHtml(it.notes || '')}</div>
        </div>

        <div class="mn-folder-footer" style="display:flex;justify-content:space-between;align-items:center;padding:6px 12px 10px;">
          <div style="display:flex;gap:4px;align-items:center;">
            ${childItems.length > 0 ? `<button type="button" class="btn-folder-turn-proj hover-act-btn" style="font-size:11px;padding:3px 8px;background:color-mix(in srgb, var(--accent) 15%, transparent);color:var(--accent);border:1px solid var(--accent);border-radius:6px;cursor:pointer;" title="Convert this folder into a full Project Board">✨ Turn into Project</button>` : ''}
          </div>
          <div style="display:flex;gap:4px;align-items:center;">
            <button type="button" class="mn-folder-open-btn btn-open-folder" title="Open Sub-Board">Open →</button>
          </div>
        </div>
      </div>
      <div class="wall-resize-handle" title="Drag corner to resize"></div>
    `;

    const titleEl = pin.querySelector('.mn-folder-title');
    titleEl?.addEventListener('pointerdown', (e) => {
      if (document.activeElement === titleEl) e.stopPropagation();
    });
    titleEl?.addEventListener('blur', () => {
      const nextTitle = (titleEl.textContent || '').trim() || 'Untitled Folder';
      if (nextTitle !== it.title) {
        it.title = nextTitle;
        saveVault('FOLDER RENAMED');
      }
    });

    const folderNote = pin.querySelector('.mn-note-editable');
    folderNote?.addEventListener('pointerdown', (e) => {
      if (document.activeElement === folderNote) e.stopPropagation();
    });
    folderNote?.addEventListener('blur', () => {
      const nextN = (folderNote.innerText || '').trim();
      if (nextN !== (it.notes || '')) {
        it.notes = nextN;
        saveVault('FOLDER NOTE SAVED');
      }
    });

    pin.querySelector('.btn-folder-turn-proj')?.addEventListener('click', (e) => {
      e.stopPropagation();
      state.batchSelectedIds = new Set(childItems.map(c => c.id));
      openBatchToProjectDialog();
    });

    pin.querySelectorAll('.child-eject-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const child = vault.items.find(x => x.id === btn.dataset.ejectId);
        if (child) {
          delete child.folderId;
          child.wallX = (it.wallX || 264) + (it.wallW || 280) + 24;
          child.wallY = it.wallY || 108;
          saveVault('POPPED OUT OF FOLDER');
          renderWorkspace();
          showStatusToast('↗ Item popped out of folder');
        }
      });
    });

    pin.querySelectorAll('.mn-folder-see-through-item').forEach(el => {
      el.addEventListener('click', (e) => {
        if (e.target.closest('button') || e.target.closest('a')) return;
        e.stopPropagation();
        openItemInspector(el.dataset.childId);
      });
    });

    pin.querySelector('.btn-open-folder')?.addEventListener('pointerdown', (e) => e.stopPropagation());
    pin.querySelector('.btn-open-folder')?.addEventListener('click', (e) => {
      e.stopPropagation();
      state.activeFolderId = it.id;
      renderAll();
    });
  } else if (isColumn) {
    const colChildren = (parentType === 'space' && parentObj && parentObj.id === 'instagram')
      ? vault.items.filter(c => c.columnId === it.id)
      : vault.items.filter(c => c.parentType === parentType && (!parentObj || c.parentId === parentObj.id) && c.columnId === it.id);
    pin.innerHTML = `
      <div class="mn-column-card">
        <div class="mn-column-header">
          <span class="mn-column-title" contenteditable="true" spellcheck="false">${escapeHtml(it.title || 'Column')}</span>
          <div style="display:flex;gap:4px;align-items:center;">
            <span class="mn-column-count">${colChildren.length}</span>
            <button type="button" class="hover-act-btn btn-pin-inspect" style="opacity:1;padding:1px 6px;" title="Inspect or Delete Column">•••</button>
          </div>
        </div>
        <div class="mn-column-dropzone" data-column-id="${escapeHtml(it.id)}">
          ${colChildren.length ? colChildren.map(c => `
            <div class="mn-column-child-card" data-child-id="${escapeHtml(c.id)}" title="Click to edit card">
              ${c.url && c.kind !== 'audio' ? `<img src="${escapeHtml(c.url)}" alt="" draggable="false">` : ''}
              <div class="mn-column-child-body">
                <strong>${escapeHtml(c.title)}</strong>
                ${c.notes ? `<p>${escapeHtml(c.notes)}</p>` : ''}
              </div>
              <div style="display:flex;gap:2px;align-items:center;">
                <button type="button" class="mn-column-eject-btn" data-eject-id="${escapeHtml(c.id)}" title="Pop out onto board">↗</button>
                <button type="button" class="mn-column-eject-btn mn-column-del-btn" data-del-child-id="${escapeHtml(c.id)}" title="Delete card">×</button>
              </div>
            </div>
          `).join('') : `<div class="mn-column-placeholder">Drag any card here or click + Add card below</div>`}
        </div>
        <button type="button" class="mn-column-add-btn">+ Add card to column</button>
      </div>
      <div class="wall-resize-handle" title="Drag corner to resize"></div>
    `;
    const colTitle = pin.querySelector('.mn-column-title');
    colTitle?.addEventListener('pointerdown', (e) => {
      if (document.activeElement === colTitle) e.stopPropagation();
    });
    colTitle?.addEventListener('blur', () => {
      it.title = (colTitle.textContent || '').trim() || 'Column';
      saveVault('COLUMN RENAMED');
    });
    pin.querySelectorAll('.mn-column-child-card').forEach(childEl => {
      childEl.addEventListener('pointerdown', (e) => e.stopPropagation());
      childEl.addEventListener('click', (e) => {
        if (e.target.closest('button')) return;
        e.stopPropagation();
        openItemInspector(childEl.dataset.childId);
      });
    });
    pin.querySelectorAll('.mn-column-eject-btn:not(.mn-column-del-btn)').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const child = vault.items.find(x => x.id === btn.dataset.ejectId);
        if (child) {
          delete child.columnId;
          child.wallX = (it.wallX || 336) + (it.wallW || 288) + 24;
          child.wallY = it.wallY || 144;
          saveVault('CARD POPPED FROM COLUMN');
          renderWorkspace();
        }
      });
    });
    pin.querySelectorAll('.mn-column-del-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const child = vault.items.find(x => x.id === btn.dataset.delChildId);
        if (child) deleteItemDirectly(child.id);
      });
    });
    pin.querySelector('.mn-column-add-btn')?.addEventListener('click', (e) => {
      e.stopPropagation();
      vault.items.unshift({
        id: 'item_' + uid(),
        parentType,
        parentId: parentObj ? parentObj.id : 'projects',
        folderId: state.activeFolderId || null,
        columnId: it.id,
        title: 'Column Note',
        kind: 'note',
        section: 'Notes',
        status: 'Active',
        url: '',
        link: '',
        notes: 'Click to edit details…',
        tags: [],
        createdAt: Date.now()
      });
      saveVault('ADDED CARD TO COLUMN');
      renderWorkspace();
    });
  } else if (isHeading) {
    pin.innerHTML = `
      <div class="mn-heading-card">
        <div class="mn-heading-editable" contenteditable="true" spellcheck="false">${escapeHtml(it.title || 'Section Heading')}</div>
        <button type="button" class="hover-act-btn btn-pin-inspect" title="Edit or Delete">•••</button>
      </div>
      <div class="wall-resize-handle" title="Drag corner to resize"></div>
    `;
    const hEl = pin.querySelector('.mn-heading-editable');
    hEl?.addEventListener('pointerdown', (e) => {
      if (document.activeElement === hEl) e.stopPropagation();
    });
    hEl?.addEventListener('blur', () => {
      it.title = (hEl.textContent || '').trim() || 'Section Heading';
      saveVault('HEADING SAVED');
    });
  } else if (isColor) {
    const hex = (it.notes || it.title || '#FF3B24').trim();
    const validHex = /^#[0-9A-Fa-f]{3,8}$/.test(hex) ? hex : '#FF3B24';
    pin.innerHTML = `
      <div class="mn-color-card">
        <label class="mn-color-swatch" style="background:${escapeHtml(validHex)};" title="Click to pick color">
          <input type="color" class="mn-color-input" value="${escapeHtml(validHex.length === 7 ? validHex : '#FF3B24')}">
        </label>
        <div class="mn-color-info" style="display:flex;justify-content:space-between;align-items:center;gap:6px;">
          <div style="display:flex;flex-direction:column;min-width:0;">
            <span class="mn-color-hex" contenteditable="true" spellcheck="false">${escapeHtml(validHex.toUpperCase())}</span>
            <span class="mn-color-label" contenteditable="true" spellcheck="false">${escapeHtml(it.title || 'Swatch')}</span>
          </div>
          <button type="button" class="hover-act-btn btn-pin-inspect" style="opacity:1;padding:1px 6px;" title="Edit or Delete Swatch">•••</button>
        </div>
      </div>
    `;
    const colorInp = pin.querySelector('.mn-color-input');
    const hexEl = pin.querySelector('.mn-color-hex');
    const lblEl = pin.querySelector('.mn-color-label');
    const swatchEl = pin.querySelector('.mn-color-swatch');
    colorInp?.addEventListener('pointerdown', (e) => e.stopPropagation());
    colorInp?.addEventListener('input', (e) => {
      it.notes = e.target.value.toUpperCase();
      if (swatchEl) swatchEl.style.background = it.notes;
      if (hexEl) hexEl.textContent = it.notes;
    });
    colorInp?.addEventListener('change', () => saveVault('SWATCH UPDATED'));
    hexEl?.addEventListener('pointerdown', (e) => e.stopPropagation());
    const commitHex = () => {
      let raw = (hexEl.textContent || '').trim();
      if (raw && !raw.startsWith('#')) raw = '#' + raw;
      if (/^#[0-9A-Fa-f]{3,8}$/.test(raw)) {
        it.notes = raw.toUpperCase();
        hexEl.textContent = it.notes;
        if (swatchEl) swatchEl.style.background = it.notes;
        if (colorInp && it.notes.length === 7) colorInp.value = it.notes;
        saveVault('SWATCH HEX SAVED');
      } else {
        hexEl.textContent = (it.notes || validHex).toUpperCase();
      }
    };
    hexEl?.addEventListener('blur', commitHex);
    hexEl?.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); hexEl.blur(); } });
    lblEl?.addEventListener('pointerdown', (e) => e.stopPropagation());
    lblEl?.addEventListener('blur', () => {
      const nextLbl = (lblEl.textContent || '').trim() || 'Swatch';
      if (nextLbl !== it.title) {
        it.title = nextLbl;
        saveVault('SWATCH LABEL SAVED');
      }
    });
    lblEl?.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); lblEl.blur(); } });
  } else {
    let bodyHtml = '';
    if (it.kind === 'video' && it.url) {
      bodyHtml = `<div class="wall-pin-media"><video src="${escapeHtml(it.url)}#t=0.1" muted loop playsinline preload="metadata"></video></div>`;
    } else if (it.kind === 'audio' && it.url) {
      bodyHtml = `
        <div class="wall-pin-body" style="display:flex;flex-direction:column;gap:8px;">
          <div class="kicker-mono" style="color:var(--accent);">🔊 AUDIO CLIP</div>
          <audio src="${escapeHtml(it.url)}" controls style="width:100%;height:32px;"></audio>
        </div>
      `;
    } else if (isVisual) {
      bodyHtml = `<div class="wall-pin-media"><img src="${escapeHtml(it.url)}" alt="${escapeHtml(it.title)}" draggable="false"></div>`;
    } else if (it.kind === 'sketch') {
      bodyHtml = `
        <div class="wall-pin-body mn-sketch-body" style="display:flex;flex-direction:column;gap:6px;">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <div class="mn-card-inline-title" contenteditable="true" spellcheck="false">${escapeHtml(it.title || 'Sketch Pad')}</div>
            <button type="button" class="hover-act-btn btn-sketch-clear" style="opacity:1;font-size:10px;padding:1px 6px;">Clear</button>
          </div>
          <canvas class="mn-sketch-canvas" width="240" height="150" style="width:100%;height:150px;background:#FAF8F5;border:1px solid var(--border);border-radius:6px;cursor:crosshair;touch-action:none;"></canvas>
        </div>
      `;
    } else if (isTodo) {
      const rawTodo = (it.notes && (it.notes.includes('[ ]') || it.notes.includes('[x]')))
        ? it.notes
        : `[ ] ${it.notes || 'First task'}\n[ ] Second task`;
      it.notes = rawTodo;
      bodyHtml = `
        <div class="wall-pin-body mn-todo-body">
          <div class="mn-card-inline-title" contenteditable="true" spellcheck="false">${escapeHtml(it.title || 'To-do List')}</div>
          <div class="checklist-box">${renderChecklistHtml(rawTodo)}</div>
          <input type="text" class="mn-todo-add-input" placeholder="+ Add task &amp; press Enter…">
        </div>
      `;
    } else if (it.kind === 'table') {
      const rows = (it.notes || 'Column A | Column B\nValue 1 | Value 2').split('\n').map(r => r.split('|').map(c => c.trim()));
      bodyHtml = `
        <div class="wall-pin-body mn-table-body">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;gap:4px;">
            <div class="mn-card-inline-title" contenteditable="true" spellcheck="false" style="flex:1;min-width:0;">${escapeHtml(it.title || 'Table')}</div>
            <div style="display:flex;gap:3px;align-items:center;">
              <button type="button" class="hover-act-btn btn-table-add-col" style="opacity:1;font-size:10px;padding:1px 6px;" title="Add Column">+ Col</button>
              <button type="button" class="hover-act-btn btn-table-add-row" style="opacity:1;font-size:10px;padding:1px 6px;" title="Add Row">+ Row</button>
            </div>
          </div>
          <table class="mn-inline-table">
            ${rows.map((r, rIdx) => `<tr>${r.map(c => `<${rIdx === 0 ? 'th' : 'td'} contenteditable="true" spellcheck="false">${escapeHtml(c)}</${rIdx === 0 ? 'th' : 'td'}>`).join('')}${rows.length > 1 ? `<td class="tbl-act" style="width:18px;padding:2px;text-align:center;"><button type="button" class="btn-table-del-row" data-row-idx="${rIdx}" style="background:none;border:none;color:var(--text-dim);cursor:pointer;font-size:11px;line-height:1;padding:2px;" title="Delete row">×</button></td>` : ''}</tr>`).join('')}
          </table>
        </div>
      `;
    } else if (it.kind === 'link' || it.kind === 'map' || it.link) {
      const isMap = it.kind === 'map' || (it.link || '').includes('maps.google');
      bodyHtml = `
        <div class="wall-pin-body" style="display:flex;flex-direction:column;gap:6px;">
          <div class="kicker-mono" style="color:var(--accent);">${isMap ? '📍 LOCATION / MAP PIN' : ((it.link || '').startsWith('~') || (it.link || '').startsWith('/') ? '📁 LOCAL MAC PATH' : '🌐 WEB LINK')}</div>
          <div class="mn-card-inline-title" contenteditable="true" spellcheck="false">${escapeHtml(it.title || 'Reference Link')}</div>
          <div style="display:flex;gap:4px;align-items:center;">
            <input type="text" class="mn-inline-link-input inspector-input" value="${escapeHtml(it.link || '')}" placeholder="Paste URL or ~/ path…" style="font-size:11px;padding:4px 7px;flex:1;">
            <button type="button" class="hover-act-btn btn-pin-link" style="opacity:1;padding:4px 7px;">Open ↗</button>
          </div>
          <div class="mn-note-editable" contenteditable="true" spellcheck="false" data-placeholder="Add notes…">${escapeHtml(it.notes || '')}</div>
        </div>
      `;
    } else {
      bodyHtml = `
        <div class="wall-pin-body mn-note-body">
          ${it.kind === 'comment' ? `<div class="kicker-mono" style="color:var(--accent);margin-bottom:2px;">💬 STUDIO COMMENT</div>` : ''}
          <div class="mn-card-inline-title" contenteditable="true" spellcheck="false">${escapeHtml(it.title || (it.kind === 'comment' ? 'Comment' : 'Note'))}</div>
          <div class="mn-note-editable" contenteditable="true" spellcheck="false" data-placeholder="Write a note…">${escapeHtml(it.notes || '')}</div>
        </div>
      `;
    }

    const sourceProj = (!parentObj || parentObj.id !== it.parentId) && it.parentType === 'project' ? (vault.projects || []).find(p => p.id === it.parentId) : null;

    pin.innerHTML = `
      ${isVisual ? `<button type="button" class="asset-select-check ${isCmp ? 'is-selected' : ''}" title="Select to Compare">✓</button>` : ''}
      ${isVisual ? `<button type="button" class="node-ig-quick-btn ${igStat === 'published' ? 'is-published' : (igStat === 'queued' ? 'is-queued' : '')}" title="Cycle IG / Website Status">${igStat === 'published' ? '●' : (igStat === 'website' ? '🌐' : '◈')}</button>` : ''}
      ${igBadge}
      ${bodyHtml}
      <div class="wall-pin-caption">
        ${isVisual ? `<span class="pin-title" data-editable-title="1" title="Click to rename: ${escapeHtml(it.title)}">${escapeHtml(it.title)}</span>` : `<span class="kicker-mono" style="font-size:9px;opacity:0.55;">${escapeHtml((it.kind || 'NOTE').toUpperCase())}</span>`}
        <div style="display:flex;gap:4px;align-items:center;">
          ${sourceProj ? `<button type="button" class="hover-act-btn btn-pin-source-board" style="opacity:1;padding:1px 6px;" title="Open ${escapeHtml(sourceProj.title)}">Board ↗</button>` : ''}
          ${(it.link && it.kind !== 'link' && it.kind !== 'map') ? `<button type="button" class="hover-act-btn btn-pin-link" style="opacity:1;padding:1px 6px;">↗</button>` : ''}
          <button type="button" class="hover-act-btn btn-pin-inspect" style="opacity:1;padding:1px 6px;">•••</button>
        </div>
      </div>
      <div class="wall-resize-handle" title="Drag corner to resize card"></div>
    `;

    pin.querySelector('.btn-pin-source-board')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (sourceProj) openProjectBoard(sourceProj.id);
    });

    const linkInp = pin.querySelector('.mn-inline-link-input');
    linkInp?.addEventListener('pointerdown', (e) => e.stopPropagation());
    linkInp?.addEventListener('change', () => { it.link = linkInp.value.trim(); saveVault('LINK UPDATED'); });
    linkInp?.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); it.link = linkInp.value.trim(); saveVault('LINK UPDATED'); linkInp.blur(); } });

    const tableEl = pin.querySelector('.mn-inline-table');
    if (tableEl) {
      const serializeTable = () => {
        it.notes = Array.from(tableEl.querySelectorAll('tr')).map(tr =>
          Array.from(tr.querySelectorAll('th:not(.tbl-act), td:not(.tbl-act)')).map(cell => (cell.textContent || '').trim()).join(' | ')
        ).join('\n');
        saveVault('TABLE UPDATED');
      };
      tableEl.querySelectorAll('th:not(.tbl-act), td:not(.tbl-act)').forEach(cell => {
        cell.addEventListener('pointerdown', (e) => {
          if (document.activeElement === cell) e.stopPropagation();
        });
        cell.addEventListener('blur', serializeTable);
      });
      pin.querySelector('.btn-table-add-row')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const colCount = tableEl.querySelector('tr')?.querySelectorAll('th:not(.tbl-act), td:not(.tbl-act)').length || 2;
        it.notes = `${(it.notes || '').trim()}\n${Array(colCount).fill('—').join(' | ')}`.trim();
        saveVault('TABLE ROW ADDED');
        renderWorkspace();
      });
      pin.querySelector('.btn-table-add-col')?.addEventListener('click', (e) => {
        e.stopPropagation();
        const curLines = (it.notes || 'Column A | Column B\nValue 1 | Value 2').split('\n');
        it.notes = curLines.map((line, idx) => `${line.trim()} | ${idx === 0 ? 'New Col' : '—'}`).join('\n');
        saveVault('TABLE COLUMN ADDED');
        renderWorkspace();
      });
      tableEl.querySelectorAll('.btn-table-del-row').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          const rIdx = parseInt(btn.dataset.rowIdx, 10);
          const curLines = (it.notes || '').split('\n');
          if (curLines.length > 1 && rIdx >= 0 && rIdx < curLines.length) {
            curLines.splice(rIdx, 1);
            it.notes = curLines.join('\n');
            saveVault('TABLE ROW REMOVED');
            renderWorkspace();
          }
        });
      });
    }

    const sketchCanvas = pin.querySelector('.mn-sketch-canvas');
    if (sketchCanvas) {
      const ctx = sketchCanvas.getContext('2d');
      ctx.strokeStyle = '#181715';
      ctx.lineWidth = 2.2;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      if (it.sketchData && it.sketchData.startsWith('data:image/')) {
        const img = new Image();
        img.onload = () => ctx.drawImage(img, 0, 0);
        img.src = it.sketchData;
      }
      let drawing = false;
      sketchCanvas.addEventListener('pointerdown', (e) => {
        e.stopPropagation();
        drawing = true;
        const r = sketchCanvas.getBoundingClientRect();
        ctx.beginPath();
        ctx.moveTo((e.clientX - r.left) * (sketchCanvas.width / r.width), (e.clientY - r.top) * (sketchCanvas.height / r.height));
        try { sketchCanvas.setPointerCapture(e.pointerId); } catch (_) {}
      });
      sketchCanvas.addEventListener('pointermove', (e) => {
        if (!drawing) return;
        e.stopPropagation();
        const r = sketchCanvas.getBoundingClientRect();
        ctx.lineTo((e.clientX - r.left) * (sketchCanvas.width / r.width), (e.clientY - r.top) * (sketchCanvas.height / r.height));
        ctx.stroke();
      });
      const endSketch = (e) => {
        if (!drawing) return;
        drawing = false;
        e?.stopPropagation();
        try { it.sketchData = sketchCanvas.toDataURL('image/png'); saveVault('SKETCH SAVED'); } catch (_) {}
      };
      sketchCanvas.addEventListener('pointerup', endSketch);
      sketchCanvas.addEventListener('lostpointercapture', endSketch);
      pin.querySelector('.btn-sketch-clear')?.addEventListener('click', (e) => {
        e.stopPropagation();
        ctx.clearRect(0, 0, sketchCanvas.width, sketchCanvas.height);
        it.sketchData = '';
        saveVault('SKETCH CLEARED');
      });
    }

    const capTitleEl = pin.querySelector('.pin-title');
    capTitleEl?.addEventListener('click', (e) => {
      e.stopPropagation();
      promptInlineRename(capTitleEl, it.title, (val) => {
        it.title = val;
        const inl = pin.querySelector('.mn-card-inline-title');
        if (inl) inl.textContent = val;
        saveVault('PIN TITLE RENAMED');
      });
    });

    const inlineTitle = pin.querySelector('.mn-card-inline-title');
    inlineTitle?.addEventListener('blur', () => {
      const nextT = (inlineTitle.textContent || '').trim();
      if (nextT && nextT !== it.title) {
        it.title = nextT;
        const capTitle = pin.querySelector('.pin-title');
        if (capTitle) capTitle.textContent = nextT;
        saveVault('CARD TITLE SAVED');
      }
    });

    const inlineNote = pin.querySelector('.mn-note-editable');
    inlineNote?.addEventListener('blur', () => {
      const nextN = (inlineNote.innerText || '').trim();
      if (nextN !== (it.notes || '')) {
        it.notes = nextN;
        saveVault('NOTE SAVED');
      }
    });

    const todoAddInput = pin.querySelector('.mn-todo-add-input');
    todoAddInput?.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && todoAddInput.value.trim()) {
        e.preventDefault();
        it.notes = `${(it.notes || '').trim()}\n[ ] ${todoAddInput.value.trim()}`.trim();
        saveVault('TASK ADDED');
        renderWorkspace();
      }
    });

    pin.querySelectorAll('.chk-row').forEach(rowEl => {
      rowEl.addEventListener('pointerdown', (e) => e.stopPropagation());
    });
    pin.querySelectorAll('.chk-row input[type="checkbox"]').forEach(chk => {
      chk.addEventListener('pointerdown', (e) => e.stopPropagation());
      chk.addEventListener('click', (e) => {
        e.stopPropagation();
        const lineIdx = parseInt(chk.dataset.line, 10);
        toggleChecklistLine(it.id, lineIdx);
      });
    });
    pin.querySelectorAll('.btn-del-chk-line').forEach(btn => {
      btn.addEventListener('pointerdown', (e) => e.stopPropagation());
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        e.preventDefault();
        deleteChecklistLine(it.id, parseInt(btn.dataset.delLine, 10));
      });
    });
  }

  // Hover Quick-Look & Video
  pin.addEventListener('mouseenter', () => {
    if (isVisual) {
      state.hoveredAssetForQuickLook = {
        id: it.id,
        title: it.title,
        category: (parentObj && parentObj.title) || 'Studio',
        kind: it.kind || 'image',
        thumbSrc: it.url,
        sizeLabel: it.status || 'Board Pin'
      };
    }
    const v = pin.querySelector('video');
    if (v) v.play().catch(() => {});
  });
  pin.addEventListener('mouseleave', () => {
    if (state.hoveredAssetForQuickLook && state.hoveredAssetForQuickLook.id === it.id) {
      state.hoveredAssetForQuickLook = null;
    }
    const v = pin.querySelector('video');
    if (v) v.pause();
  });

  pin.querySelector('.asset-select-check')?.addEventListener('click', (e) => {
    e.stopPropagation();
    toggleCompareSelect({ id: it.id, title: it.title || 'Visual', url: it.url, kind: it.kind || 'image', igStatus: it.igStatus || '', vaultItemId: it.id, notes: it.notes || '' });
  });

  pin.querySelector('.node-ig-quick-btn')?.addEventListener('click', (e) => {
    e.stopPropagation();
    cycleItemIgStatus(it.id);
  });

  pin.querySelector('.btn-pin-inspect')?.addEventListener('click', (e) => {
    e.stopPropagation();
    openItemInspector(it.id);
  });

  pin.querySelector('.btn-pin-link')?.addEventListener('click', (e) => {
    e.stopPropagation();
    openUrlOrMacPath(it.link);
  });

  // Pointer Capture Dragging + Drop targets
  let draggingPin = false;
  let movedPin = false;
  let dStartX = 0;
  let dStartY = 0;
  let origPinX = 0;
  let origPinY = 0;
  let pendingFocusEditable = null;
  let batchPeerOffsets = [];
  let hoveredFolderEl = null;
  let hoveredColumnEl = null;
  let hoveredBreadcrumbEl = null;
  let hoveredSphereEl = null;
  let hoveredProjEl = null;

  pin.addEventListener('pointerdown', (e) => {
    if (e.button !== 0 || e.target.closest('.wall-resize-handle') || e.target.closest('button') || e.target.closest('a') || e.target.closest('input') || e.target.closest('canvas') || e.target.closest('audio')) return;

    if (e.shiftKey) {
      e.stopPropagation();
      e.preventDefault();
      state.batchSelectedIds = state.batchSelectedIds || new Set();
      if (state.batchSelectedIds.has(it.id)) {
        state.batchSelectedIds.delete(it.id);
        pin.classList.remove('is-batch-selected');
      } else {
        state.batchSelectedIds.add(it.id);
        pin.classList.add('is-batch-selected');
      }
      renderBatchActionBar(document.getElementById('giantWallStage'), document.getElementById('giantWallPlane'));
      return;
    }

    const editableTarget = e.target.closest('[contenteditable="true"]');
    if (editableTarget && document.activeElement === editableTarget) {
      return;
    }

    e.stopPropagation();
    draggingPin = true;
    movedPin = false;
    pendingFocusEditable = editableTarget || null;
    dStartX = e.clientX;
    dStartY = e.clientY;
    origPinX = typeof it.wallX === 'number' ? it.wallX : 264;
    origPinY = typeof it.wallY === 'number' ? it.wallY : 108;
    hoveredSphereEl = null;
    hoveredProjEl = null;
    batchPeerOffsets = [];

    if (state.batchSelectedIds && state.batchSelectedIds.has(it.id) && state.batchSelectedIds.size > 1) {
      const planeEl = pin.parentElement;
      state.batchSelectedIds.forEach(peerId => {
        if (peerId === it.id) return;
        const peerItem = vault.items.find(x => x.id === peerId);
        if (peerItem) {
          const domEl = planeEl?.querySelector(`.wall-pin-item[data-item-id="${peerId}"]`);
          batchPeerOffsets.push({ kind: 'item', obj: peerItem, el: domEl, startX: peerItem.wallX || 0, startY: peerItem.wallY || 0 });
          return;
        }
        const peerProj = vault.projects.find(p => p.id === peerId);
        if (peerProj) {
          const domEl = planeEl?.querySelector(`.clear-drawer-card[data-id="${peerId}"]`);
          batchPeerOffsets.push({ kind: 'project', obj: peerProj, el: domEl, startX: peerProj.boardX || 0, startY: peerProj.boardY || 0 });
        }
      });
    }
  });

  pin.addEventListener('pointermove', (e) => {
    if (!draggingPin) return;
    const dxScreen = e.clientX - dStartX;
    const dyScreen = e.clientY - dStartY;
    if (!movedPin && Math.hypot(dxScreen, dyScreen) < 4) return;
    if (!movedPin) {
      movedPin = true;
      if (document.activeElement && document.activeElement.isContentEditable) {
        document.activeElement.blur();
      }
      window.getSelection?.()?.removeAllRanges?.();
      pin.classList.add('is-dragging');
      try { pin.setPointerCapture(e.pointerId); } catch (_) {}
    }

    const cam = getActiveBoardCamera();
    const dx = dxScreen / (cam.zoom || 1);
    const dy = dyScreen / (cam.zoom || 1);

    const rawX = origPinX + dx;
    const rawY = origPinY + dy;
    const snappedX = snapCoord(rawX, e.altKey);
    const snappedY = snapCoord(rawY, e.altKey);

    it.wallX = snappedX;
    it.wallY = snappedY;
    pin.style.left = `${snappedX}px`;
    pin.style.top = `${snappedY}px`;

    if (batchPeerOffsets.length > 0) {
      const actualDx = snappedX - origPinX;
      const actualDy = snappedY - origPinY;
      batchPeerOffsets.forEach(peer => {
        const px = snapCoord(peer.startX + actualDx, e.altKey);
        const py = snapCoord(peer.startY + actualDy, e.altKey);
        if (peer.kind === 'item') {
          peer.obj.wallX = px;
          peer.obj.wallY = py;
        } else {
          peer.obj.boardX = px;
          peer.obj.boardY = py;
        }
        if (peer.el) {
          peer.el.style.left = `${px}px`;
          peer.el.style.top = `${py}px`;
        }
      });
    }

    const snapPreview = document.getElementById('wallSnapPreview');
    if (snapPreview && state.snapToGrid && movedPin) {
      snapPreview.hidden = false;
      snapPreview.style.left = `${snappedX}px`;
      snapPreview.style.top = `${snappedY}px`;
      snapPreview.style.width = `${pin.offsetWidth}px`;
      snapPreview.style.height = `${pin.offsetHeight}px`;
    }

    pin.style.pointerEvents = 'none';
    const underEl = document.elementFromPoint(e.clientX, e.clientY);
    pin.style.pointerEvents = '';

    const projTarget = underEl?.closest('.clear-drawer-card[data-id]');
    if (hoveredProjEl && hoveredProjEl !== projTarget) hoveredProjEl.classList.remove('is-drop-target');
    if (projTarget) {
      projTarget.classList.add('is-drop-target');
      hoveredProjEl = projTarget;
    } else {
      hoveredProjEl = null;
    }

    const folderTarget = underEl?.closest('.wall-pin-item.is-folder-pin');
    if (hoveredFolderEl && hoveredFolderEl !== folderTarget) hoveredFolderEl.classList.remove('is-drop-target');
    if (folderTarget && folderTarget !== pin) {
      folderTarget.classList.add('is-drop-target');
      hoveredFolderEl = folderTarget;
    } else {
      hoveredFolderEl = null;
    }

    const sphereTarget = underEl?.closest('.mn-sphere-container');
    if (hoveredSphereEl && hoveredSphereEl !== sphereTarget) hoveredSphereEl.classList.remove('is-drop-target');
    if (sphereTarget && !isFolder && it.kind !== 'sphere') {
      sphereTarget.classList.add('is-drop-target');
      hoveredSphereEl = sphereTarget;
    } else {
      hoveredSphereEl = null;
    }

    const colTarget = underEl?.closest('.wall-pin-item.is-column-pin');
    if (hoveredColumnEl && hoveredColumnEl !== colTarget) hoveredColumnEl.classList.remove('is-drop-target');
    if (colTarget && colTarget !== pin && !isFolder && !isColumn) {
      colTarget.classList.add('is-drop-target');
      hoveredColumnEl = colTarget;
    } else {
      hoveredColumnEl = null;
    }

    const crumbTarget = underEl?.closest('.crumb-folder-drop');
    if (hoveredBreadcrumbEl && hoveredBreadcrumbEl !== crumbTarget) hoveredBreadcrumbEl.classList.remove('is-drop-target');
    if (crumbTarget) {
      crumbTarget.classList.add('is-drop-target');
      hoveredBreadcrumbEl = crumbTarget;
    } else {
      hoveredBreadcrumbEl = null;
    }

    const trashBtn = document.getElementById('milanoteTrashDropZone');
    if (trashBtn) {
      const r = trashBtn.getBoundingClientRect();
      const overTrash = e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
      trashBtn.classList.toggle('is-drag-over', overTrash);
    }
  });

  const finishPinDrag = (e) => {
    if (!draggingPin) return;
    draggingPin = false;
    pin.classList.remove('is-dragging');
    const snapPreview = document.getElementById('wallSnapPreview');
    if (snapPreview) snapPreview.hidden = true;

    if (!movedPin) {
      if (pendingFocusEditable) {
        pendingFocusEditable.focus();
      }
      pendingFocusEditable = null;
      batchPeerOffsets = [];
      return;
    }
    pendingFocusEditable = null;
    batchPeerOffsets = [];

    if (hoveredProjEl) {
      const targetProjId = hoveredProjEl.dataset.id;
      hoveredProjEl.classList.remove('is-drop-target');
      hoveredProjEl = null;
      if (targetProjId) {
        it.parentType = 'project';
        it.parentId = targetProjId;
        delete it.folderId;
        delete it.columnId;
        delete it.sphereId;
        saveVault('MOVED INTO PROJECT BOARD');
        renderAll();
        showStatusToast('Moved to project board');
        return;
      }
    }

    if (hoveredSphereEl) {
      const targetSphereId = hoveredSphereEl.dataset.sphereId;
      hoveredSphereEl.classList.remove('is-drop-target');
      hoveredSphereEl = null;
      if (targetSphereId && targetSphereId !== it.id) {
        it.sphereId = targetSphereId;
        delete it.folderId;
        delete it.columnId;
        saveVault('MOVED INTO SPHERE');
        renderWorkspace();
        showStatusToast('◎ Added to sphere');
        return;
      }
    }

    if (hoveredFolderEl) {
      const targetFolderId = hoveredFolderEl.dataset.itemId;
      hoveredFolderEl.classList.remove('is-drop-target');
      hoveredFolderEl = null;
      if (targetFolderId && targetFolderId !== it.id) {
        it.folderId = targetFolderId;
        delete it.sphereId;
        saveVault('MOVED INTO FOLDER');
        renderAll();
        return;
      }
    }

    if (hoveredColumnEl) {
      const targetColId = hoveredColumnEl.dataset.itemId;
      hoveredColumnEl.classList.remove('is-drop-target');
      hoveredColumnEl = null;
      if (targetColId && targetColId !== it.id) {
        it.columnId = targetColId;
        delete it.sphereId;
        saveVault('ADDED TO COLUMN');
        renderWorkspace();
        return;
      }
    }

    if (hoveredBreadcrumbEl) {
      const destFolderId = hoveredBreadcrumbEl.dataset.crumbFolder || hoveredBreadcrumbEl.dataset.folderDrop || null;
      hoveredBreadcrumbEl.classList.remove('is-drop-target');
      hoveredBreadcrumbEl = null;
      it.folderId = destFolderId || null;
      delete it.sphereId;
      saveVault('MOVED TO PARENT BOARD');
      renderAll();
      return;
    }

    const trashBtn = document.getElementById('milanoteTrashDropZone');
    if (trashBtn) {
      const r = trashBtn.getBoundingClientRect();
      trashBtn.classList.remove('is-drag-over');
      if (e && e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom) {
        deleteItemDirectly(it.id);
        return;
      }
    }

    if (movedPin) {
      saveVault('PIN POSITION SAVED');
    }
  };

  pin.addEventListener('pointerup', finishPinDrag);
  pin.addEventListener('lostpointercapture', finishPinDrag);

  pin.addEventListener('dblclick', (e) => {
    if (e.target.closest('[contenteditable="true"]') || e.target.closest('input')) return;
    if (isFolder) {
      state.activeFolderId = it.id;
      renderAll();
    } else {
      openItemInspector(it.id);
    }
  });

  const rHandle = pin.querySelector('.wall-resize-handle');
  let resizingPin = false;
  let rStartX = 0;
  let origW = w;
  rHandle?.addEventListener('pointerdown', (e) => {
    e.stopPropagation();
    resizingPin = true;
    rStartX = e.clientX;
    origW = pin.offsetWidth;
    try { rHandle.setPointerCapture(e.pointerId); } catch (_) {}
  });
  rHandle?.addEventListener('pointermove', (e) => {
    if (!resizingPin) return;
    const cam = getActiveBoardCamera();
    const rawW = Math.max(168, Math.min(768, origW + (e.clientX - rStartX) / (cam.zoom || 1)));
    const nw = snapCoord(rawW);
    it.wallW = nw;
    pin.style.width = `${nw}px`;
  });
  const finishResize = () => {
    if (!resizingPin) return;
    resizingPin = false;
    saveVault('PIN SIZE SAVED');
  };
  rHandle?.addEventListener('pointerup', finishResize);
  rHandle?.addEventListener('lostpointercapture', finishResize);

  const quickDelBtn = document.createElement('button');
  quickDelBtn.type = 'button';
  quickDelBtn.className = 'pin-quick-delete-btn';
  quickDelBtn.title = 'Delete item';
  quickDelBtn.innerHTML = '✕';
  quickDelBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    deleteItemDirectly(it.id);
  });
  pin.appendChild(quickDelBtn);

  return pin;
}

function renderProjectsSpatialBoard(ws, list, passedLooseItems) {
  const snapOn = state.snapToGrid !== false;
  const cam = getActiveBoardCamera();
  const rawLoose = Array.isArray(passedLooseItems)
    ? passedLooseItems
    : vault.items.filter(i => i.parentType === 'space' && i.parentId === 'projects' && !i.folderId && !i.columnId);
  const looseItems = rawLoose.filter(i => !i.sphereId);

  ws.innerHTML = `
    <div class="giant-wall-stage" id="giantWallStage">
      <div class="giant-wall-plane" id="giantWallPlane">
        <div class="wall-snap-preview" id="wallSnapPreview" hidden></div>
      </div>
      <div class="giant-wall-hud">
        <div class="giant-wall-hud-pill">
          <button type="button" id="btnWallZoomOut" title="Zoom Out (⌘-)">−</button>
          <button type="button" id="btnResetWallCamera" title="Reset Zoom &amp; Pan (⌘0)">${Math.round((cam.zoom || 1) * 100)}%</button>
          <button type="button" id="btnWallZoomIn" title="Zoom In (⌘+)">+</button>
          <button type="button" id="btnToggleGridSnap" class="${snapOn ? 'is-active' : ''}" title="Toggle 24px Magnetic Grid Snapping">${snapOn ? '⊞ Snap: ON' : '⊞ Snap: OFF'}</button>
          <button type="button" id="btnAutoArrangeWall" title="Tidy project boards into clean grid">⊞ Tidy</button>
        </div>
        <button type="button" class="floating-new-project-fab" id="btnFloatingNewProject" title="Create New Project Board">+ New Project</button>
      </div>
    </div>
  `;

  ws.querySelector('#btnFloatingNewProject')?.addEventListener('click', () => createAndOpenNewProjectBoard());

  const stage = ws.querySelector('#giantWallStage');
  const plane = ws.querySelector('#giantWallPlane');
  const snapBox = ws.querySelector('#wallSnapPreview');

  bindSpatialStageCamera(stage, plane, () => {
    list.forEach((proj, idx) => {
      const col = idx % 3;
      const row = Math.floor(idx / 3);
      proj.boardX = snapCoord(264 + col * 356);
      proj.boardY = snapCoord(108 + row * 336);
      proj.boardW = 336;
    });
    const baseRow = Math.ceil(list.length / 3);
    looseItems.forEach((it, idx) => {
      const col = idx % 3;
      const row = Math.floor(idx / 3);
      it.wallX = snapCoord(264 + col * 356);
      it.wallY = snapCoord(108 + (baseRow + row) * 336);
      it.wallW = it.wallW || 288;
    });
    saveVault('TIDIED BOARD');
    renderWorkspace();
  });

  list.forEach((proj, idx) => {
    if (typeof proj.boardX !== 'number' || Number.isNaN(proj.boardX) || typeof proj.boardY !== 'number' || Number.isNaN(proj.boardY)) {
      const col = idx % 3;
      const row = Math.floor(idx / 3);
      proj.boardX = snapCoord(264 + col * 356);
      proj.boardY = snapCoord(108 + row * 336);
      proj.boardW = Math.min(336, proj.boardW || 336);
    }
    const card = buildClearDrawerProjectEl(proj, idx, true, snapBox);
    plane.appendChild(card);
  });

  // Also render any Milanote items created directly on the 01 Studio Projects spatial canvas (with drag, resize, drop-into-board & trash)
  const spaceObj = vault.spaces.find(s => s.id === 'projects') || { id: 'projects', title: 'Studio Projects' };
  looseItems.forEach((it, idx) => {
    if (it.sphereId) return;
    if (it.kind === 'line') {
      const connEl = buildSpatialConnectorEl(it, true);
      plane.appendChild(connEl);
      return;
    }
    if (it.kind === 'sphere') {
      const sphereEl = buildSphereContainerEl(it);
      plane.appendChild(sphereEl);
      return;
    }
    const pin = buildSpatialPinEl(it, 'space', spaceObj, idx);
    if (pin) plane.appendChild(pin);
  });
  if (state.batchSelectedIds && state.batchSelectedIds.size > 0) {
    renderBatchActionBar(stage, plane);
  }
}

function bindProjectLifecycleBar(ws) {
  ws.querySelectorAll('[data-proj-lifecycle]').forEach(btn => {
    btn.addEventListener('click', () => {
      state.projectsLifecycleFilter = btn.dataset.projLifecycle;
      renderWorkspace();
    });
  });
}

function buildClearDrawerProjectEl(proj, idx, isSpatial = false, snapBox = null) {
  let items = vault.items.filter(i => i.parentType === 'project' && i.parentId === proj.id);
  if (state.igStatusFilter && state.igStatusFilter !== 'all') {
    items = items.filter(i => i.igStatus === state.igStatusFilter);
  }
  const numStr = getProjectDisplayNumber(proj);
  const isBatchSel = Boolean(state.batchSelectedIds && state.batchSelectedIds.has(proj.id));
  const drawer = document.createElement('article');
  drawer.className = 'clear-drawer-card' + (isSpatial ? ' spatial-project-cluster' : '') + (isBatchSel ? ' is-batch-selected' : '');
  drawer.dataset.id = proj.id;

  if (isSpatial) {
    const w = proj.boardW || 360;
    drawer.style.left = `${proj.boardX}px`;
    drawer.style.top = `${proj.boardY}px`;
    drawer.style.width = `${w}px`;
    drawer.style.setProperty('--grid-size', `${w}px`);
  }

  const previewItems = items.slice(0, 6);
  const cellsHtml = previewItems.map((it, cIdx) => {
    const isCmp = isAssetCompareSelected(it.id);
    const igStat = it.igStatus || '';
    const igBadge = igStat === 'published'
      ? `<span class="ig-status-badge is-published">●</span>`
      : (igStat === 'queued'
          ? `<span class="ig-status-badge is-queued">◈</span>`
          : (igStat === 'website' ? `<span class="ig-status-badge" style="background:rgba(59,130,246,0.92);color:#FFF;">🌐</span>` : ''));

    if (it.url && it.kind !== 'audio') {
      const prio = idx === 0 && cIdx < 2 ? 'fetchpriority="high"' : 'loading="lazy" decoding="async"';
      const mediaTag = it.kind === 'video'
        ? `<video src="${escapeHtml(it.url)}#t=0.1" muted loop playsinline preload="metadata" draggable="false"></video>`
        : `<img src="${escapeHtml(it.url)}" alt="${escapeHtml(it.title)}" draggable="false" ${prio}>`;
      return `
        <div class="clear-drawer-thumb ${isCmp ? 'is-compare-selected' : ''}" data-item-id="${escapeHtml(it.id)}" title="${escapeHtml(it.title)} — Click to open board · Drag to move board">
          ${mediaTag}
          <button type="button" class="asset-select-check ${isCmp ? 'is-selected' : ''}" data-check-item="${escapeHtml(it.id)}" title="Select to Compare">✓</button>
          ${igBadge}
        </div>
      `;
    }
    return `
      <div class="clear-drawer-thumb is-note-thumb" data-item-id="${escapeHtml(it.id)}" title="${escapeHtml(it.title)} — Click to open board">
        <div class="note-preview-mini"><strong>${escapeHtml(it.title)}</strong><br>${escapeHtml((it.notes || it.link || '').slice(0, 65))}</div>
      </div>
    `;
  }).join('');

  drawer.innerHTML = `
    <div class="clear-drawer-header">
      <div class="clear-drawer-title-line">
        <span class="cluster-board-glyph" title="Click to open Project Board">⊞</span>
        <span class="cluster-index">${numStr}</span>
        <h3 class="clear-drawer-title" title="Click to open Project Board">${escapeHtml(proj.title)}</h3>
        ${proj.finlandLinked ? `<span class="cluster-finland-dot" title="Synced with Finland">●</span>` : ''}
      </div>
      <div class="cluster-hover-actions">
        <button type="button" class="quiet-action-link danger btn-del-board" title="Delete project">×</button>
      </div>
    </div>

    <div class="clear-drawer-bento">
      ${cellsHtml || `<div class="cluster-empty-drop">Click to open board</div>`}
    </div>
    ${isSpatial ? `<div class="wall-resize-handle" title="Drag corner to resize cluster"></div>` : ''}
  `;

  drawer.querySelector('.btn-del-board')?.addEventListener('click', (e) => {
    e.stopPropagation();
    requestDelete('project', proj.id, proj.title);
  });

  if (!isSpatial) {
    drawer.addEventListener('click', (e) => {
      if (e.target.closest('button') || e.target.closest('.inline-rename-field')) return;
      openProjectBoard(proj.id);
    });
  }

  drawer.querySelectorAll('.clear-drawer-thumb').forEach(thumb => {
    const itemId = thumb.dataset.itemId;
    const it = vault.items.find(i => i.id === itemId);
    if (!it) return;

    thumb.addEventListener('mouseenter', () => {
      if (it.url && it.kind !== 'audio') {
        state.hoveredAssetForQuickLook = {
          id: it.id,
          title: it.title,
          category: proj.title,
          kind: it.kind || 'image',
          thumbSrc: it.url,
          sizeLabel: it.status || 'Project File'
        };
      }
      const v = thumb.querySelector('video');
      if (v) v.play().catch(() => {});
    });
    thumb.addEventListener('mouseleave', () => {
      if (state.hoveredAssetForQuickLook && state.hoveredAssetForQuickLook.id === it.id) {
        state.hoveredAssetForQuickLook = null;
      }
      const v = thumb.querySelector('video');
      if (v) v.pause();
    });

    thumb.querySelector('.asset-select-check')?.addEventListener('click', (e) => {
      e.stopPropagation();
      toggleCompareSelect({
        id: it.id,
        title: it.title || 'Visual',
        url: it.url,
        kind: it.kind || 'image',
        igStatus: it.igStatus || '',
        vaultItemId: it.id,
        notes: it.notes || ''
      });
    });
  });

  if (isSpatial) {
    // True Pointer-Capture Grab & Move on the Spatial Board (with 4px click-vs-drag threshold & 24px grid snap)
    drawer.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      if (e.target.closest('button') || e.target.closest('.wall-resize-handle') || e.target.closest('.inline-rename-field')) return;
      e.stopPropagation();

      if (e.shiftKey) {
        e.preventDefault();
        state.batchSelectedIds = state.batchSelectedIds || new Set();
        if (state.batchSelectedIds.has(proj.id)) {
          state.batchSelectedIds.delete(proj.id);
          drawer.classList.remove('is-batch-selected');
        } else {
          state.batchSelectedIds.add(proj.id);
          drawer.classList.add('is-batch-selected');
        }
        renderBatchActionBar(document.getElementById('giantWallStage'), document.getElementById('giantWallPlane'));
        return;
      }

      const cam = getActiveBoardCamera();
      const startX = e.clientX;
      const startY = e.clientY;
      const origX = typeof proj.boardX === 'number' ? proj.boardX : 336;
      const origY = typeof proj.boardY === 'number' ? proj.boardY : 144;
      let moved = false;
      const trashZone = document.getElementById('milanoteTrashDropZone');
      const peerOffsets = [];

      if (state.batchSelectedIds && state.batchSelectedIds.has(proj.id) && state.batchSelectedIds.size > 1) {
        const planeEl = drawer.parentElement;
        state.batchSelectedIds.forEach(peerId => {
          if (peerId === proj.id) return;
          const peerProj = vault.projects.find(p => p.id === peerId);
          if (peerProj) {
            const domEl = planeEl?.querySelector(`.clear-drawer-card[data-id="${peerId}"]`);
            peerOffsets.push({ kind: 'project', obj: peerProj, el: domEl, startX: peerProj.boardX || 0, startY: peerProj.boardY || 0 });
            return;
          }
          const peerItem = vault.items.find(x => x.id === peerId);
          if (peerItem) {
            const domEl = planeEl?.querySelector(`.wall-pin-item[data-item-id="${peerId}"]`);
            peerOffsets.push({ kind: 'item', obj: peerItem, el: domEl, startX: peerItem.wallX || 0, startY: peerItem.wallY || 0 });
          }
        });
      }

      drawer.setPointerCapture(e.pointerId);

      const onMove = (ev) => {
        const dxScreen = ev.clientX - startX;
        const dyScreen = ev.clientY - startY;
        if (!moved && Math.hypot(dxScreen, dyScreen) < 4) return;
        if (!moved) {
          moved = true;
          drawer.classList.add('dragging');
        }
        const z = cam.zoom || 1;
        const rawX = origX + dxScreen / z;
        const rawY = origY + dyScreen / z;
        const snappedX = snapCoord(rawX, ev.altKey);
        const snappedY = snapCoord(rawY, ev.altKey);

        proj.boardX = snappedX;
        proj.boardY = snappedY;
        drawer.style.left = `${snappedX}px`;
        drawer.style.top = `${snappedY}px`;

        if (peerOffsets.length > 0) {
          const actualDx = snappedX - origX;
          const actualDy = snappedY - origY;
          peerOffsets.forEach(peer => {
            const px = snapCoord(peer.startX + actualDx, ev.altKey);
            const py = snapCoord(peer.startY + actualDy, ev.altKey);
            if (peer.kind === 'project') {
              peer.obj.boardX = px;
              peer.obj.boardY = py;
            } else {
              peer.obj.wallX = px;
              peer.obj.wallY = py;
            }
            if (peer.el) {
              peer.el.style.left = `${px}px`;
              peer.el.style.top = `${py}px`;
            }
          });
        }

        if (snapBox) {
          snapBox.hidden = false;
          snapBox.style.left = `${snappedX}px`;
          snapBox.style.top = `${snappedY}px`;
          snapBox.style.width = `${drawer.offsetWidth}px`;
          snapBox.style.height = `${drawer.offsetHeight}px`;
        }

        if (trashZone) {
          const tr = trashZone.getBoundingClientRect();
          const overTrash = ev.clientX >= tr.left && ev.clientX <= tr.right && ev.clientY >= tr.top && ev.clientY <= tr.bottom;
          trashZone.classList.toggle('is-trash-hot', overTrash);
        }
      };

      const onStop = () => {
        drawer.removeEventListener('pointermove', onMove);
        drawer.removeEventListener('lostpointercapture', onStop);
        drawer.classList.remove('dragging');
        if (snapBox) snapBox.hidden = true;

        if (trashZone && trashZone.classList.contains('is-trash-hot')) {
          trashZone.classList.remove('is-trash-hot');
          requestDelete('project', proj.id, proj.title);
          return;
        }

        if (moved) {
          saveVault('BOARD POSITION SAVED');
        } else {
          openProjectBoard(proj.id);
        }
      };

      drawer.addEventListener('pointermove', onMove);
      drawer.addEventListener('lostpointercapture', onStop);
    });

    // Corner Resize Handle for Project Cluster
    const rHandle = drawer.querySelector('.wall-resize-handle');
    rHandle?.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      e.stopPropagation();
      e.preventDefault();
      rHandle.setPointerCapture(e.pointerId);
      const startX = e.clientX;
      const origW = drawer.offsetWidth;
      const cam = getActiveBoardCamera();

      const onResizeMove = (ev) => {
        const z = cam.zoom || 1;
        const rawW = origW + (ev.clientX - startX) / z;
        const nw = Math.max(240, Math.min(768, snapCoord(rawW, ev.altKey)));
        proj.boardW = nw;
        drawer.style.width = `${nw}px`;
        drawer.style.setProperty('--grid-size', `${nw}px`);
      };
      const onResizeStop = () => {
        rHandle.removeEventListener('pointermove', onResizeMove);
        rHandle.removeEventListener('lostpointercapture', onResizeStop);
        saveVault('BOARD SIZE SAVED');
      };
      rHandle.addEventListener('pointermove', onResizeMove);
      rHandle.addEventListener('lostpointercapture', onResizeStop);
    });
  }

  return drawer;
}

function buildProjectCardEl(proj, idx) {
  return buildClearDrawerProjectEl(proj, idx, false);
}

function deliverProjectAndSpawnShowcase(projId) {
  const proj = vault.projects.find(p => p.id === projId);
  if (!proj) return;

  if (proj.lifecycleState === 'delivered') {
    proj.lifecycleState = 'active';
    proj.status = 'Open';
    proj.updatedAt = Date.now();
    saveVault('MOVED TO OPEN');
    renderAll();
    return;
  }

  proj.lifecycleState = 'delivered';
  proj.status = '✓ Finished';
  proj.updatedAt = Date.now();
  saveVault('MARKED FINISHED');
  renderAll();
}

function openProjectBoard(projId, folderId = null) {
  const proj = vault.projects.find(p => p.id === projId);
  if (!proj) return;
  guardLeaveCustomize(() => {
    state.viewType = 'project';
    state.activeProjectId = proj.id;
    state.activeFolderId = folderId || null;
    state.activeCategory = (proj.sections && proj.sections[0]) || 'All';
    state.giantWallZoom = (typeof proj.ui?.cameraZoom === 'number' && proj.ui.cameraZoom > 0) ? proj.ui.cameraZoom : 1;
    state.giantWallPanX = (typeof proj.ui?.cameraPanX === 'number') ? proj.ui.cameraPanX : 0;
    state.giantWallPanY = (typeof proj.ui?.cameraPanY === 'number') ? proj.ui.cameraPanY : 0;
    if (!proj.ui || !proj.ui.layoutMode || proj.ui.layoutMode === 'sphere') {
      proj.ui = proj.ui || {};
      proj.ui.layoutMode = 'giant_wall';
    }
    applyCustomizationToDOM();
    renderAll();
  });
}

function createAndOpenNewProjectBoard() {
  const projSpaceForCat = vault.spaces.find(s => s.id === 'projects');
  const firstProjCat = (projSpaceForCat && projSpaceForCat.categories && projSpaceForCat.categories[0]) || 'All Disciplines';
  const curCat = state.activeCategory || '';
  const activeSpaceCat = (state.viewType === 'space' && state.activeSpaceId === 'projects' && curCat && curCat !== firstProjCat && !curCat.startsWith('All'))
    ? curCat
    : '3D & Motion';
  const projSpot = findNextOpenProjectClusterSpot();
  const newProj = {
    id: 'proj_' + Date.now(),
    title: 'Untitled Project',
    status: '🔥 In Progress',
    category: activeSpaceCat,
    subtitle: '',
    sections: ['All', 'WIP', 'References', 'Notes'],
    tags: [activeSpaceCat, 'Studio'],
    finlandLinked: false,
    boardX: projSpot.x,
    boardY: projSpot.y,
    boardW: 360,
    ui: { layoutMode: 'giant_wall', cardSize: 280, aspectRatio: '16 / 10.5', imageFit: 'cover', sortOrder: 'manual' },
    createdAt: Date.now(),
    updatedAt: Date.now()
  };
  vault.projects.unshift(newProj);
  saveVault('CREATED NEW PROJECT BOARD');
  openProjectBoard(newProj.id);
  setTimeout(() => {
    const titleEl = document.getElementById('viewTitle');
    if (titleEl) titleEl.click();
  }, 60);
}

function moveProjectOrder(projId, delta) {
  const idx = vault.projects.findIndex(p => p.id === projId);
  if (idx === -1) return;
  const target = idx + delta;
  if (target < 0 || target >= vault.projects.length) return;
  const [moved] = vault.projects.splice(idx, 1);
  vault.projects.splice(target, 0, moved);
  saveVault();
  renderAll();
}

/* --------------------------------------------------------------------------
   ITEMS COLLECTION VIEW (Inside Any Project Board or Sidebar Section 03–06)
   -------------------------------------------------------------------------- */
function renderItemsCollection(ws, parentType, parentObj) {
  const ui = parentObj.ui || {};
  const isSpatialParent = (parentType === 'project' || parentObj.id === 'incubator' || parentObj.id === 'drop_table');
  const defaultMode = isSpatialParent ? 'giant_wall' : 'wall';
  let mode = ui.layoutMode || defaultMode;
  if (isSpatialParent && mode === 'sphere') {
    mode = 'giant_wall';
    ui.layoutMode = 'giant_wall';
  }

  const sortOrder = ui.sortOrder || 'manual';
  const tabs = parentType === 'project' ? (parentObj.sections || ['All']) : (parentObj.categories || ['All']);
  const firstTab = tabs[0] || 'All';

  const isInstagramSpace = (parentType === 'space' && parentObj.id === 'instagram');
  const baseSourceItems = isInstagramSpace ? getInstagramAllItems() : vault.items;

  let items = baseSourceItems.filter(it => {
    if (!isInstagramSpace && (it.parentType !== parentType || it.parentId !== parentObj.id)) return false;
    // Folder scope filtering: only show items at the current folder level (unless searching globally)
    if (!state.searchQuery) {
      if (isInstagramSpace) {
        if (!isInstagramFolderMatch(it, state.activeFolderId)) return false;
      } else {
        const itemFolder = it.folderId || null;
        const activeFolder = state.activeFolderId || null;
        if (itemFolder !== activeFolder) return false;
      }
    }
    // Exclude items parked inside a Column or Sphere container from freeform root rendering
    if (mode === 'giant_wall' && (it.columnId || it.sphereId)) return false;

    if (state.activeCategory && state.activeCategory !== firstTab) {
      if (isInstagramSpace) {
        if (!matchesInstagramCategory(it, state.activeCategory, false)) return false;
      } else if (it.section !== state.activeCategory) {
        return false;
      }
    }
    if (state.igStatusFilter && state.igStatusFilter !== 'all') {
      if (it.igStatus !== state.igStatusFilter) return false;
    }
    if (state.searchQuery) {
      const q = state.searchQuery.toLowerCase();
      const sourceProj = (isInstagramSpace && it.parentType === 'project')
        ? (vault.projects || []).find(p => p.id === it.parentId)
        : null;
      const hay = `${it.title} ${it.notes} ${it.status} ${(it.tags || []).join(' ')} ${it.link || ''} ${sourceProj ? sourceProj.title : ''}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  if (sortOrder === 'newest' || sortOrder === 'updated') {
    items = [...items].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
  } else if (sortOrder === 'alpha') {
    items = [...items].sort((a, b) => (a.title || '').localeCompare(b.title || ''));
  }

  // 3D Sphere View support for 02 Incubator and any Project/Space
  if (mode === 'sphere') {
    const allSphere = convertItemsToSphereLayerNodes(items);
    const sphereBatches = [
      {
        id: `${parentObj.id}_all_sphere`,
        code: '00',
        title: parentObj.heading || parentObj.title || 'Incubator',
        subtitle: `${items.length} Elements · Hatching Up & WIP`,
        category: parentObj.title || 'Incubator',
        status: '3D Sphere View',
        visualNodes: allSphere.visualNodes,
        outerNodes: allSphere.outerNodes,
        totalCount: items.length,
        primaryActionLabel: 'Spatial Wall →',
        onPrimaryOpen: () => {
          parentObj.ui = parentObj.ui || {};
          parentObj.ui.layoutMode = 'giant_wall';
          saveVault();
          renderAll();
        },
        onRightTopAction: () => {
          parentObj.ui = parentObj.ui || {};
          parentObj.ui.layoutMode = 'giant_wall';
          saveVault();
          renderAll();
        },
        onRightBottomAction: () => openQuickComposer('note'),
        onRename: (newTitle) => {
          parentObj.title = newTitle;
          if (parentType === 'space') parentObj.heading = newTitle;
          saveVault('RENAMED SECTION');
          renderAll();
        }
      }
    ];
    tabs.slice(1).forEach((secName, idx) => {
      const secItems = items.filter(i => i.section === secName);
      if (secItems.length > 0) {
        const secSphere = convertItemsToSphereLayerNodes(secItems);
        sphereBatches.push({
          id: `${parentObj.id}_sec_${idx}`,
          code: '0' + (idx + 1),
          title: secName,
          subtitle: `${secItems.length} Elements in ${secName}`,
          category: secName,
          status: 'Cluster',
          visualNodes: secSphere.visualNodes,
          outerNodes: secSphere.outerNodes,
          totalCount: secItems.length,
          onTurnIntoProject: parentObj.id === 'incubator' ? () => {
            state.batchSelectedIds = new Set(secItems.map(it => it.id));
            openBatchToProjectDialog();
          } : undefined,
          primaryActionLabel: 'Filter Wall →',
          onPrimaryOpen: () => {
            state.activeCategory = secName;
            parentObj.ui = parentObj.ui || {};
            parentObj.ui.layoutMode = 'giant_wall';
            saveVault();
            renderAll();
          },
          onRightTopAction: () => {
            state.activeCategory = secName;
            parentObj.ui = parentObj.ui || {};
            parentObj.ui.layoutMode = 'giant_wall';
            saveVault();
            renderAll();
          },
          onRename: (newTitle) => {
            const catIdx = tabs.indexOf(secName);
            if (catIdx !== -1) tabs[catIdx] = newTitle;
            vault.items.forEach(it => {
              if (it.parentType === parentType && it.parentId === parentObj.id && it.section === secName) {
                it.section = newTitle;
              }
            });
            saveVault('RENAMED CATEGORY');
            renderAll();
          }
        });
      }
    });
    renderSphericalStage(ws, sphereBatches, { isIncubator: parentObj.id === 'incubator' });
    return;
  }

  // Module 3: 03 Instagram and 04 Website & Portfolio -> Post-Delivery Showcase & Rollout Staging Board
  if (parentType === 'space' && (parentObj.id === 'instagram' || parentObj.id === 'website')) {
    let combinedItems;
    if (parentObj.id === 'instagram') {
      combinedItems = items;
    } else {
      const connectedProjItems = vault.items.filter(it => {
        const isFromCreativeStudio = it.parentType === 'project' || (it.parentType === 'space' && it.parentId === 'incubator');
        if (!isFromCreativeStudio) return false;
        if (parentObj.id === 'website') return it.igStatus === 'website';
        return false;
      });
      combinedItems = [...items];
      connectedProjItems.forEach(ci => {
        if (!combinedItems.some(x => x.id === ci.id)) combinedItems.push(ci);
      });
    }

    if (mode === 'wall') {
      renderShowcaseStagingBoard(ws, parentObj, combinedItems);
      return;
    }
    if (mode === 'giant_wall') {
      renderGiantWallView(ws, parentType, parentObj, combinedItems);
      return;
    }
  }

  // Module 1: The "Giant Wall" (Milanote-Style Spatial Board with Nested Folders, Columns, Snap Grid & Inline Cards)
  if (mode === 'giant_wall') {
    renderGiantWallView(ws, parentType, parentObj, items);
    return;
  }

  if (mode === 'list') {
    ws.innerHTML = `<div class="visual-list-table" id="itemsListTable"></div>`;
    const table = ws.querySelector('#itemsListTable');
    items.forEach((it) => {
      const row = document.createElement('div');
      row.className = 'list-row-item';
      row.innerHTML = `
        <div class="list-thumb">${it.url && it.kind !== 'audio' ? `<img src="${escapeHtml(it.url)}" alt="">` : `<span class="kicker-mono">${escapeHtml(it.kind.toUpperCase())}</span>`}</div>
        <div>
          <div class="card-title" data-editable-title="1" title="Click to rename">${escapeHtml(it.title)}</div>
          <span class="kicker-mono">${escapeHtml(it.status || it.section || '')}</span>
        </div>
        <div class="card-desc">${escapeHtml(it.notes || it.link || '')}</div>
        <div class="card-tags-row">${(it.tags || []).slice(0, 2).map(t => `<span class="tag-chip">${escapeHtml(t)}</span>`).join('')}</div>
        <div class="card-footer-actions" style="justify-content:flex-end;">
          ${it.url ? `<a href="${escapeHtml(it.url)}" download class="outline-btn">↓ Original</a>` : ''}
          ${(it.parentType === 'space' && it.parentId === 'incubator') ? `<button type="button" class="text-act-btn btn-promote-proj" title="Promote to Studio Project">↗ Project</button>` : ''}
          <button type="button" class="text-act-btn btn-inspect">Inspect</button>
          <button type="button" class="text-act-btn danger btn-del">×</button>
        </div>
      `;
      row.querySelector('.list-thumb').addEventListener('click', () => {
        if (it.kind === 'folder') {
          state.activeFolderId = it.id;
          renderAll();
        } else {
          openItemInspector(it.id);
        }
      });
      row.querySelector('.card-title').addEventListener('click', (e) => {
        e.stopPropagation();
        promptInlineRename(e.currentTarget, it.title, (val) => {
          it.title = val;
          saveVault('RENAMED ITEM');
          renderWorkspace();
        });
      });
      row.querySelector('.btn-promote-proj')?.addEventListener('click', () => promoteIncubatorItemToProject(it.id));
      row.querySelector('.btn-inspect').addEventListener('click', () => openItemInspector(it.id));
      row.querySelector('.btn-del').addEventListener('click', () => requestDelete('item', it.id, it.title));
      table.appendChild(row);
    });
    return;
  }

  if (mode === 'kanban') {
    const cols = tabs.length > 1 ? tabs.slice(1) : ['All'];
    ws.innerHTML = `<div class="kanban-board" id="itemsKanban"></div>`;
    const kb = ws.querySelector('#itemsKanban');
    cols.forEach(secName => {
      const colItems = items.filter(i => {
        if (secName === 'All') return true;
        if (isInstagramSpace) return matchesInstagramCategory(i, secName, false);
        return i.section === secName;
      });
      const colEl = document.createElement('div');
      colEl.className = 'kanban-col';
      colEl.innerHTML = `
        <div class="kanban-col-header">
          <span class="kanban-col-title" data-editable-title="1" title="Click to rename column">${escapeHtml(secName)}</span>
          <span class="sidebar-count-pill">${colItems.length}</span>
        </div>
        <div class="kanban-cards" style="display:flex;flex-direction:column;gap:20px;"></div>
      `;
      colEl.querySelector('.kanban-col-title')?.addEventListener('click', (e) => {
        e.stopPropagation();
        promptInlineRename(e.currentTarget, secName, (val) => {
          const catIdx = tabs.indexOf(secName);
          if (catIdx !== -1) tabs[catIdx] = val;
          if (isInstagramSpace) {
            getInstagramAllItems().forEach(it => {
              if (it.section === secName) it.section = val;
            });
          } else {
            vault.items.forEach(it => {
              if (it.parentType === parentType && it.parentId === parentObj.id && it.section === secName) {
                it.section = val;
              }
            });
          }
          saveVault('RENAMED COLUMN');
          renderAll();
        });
      });
      const container = colEl.querySelector('.kanban-cards');
      colItems.forEach((it, idx) => container.appendChild(buildItemCardEl(it, idx)));
      kb.appendChild(colEl);
    });
    return;
  }

  ws.innerHTML = `<div class="cards-wall" id="itemsWallGrid"></div>`;
  const grid = ws.querySelector('#itemsWallGrid');
  items.forEach((it, idx) => {
    grid.appendChild(buildItemCardEl(it, idx));
  });
}

/* --------------------------------------------------------------------------
   INCUBATOR → STUDIO PROJECT PROMOTION BRIDGE
   -------------------------------------------------------------------------- */
function promoteIncubatorItemToProject(itemId) {
  const it = vault.items.find(x => x.id === itemId);
  if (!it) return;

  if (it.kind === 'folder') {
    const newProjId = 'proj_' + uid();
    const childItems = vault.items.filter(c => c.parentType === it.parentType && c.parentId === it.parentId && c.folderId === it.id);
    const firstVisual = childItems.find(c => c.url && c.kind !== 'audio');
    const projSpot = findNextOpenProjectClusterSpot();
    const newProj = {
      id: newProjId,
      title: it.title || 'Promoted Studio Project',
      category: '3D & Motion',
      status: 'Active',
      lifecycleState: 'active',
      summary: it.notes || `Promoted from Incubator (${childItems.length} items)`,
      coverUrl: firstVisual ? firstVisual.url : '',
      sections: ['All', 'WIP', 'References', 'Notes', 'Final'],
      tags: it.tags || [],
      boardX: projSpot.x,
      boardY: projSpot.y,
      boardW: 360,
      ui: { layoutMode: 'giant_wall', sortOrder: 'manual' },
      createdAt: Date.now()
    };
    vault.projects.unshift(newProj);
    childItems.forEach((c, idx) => {
      c.parentType = 'project';
      c.parentId = newProjId;
      delete c.folderId;
      c.wallX = 336 + (idx % 3) * 312;
      c.wallY = 144 + Math.floor(idx / 3) * 312;
    });
    vault.items = vault.items.filter(x => x.id !== it.id);
    saveVault(`PROMOTED "${newProj.title.toUpperCase()}" TO 01 STUDIO PROJECTS`);
    openProjectBoard(newProjId);
    return;
  }

  let modal = document.getElementById('promoteIncubatorModal');
  if (modal) modal.remove();

  modal = document.createElement('dialog');
  modal.id = 'promoteIncubatorModal';
  modal.className = 'modal-dialog';
  const projOptions = (vault.projects || []).map(p => `<option value="${escapeHtml(p.id)}">Move into: ${escapeHtml(p.title)}</option>`).join('');

  modal.innerHTML = `
    <div class="modal-card" style="max-width:460px;">
      <div class="modal-header">
        <div>
          <span class="kicker-mono">${it.parentId === 'projects' ? '01 STUDIO PROJECTS → PROJECT BOARD' : '02 INCUBATOR → 01 STUDIO PROJECTS'}</span>
          <h2>${it.parentId === 'projects' ? 'Move into Project Board' : 'Promote to Studio Project'}</h2>
        </div>
        <button type="button" class="icon-close-btn" id="btnClosePromoteModal">×</button>
      </div>
      <div style="display:flex;flex-direction:column;gap:14px;padding-top:8px;">
        <div style="font-size:12px;color:var(--text-mid);">
          Item: <strong style="color:var(--text);">${escapeHtml(it.title)}</strong>
        </div>
        <label class="form-field">
          <span>Action</span>
          <select id="promoteActionSelect">
            <option value="__new__">✦ Create a New Studio Project Board from this idea</option>
            ${projOptions}
          </select>
        </label>
        <label class="form-field" id="promoteNewTitleWrap">
          <span>New Project Title</span>
          <input type="text" id="promoteNewTitleInput" value="${escapeHtml(it.title || 'New Studio Project')}">
        </label>
        <div class="modal-footer" style="margin-top:6px;">
          <button type="button" class="ghost-btn" id="btnCancelPromoteModal">Cancel</button>
          <button type="button" class="primary-pill-btn" id="btnConfirmPromoteModal">Promote &amp; Open Board →</button>
        </div>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
  modal.showModal();

  const sel = modal.querySelector('#promoteActionSelect');
  const titleWrap = modal.querySelector('#promoteNewTitleWrap');
  sel?.addEventListener('change', () => {
    if (titleWrap) titleWrap.style.display = sel.value === '__new__' ? '' : 'none';
  });

  const close = () => {
    modal.close();
    modal.remove();
  };
  modal.querySelector('#btnClosePromoteModal')?.addEventListener('click', close);
  modal.querySelector('#btnCancelPromoteModal')?.addEventListener('click', close);
  modal.addEventListener('click', (e) => {
    if (e.target === modal) close();
  });

  modal.querySelector('#btnConfirmPromoteModal')?.addEventListener('click', () => {
    const targetVal = sel.value;
    let targetProjId = targetVal;
    if (targetVal === '__new__') {
      const newTitle = (modal.querySelector('#promoteNewTitleInput')?.value || it.title || 'New Studio Project').trim();
      targetProjId = 'proj_' + uid();
      const projSpot = findNextOpenProjectClusterSpot();
      vault.projects.unshift({
        id: targetProjId,
        title: newTitle,
        category: '3D & Motion',
        status: 'Active',
        lifecycleState: 'active',
        summary: it.notes || 'Promoted from 02 Incubator',
        coverUrl: (it.url && it.kind !== 'audio') ? it.url : '',
        sections: ['All', 'WIP', 'References', 'Notes', 'Final'],
        tags: it.tags || [],
        boardX: projSpot.x,
        boardY: projSpot.y,
        boardW: 360,
        ui: { layoutMode: 'giant_wall', sortOrder: 'manual' },
        createdAt: Date.now()
      });
    }
    it.parentType = 'project';
    it.parentId = targetProjId;
    delete it.folderId;
    it.wallX = 336;
    it.wallY = 144;
    close();
    saveVault('PROMOTED TO STUDIO PROJECT');
    openProjectBoard(targetProjId);
  });
}

/* --------------------------------------------------------------------------
   MODULE 1: THE "GIANT WALL" (Milanote-Style Spatial Board + Nested Folders)
   -------------------------------------------------------------------------- */
function renderGiantWallView(ws, parentType, parentObj, items) {
  const isProject = parentType === 'project';
  const isIncubator = parentType === 'space' && parentObj.id === 'incubator';
  const isDelivered = isProject && parentObj.lifecycleState === 'delivered';

  ws.innerHTML = `
    <div class="giant-wall-stage" id="giantWallStage">
      <div class="giant-wall-plane" id="giantWallPlane">
        <div class="wall-snap-preview" id="wallSnapPreview" hidden></div>
      </div>
      <div class="giant-wall-hud">
        <div class="giant-wall-hud-pill">
          <button type="button" id="btnToggleGridSnap" class="${state.snapToGrid !== false ? 'is-active' : ''}" title="Toggle 24px Magnetic Grid Snap">${state.snapToGrid !== false ? '⊞ Snap: ON' : '⊞ Snap: OFF'}</button>
          <button type="button" id="btnAutoArrangeWall" title="Tidy elements into clean 24px grid">⊞ Tidy</button>
          <button type="button" id="btnWallZoomOut" title="Zoom Out (Cmd -)">−</button>
          <button type="button" id="btnResetWallCamera" title="Reset zoom &amp; pan (Cmd 0)">100%</button>
          <button type="button" id="btnWallZoomIn" title="Zoom In (Cmd +)">+</button>
        </div>
      </div>
    </div>
  `;

  const stage = ws.querySelector('#giantWallStage');
  const plane = ws.querySelector('#giantWallPlane');
  if (!stage || !plane) return;

  ws.querySelector('#btnWallDeliverProj')?.addEventListener('click', () => {
    deliverProjectAndSpawnShowcase(parentObj.id);
  });

  bindSpatialStageCamera(stage, plane, () => {
    items.forEach((it, idx) => {
      const col = idx % 3;
      const row = Math.floor(idx / 3);
      it.wallX = 264 + col * 312;
      it.wallY = 108 + row * 312;
      it.wallW = it.wallW || 264;
    });
    saveVault('TIDIED BOARD TO GRID');
    renderWorkspace();
  });

  // Render each freeform pinned element on the Milanote Spatial Board
  items.forEach((it, idx) => {
    if (it.sphereId) return; // Enclosed inside a sphere container!
    if (it.kind === 'line') {
      const connEl = buildSpatialConnectorEl(it, false);
      plane.appendChild(connEl);
      return;
    }
    if (it.kind === 'sphere') {
      const sphereEl = buildSphereContainerEl(it);
      plane.appendChild(sphereEl);
      return;
    }
    const pin = buildSpatialPinEl(it, parentType, parentObj, idx);
    if (pin) plane.appendChild(pin);
  });
  if (state.batchSelectedIds && state.batchSelectedIds.size > 0) {
    renderBatchActionBar(stage, plane);
  }
}

/* --------------------------------------------------------------------------
   MODULE 3: POST-DELIVERY SHOWCASE & INSTAGRAM / WEBSITE STAGING BOARD
   -------------------------------------------------------------------------- */
function renderShowcaseStagingBoard(ws, spaceObj, spaceItems) {
  vault.showcaseRollouts = vault.showcaseRollouts || [];
  const isWebsiteSpace = spaceObj.id === 'website';

  const stageFilter = state.igStatusFilter || 'all';
  const filteredSpaceItems = spaceItems.filter(it => {
    if (stageFilter === 'all') return true;
    return it.igStatus === stageFilter;
  });

  // Show rollouts relevant to this staging channel
  const visibleRollouts = vault.showcaseRollouts.filter(r => {
    if (r.channel && r.channel !== spaceObj.id) return false;
    if (!isWebsiteSpace) {
      if (state.activeFolderId) return false;
      const rStat = r.igStatus || ((r.promoStatus || '').toLowerCase().includes('live') ? 'published' : 'queued');
      if (stageFilter !== 'all' && rStat !== stageFilter) return false;
      if (state.activeCategory === 'IG Ready' && rStat !== 'queued') return false;
      if (state.activeCategory === 'IG Live' && rStat !== 'published') return false;
      if (state.searchQuery) {
        const q = state.searchQuery.toLowerCase();
        const hay = `${r.title || ''} ${r.projectTitle || ''} ${r.captionDraft || ''} ${r.promoStatus || ''}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
    }
    return true;
  });

  const rolloutsHtml = visibleRollouts.map(r => {
    const proj = vault.projects.find(p => p.id === r.projectId);
    let pVisuals;
    if (!isWebsiteSpace && Array.isArray(r.slideItemIds) && r.slideItemIds.length > 0) {
      pVisuals = r.slideItemIds
        .map(id => vault.items.find(i => i.id === id && i.url && i.kind !== 'audio'))
        .filter(Boolean);
    } else if (!isWebsiteSpace && Array.isArray(r.carouselItemIds) && r.carouselItemIds.length > 0) {
      pVisuals = r.carouselItemIds
        .map(id => vault.items.find(i => i.id === id && i.url && i.kind !== 'audio'))
        .filter(Boolean);
    } else {
      pVisuals = vault.items.filter(i => i.parentType === 'project' && i.parentId === r.projectId && i.url && i.kind !== 'audio');
    }
    const feedCells = pVisuals.slice(0, 9).map(v => `
      <div class="ig-feed-sim-cell" data-item-id="${escapeHtml(v.id)}" title="${escapeHtml(v.title)}">
        <img src="${escapeHtml(v.url)}" alt="">
      </div>
    `).join('');

    const carouselHtml = pVisuals.slice(0, 6).map((v, sIdx) => `
      <div class="carousel-slide-chip" data-item-id="${escapeHtml(v.id)}" style="${isWebsiteSpace ? 'width:118px;aspect-ratio:16/10;' : ''}">
        <img src="${escapeHtml(v.url)}" alt="">
        <span class="slide-num">${isWebsiteSpace ? `HERO 0${sIdx + 1}` : `SLIDE 0${sIdx + 1}`}</span>
      </div>
    `).join('');

    const rightPreviewHtml = isWebsiteSpace ? `
      <div style="border:1px solid var(--border);border-radius:8px;overflow:hidden;background:var(--bg);padding:8px;display:flex;flex-direction:column;gap:6px;">
        <div class="kicker-mono" style="font-size:9px;display:flex;justify-content:space-between;">
          <span>🌐 CASE STUDY PREVIEW</span>
          <span>16:10 WEB</span>
        </div>
        ${pVisuals[0] ? `<img src="${escapeHtml(pVisuals[0].url)}" alt="" style="width:100%;aspect-ratio:16/10;object-fit:cover;border-radius:4px;">` : ''}
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:4px;">
          ${pVisuals.slice(1, 4).map(v => `<img src="${escapeHtml(v.url)}" alt="" style="width:100%;aspect-ratio:16/10;object-fit:cover;border-radius:3px;">`).join('')}
        </div>
      </div>
    ` : `<div class="ig-feed-sim-grid">${feedCells}</div>`;

    return `
      <article class="showcase-rollout-card" data-rollout-id="${escapeHtml(r.id)}">
        <div class="showcase-rollout-header">
          <h3 class="rollout-title-el" data-editable-title="1" data-rollout-id="${escapeHtml(r.id)}" title="Click to rename rollout" style="font-family:var(--font-heading);font-size:14px;font-weight:600;margin:0;cursor:text;">${escapeHtml(r.title || r.projectTitle || 'Showcase Rollout')}</h3>
          <div style="display:flex;gap:10px;align-items:center;">
            ${isWebsiteSpace
              ? `<span class="kicker-mono">${escapeHtml(r.websiteLayout || '🌐 Portfolio Case Study')}</span>`
              : `<span class="kicker-mono btn-toggle-rollout-status" data-rollout-id="${escapeHtml(r.id)}" title="Click to toggle IG Staged / IG Live" style="cursor:pointer;">${escapeHtml(r.promoStatus || '◈ IG Carousel Staged')}</span>`
            }
            ${!isWebsiteSpace ? `<button type="button" class="quiet-action-link btn-manage-rollout-slides" data-rollout-id="${escapeHtml(r.id)}" title="Choose carousel slides for this rollout">Slides (${pVisuals.length})</button>` : ''}
            ${proj ? `<button type="button" class="quiet-action-link btn-open-source-proj" data-proj-id="${escapeHtml(proj.id)}">Source Board →</button>` : ''}
            <button type="button" class="hover-act-btn danger btn-del-rollout" data-rollout-id="${escapeHtml(r.id)}" style="opacity:1;" title="Remove rollout card">×</button>
          </div>
        </div>
        <div class="showcase-rollout-body">
          <div>
            <div class="carousel-sequence-strip">${carouselHtml || '<span class="kicker-mono">Click Slides above or tag visuals with ◈ Ready to populate</span>'}</div>
            <textarea class="pitch-scratchpad rollout-caption-in" style="margin-top:10px;" data-rollout-id="${escapeHtml(r.id)}" data-field="${isWebsiteSpace ? 'caseStudyNotes' : 'captionDraft'}" placeholder="${isWebsiteSpace ? 'Case study text, project credits, embed links...' : 'Instagram caption, @mentions, hashtags, release notes...'}">${escapeHtml(isWebsiteSpace ? (r.caseStudyNotes || r.captionDraft || '') : (r.captionDraft || ''))}</textarea>
          </div>
          <div>
            ${rightPreviewHtml}
          </div>
        </div>
      </article>
    `;
  }).join('');

  ws.innerHTML = `
    <div class="showcase-staging-shell">
      <div class="minimal-inline-subbar" style="justify-content:space-between;flex-wrap:wrap;gap:12px;">
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
          <span class="kicker-mono">${isWebsiteSpace ? '🌐 WEBSITE &amp; PORTFOLIO STAGING' : '◈ INSTAGRAM FEED &amp; REELS PIPELINE'}</span>
          <span class="quiet-sep">·</span>
          <span class="kicker-mono" style="color:var(--text-mid);">${filteredSpaceItems.length} ${filteredSpaceItems.length === 1 ? 'item' : 'items'}</span>
        </div>
        <div style="display:flex;align-items:center;gap:8px;">
          ${!isWebsiteSpace ? `<button type="button" class="quiet-action-link" id="btnAddIgRollout">+ New Rollout Post</button>` : ''}
          <button type="button" class="quiet-action-link" id="btnAddStagedVisual">+ Stage from Projects / Upload</button>
          <button type="button" class="quiet-action-link" id="btnSwitchShowcaseToWall">✥ Freeform Canvas</button>
        </div>
      </div>

      ${rolloutsHtml ? `<div class="showcase-rollouts-grid">${rolloutsHtml}</div>` : ''}

      <div class="cards-wall" id="showcaseItemsWall"></div>
    </div>
  `;

  ws.querySelector('#btnAddIgRollout')?.addEventListener('click', () => {
    vault.showcaseRollouts = vault.showcaseRollouts || [];
    const stagedVisuals = getInstagramAllItems().filter(i => i.url && i.kind !== 'audio');
    const newRollout = {
      id: 'roll_' + Date.now() + '_ig',
      channel: 'instagram',
      projectId: '',
      projectTitle: '',
      title: 'Instagram Rollout — New Post',
      promoStatus: '◈ IG Carousel Staged',
      igStatus: 'queued',
      slideItemIds: stagedVisuals.slice(0, 6).map(i => i.id),
      captionDraft: 'New post draft —\n\n#3D #MotionDesign #DigitalArt',
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
    vault.showcaseRollouts.unshift(newRollout);
    saveVault('CREATED IG ROLLOUT');
    renderWorkspace();
  });

  ws.querySelector('#btnAddStagedVisual')?.addEventListener('click', () => openStageFromProjectsDialog(spaceObj.id));
  ws.querySelector('#btnSwitchShowcaseToWall')?.addEventListener('click', () => {
    spaceObj.ui = spaceObj.ui || {};
    spaceObj.ui.layoutMode = 'giant_wall';
    saveVault();
    renderAll();
  });

  ws.querySelectorAll('.btn-toggle-rollout-status').forEach(badge => {
    badge.addEventListener('click', (e) => {
      e.stopPropagation();
      const r = vault.showcaseRollouts.find(x => x.id === badge.dataset.rolloutId);
      if (!r) return;
      const curLive = r.igStatus === 'published' || (r.promoStatus || '').toLowerCase().includes('live');
      if (curLive) {
        r.igStatus = 'queued';
        r.promoStatus = '◈ IG Carousel Staged';
      } else {
        r.igStatus = 'published';
        r.promoStatus = '● IG Live';
      }
      r.updatedAt = Date.now();
      saveVault('UPDATED ROLLOUT STATUS');
      renderWorkspace();
    });
  });

  ws.querySelectorAll('.btn-manage-rollout-slides').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      openRolloutSlidesPickerDialog(btn.dataset.rolloutId);
    });
  });

  ws.querySelectorAll('.btn-del-rollout').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!isWebsiteSpace) {
        const r = (vault.showcaseRollouts || []).find(x => x.id === btn.dataset.rolloutId);
        requestDelete('showcase_rollout', btn.dataset.rolloutId, r?.title || r?.projectTitle || 'Showcase Rollout');
        return;
      }
      vault.showcaseRollouts = (vault.showcaseRollouts || []).filter(x => x.id !== btn.dataset.rolloutId);
      saveVault('REMOVED SHOWCASE ROLLOUT');
      renderWorkspace();
    });
  });

  ws.querySelectorAll('.rollout-title-el').forEach(el => {
    el.addEventListener('click', (e) => {
      e.stopPropagation();
      const r = vault.showcaseRollouts.find(x => x.id === el.dataset.rolloutId);
      if (!r) return;
      promptInlineRename(el, r.title || 'Showcase Rollout', (val) => {
        r.title = val;
        saveVault('RENAMED ROLLOUT');
        renderWorkspace();
      });
    });
  });

  ws.querySelectorAll('.btn-open-source-proj').forEach(btn => {
    btn.addEventListener('click', () => openProjectBoard(btn.dataset.projId));
  });

  ws.querySelectorAll('.rollout-caption-in').forEach(area => {
    let capTimer = null;
    const persistCap = () => {
      const r = vault.showcaseRollouts.find(x => x.id === area.dataset.rolloutId);
      if (r) {
        const field = area.dataset.field || 'captionDraft';
        r[field] = area.value;
        r.updatedAt = Date.now();
        saveVault('SAVED');
      }
    };
    area.addEventListener('change', persistCap);
    area.addEventListener('input', () => {
      clearTimeout(capTimer);
      capTimer = setTimeout(persistCap, 350);
    });
  });

  ws.querySelectorAll('.ig-feed-sim-cell, .carousel-slide-chip').forEach(el => {
    el.addEventListener('click', () => {
      if (el.dataset.itemId) openItemInspector(el.dataset.itemId);
    });
  });

  const grid = ws.querySelector('#showcaseItemsWall');
  filteredSpaceItems.forEach((it, idx) => {
    grid?.appendChild(buildItemCardEl(it, idx));
  });
}

function openRolloutSlidesPickerDialog(rolloutId) {
  const r = (vault.showcaseRollouts || []).find(x => x.id === rolloutId);
  if (!r) return;

  let dlg = document.getElementById('rolloutSlidesPickerDialog');
  if (!dlg) {
    dlg = document.createElement('dialog');
    dlg.id = 'rolloutSlidesPickerDialog';
    dlg.className = 'inspector-dialog';
    dlg.setAttribute('closedby', 'any');
    document.body.appendChild(dlg);
  }

  if (!Array.isArray(r.slideItemIds)) {
    if (Array.isArray(r.carouselItemIds) && r.carouselItemIds.length) {
      r.slideItemIds = [...r.carouselItemIds];
    } else if (r.projectId) {
      r.slideItemIds = vault.items
        .filter(i => i.parentType === 'project' && i.parentId === r.projectId && i.url && i.kind !== 'audio')
        .slice(0, 9)
        .map(i => i.id);
    } else {
      r.slideItemIds = [];
    }
  }

  const candidateVisuals = vault.items.filter(i => {
    if (!i.url || i.kind === 'audio' || i.kind === 'folder') return false;
    if (i.parentType === 'space' && i.parentId === 'instagram') return true;
    if (i.parentType === 'project') return true;
    if (i.parentType === 'space' && i.parentId === 'incubator') return true;
    return false;
  });

  dlg.innerHTML = `
    <div class="sheet-card" style="max-width:720px;width:92vw;">
      <div class="sheet-header">
        <span class="kicker-mono">◈ SELECT SLIDES FOR: ${escapeHtml(r.title || 'INSTAGRAM ROLLOUT')}</span>
        <button type="button" class="icon-btn" id="btnCloseRolloutSlidesPicker">✕</button>
      </div>
      <div class="sheet-body" style="display:flex;flex-direction:column;gap:14px;max-height:70vh;overflow-y:auto;">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding-bottom:10px;border-bottom:1px solid var(--border);">
          <span style="font-size:12.5px;color:var(--text-mid);">Click any visual below to add or remove it from this rollout's carousel &amp; 3×3 grid preview (${r.slideItemIds.length} selected):</span>
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(148px,1fr));gap:12px;">
          ${candidateVisuals.map(v => {
            const p = v.parentType === 'project' ? vault.projects.find(x => x.id === v.parentId) : null;
            const sourceLabel = p ? p.title : (v.parentId === 'incubator' ? '02 Incubator' : '03 Instagram');
            const slideIdx = r.slideItemIds.indexOf(v.id);
            const active = slideIdx !== -1;
            return `
              <div class="rollout-slide-picker-item" data-vid="${escapeHtml(v.id)}" style="border:2px solid ${active ? 'var(--accent)' : 'var(--border)'};border-radius:8px;overflow:hidden;cursor:pointer;background:var(--bg-surface);">
                <div style="height:104px;background:#141312;position:relative;">
                  <img src="${escapeHtml(v.url)}" alt="" style="width:100%;height:100%;object-fit:cover;">
                  <span style="position:absolute;top:6px;right:6px;font-size:10px;padding:2px 6px;border-radius:4px;background:${active ? 'var(--accent)' : 'rgba(20,19,18,0.75)'};color:#FFF;font-family:var(--font-mono);">${active ? `SLIDE 0${slideIdx + 1}` : '+ Slide'}</span>
                </div>
                <div style="padding:7px 8px;">
                  <div style="font-size:11.5px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(v.title)}</div>
                  <div class="kicker-mono" style="font-size:9.5px;color:var(--text-mid);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(sourceLabel)}</div>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    </div>
  `;

  dlg.querySelector('#btnCloseRolloutSlidesPicker')?.addEventListener('click', () => dlg.close());
  dlg.querySelectorAll('.rollout-slide-picker-item').forEach(card => {
    card.addEventListener('click', () => {
      const vid = card.dataset.vid;
      const idx = r.slideItemIds.indexOf(vid);
      if (idx !== -1) {
        r.slideItemIds.splice(idx, 1);
      } else {
        r.slideItemIds.push(vid);
      }
      r.carouselItemIds = [...r.slideItemIds];
      r.updatedAt = Date.now();
      saveVault('UPDATED ROLLOUT SLIDES');
      renderWorkspace();
      openRolloutSlidesPickerDialog(rolloutId);
    });
  });

  if (!dlg.open) dlg.showModal();
}

function openStageFromProjectsDialog(targetSpaceId) {
  let dlg = document.getElementById('stageFromProjectsDialog');
  if (!dlg) {
    dlg = document.createElement('dialog');
    dlg.id = 'stageFromProjectsDialog';
    dlg.className = 'inspector-dialog';
    dlg.setAttribute('closedby', 'any');
    document.body.appendChild(dlg);
  }
  const isWeb = targetSpaceId === 'website';
  const targetBadge = isWeb ? 'website' : 'queued';
  const projectVisuals = vault.items.filter(i => {
    if (!i.url || i.kind === 'audio' || i.kind === 'folder') return false;
    if (i.parentType === 'project') return true;
    if (!isWeb && i.parentType === 'space' && i.parentId === 'incubator') return true;
    return false;
  });

  dlg.innerHTML = `
    <div class="sheet-card" style="max-width:720px;width:92vw;">
      <div class="sheet-header">
        <span class="kicker-mono">${isWeb ? '🌐 STAGE VISUAL TO WEBSITE & PORTFOLIO' : '◈ STAGE VISUAL TO INSTAGRAM PIPELINE'}</span>
        <button type="button" class="icon-btn" id="btnCloseStagePicker">✕</button>
      </div>
      <div class="sheet-body" style="display:flex;flex-direction:column;gap:14px;max-height:70vh;overflow-y:auto;">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding-bottom:10px;border-bottom:1px solid var(--border);">
          <span style="font-size:12.5px;color:var(--text-mid);">Click any artwork from your ${isWeb ? 'Studio Projects' : 'Studio Projects or Incubator'} below to toggle it onto <strong>${isWeb ? '04 Website & Portfolio' : '03 Instagram'}</strong>, or upload a new file directly:</span>
          <button type="button" class="primary-btn" id="btnStageUploadNew">+ Upload File</button>
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(148px,1fr));gap:12px;">
          ${projectVisuals.map(v => {
            const p = v.parentType === 'project' ? vault.projects.find(x => x.id === v.parentId) : null;
            const sourceLabel = p ? p.title : (v.parentId === 'incubator' ? '02 Incubator' : 'Project');
            const active = v.igStatus === targetBadge || ( !isWeb && v.igStatus === 'published' );
            return `
              <div class="stage-picker-item" data-vid="${escapeHtml(v.id)}" style="border:2px solid ${active ? 'var(--accent)' : 'var(--border)'};border-radius:8px;overflow:hidden;cursor:pointer;background:var(--bg-surface);">
                <div style="height:104px;background:#141312;position:relative;">
                  <img src="${escapeHtml(v.url)}" alt="" style="width:100%;height:100%;object-fit:cover;">
                  <span style="position:absolute;top:6px;right:6px;font-size:10px;padding:2px 6px;border-radius:4px;background:${active ? 'var(--accent)' : 'rgba(20,19,18,0.75)'};color:#FFF;font-family:var(--font-mono);">${active ? '✓ Staged' : '+ Stage'}</span>
                </div>
                <div style="padding:7px 8px;">
                  <div style="font-size:11.5px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(v.title)}</div>
                  <div class="kicker-mono" style="font-size:9.5px;color:var(--text-mid);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(sourceLabel)}</div>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    </div>
  `;

  dlg.querySelector('#btnCloseStagePicker')?.addEventListener('click', () => dlg.close());
  dlg.querySelector('#btnStageUploadNew')?.addEventListener('click', () => {
    dlg.close();
    document.getElementById('globalFileInput')?.click();
  });
  dlg.querySelectorAll('.stage-picker-item').forEach(card => {
    card.addEventListener('click', () => {
      const it = vault.items.find(x => x.id === card.dataset.vid);
      if (!it) return;
      if (!isWeb) {
        it.igStatus = (it.igStatus === 'queued' || it.igStatus === 'published') ? '' : 'queued';
      } else {
        it.igStatus = (it.igStatus === targetBadge) ? '' : targetBadge;
      }
      saveVault(it.igStatus ? `STAGED TO ${isWeb ? 'WEBSITE' : 'INSTAGRAM'}` : 'UNSTAGED ITEM');
      renderAll();
      openStageFromProjectsDialog(targetSpaceId);
    });
  });

  if (!dlg.open) dlg.showModal();
}

function buildItemCardEl(it, idx) {
  const numStr = '#' + String(idx + 1).padStart(2, '0');
  const card = document.createElement('article');
  card.className = 'studio-card';
  card.draggable = true;
  card.dataset.id = it.id;

  const isFolder = it.kind === 'folder';
  const isIncubatorItem = it.parentType === 'space' && (it.parentId === 'incubator' || it.parentId === 'projects');
  const sourceProj = it.parentType === 'project' ? (vault.projects || []).find(p => p.id === it.parentId) : null;
  const hasChecklist = (it.notes || '').includes('[ ]') || (it.notes || '').includes('[x]') || (it.notes || '').includes('[X]');
  const prioAttr = idx === 0 ? 'fetchpriority="high"' : 'loading="lazy" decoding="async"';

  let stageHtml = '';
  if (isFolder) {
    const childItems = (state.viewType === 'space' && state.activeSpaceId === 'instagram')
      ? vault.items.filter(c => c.folderId === it.id)
      : vault.items.filter(c => c.parentType === it.parentType && c.parentId === it.parentId && c.folderId === it.id);
    const childVisuals = childItems.filter(c => c.url && c.kind !== 'audio').slice(0, 4);
    stageHtml = `
      <div class="stage-note-pad" style="display:grid;grid-template-columns:repeat(2,1fr);gap:6px;padding:12px;">
        ${childVisuals.length ? childVisuals.map(v => `<img src="${escapeHtml(v.url)}" alt="" style="width:100%;height:74px;object-fit:cover;border-radius:6px;">`).join('') : `
          <div style="grid-column:1/-1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:18px;color:var(--text-mid);">
            <span class="kicker-mono">📂 SUB-FOLDER (${childItems.length} ITEMS)</span>
            <span style="font-size:11.5px;">Click card to open folder</span>
          </div>
        `}
      </div>
    `;
  } else if (it.kind === 'video' && it.url) {
    stageHtml = `<video src="${escapeHtml(it.url)}#t=0.1" preload="metadata" muted playsinline></video>`;
  } else if (it.url && it.kind !== 'audio') {
    stageHtml = `<img src="${escapeHtml(it.url)}" alt="${escapeHtml(it.title)}" ${prioAttr}>`;
  } else if (it.kind === 'audio' && it.url) {
    stageHtml = `
      <div class="stage-note-pad" style="display:flex;flex-direction:column;justify-content:center;align-items:center;gap:12px;text-align:center;">
        <div class="kicker-mono" style="color:var(--accent);">🔊 ORIGINAL STUDIO AUDIO (WAV / MP3)</div>
        <audio src="${escapeHtml(it.url)}" controls style="width:90%;max-width:280px;"></audio>
        <div class="typewriter" style="font-size:11.5px;color:var(--text-mid);">${escapeHtml(it.notes || '')}</div>
      </div>
    `;
  } else if (hasChecklist) {
    stageHtml = `<div class="stage-note-pad"><div class="checklist-box" data-item-id="${escapeHtml(it.id)}">${renderChecklistHtml(it.notes)}</div></div>`;
  } else if (it.kind === 'column') {
    const colChildren = (state.viewType === 'space' && state.activeSpaceId === 'instagram')
      ? vault.items.filter(c => c.columnId === it.id)
      : vault.items.filter(c => c.parentType === it.parentType && c.parentId === it.parentId && c.columnId === it.id);
    stageHtml = `
      <div class="stage-note-pad" style="display:flex;flex-direction:column;gap:6px;padding:12px;">
        <div class="kicker-mono" style="color:var(--accent);">▤ COLUMN STACK (${colChildren.length} CARDS)</div>
        ${colChildren.slice(0, 3).map(c => `<div style="font-size:11.5px;padding:4px 8px;border:1px solid var(--border);border-radius:4px;background:var(--bg-surface);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(c.title)}</div>`).join('') || `<div style="font-size:11.5px;color:var(--text-mid);">Empty column</div>`}
      </div>
    `;
  } else if (it.kind === 'heading') {
    stageHtml = `
      <div class="stage-note-pad" style="display:flex;flex-direction:column;justify-content:center;gap:4px;">
        <div class="kicker-mono" style="color:var(--text-mid);">SECTION HEADING</div>
        <div style="font-size:18px;font-weight:700;letter-spacing:-0.02em;color:var(--text);">${escapeHtml(it.title || 'Section Heading')}</div>
      </div>
    `;
  } else if (it.kind === 'color') {
    const hex = /^#[0-9A-Fa-f]{3,8}$/.test((it.notes || '').trim()) ? it.notes.trim() : '#FF3B24';
    stageHtml = `
      <div class="stage-note-pad" style="display:flex;align-items:center;gap:14px;padding:16px;">
        <div style="width:56px;height:56px;border-radius:10px;background:${escapeHtml(hex)};border:1px solid var(--border);flex-shrink:0;"></div>
        <div style="display:flex;flex-direction:column;gap:2px;">
          <div class="kicker-mono" style="font-size:13px;font-weight:700;color:var(--text);">${escapeHtml(hex.toUpperCase())}</div>
          <div style="font-size:12px;color:var(--text-mid);">${escapeHtml(it.title || 'Swatch')}</div>
        </div>
      </div>
    `;
  } else if (it.kind === 'sketch') {
    stageHtml = (it.sketchData && it.sketchData.startsWith('data:image/'))
      ? `<img src="${escapeHtml(it.sketchData)}" alt="${escapeHtml(it.title || 'Sketch')}" style="background:#FAF8F5;object-fit:contain;">`
      : `<div class="stage-note-pad" style="display:flex;align-items:center;justify-content:center;color:var(--text-mid);"><span class="kicker-mono">✎ SKETCH PAD</span></div>`;
  } else if (it.kind === 'table') {
    const rows = (it.notes || 'Column A | Column B\nValue 1 | Value 2').split('\n').map(r => r.split('|').map(c => c.trim()));
    stageHtml = `
      <div class="stage-note-pad" style="padding:10px;overflow:auto;">
        <table class="mn-inline-table" style="width:100%;font-size:11px;">
          ${rows.map((r, rIdx) => `<tr>${r.map(c => `<${rIdx === 0 ? 'th' : 'td'}>${escapeHtml(c)}</${rIdx === 0 ? 'th' : 'td'}>`).join('')}</tr>`).join('')}
        </table>
      </div>
    `;
  } else if (it.kind === 'line') {
    stageHtml = `
      <div class="stage-note-pad" style="display:flex;align-items:center;justify-content:center;gap:10px;">
        <span class="kicker-mono">───► ${escapeHtml(it.title || 'Connector')}</span>
      </div>
    `;
  } else if (it.kind === 'link' || (it.link && !it.notes)) {
    stageHtml = `
      <div class="stage-note-pad" style="display:flex;flex-direction:column;justify-content:center;gap:8px;">
        <div class="kicker-mono">${it.link.startsWith('~') || it.link.startsWith('/') ? '📁 LOCAL MAC PATH' : '🌐 WEB REFERENCE LINK'}</div>
        <div class="typewriter" style="font-size:13px;word-break:break-all;color:var(--accent);">${escapeHtml(it.link)}</div>
        <div class="typewriter" style="font-size:11.5px;color:var(--text-mid);">${escapeHtml(it.notes || '')}</div>
      </div>
    `;
  } else {
    stageHtml = `<div class="stage-note-pad">${escapeHtml(it.notes || it.title)}</div>`;
  }

  const tagsHtml = (it.tags || []).map(t => `<span class="tag-chip">${escapeHtml(t)}</span>`).join('');
  const isVisualAsset = Boolean(it.url && it.kind !== 'audio' && !isFolder);
  const isCmpSel = isAssetCompareSelected(it.id);
  const igStat = it.igStatus || '';

  const igBadgeCardHtml = igStat === 'published'
    ? `<span class="ig-status-badge is-published" title="Published (IG Live) — Click to cycle">● IG LIVE</span>`
    : (igStat === 'queued'
        ? `<span class="ig-status-badge is-queued" title="Queued (IG Ready / Next Up) — Click to cycle">◈ IG READY</span>`
        : (igStat === 'website'
            ? `<span class="ig-status-badge" style="background:rgba(59,130,246,0.92);color:#FFF;" title="On Portfolio Website — Click to cycle">🌐 ON SITE</span>`
            : ''));

  const cardControlsHtml = isVisualAsset ? `
    <button type="button" class="asset-select-check ${isCmpSel ? 'is-selected' : ''}" title="Select to Compare (1:1 Layer Stack / Split View)">✓</button>
    <button type="button" class="node-ig-quick-btn ${igStat === 'published' ? 'is-published' : (igStat === 'queued' ? 'is-queued' : '')}" title="1-Click Toggle Status (WIP → ◈ IG Ready → ● IG Live → 🌐 Website)">${igStat === 'published' ? '●' : (igStat === 'website' ? '🌐' : '◈')}</button>
    ${igBadgeCardHtml}
  ` : igBadgeCardHtml;

  if (isCmpSel) card.classList.add('is-compare-selected');

  card.innerHTML = `
    <div class="card-stage">
      ${stageHtml}
      ${cardControlsHtml}
    </div>
    <div class="card-body">
      <div class="card-meta-kicker-row">
        <div class="card-inline-meta">
          <span class="meta-index">${numStr}</span>
          <span class="meta-sep">·</span>
          <span class="meta-status">${escapeHtml(it.status || it.kind.toUpperCase())}</span>
          <span class="meta-sep">·</span>
          <span class="meta-count">${escapeHtml(sourceProj ? sourceProj.title : (it.section || 'Vault'))}</span>
        </div>
        <div class="card-hover-toolbar">
          ${isFolder ? `<button type="button" class="hover-act-btn primary-act btn-open-folder-card">Open →</button>` : `<button type="button" class="hover-act-btn primary-act btn-inspect">Inspect</button>`}
          ${isIncubatorItem ? `<button type="button" class="hover-act-btn btn-promote-to-proj" title="Promote to 01 Studio Project">↗ Project</button>` : ''}
          ${(sourceProj && state.viewType === 'space') ? `<button type="button" class="hover-act-btn btn-jump-source-proj" title="Open Source Project Board">Board ↗</button>` : ''}
          ${it.url ? `<a href="${escapeHtml(it.url)}" download class="hover-act-btn" title="Download uncompressed original">↓ Orig</a>` : ''}
          ${it.link ? `<button type="button" class="hover-act-btn btn-open-link" title="${escapeHtml(it.link)}">${it.link.startsWith('~') || it.link.startsWith('/') ? 'Finder ↗' : 'Link ↗'}</button>` : ''}
          <button type="button" class="hover-act-btn btn-up" title="Move earlier">↑</button>
          <button type="button" class="hover-act-btn btn-down" title="Move later">↓</button>
          <button type="button" class="hover-act-btn danger btn-del-item" title="Delete item">×</button>
        </div>
      </div>
      <div class="card-title-row">
        <h3 class="card-title" data-editable-title="1" title="Click to rename">${escapeHtml(it.title)}</h3>
      </div>
      ${(it.url && it.notes && it.kind !== 'audio') ? `<p class="card-desc">${escapeHtml(it.notes)}</p>` : ''}
      <div class="card-tags-row">${tagsHtml}</div>
    </div>
  `;

  // Hover Spacebar Quick-Look support
  card.addEventListener('mouseenter', () => {
    if (isVisualAsset) {
      state.hoveredAssetForQuickLook = {
        id: it.id,
        title: it.title,
        category: it.section || 'Studio Asset',
        kind: it.kind || 'image',
        thumbSrc: it.url,
        sizeLabel: it.status || ''
      };
    }
  });
  card.addEventListener('mouseleave', () => {
    if (state.hoveredAssetForQuickLook && state.hoveredAssetForQuickLook.id === it.id) {
      state.hoveredAssetForQuickLook = null;
    }
  });

  // Interactive Checkboxes right on the card stage!
  card.querySelectorAll('.chk-row input[type="checkbox"]').forEach(chk => {
    chk.addEventListener('click', (e) => {
      e.stopPropagation();
      const lineIdx = parseInt(chk.dataset.line, 10);
      toggleChecklistLine(it.id, lineIdx);
    });
  });
  card.querySelectorAll('.btn-del-chk-line').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      e.preventDefault();
      deleteChecklistLine(it.id, parseInt(btn.dataset.delLine, 10));
    });
  });

  // Open Inspector or Folder when clicking stage
  card.querySelector('.card-stage').addEventListener('click', (e) => {
    if (e.target.closest('audio') || e.target.closest('.chk-row') || e.target.closest('.asset-select-check') || e.target.closest('.node-ig-quick-btn') || e.target.closest('.ig-status-badge')) return;
    if (isFolder) {
      state.activeFolderId = it.id;
      renderAll();
    } else {
      openItemInspector(it.id);
    }
  });
  card.querySelector('.btn-open-folder-card')?.addEventListener('click', (e) => {
    e.stopPropagation();
    state.activeFolderId = it.id;
    renderAll();
  });
  card.querySelector('.btn-promote-to-proj')?.addEventListener('click', (e) => {
    e.stopPropagation();
    promoteIncubatorItemToProject(it.id);
  });
  card.querySelector('.btn-jump-source-proj')?.addEventListener('click', (e) => {
    e.stopPropagation();
    if (sourceProj) openProjectBoard(sourceProj.id);
  });
  card.querySelector('.asset-select-check')?.addEventListener('click', (e) => {
    e.stopPropagation();
    toggleCompareSelect({
      id: it.id,
      title: it.title || 'Visual',
      url: it.url,
      kind: it.kind || 'image',
      igStatus: it.igStatus || '',
      vaultItemId: it.id,
      notes: it.notes || ''
    });
  });
  card.querySelector('.node-ig-quick-btn')?.addEventListener('click', (e) => {
    e.stopPropagation();
    cycleItemIgStatus(it.id);
  });
  card.querySelector('.ig-status-badge')?.addEventListener('click', (e) => {
    e.stopPropagation();
    cycleItemIgStatus(it.id);
  });
  card.querySelector('.card-title').addEventListener('click', (e) => {
    e.stopPropagation();
    promptInlineRename(e.currentTarget, it.title, (val) => {
      it.title = val;
      saveVault('RENAMED ITEM');
      renderWorkspace();
    });
  });
  card.querySelector('.btn-inspect')?.addEventListener('click', () => openItemInspector(it.id));
  card.querySelector('.btn-del-item').addEventListener('click', () => requestDelete('item', it.id, it.title));

  const openLinkBtn = card.querySelector('.btn-open-link');
  if (openLinkBtn) {
    openLinkBtn.addEventListener('click', () => openUrlOrMacPath(it.link));
  }

  // Manual arrow ordering
  card.querySelector('.btn-up').addEventListener('click', () => moveItemOrder(it.id, -1));
  card.querySelector('.btn-down').addEventListener('click', () => moveItemOrder(it.id, 1));

  // Drag & drop reorder
  card.addEventListener('dragstart', () => {
    state.draggedId = it.id;
    state.draggedKind = 'item';
    card.classList.add('dragging');
  });
  card.addEventListener('dragend', () => card.classList.remove('dragging'));
  card.addEventListener('dragover', (e) => e.preventDefault());
  card.addEventListener('drop', (e) => {
    e.preventDefault();
    if (state.draggedKind === 'item' && state.draggedId && state.draggedId !== it.id) {
      if (state.viewType === 'space' && state.activeSpaceId === 'instagram') {
        const igSpace = vault.spaces.find(s => s.id === 'instagram');
        if (igSpace) {
          igSpace.ui = igSpace.ui || {};
          igSpace.ui.sortOrder = 'manual';
          const sortSelect = document.getElementById('sortSelect');
          if (sortSelect) sortSelect.value = 'manual';
        }
      }
      reorderArrayById(vault.items, state.draggedId, it.id);
      saveVault();
      renderWorkspace();
    }
  });

  card.querySelector('.card-body')?.addEventListener('click', (e) => {
    if (e.target.closest('button') || e.target.closest('a') || e.target.closest('[data-editable-title]')) return;
    if (isFolder) {
      state.activeFolderId = it.id;
      renderAll();
    } else {
      openItemInspector(it.id);
    }
  });

  return card;
}

function renderChecklistHtml(text) {
  const lines = (text || '').split('\n');
  return lines.map((line, idx) => {
    const trimmed = line.trim();
    if (trimmed.startsWith('[ ]') || trimmed.startsWith('[x]') || trimmed.startsWith('[X]')) {
      const checked = trimmed.toLowerCase().startsWith('[x]');
      const label = trimmed.slice(3).trim();
      return `
        <label class="chk-row ${checked ? 'checked' : ''}" style="display:flex;align-items:center;justify-content:space-between;gap:6px;">
          <span style="display:flex;align-items:center;gap:6px;min-width:0;flex:1;">
            <input type="checkbox" data-line="${idx}" ${checked ? 'checked' : ''}>
            <span style="word-break:break-word;">${escapeHtml(label)}</span>
          </span>
          <button type="button" class="btn-del-chk-line" data-del-line="${idx}" style="background:none;border:none;color:var(--text-dim);cursor:pointer;font-size:11px;line-height:1;padding:0 3px;opacity:0.65;" title="Delete task">×</button>
        </label>
      `;
    }
    if (!trimmed) return `<div style="height:4px;"></div>`;
    return `<div class="typewriter" style="font-size:11.5px;color:var(--text-mid);margin-top:4px;">${escapeHtml(line)}</div>`;
  }).join('');
}

function toggleChecklistLine(itemId, lineIdx) {
  const it = vault.items.find(i => i.id === itemId);
  if (!it || !it.notes) return;
  const lines = it.notes.split('\n');
  if (lineIdx < 0 || lineIdx >= lines.length) return;
  const line = lines[lineIdx];
  if (line.includes('[ ]')) {
    lines[lineIdx] = line.replace('[ ]', '[x]');
  } else if (line.includes('[x]')) {
    lines[lineIdx] = line.replace('[x]', '[ ]');
  } else if (line.includes('[X]')) {
    lines[lineIdx] = line.replace('[X]', '[ ]');
  }
  it.notes = lines.join('\n');
  saveVault();
  renderWorkspace();
}

function deleteChecklistLine(itemId, lineIdx) {
  const it = vault.items.find(i => i.id === itemId);
  if (!it || !it.notes) return;
  const lines = it.notes.split('\n');
  if (lineIdx < 0 || lineIdx >= lines.length) return;
  lines.splice(lineIdx, 1);
  it.notes = lines.join('\n');
  saveVault('TASK REMOVED');
  renderWorkspace();
}

function moveItemOrder(itemId, delta) {
  if (state.viewType === 'space' && state.activeSpaceId === 'instagram') {
    const visibleCards = Array.from(document.querySelectorAll('#workspaceContainer .studio-card[data-id]'))
      .map(el => el.dataset.id)
      .filter(Boolean);
    const vIdx = visibleCards.indexOf(itemId);
    const neighborId = (vIdx !== -1) ? visibleCards[vIdx + delta] : null;
    if (neighborId) {
      const igSpace = vault.spaces.find(s => s.id === 'instagram');
      if (igSpace) {
        igSpace.ui = igSpace.ui || {};
        igSpace.ui.sortOrder = 'manual';
        const sortSelect = document.getElementById('sortSelect');
        if (sortSelect) sortSelect.value = 'manual';
      }
      const fromIdx = vault.items.findIndex(i => i.id === itemId);
      const toIdx = vault.items.findIndex(i => i.id === neighborId);
      if (fromIdx !== -1 && toIdx !== -1) {
        const [moved] = vault.items.splice(fromIdx, 1);
        vault.items.splice(toIdx, 0, moved);
        saveVault();
        renderWorkspace();
        return;
      }
    }
  }
  const idx = vault.items.findIndex(i => i.id === itemId);
  if (idx === -1) return;
  const target = idx + delta;
  if (target < 0 || target >= vault.items.length) return;
  const [moved] = vault.items.splice(idx, 1);
  vault.items.splice(target, 0, moved);
  saveVault();
  renderWorkspace();
}

/* --------------------------------------------------------------------------
   08 FINLAND LINK VIEW (100% Read-Only Bridge — Clear Drawers Bento)
   -------------------------------------------------------------------------- */
function renderFinlandView(ws) {
  const linkedBoards = vault.projects.filter(p => p.finlandLinked);

  ws.innerHTML = `
    <div style="margin-bottom:18px;padding:14px 18px;background:var(--surface);border:1px solid var(--border);border-radius:var(--card-radius);display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
      <div>
        <div class="kicker-mono" style="color:var(--ok);">● 100% READ-ONLY FINLAND BRIDGE</div>
        <p class="typewriter" style="font-size:12px;color:var(--text-mid);margin-top:2px;">Ideal reads active projects from Finland without ever modifying or touching your Finland database.</p>
      </div>
      <span class="stage-badge">${linkedBoards.length} Linked Studio Clear Drawers</span>
    </div>
    <div class="clear-drawers-grid" id="finlandBoardsWall"></div>
  `;
  const grid = ws.querySelector('#finlandBoardsWall');
  linkedBoards.forEach((proj, idx) => {
    grid.appendChild(buildClearDrawerProjectEl(proj, idx));
  });
}

