function normalizeMovingForwardCard(c) {
  if (!c || typeof c !== 'object') return c;
  const preset = getMfCardPresets()[c.id];
  if (preset) {
    c.spaceId = preset.spaceId;
    if (!c.mfMigratedV34) {
      c.stage = preset.stage;
      c.org = preset.org;
      c.deadlineShort = preset.deadlineShort;
      c.deadlineDate = preset.deadlineDate;
      c.daysLeft = preset.daysLeft;
      c.nextStep = preset.nextStep;
      c.requirementsList = preset.requirementsList.map(r => ({ ...r }));
      c.keyFacts = { ...preset.keyFacts };
      if (preset.notes) c.notes = preset.notes;
      c.mfMigratedV34 = true;
    }
  }

  if (!c.stage) {
    const st = String(c.status || '').toLowerCase();
    if (st.includes('accept')) c.stage = 'accepted';
    else if (st.includes('reject') || st.includes('closed')) c.stage = 'closed';
    else if (st.includes('sent') || st.includes('submit')) c.stage = 'sent';
    else if (st.includes('spot')) c.stage = 'spotted';
    else c.stage = 'preparing';
  }

  if (!c.org) {
    const parts = String(c.title || '').split('—');
    c.org = (parts[0] || c.category || 'STUDIO LEAD').trim().toUpperCase();
  }

  if (!c.deadlineDate) {
    c.deadlineDate = c.deadline || 'Rolling';
  }
  if (!c.deadlineShort) {
    c.deadlineShort = c.deadline || 'Rolling';
  }

  if (!c.nextStep) {
    const firstLine = String(c.notes || '').split('\n').map(s => s.trim()).filter(Boolean)[0];
    c.nextStep = firstLine || 'Prepare application materials and portfolio link';
  }

  if (!Array.isArray(c.requirementsList)) {
    const req = c.requirements || {};
    c.requirementsList = [
      { id: 'r1', label: 'Portfolio PDF', done: req.portfolioPdf !== undefined ? Boolean(req.portfolioPdf) : true },
      { id: 'r2', label: 'Website link', done: req.websiteLink !== undefined ? Boolean(req.websiteLink) : true },
      { id: 'r3', label: 'CV', done: req.cv !== undefined ? Boolean(req.cv) : true },
      { id: 'r4', label: 'Artist statement', done: Boolean(req.artistStatement) },
      { id: 'r5', label: 'Project proposal', done: Boolean(req.projectProposal) }
    ];
  }

  if (!c.keyFacts || typeof c.keyFacts !== 'object') {
    let domain = '';
    if (c.link && c.link.startsWith('http')) {
      try { domain = new URL(c.link).hostname.replace(/^www\./, ''); } catch (e) {}
    }
    c.keyFacts = {
      deadline: c.deadlineDate || 'Rolling',
      fee: '',
      offer: '',
      contact: '',
      website: domain,
      websiteUrl: c.link || ''
    };
  }

  if (!c.artistKit || typeof c.artistKit !== 'object') {
    c.artistKit = {
      shortBio: false,
      artistStatement: false,
      cv: false,
      topWorks: false
    };
  }

  if (!Array.isArray(c.notesList) || c.notesList.length === 0) {
    c.notesList = [typeof c.notes === 'string' ? c.notes : ''];
  }

  return c;
}

function buildMfLeadCardHtml(c) {
  const reqList = Array.isArray(c.requirementsList) ? c.requirementsList : [];
  const totalReqs = reqList.length || 5;
  const doneReqs = reqList.filter(r => r.done).length;
  const dotsHtml = reqList.map(r => `<span class="mf-req-dot ${r.done ? 'is-done' : ''}"></span>`).join('');
  const isPoolCard = (c.spaceId === 'opportunity_pool');

  const poolActionsHtml = isPoolCard ? `
    <div class="mf-pool-card-actions">
      <button type="button" class="mf-pool-move-btn ${c.poolGroup === 'residencies' ? 'is-suggested' : ''}" data-move-pool-target="residencies" data-move-card-id="${escapeHtml(c.id)}" title="Move to Spotted in 07 Residencies & Awards">+ Residencies</button>
      <button type="button" class="mf-pool-move-btn ${c.poolGroup === 'work_apps' ? 'is-suggested' : ''}" data-move-pool-target="work_apps" data-move-card-id="${escapeHtml(c.id)}" title="Move to Spotted in 08 Work Applications">+ Work Apps</button>
      <button type="button" class="mf-pool-move-btn ${c.poolGroup === 'dream_clients' ? 'is-suggested' : ''}" data-move-pool-target="dream_clients" data-move-card-id="${escapeHtml(c.id)}" title="Move to Spotted in 09 Clients">+ Clients</button>
    </div>
  ` : '';

  return `
    <article class="mf-lead-card ${isPoolCard ? 'is-pool-card' : ''}" data-lead-id="${escapeHtml(c.id)}" draggable="true">
      <h3 class="mf-lead-title">${escapeHtml(c.title)}</h3>
      <div class="mf-lead-org">${escapeHtml(c.org || '')}</div>
      <div class="mf-lead-meta-row">
        <span class="mf-deadline-pill">${escapeHtml(c.deadlineShort || c.deadline || 'Rolling')}</span>
        ${c.mediaUrl ? `<span class="mf-lead-media-badge" title="Source flyer / screenshot attached">📎 Flyer</span>` : ''}
        <div class="mf-req-progress" title="${doneReqs} of ${totalReqs} requirements ready">
          <div class="mf-req-dots">${dotsHtml}</div>
          <span class="mf-req-count">${doneReqs}/${totalReqs}</span>
        </div>
      </div>
      <div class="mf-lead-next">${escapeHtml(c.nextStep || '')}</div>
      ${poolActionsHtml}
    </article>
  `;
}

