/* ==========================================================================
   QUICK INLINE COMPOSER, FILE UPLOADS, MODALS & EVENT LISTENERS
   ========================================================================== */
function openQuickComposer(kind = 'note') {
  const { type, obj } = getActiveContainer();
  if (type === 'space' && obj && obj.id === 'gdrive_assets') return;
  if (type === 'space' && obj && obj.id === 'tool_dock') {
    openToolDockModal({ mode: kind === 'link' ? 'link' : 'rd', id: null });
    return;
  }

  const bar = document.getElementById('quickComposerBar');
  if (!bar) return;
  bar.hidden = false;

  const isProjectsOverview = (type === 'space' && obj.id === 'projects');
  const secDefault = (state.activeCategory && !state.activeCategory.startsWith('All')) ? state.activeCategory : 'Notes';

  const targetPickerHtml = isProjectsOverview ? `
    <select id="qcTargetSelect" class="inspector-input" style="max-width:210px;" title="Choose where to place this item">
      <option value="space:projects">📌 Studio Projects Wall</option>
      ${vault.projects.map(p => `<option value="project:${escapeHtml(p.id)}">Board: ${escapeHtml(p.title)}</option>`).join('')}
    </select>
  ` : '';

  bar.innerHTML = `
    <span class="kicker-mono" style="color:var(--accent);">${kind === 'link' ? '+ ADD LINK / LOCAL MAC PATH' : '+ ADD NOTE / INTERACTIVE CHECKLIST'}</span>
    ${targetPickerHtml}
    <input type="text" id="qcTitle" class="inspector-input" style="max-width:240px;" placeholder="${kind === 'link' ? 'Title (e.g. Render Folder)...' : 'Title (e.g. Sculpting To-Do)...'}">
    ${kind === 'link'
      ? `<input type="text" id="qcLink" class="inspector-input" style="flex:1;min-width:220px;" placeholder="https://... or ~/Desktop/3d projects 2026">`
      : `<input type="text" id="qcNotes" class="inspector-input" style="flex:1;min-width:240px;" placeholder="Write note or use [ ] Task 1  [ ] Task 2 for checkboxes...">`
    }
    <input type="text" id="qcStatus" class="inspector-input" style="max-width:140px;" placeholder="Badge (e.g. WIP)">
    <button type="button" class="primary-block-btn" id="btnQcSave" style="width:auto;padding:7px 16px;">Add to Vault</button>
    <button type="button" class="outline-btn" id="btnQcChecklistTpl" title="Insert [ ] checkboxes">+ [ ] Task</button>
    <button type="button" class="icon-chip" id="btnQcCancel">✕</button>
  `;

  const titleIn = bar.querySelector('#qcTitle');
  titleIn?.focus();

  bar.querySelector('#btnQcChecklistTpl')?.addEventListener('click', () => {
    const notesIn = bar.querySelector('#qcNotes');
    if (notesIn) {
      notesIn.value = (notesIn.value ? notesIn.value + '\n' : '') + '[ ] First task\n[ ] Second task';
      notesIn.focus();
    }
  });

  bar.querySelector('#btnQcCancel')?.addEventListener('click', () => {
    bar.hidden = true;
  });

  bar.querySelector('#btnQcSave')?.addEventListener('click', () => {
    const title = (bar.querySelector('#qcTitle')?.value || '').trim() || (kind === 'link' ? 'Saved Link / Path' : 'Studio Note');
    const link = (bar.querySelector('#qcLink')?.value || '').trim();
    const rawNotes = (bar.querySelector('#qcNotes')?.value || '').trim();
    const status = (bar.querySelector('#qcStatus')?.value || '').trim() || (kind === 'link' ? '🔗 Link' : '📝 Note');

    let targetParentType = type;
    let targetParentId = obj.id;
    const targetSelVal = bar.querySelector('#qcTargetSelect')?.value;
    if (targetSelVal && targetSelVal.includes(':')) {
      const [selType, selId] = targetSelVal.split(':');
      targetParentType = selType;
      targetParentId = selId;
    }

    const spot = findNextOpenBoardSpot();
    const newItem = {
      id: 'itm_' + Date.now(),
      parentType: targetParentType,
      parentId: targetParentId,
      folderId: state.activeFolderId || null,
      section: secDefault,
      kind: rawNotes.includes('[ ]') ? 'checklist' : kind,
      title,
      status,
      igStatus: (targetParentType === 'space' && targetParentId === 'instagram')
        ? ((state.igStatusFilter === 'published' || state.activeCategory === 'IG Live') ? 'published' : ((state.igStatusFilter === 'queued' || state.activeCategory === 'IG Ready') ? 'queued' : ''))
        : undefined,
      url: '',
      notes: rawNotes,
      tags: [secDefault],
      link,
      wallX: spot.x,
      wallY: spot.y,
      wallW: 264,
      createdAt: Date.now()
    };

    vault.items.unshift(newItem);
    bar.hidden = true;
    saveVault();
    renderAll();
  });
}

async function computeFileSha256(file) {
  try {
    if (window.crypto && window.crypto.subtle && typeof file.arrayBuffer === 'function') {
      const buf = await file.arrayBuffer();
      const hashBuf = await window.crypto.subtle.digest('SHA-256', buf);
      const hashArr = Array.from(new Uint8Array(hashBuf));
      return hashArr.map(b => b.toString(16).padStart(2, '0')).join('');
    }
  } catch (e) {}
  return '';
}

function probeMediaDimensionsFromBlobUrl(blobUrl, kind) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (w, h, duration) => {
      if (settled) return;
      settled = true;
      resolve({ w: Number(w) || 0, h: Number(h) || 0, duration: Number(duration) || 0 });
    };
    const timer = setTimeout(() => finish(0, 0, 0), 3500);
    if (kind === 'video') {
      const vid = document.createElement('video');
      vid.preload = 'metadata';
      vid.muted = true;
      vid.onloadedmetadata = () => {
        clearTimeout(timer);
        finish(vid.videoWidth, vid.videoHeight, vid.duration);
      };
      vid.onerror = () => {
        clearTimeout(timer);
        finish(0, 0, 0);
      };
      vid.src = blobUrl;
    } else if (kind === 'image') {
      const img = new Image();
      img.onload = () => {
        clearTimeout(timer);
        finish(img.naturalWidth, img.naturalHeight, 0);
      };
      img.onerror = () => {
        clearTimeout(timer);
        finish(0, 0, 0);
      };
      img.src = blobUrl;
    } else {
      clearTimeout(timer);
      finish(0, 0, 0);
    }
  });
}

function findExactDuplicateInVault(file, sha256) {
  const normIncoming = String(file.name || '').trim().toLowerCase();
  const incomingSize = Number(file.size) || 0;
  const candidates = (vault.items || []).filter(it => it && it.url);
  // First check exact SHA-256 cryptographic match
  if (sha256) {
    const byHash = candidates.find(it => it.sha256 && it.sha256 === sha256);
    if (byHash) return { existing: byHash, matchReason: '100% Identical SHA-256 Cryptographic Hash & Byte Stream' };
  }
  // Second check exact filename + identical non-zero byte size (never block different files that only share a name)
  if (incomingSize > 0) {
    const byNameAndSize = candidates.find(it => {
      const itName = String(it.originalFileName || it.title || '').trim().toLowerCase();
      const urlBase = String(it.url || '').split('/').pop().replace(/^\d+_/, '').toLowerCase();
      const sameName = (itName === normIncoming || urlBase === normIncoming);
      return sameName && Number(it.fileSize) === incomingSize;
    });
    if (byNameAndSize) {
      return { existing: byNameAndSize, matchReason: 'Exact Filename & Identical Byte Size Match' };
    }
  }
  return null;
}

function announceLightboxPolite(message, delayMs = 120) {
  const text = String(message || '').trim();
  if (!text) return;
  setTimeout(() => {
    const el = document.getElementById('lbPoliteAnnouncer');
    if (!el) return;
    el.textContent = '';
    requestAnimationFrame(() => { el.textContent = text; });
  }, delayMs);
}

function syncLightboxLiveProgressDom() {
  const banner = document.getElementById('lbUploadProgressBanner');
  if (!banner) return;
  const prog = state.lightboxUploadProgress;
  if (!prog || !prog.active) {
    banner.hidden = true;
    return;
  }
  banner.hidden = false;
  const labelEl = document.getElementById('lbUploadProgressLabel');
  const metaEl = document.getElementById('lbUploadProgressMeta');
  const barEl = document.getElementById('lbUploadProgressBarEl');
  if (labelEl) labelEl.textContent = prog.label || 'Uploading original files…';
  if (metaEl) {
    metaEl.textContent = prog.total > 0 ? `${prog.done} / ${prog.total}` : 'Scanning…';
  }
  if (barEl) {
    if (prog.total > 0 && prog.done > 0) {
      barEl.max = prog.total;
      barEl.value = prog.done;
    } else {
      barEl.removeAttribute('value');
    }
  }
}

function showDuplicateProofDialog({ file, blobUrl, kind, dims, sha256, existing, matchReason, isBatchDrop = false }) {
  return new Promise((resolve) => {
    const dlg = document.getElementById('lightboxDuplicateDialog');
    const body = document.getElementById('lightboxDuplicateBody');
    const btnClose = document.getElementById('btnCloseDuplicateDialog');
    if (!dlg || !body) {
      resolve({ action: 'skip', applyToAll: true });
      return;
    }

    const existingDims = (existing.naturalW && existing.naturalH)
      ? `${existing.naturalW} × ${existing.naturalH} px (${computeExactAspectRatio(existing.naturalW, existing.naturalH).label})`
      : 'Original Vault Media';
    const incomingDimsClean = (dims && dims.w && dims.h)
      ? `${dims.w} × ${dims.h} px (${computeExactAspectRatio(dims.w, dims.h).label})`
      : 'Original Media';
    const hashDisplay = sha256
      ? `${sha256.slice(0, 16)}…${sha256.slice(-16)}`
      : 'Verified Exact File Match';
    const existingSizeStr = existing.fileSize ? `${formatBytes(existing.fileSize)} (${existing.fileSize.toLocaleString()} bytes)` : formatBytes(file.size || 0);
    const incomingSizeStr = `${formatBytes(file.size || 0)} (${(file.size || 0).toLocaleString()} bytes)`;
    const existingDate = existing.createdAt ? new Date(existing.createdAt).toLocaleString() : 'Previously Ingested';
    const existingDispUrl = getLightboxDisplayUrl(existing);

    const existingMediaHtml = existing.kind === 'video'
      ? `<video src="${escapeHtml(existing.url)}" autoplay loop muted playsinline class="dup-proof-media"></video>`
      : `<img src="${escapeHtml(existingDispUrl)}" alt="${escapeHtml(existing.title)}" class="dup-proof-media" data-pin-nopin="true">`;
    const incomingMediaHtml = kind === 'video'
      ? `<video src="${escapeHtml(blobUrl)}" autoplay loop muted playsinline class="dup-proof-media"></video>`
      : `<img src="${escapeHtml(blobUrl)}" alt="${escapeHtml(file.name)}" class="dup-proof-media" data-pin-nopin="true">`;

    body.innerHTML = `
      <div class="dup-proof-banner">
        <span class="dup-proof-badge">✓ 100% EXACT MATCH PROOF</span>
        <span class="dup-proof-reason">${escapeHtml(matchReason)}</span>
      </div>
      <div class="dup-proof-hash-bar">
        <span class="kicker-mono">SHA-256 FINGERPRINT MATCH:</span>
        <code>${escapeHtml(hashDisplay)}</code>
      </div>
      <div class="dup-proof-grid">
        <div class="dup-proof-card is-existing">
          <div class="dup-proof-card-head">
            <span class="kicker-mono">ALREADY IN VAULT</span>
            <span class="dup-match-tag">Original</span>
          </div>
          <div class="dup-proof-stage">${existingMediaHtml}</div>
          <div class="dup-proof-specs">
            <div><strong>Filename:</strong> ${escapeHtml(existing.title || file.name)}</div>
            <div><strong>Exact Size:</strong> ${escapeHtml(existingSizeStr)}</div>
            <div><strong>Resolution / Ratio:</strong> ${escapeHtml(existingDims)}</div>
            <div><strong>Added:</strong> ${escapeHtml(existingDate)}</div>
          </div>
        </div>
        <div class="dup-proof-card is-incoming">
          <div class="dup-proof-card-head">
            <span class="kicker-mono">INCOMING DROPPED FILE (DUPLICATE)</span>
            <span class="dup-match-tag">IDENTICAL</span>
          </div>
          <div class="dup-proof-stage">${incomingMediaHtml}</div>
          <div class="dup-proof-specs">
            <div><strong>Filename:</strong> ${escapeHtml(file.name)}</div>
            <div><strong>Exact Size:</strong> ${escapeHtml(incomingSizeStr)}</div>
            <div><strong>Resolution / Ratio:</strong> ${escapeHtml(incomingDimsClean)}</div>
            <div><strong>Status:</strong> Duplicate detected before write</div>
          </div>
        </div>
      </div>
      ${isBatchDrop ? `
        <label class="chk-row" style="margin-top:4px;padding:7px 10px;border:1px solid var(--border);border-radius:6px;background:var(--surface-pill);cursor:pointer;font-size:11.5px;display:flex;align-items:center;gap:8px;">
          <input type="checkbox" id="chkDupApplyAllBatch" checked>
          <span>Apply this choice to all remaining duplicates in this folder/batch drop</span>
        </label>
      ` : ''}
      <div class="dup-proof-actions">
        <button type="button" class="outline-btn" id="btnDupKeepAnyway">Upload Copy Anyway</button>
        <button type="button" class="primary-btn" id="btnDupSkipFile" autofocus>Skip Duplicate (Keep Original Only)</button>
      </div>
    `;

    const cleanupAndResolve = (action) => {
      const applyToAll = isBatchDrop ? Boolean(body.querySelector('#chkDupApplyAllBatch')?.checked) : false;
      if (dlg.open) dlg.close();
      resolve({ action, applyToAll });
    };

    body.querySelector('#btnDupSkipFile')?.addEventListener('click', () => cleanupAndResolve('skip'));
    body.querySelector('#btnDupKeepAnyway')?.addEventListener('click', () => cleanupAndResolve('keep'));
    if (btnClose) {
      btnClose.onclick = () => cleanupAndResolve('skip');
    }
    dlg.onclose = () => resolve({ action: 'skip', applyToAll: true });
    if (!dlg.open) dlg.showModal();
  });
}

function isSupportedStudioUploadFile(fileName, fileSize = -1) {
  const base = String(fileName || '').split('/').pop().trim();
  if (!base || base.startsWith('.')) return false; // Skip .DS_Store, ._AppleDouble, .localized
  const lower = base.toLowerCase();
  if (lower === 'thumbs.db' || lower === 'desktop.ini' || lower === 'icon\r') return false;
  if (fileSize === 0) return false;
  const ext = lower.includes('.') ? lower.split('.').pop() : '';
  const allowedExts = new Set([
    'png', 'jpg', 'jpeg', 'webp', 'gif', 'svg', 'avif', 'heic', 'heif', 'tif', 'tiff', 'bmp', 'ico',
    'mp4', 'mov', 'webm', 'm4v', 'avi', 'mkv',
    'wav', 'mp3', 'aiff', 'flac', 'm4a', 'ogg',
    'psd', 'psb', 'exr', 'hdr', 'pdf'
  ]);
  return allowedExts.has(ext);
}

function captureDropPayloadSynchronously(dataTransfer) {
  const entries = [];
  const rawFiles = [];
  if (!dataTransfer) return { entries, rawFiles };

  if (dataTransfer.items && dataTransfer.items.length > 0) {
    for (let i = 0; i < dataTransfer.items.length; i++) {
      const item = dataTransfer.items[i];
      if (!item || item.kind !== 'file') continue;
      const entry = typeof item.webkitGetAsEntry === 'function'
        ? item.webkitGetAsEntry()
        : (typeof item.getAsEntry === 'function' ? item.getAsEntry() : null);
      if (entry) {
        entries.push(entry);
      } else {
        const f = item.getAsFile && item.getAsFile();
        if (f) rawFiles.push(f);
      }
    }
  }
  if (entries.length === 0 && dataTransfer.files && dataTransfer.files.length > 0) {
    for (let i = 0; i < dataTransfer.files.length; i++) {
      rawFiles.push(dataTransfer.files[i]);
    }
  }
  return { entries, rawFiles };
}

async function readDirectoryEntriesAll(dirReader) {
  const allEntries = [];
  while (true) {
    const batch = await new Promise((resolve) => {
      try {
        dirReader.readEntries(
          (res) => resolve(Array.isArray(res) ? res : []),
          () => resolve([])
        );
      } catch (e) {
        resolve([]);
      }
    });
    if (!batch || batch.length === 0) break;
    allEntries.push(...batch);
  }
  return allEntries;
}

async function traverseFileSystemEntryRecursive(entry, parentPath = '') {
  if (!entry) return [];
  const name = entry.name || '';
  if (name.startsWith('.')) return [];

  if (entry.isFile) {
    const fileObj = await new Promise((resolve) => {
      try {
        entry.file((f) => resolve(f), () => resolve(null));
      } catch (e) {
        resolve(null);
      }
    });
    if (!fileObj || !isSupportedStudioUploadFile(fileObj.name, fileObj.size)) return [];
    const relPath = parentPath ? `${parentPath}/${fileObj.name}` : fileObj.name;
    try {
      fileObj._relativePath = relPath;
      fileObj._subfolderName = parentPath || '';
    } catch (e) {}
    return [fileObj];
  }

  if (entry.isDirectory) {
    const nextParent = parentPath ? `${parentPath}/${name}` : name;
    const reader = entry.createReader();
    const children = await readDirectoryEntriesAll(reader);
    const nestedLists = await Promise.all(
      children.map(child => traverseFileSystemEntryRecursive(child, nextParent))
    );
    return nestedLists.flat();
  }

  return [];
}

async function extractAllDroppedFiles(fileListOrCaptured) {
  if (!fileListOrCaptured) return [];

  // Case 1: Captured drop payload with FileSystemEntry handles (supports folders & nested subfolders)
  if (fileListOrCaptured.entries && fileListOrCaptured.entries.length > 0) {
    const lists = await Promise.all(
      fileListOrCaptured.entries.map(entry => traverseFileSystemEntryRecursive(entry, ''))
    );
    const extracted = lists.flat();
    if (extracted.length > 0) return extracted;
  }

  // Case 2: Standard FileList or Array of File objects (e.g. <input type="file" multiple> or <input webkitdirectory>)
  const rawArr = Array.isArray(fileListOrCaptured.rawFiles)
    ? fileListOrCaptured.rawFiles
    : Array.from(fileListOrCaptured);

  return rawArr.filter(f => {
    if (!f || !isSupportedStudioUploadFile(f.name, f.size)) return false;
    if (f.webkitRelativePath) {
      const parts = f.webkitRelativePath.split('/').filter(Boolean);
      if (parts.length > 1) {
        try {
          f._relativePath = f.webkitRelativePath;
          f._subfolderName = parts.slice(0, -1).join('/');
        } catch (e) {}
      }
    }
    return true;
  });
}

function forceHideAllDropOverlays() {
  const dropOverlay = document.getElementById('globalDropOverlay');
  if (dropOverlay) dropOverlay.hidden = true;
  document.querySelectorAll('.is-dragover, .is-file-drag-over, .is-drag-over').forEach(el => {
    el.classList.remove('is-dragover', 'is-file-drag-over', 'is-drag-over');
  });
}

async function handleFilesUpload(fileListOrCaptured, dropOpts = null) {
  forceHideAllDropOverlays();
  if (!fileListOrCaptured) return;

  const { type, obj } = getActiveContainer();
  if (type === 'space' && obj && (obj.id === 'gdrive_assets' || obj.id === 'tool_dock')) return;

  const isLightbox = (type === 'space' && obj && obj.id === 'lightbox');
  const syncText = document.getElementById('syncStatusText');
  if (syncText) syncText.textContent = 'SCANNING FOLDER & SUBFOLDERS FOR MEDIA...';

  if (isLightbox) {
    state.lightboxUploadProgress = {
      active: true,
      done: 0,
      total: 0,
      label: 'Scanning files & folders…'
    };
    syncLightboxLiveProgressDom();
  }

  const resolvedFiles = await extractAllDroppedFiles(fileListOrCaptured);
  forceHideAllDropOverlays();

  if (!resolvedFiles || resolvedFiles.length === 0) {
    if (syncText) syncText.textContent = 'ALL CHANGES SAVED';
    if (isLightbox) {
      state.lightboxUploadProgress = { active: false, done: 0, total: 0, label: '' };
      syncLightboxLiveProgressDom();
    }
    showStatusToast('No supported media files found in dropped item.');
    return;
  }

  let targetParentType = type;
  let targetParentId = obj.id;
  let targetFolderId = state.activeFolderId || null;
  let customBaseSpot = null;
  let autoCreatedOrMatchedProj = null;

  if (isLightbox) {
    // Check if files were dropped directly onto a Lightbox project pill
    let explicitProjTarget = (dropOpts && dropOpts.lightboxProjectId) ? dropOpts.lightboxProjectId : state.lightboxProjectId;
    if (dropOpts && typeof dropOpts.clientX === 'number' && typeof dropOpts.clientY === 'number') {
      const hitEls = document.elementsFromPoint(dropOpts.clientX, dropOpts.clientY) || [];
      const hitPill = hitEls.find(el => el.classList && el.classList.contains('lb-proj-pill') && el.dataset.lbProjPill);
      if (hitPill && hitPill.dataset.lbProjPill) {
        explicitProjTarget = hitPill.dataset.lbProjPill;
      }
    }

    if (explicitProjTarget && explicitProjTarget !== 'all' && explicitProjTarget !== 'unsorted' && vault.projects.some(p => p.id === explicitProjTarget)) {
      targetParentType = 'project';
      targetParentId = explicitProjTarget;
      targetFolderId = null;
      state.lightboxProjectId = explicitProjTarget;
    } else {
      // Check if user dropped/selected a single named root folder while in All Projects -> auto-match or auto-create that project!
      const rootFolders = Array.from(new Set(
        resolvedFiles
          .map(f => String(f._subfolderName || '').split('/').filter(Boolean)[0] || '')
          .filter(Boolean)
      ));

      if (explicitProjTarget !== 'unsorted' && rootFolders.length === 1) {
        const folderTitle = rootFolders[0].trim();
        let matchedProj = (vault.projects || []).find(p => String(p.title || '').trim().toLowerCase() === folderTitle.toLowerCase());
        if (!matchedProj) {
          const newId = 'proj_' + Date.now();
          const nextCode = '#' + String((vault.projects?.length || 0) + 1).padStart(2, '0');
          matchedProj = {
            id: newId,
            code: nextCode,
            title: folderTitle,
            subtitle: 'Lightbox Folder Upload',
            category: '3D & Motion',
            lifecycleState: 'active',
            sections: ['All', 'Renders', 'Passes', 'Selects'],
            tags: ['3D & Motion', 'Lightbox'],
            ui: { layoutMode: 'giant_wall', cardSize: 300, aspectRatio: '16 / 10.5', imageFit: 'cover', sortOrder: 'manual' },
            boardX: 288,
            boardY: 120,
            createdAt: Date.now(),
            updatedAt: Date.now()
          };
          vault.projects.unshift(matchedProj);
        }
        autoCreatedOrMatchedProj = matchedProj;
        targetParentType = 'project';
        targetParentId = matchedProj.id;
        targetFolderId = null;
        state.lightboxProjectId = matchedProj.id;
      } else {
        // Stage loose files in Lightbox Unsorted (never silently dump into vault.projects[0])
        targetParentType = 'space';
        targetParentId = 'lightbox';
        targetFolderId = null;
      }
    }
  } else if (type === 'space' && (obj.id === 'customize' || obj.id === 'finland')) {
    targetParentType = 'project';
    targetParentId = vault.projects[0]?.id || 'proj_test_sculpt';
  }

  if (!isLightbox && dropOpts && typeof dropOpts.clientX === 'number' && typeof dropOpts.clientY === 'number') {
    const hitEls = document.elementsFromPoint(dropOpts.clientX, dropOpts.clientY) || [];
    const projCard = hitEls.find(el => el.classList && el.classList.contains('clear-drawer-card') && el.dataset.id);
    const folderCard = hitEls.find(el => el.classList && el.classList.contains('is-folder-pin') && el.dataset.itemId);
    if (projCard && projCard.dataset.id) {
      targetParentType = 'project';
      targetParentId = projCard.dataset.id;
      targetFolderId = null;
    } else if (folderCard && folderCard.dataset.itemId) {
      targetFolderId = folderCard.dataset.itemId;
    } else {
      const stage = document.getElementById('giantWallStage');
      if (stage) {
        const rect = stage.getBoundingClientRect();
        const cam = getActiveBoardCamera();
        customBaseSpot = {
          x: snapCoord((dropOpts.clientX - rect.left - (cam.panX || 0)) / (cam.zoom || 1) - 110),
          y: snapCoord((dropOpts.clientY - rect.top - (cam.zoom ? (cam.panY || 0) : 0)) / (cam.zoom || 1) - 60)
        };
      }
    }
  }

  const destProjObj = targetParentType === 'project' ? vault.projects.find(p => p.id === targetParentId) : null;
  const destLabel = destProjObj ? destProjObj.title : (isLightbox ? 'Unsorted' : (obj?.title || 'Vault'));

  const secDefault = (state.activeCategory && !state.activeCategory.startsWith('All') && type !== 'space') ? state.activeCategory : 'All';
  const totalFiles = resolvedFiles.length;
  const isBatchDrop = totalFiles > 1;
  showStatusToast(`⚡ Uploading ${totalFiles} original file${totalFiles === 1 ? '' : 's'} to ${destLabel}…`);

  if (isLightbox) {
    state.lightboxUploadProgress = {
      active: true,
      done: 0,
      total: totalFiles,
      label: `Uploading to ${destLabel}…`
    };
    syncLightboxLiveProgressDom();
  }

  try {
    let uploadedCount = 0;
    let skippedDuplicates = 0;
    let processedCount = 0;
    let batchDuplicatePolicy = null; // 'skip' | 'keep' | null
    let dupModalLock = Promise.resolve();
    let lastProgressRender = Date.now();
    const newlyCreatedItems = [];

    const bumpProgressUi = () => {
      if (syncText) {
        syncText.textContent = `INGESTING ${processedCount} / ${totalFiles} ORIGINAL FILE(S)...`;
      }
      if (isLightbox) {
        state.lightboxUploadProgress = {
          active: true,
          done: processedCount,
          total: totalFiles,
          label: `Uploading to ${destLabel}…`
        };
        syncLightboxLiveProgressDom();
      }
    };

    const processSingleFile = async (file, idx) => {
      const ext = (file.name || '').split('.').pop().toLowerCase();
      let kind = 'image';
      if (['mp4', 'mov', 'webm', 'm4v', 'avi', 'mkv'].includes(ext)) kind = 'video';
      else if (['wav', 'mp3', 'aiff', 'flac', 'm4a', 'ogg'].includes(ext)) kind = 'audio';

      // Fast SHA-256 only for files <= 20MB on client; server always computes full SHA-256 on stream
      const sha256 = (file.size <= 20 * 1024 * 1024) ? await computeFileSha256(file) : '';

      // Active Exact Duplicate Detection
      const dupMatch = findExactDuplicateInVault(file, sha256);
      if (dupMatch && dupMatch.existing) {
        if (batchDuplicatePolicy === 'skip') {
          skippedDuplicates++;
          processedCount++;
          bumpProgressUi();
          return;
        }
        if (batchDuplicatePolicy !== 'keep') {
          // Serialize modal prompt so only one dialog opens at a time
          await (dupModalLock = dupModalLock.then(async () => {
            if (batchDuplicatePolicy !== null) return;
            const tempBlobUrl = URL.createObjectURL(file);
            const decision = await showDuplicateProofDialog({
              file,
              blobUrl: tempBlobUrl,
              kind,
              dims: { w: dupMatch.existing.naturalW || 0, h: dupMatch.existing.naturalH || 0 },
              sha256: sha256 || dupMatch.existing.sha256 || '',
              existing: dupMatch.existing,
              matchReason: dupMatch.matchReason,
              isBatchDrop
            });
            URL.revokeObjectURL(tempBlobUrl);
            if (decision.applyToAll) {
              batchDuplicatePolicy = decision.action;
            }
            file._dupDecision = decision.action;
          }));
          if ((file._dupDecision || batchDuplicatePolicy) === 'skip') {
            skippedDuplicates++;
            processedCount++;
            bumpProgressUi();
            return;
          }
        }
      }

      const res = await fetch('/api/upload', {
        method: 'POST',
        headers: {
          'X-File-Name': encodeURIComponent(file.name)
        },
        body: file
      });

      processedCount++;
      bumpProgressUi();

      if (res.ok) {
        const u = await res.json();
        const cleanUrl = (u.fileUrl || '').replace(/^\//, '');
        const spot = customBaseSpot
          ? { x: snapCoord(customBaseSpot.x + (idx % 4) * 288), y: snapCoord(customBaseSpot.y + Math.floor(idx / 4) * 240) }
          : { x: 288 + (idx % 5) * 288, y: 120 + Math.floor(idx / 5) * 240 };
        uploadedCount++;

        const subParts = file._subfolderName ? String(file._subfolderName).split('/').filter(Boolean) : [];
        const subf = (autoCreatedOrMatchedProj && subParts.length === 1) ? '' : (subParts.pop() || '');
        const displayTitle = u.fileName || file.name;
        const stackInfo = parseRenderStackInfo({
          title: subf ? `${displayTitle} (${subf})` : displayTitle,
          originalFileName: u.fileName || file.name,
          url: cleanUrl,
          kind
        });
        const itemTags = [kind.toUpperCase()];
        if (subf) itemTags.push(`Folder: ${subf}`);
        if (stackInfo.isStackedCandidate && stackInfo.versionLabel) {
          itemTags.push(`Pass: ${stackInfo.versionLabel}`);
        }

        const newItem = {
          id: 'itm_' + Date.now() + '_' + idx + '_' + Math.random().toString(36).slice(2, 6),
          parentType: targetParentType,
          parentId: targetParentId,
          folderId: targetFolderId,
          section: subf || secDefault,
          subfolderName: subf || '',
          sourceSubfolder: subf || '',
          relativePath: file._relativePath || file.name,
          kind,
          title: u.fileName || file.name,
          originalFileName: u.fileName || file.name,
          status: 'Active',
          sha256: u.sha256 || sha256 || '',
          fileSize: Number(u.fileSize || file.size || 0),
          naturalW: 0,
          naturalH: 0,
          duration: 0,
          aspectRatioKey: '',
          aspectRatioLabel: '',
          isOddRatio: false,
          stackStem: stackInfo.baseStem || '',
          stackVersionLabel: stackInfo.versionLabel || '',
          url: cleanUrl,
          notes: `${formatBytes(u.fileSize || file.size || 0)}${subf ? ` • Subfolder: ${subf}` : ''}`,
          tags: itemTags,
          link: '',
          wallX: spot.x,
          wallY: spot.y,
          wallW: 264,
          createdAt: Date.now()
        };

        vault.items.unshift(newItem);
        newlyCreatedItems.push(newItem);

        // Progressive live render every 600ms during large folder drops so user sees files appear live
        const now = Date.now();
        if (now - lastProgressRender > 600) {
          lastProgressRender = now;
          renderWorkspace();
        }
      }
    };

    // Run 6 parallel upload workers for maximum speed without blocking UI
    const CONCURRENCY = 6;
    let cursor = 0;
    const workers = Array.from({ length: Math.min(CONCURRENCY, totalFiles) }, async () => {
      while (cursor < totalFiles) {
        const myIdx = cursor++;
        await processSingleFile(resolvedFiles[myIdx], myIdx);
      }
    });
    await Promise.all(workers);

    if (uploadedCount > 0) {
      saveVault(`INGESTED ${uploadedCount} LOCKED ORIGINAL(S)`);
      const doneMsg = `Uploaded ${uploadedCount} file${uploadedCount === 1 ? '' : 's'} to ${destLabel}${skippedDuplicates ? ` · ${skippedDuplicates} duplicate skipped` : ''}`;
      showStatusToast(`✓ ${doneMsg}`);
      if (isLightbox) announceLightboxPolite(doneMsg);
      if (newlyCreatedItems.length > 0) {
        scanMissingLightboxDimensions(newlyCreatedItems);
      }
    } else if (skippedDuplicates > 0) {
      const skipMsg = `Skipped ${skippedDuplicates} exact duplicate file(s)`;
      showStatusToast(skipMsg);
      if (isLightbox) announceLightboxPolite(skipMsg);
    }
    state.lightboxUploadProgress = { active: false, done: 0, total: 0, label: '' };
    renderAll();
  } catch (err) {
    console.error('Upload failed:', err);
    showStatusToast('Upload encountered an error — check console.');
  } finally {
    state.lightboxUploadProgress = { active: false, done: 0, total: 0, label: '' };
    syncLightboxLiveProgressDom();
    forceHideAllDropOverlays();
  }
}

/* --------------------------------------------------------------------------
   ITEM INSPECTOR MODAL & PROJECT BOARD EDITOR MODAL
   -------------------------------------------------------------------------- */
function openItemInspector(itemId) {
  const it = vault.items.find(i => i.id === itemId);
  if (!it) return;
  state.editingItemId = it.id;

  const dlg = document.getElementById('itemDialog');
  const stage = document.getElementById('sheetMedia');
  const meta = document.getElementById('sheetFileMeta');
  const titleIn = document.getElementById('sheetTitle');
  const statusIn = document.getElementById('sheetStatusInput');
  const notesIn = document.getElementById('sheetNotes');
  const parentSel = document.getElementById('sheetParentSelect');
  const secIn = document.getElementById('sheetSectionInput');
  const tagsIn = document.getElementById('sheetTagsInput');
  const linkIn = document.getElementById('sheetLinkInput');
  const dlRow = document.getElementById('sheetDownloadRow');

  if (meta) meta.textContent = `${(it.kind || 'ITEM').toUpperCase()} • ${it.section || 'VAULT'}`;
  if (titleIn) titleIn.value = it.title || '';
  if (statusIn) statusIn.value = it.status || '';
  if (notesIn) notesIn.value = it.notes || '';
  if (secIn) secIn.value = it.section || '';
  if (tagsIn) tagsIn.value = (it.tags || []).join(', ');
  if (linkIn) linkIn.value = it.link || '';

  if (parentSel) {
    const projOpts = vault.projects.map(p => `<option value="project:${p.id}" ${it.parentType === 'project' && it.parentId === p.id ? 'selected' : ''}>Project: ${escapeHtml(p.title)}</option>`).join('');
    const spaceOpts = vault.spaces.filter(s => !['finland', 'customize'].includes(s.id)).map(s => `<option value="space:${s.id}" ${it.parentType === 'space' && it.parentId === s.id ? 'selected' : ''}>Section: ${escapeHtml(s.code)} ${escapeHtml(s.title)}</option>`).join('');
    parentSel.innerHTML = `<optgroup label="Project Boards">${projOpts}</optgroup><optgroup label="Sidebar Sections">${spaceOpts}</optgroup>`;
  }

  if (stage) {
    if (it.kind === 'video' && it.url) {
      stage.innerHTML = `<video src="${escapeHtml(it.url)}" controls autoplay loop playsinline></video>`;
    } else if (it.url && it.kind !== 'audio') {
      stage.innerHTML = `<img src="${escapeHtml(it.url)}" alt="${escapeHtml(it.title)}">`;
    } else if (it.kind === 'audio' && it.url) {
      stage.innerHTML = `
        <div style="text-align:center;width:100%;padding:32px;">
          <div class="kicker-mono" style="margin-bottom:12px;">🔊 ORIGINAL QUALITY AUDIO</div>
          <audio src="${escapeHtml(it.url)}" controls autoplay style="width:100%;max-width:360px;"></audio>
        </div>
      `;
    } else {
      stage.innerHTML = `<div class="stage-note-pad" style="max-width:520px;height:auto;border:1px solid var(--border);border-radius:6px;padding:24px;">${renderChecklistHtml(it.notes || it.title)}</div>`;
      stage.querySelectorAll('.chk-row input[type="checkbox"]').forEach(chk => {
        chk.addEventListener('change', () => {
          const lineIdx = parseInt(chk.dataset.line, 10);
          toggleChecklistLine(it.id, lineIdx);
          if (notesIn) notesIn.value = it.notes;
        });
      });
      stage.querySelectorAll('.btn-del-chk-line').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.preventDefault();
          e.stopPropagation();
          deleteChecklistLine(it.id, parseInt(btn.dataset.delLine, 10));
          if (notesIn) notesIn.value = it.notes;
          openItemInspector(it.id);
        });
      });
    }
  }

  if (dlRow) {
    dlRow.innerHTML = it.url
      ? `<a href="${escapeHtml(it.url)}" download class="outline-btn">↓ Download Original Uncompressed File</a>`
      : '';
  }

  // Sync IG Publishing Status segmented pill inside Inspector
  const igGroup = document.getElementById('sheetIgStatusGroup');
  if (igGroup) {
    const curIg = it.igStatus || '';
    igGroup.querySelectorAll('.seg-btn').forEach(btn => {
      btn.classList.toggle('active', (btn.dataset.igSet || '') === curIg);
    });
  }

  dlg?.showModal();
}

function saveInspectorChanges() {
  const it = vault.items.find(i => i.id === state.editingItemId);
  if (!it) return;

  it.title = (document.getElementById('sheetTitle')?.value || '').trim() || it.title;
  it.status = (document.getElementById('sheetStatusInput')?.value || '').trim();
  it.notes = document.getElementById('sheetNotes')?.value || '';
  it.section = (document.getElementById('sheetSectionInput')?.value || '').trim() || 'All';
  it.tags = (document.getElementById('sheetTagsInput')?.value || '').split(',').map(s => s.trim()).filter(Boolean);
  it.link = (document.getElementById('sheetLinkInput')?.value || '').trim();

  const activeIgBtn = document.querySelector('#sheetIgStatusGroup .seg-btn.active');
  if (activeIgBtn) {
    it.igStatus = activeIgBtn.dataset.igSet || '';
    if (it.igStatus === 'published' && !it.status.includes('IG Live')) {
      it.status = '● IG Live';
    } else if (it.igStatus === 'queued' && !it.status.includes('IG Ready')) {
      it.status = '◈ IG Ready';
    } else if (it.igStatus === 'website' && !it.status.includes('Website Ready')) {
      it.status = '🌐 Website Ready';
    }
  }

  const parentVal = document.getElementById('sheetParentSelect')?.value || '';
  if (parentVal.includes(':')) {
    const [pType, pId] = parentVal.split(':');
    it.parentType = pType;
    it.parentId = pId;
  }

  document.getElementById('itemDialog')?.close();
  saveVault();
  renderAll();
}

function openProjectModal(projId) {
  state.editingProjectId = projId;
  const dlg = document.getElementById('projectDialog');
  const heading = document.getElementById('projectDialogHeading');
  const delBtn = document.getElementById('btnProjDialogDelete');

  const proj = projId ? vault.projects.find(p => p.id === projId) : null;
  if (heading) heading.textContent = proj ? 'CUSTOMIZE PROJECT BOARD' : 'CREATE NEW PROJECT BOARD';
  if (delBtn) delBtn.style.visibility = proj ? 'visible' : 'hidden';

  document.getElementById('projEditTitle').value = proj ? proj.title : '';
  document.getElementById('projEditStatus').value = proj ? (proj.status || '🔥 In Progress') : '🔥 In Progress';
  document.getElementById('projEditCategory').value = proj ? (proj.category || '3D & Motion') : '3D & Motion';
  document.getElementById('projEditSubtitle').value = proj ? (proj.subtitle || '') : '';
  document.getElementById('projEditSections').value = proj ? (proj.sections || ['All', 'WIP', 'Final', 'Notes']).join(', ') : 'All, WIP, References, Notes';
  document.getElementById('projEditTags').value = proj ? (proj.tags || []).join(', ') : '3D & Motion, Studio';

  dlg?.showModal();
}

function saveProjectModal() {
  const title = (document.getElementById('projEditTitle')?.value || '').trim() || 'Untitled Studio Board';
  const status = (document.getElementById('projEditStatus')?.value || '').trim() || 'Active';
  const category = (document.getElementById('projEditCategory')?.value || '').trim() || '3D & Motion';
  const subtitle = (document.getElementById('projEditSubtitle')?.value || '').trim();
  const sections = (document.getElementById('projEditSections')?.value || '').split(',').map(s => s.trim()).filter(Boolean);
  if (!sections.includes('All')) sections.unshift('All');
  const tags = (document.getElementById('projEditTags')?.value || '').split(',').map(s => s.trim()).filter(Boolean);

  if (state.editingProjectId) {
    const proj = vault.projects.find(p => p.id === state.editingProjectId);
    if (proj) {
      proj.title = title;
      proj.status = status;
      proj.category = category;
      proj.subtitle = subtitle;
      proj.sections = sections;
      proj.tags = tags;
      proj.updatedAt = Date.now();
    }
  } else {
    const projSpot = findNextOpenProjectClusterSpot();
    const newProj = {
      id: 'proj_' + Date.now(),
      title,
      status,
      category,
      subtitle,
      sections,
      tags,
      finlandLinked: false,
      boardX: projSpot.x,
      boardY: projSpot.y,
      boardW: 360,
      ui: { layoutMode: 'giant_wall', cardSize: 280, aspectRatio: '16 / 10.5', imageFit: 'cover', sortOrder: 'manual' },
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
    vault.projects.unshift(newProj);
    const projectsSpace = vault.spaces.find(s => s.id === 'projects');
    if (projectsSpace && category && !projectsSpace.categories.includes(category)) {
      projectsSpace.categories.push(category);
    }
    document.getElementById('projectDialog')?.close();
    saveVault('CREATED NEW PROJECT BOARD');
    openProjectBoard(newProj.id);
    return;
  }

  const projectsSpace = vault.spaces.find(s => s.id === 'projects');
  if (projectsSpace && category && !projectsSpace.categories.includes(category)) {
    projectsSpace.categories.push(category);
  }

  document.getElementById('projectDialog')?.close();
  saveVault();
  renderAll();
}

/* --------------------------------------------------------------------------
   EXPLICIT DELETE CONFIRMATION (Soft-Moves to Trash on Server)
   -------------------------------------------------------------------------- */
function requestDelete(kind, id, title, meta = null) {
  state.pendingDelete = { kind, id, title, meta };
  const dlg = document.getElementById('confirmDeleteDialog');
  const titleEl = document.getElementById('confirmDeleteTitle');
  const msgEl = document.getElementById('confirmDeleteMessage');
  const yesBtn = document.getElementById('btnConfirmDeleteYes');

  if (titleEl) {
    titleEl.textContent = (kind === 'lb_project' || kind === 'lb_item' || kind === 'lb_batch_items')
      ? `Remove "${title}" from Lightbox?`
      : `Delete "${title}"?`;
  }
  if (msgEl) {
    if (kind === 'lb_project') {
      msgEl.textContent = 'This removes the project and its linked items from Lightbox only. Your original files on your Mac stay 100% untouched.';
    } else if (kind === 'lb_item') {
      msgEl.textContent = 'This removes the item from Lightbox only. Any local file on your Mac stays 100% untouched in its folder.';
    } else if (kind === 'lb_batch_items') {
      msgEl.textContent = 'All selected items will be removed from Lightbox only. Your original local files on your Mac stay 100% untouched.';
    } else if (kind === 'mf_req') {
      msgEl.textContent = 'Are you sure you want to delete this requirement?';
    } else if (kind === 'mf_lead') {
      msgEl.textContent = 'Are you sure you want to delete this opportunity?';
    } else if (kind === 'cust_template') {
      msgEl.textContent = 'Are you sure you want to delete this preset?';
    } else if (kind === 'tool_cluster') {
      const count = meta?.toolCount || 0;
      const fallback = meta?.fallbackCluster || 'another cluster';
      msgEl.textContent = count > 0
        ? `Delete cluster "${title}"? Its ${count} tool${count === 1 ? '' : 's'} will safely move to "${fallback}".`
        : `Are you sure you want to delete the empty cluster "${title}"?`;
    } else if (kind === 'tool_launchpad') {
      msgEl.textContent = 'This tool will be moved to Tool Dock trash. Nothing is ever permanently deleted without your confirmation.';
    } else if (kind === 'tool_rd') {
      msgEl.textContent = 'This R&D / Wishlist item will be moved to Tool Dock trash. Nothing is ever permanently deleted without your confirmation.';
    } else if (kind === 'tool_link') {
      msgEl.textContent = 'This Useful Link will be moved to Tool Dock trash. Nothing is ever permanently deleted without your confirmation.';
    } else if (kind === 'project') {
      msgEl.textContent = 'This will remove the project board and move any attached items to vault_trash. Nothing is ever deleted without your confirmation.';
    } else if (kind === 'batch_items') {
      msgEl.textContent = 'All selected items will be soft-moved to vault_trash so your original files remain recoverable. Nothing is ever deleted without your confirmation.';
    } else if (kind === 'showcase_rollout') {
      msgEl.textContent = 'This rollout post card will be moved to trash. Your staged artwork files remain safe in your vault.';
    } else {
      msgEl.textContent = 'This item will be soft-moved to vault_trash so your original files remain recoverable.';
    }
  }
  if (yesBtn) {
    if (kind === 'lb_project' || kind === 'lb_item' || kind === 'lb_batch_items') {
      yesBtn.textContent = 'Remove from Lightbox';
    } else {
      yesBtn.textContent = (kind === 'mf_req' || kind === 'mf_lead' || kind === 'cust_template' || kind === 'tool_cluster') ? 'Delete' : 'Move to Trash';
    }
  }
  dlg?.showModal();
}

async function executeConfirmedDelete() {
  const pd = state.pendingDelete;
  if (!pd) return;

  if (pd.kind === 'lb_project') {
    const lbProj = getLightboxProjects().find(p => p.id === pd.id);
    const lbItems = (vault.items || []).filter(i => i.parentType === 'space' && i.parentId === 'lightbox' && i.lightboxProjectId === pd.id);
    if (lbProj) {
      vault.lightboxTrash = Array.isArray(vault.lightboxTrash) ? vault.lightboxTrash : [];
      vault.lightboxTrash.push({
        project: JSON.parse(JSON.stringify(lbProj)),
        items: JSON.parse(JSON.stringify(lbItems)),
        deletedAt: new Date().toISOString()
      });
      pushLightboxUndo({
        type: 'remove_project',
        desc: `Removed project "${lbProj.title}" from Lightbox`,
        project: JSON.parse(JSON.stringify(lbProj)),
        items: JSON.parse(JSON.stringify(lbItems))
      });
    }
    const removedIds = new Set(lbItems.map(x => x.id));
    for (const pi of lbItems) {
      cleanupRemovedLightboxItemResources(pi);
    }
    vault.lightboxProjects = getLightboxProjects().filter(p => p.id !== pd.id);
    vault.items = (vault.items || []).filter(i => !removedIds.has(i.id));
    if (state.lightboxProjectId === pd.id) {
      state.lightboxProjectId = getLightboxProjects()[0]?.id || 'all';
    }
    if (Array.isArray(state.selectedCompareAssets)) {
      state.selectedCompareAssets = state.selectedCompareAssets.filter(a => !removedIds.has(a.vaultItemId || a.id));
    }
  } else if (pd.kind === 'lb_item') {
    const it = (vault.items || []).find(i => i.id === pd.id);
    if (it) {
      vault.lightboxTrash = Array.isArray(vault.lightboxTrash) ? vault.lightboxTrash : [];
      vault.lightboxTrash.push({ item: JSON.parse(JSON.stringify(it)), deletedAt: new Date().toISOString() });
      pushLightboxUndo({
        type: 'remove_items',
        desc: `Removed "${it.title || 'asset'}" from Lightbox`,
        items: [JSON.parse(JSON.stringify(it))]
      });
      cleanupRemovedLightboxItemResources(it);
    }
    vault.items = (vault.items || []).filter(i => i.id !== pd.id);
  } else if (pd.kind === 'lb_batch_items') {
    const ids = Array.isArray(pd.id) ? pd.id : [];
    const rmSet = new Set(ids);
    const removedItems = (vault.items || []).filter(i => rmSet.has(i.id));
    if (removedItems.length > 0) {
      vault.lightboxTrash = Array.isArray(vault.lightboxTrash) ? vault.lightboxTrash : [];
      vault.lightboxTrash.push({ items: JSON.parse(JSON.stringify(removedItems)), deletedAt: new Date().toISOString() });
      pushLightboxUndo({
        type: 'remove_items',
        desc: `Removed ${removedItems.length} items from Lightbox`,
        items: JSON.parse(JSON.stringify(removedItems))
      });
      for (const it of removedItems) {
        cleanupRemovedLightboxItemResources(it);
      }
    }
    vault.items = (vault.items || []).filter(i => !rmSet.has(i.id));
  } else if (pd.kind === 'cust_template') {
    ensureCustomizationTemplates(vault);
    if ((vault.customizationTemplates || []).length > 1) {
      vault.customizationTemplates = (vault.customizationTemplates || []).filter(t => t && t.id !== pd.id);
      if (vault.defaultTemplateId === pd.id) {
        const nextDef = vault.customizationTemplates[0];
        if (nextDef) {
          vault.defaultTemplateId = nextDef.id;
          vault.customizationTemplates.forEach(t => { if (t) t.isDefault = (t.id === nextDef.id); });
          try {
            localStorage.setItem(DEFAULT_TEMPLATE_LS_KEY, JSON.stringify(nextDef));
          } catch (e) {}
        }
      }
      if (vault.customization?.activeTemplateId === pd.id) {
        const fallbackTpl = getWebsiteDefaultTemplate(vault);
        applyTemplateObjectToVault(fallbackTpl, vault);
        applyCustomizationToDOM();
      }
    }
    state.pendingDelete = null;
    document.getElementById('confirmDeleteDialog')?.close();
    saveVault('DELETED PRESET');
    state.custSavedSnapshot = captureCustomizationSnapshot(vault);
    state.custDirty = false;
    renderAll();
    return;
  } else if (pd.kind === 'project') {
    const projToTrash = vault.projects.find(p => p.id === pd.id);
    const projItems = vault.items.filter(i => i.parentType === 'project' && i.parentId === pd.id);
    if (projToTrash) {
      vault.projectsTrash = Array.isArray(vault.projectsTrash) ? vault.projectsTrash : [];
      vault.projectsTrash.push({
        project: JSON.parse(JSON.stringify(projToTrash)),
        items: JSON.parse(JSON.stringify(projItems)),
        deletedAt: new Date().toISOString()
      });
    }
    const trashedProjItemIds = new Set(projItems.map(pi => pi.id));
    for (const pi of projItems) {
      if (pi.url && pi.url.includes('vault_media/')) {
        try {
          await fetch('/api/trash', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ storedName: pi.url.replace(/^\/?vault_media\//, '') })
          });
        } catch (e) {}
      }
    }
    vault.projects = vault.projects.filter(p => p.id !== pd.id);
    vault.items = vault.items.filter(i => !(i.parentType === 'project' && i.parentId === pd.id));
    if (state.lightboxProjectId === pd.id) {
      state.lightboxProjectId = 'all';
    }
    if (Array.isArray(state.selectedCompareAssets)) {
      state.selectedCompareAssets = state.selectedCompareAssets.filter(a => !trashedProjItemIds.has(a.vaultItemId || a.id));
    }
    if (state.viewType === 'project' && state.activeProjectId === pd.id) {
      state.viewType = 'space';
      state.activeSpaceId = 'projects';
      state.activeProjectId = null;
    }
  } else if (pd.kind === 'tool_cluster') {
    const clusterName = String(pd.id || '').trim();
    const clusterLower = clusterName.toLowerCase();
    const sp = vault.spaces?.find(s => s.id === 'tool_dock');
    const existingCats = Array.isArray(sp?.categories) ? sp.categories : [];
    const remainingCats = existingCats.filter(c => c && c !== 'All' && !c.startsWith('All ') && String(c).trim().toLowerCase() !== clusterLower);
    const fallbackCluster = pd.meta?.fallbackCluster || remainingCats[0] || 'Active Launchpad';

    if (vault.toolDock) {
      const matchCluster = (name) => String(name || '').trim().toLowerCase() === clusterLower;
      (vault.toolDock.launchpad || []).forEach(t => {
        if (matchCluster(t.cluster) || matchCluster(t.category)) {
          t.cluster = fallbackCluster;
          if (matchCluster(t.category)) t.category = fallbackCluster;
        }
      });
      (vault.toolDock.rdLab || []).forEach(r => {
        if (matchCluster(r.targetCluster) || matchCluster(r.category)) {
          r.targetCluster = fallbackCluster;
          if (matchCluster(r.category)) r.category = fallbackCluster;
        }
      });
      (vault.toolDock.usefulLinks || []).forEach(l => {
        if (matchCluster(l.cluster) || matchCluster(l.category)) {
          l.cluster = fallbackCluster;
          if (matchCluster(l.category)) l.category = fallbackCluster;
        }
      });
      if (Array.isArray(vault.toolDock.tools)) {
        vault.toolDock.tools.forEach(t => {
          if (matchCluster(t.cluster) || matchCluster(t.category)) {
            t.cluster = fallbackCluster;
            if (matchCluster(t.category)) t.category = fallbackCluster;
          }
        });
      }
      if (Array.isArray(vault.toolDock.categories)) {
        vault.toolDock.categories = vault.toolDock.categories.filter(c => !matchCluster(c));
      }
      vault.toolDock.trash = Array.isArray(vault.toolDock.trash) ? vault.toolDock.trash : [];
      if (!vault.toolDock.trash.some(t => t && t.trashType === 'cluster' && String(t.name || '').trim().toLowerCase() === clusterLower)) {
        vault.toolDock.trash.push({
          trashType: 'cluster',
          name: clusterName,
          deletedAt: new Date().toISOString()
        });
      }
    }
    if (sp && Array.isArray(sp.categories)) {
      sp.categories = sp.categories.filter(c => String(c).trim().toLowerCase() !== clusterLower);
      if (sp.categories.length === 0 || (sp.categories.length === 1 && sp.categories[0] === 'All')) {
        sp.categories = ['All', fallbackCluster];
      }
    }
    if (state.activeCategory && state.activeCategory.trim().toLowerCase() === clusterLower) {
      state.activeCategory = (sp && sp.categories && sp.categories[0]) || 'All';
    }
  } else if (pd.kind === 'tool_launchpad') {
    if (vault.toolDock && Array.isArray(vault.toolDock.launchpad)) {
      const target = vault.toolDock.launchpad.find(t => t.id === pd.id);
      if (target) {
        vault.toolDock.trash = Array.isArray(vault.toolDock.trash) ? vault.toolDock.trash : [];
        vault.toolDock.trash.push({ ...target, trashType: 'launchpad', deletedAt: new Date().toISOString() });
      }
      vault.toolDock.launchpad = vault.toolDock.launchpad.filter(t => t.id !== pd.id);
      vault.toolDock.tools = vault.toolDock.launchpad;
    }
  } else if (pd.kind === 'tool_rd') {
    if (vault.toolDock && Array.isArray(vault.toolDock.rdLab)) {
      const target = vault.toolDock.rdLab.find(r => r.id === pd.id);
      if (target) {
        vault.toolDock.trash = Array.isArray(vault.toolDock.trash) ? vault.toolDock.trash : [];
        vault.toolDock.trash.push({ ...target, trashType: 'rd', deletedAt: new Date().toISOString() });
      }
      vault.toolDock.rdLab = vault.toolDock.rdLab.filter(r => r.id !== pd.id);
      vault.toolDock.rdItems = vault.toolDock.rdLab;
    }
  } else if (pd.kind === 'tool_link') {
    if (vault.toolDock && Array.isArray(vault.toolDock.usefulLinks)) {
      const target = vault.toolDock.usefulLinks.find(l => l.id === pd.id);
      if (target) {
        vault.toolDock.trash = Array.isArray(vault.toolDock.trash) ? vault.toolDock.trash : [];
        vault.toolDock.trash.push({ ...target, trashType: 'link', deletedAt: new Date().toISOString() });
      }
      vault.toolDock.usefulLinks = vault.toolDock.usefulLinks.filter(l => l.id !== pd.id);
    }
  } else if (pd.kind === 'item') {
    const it = vault.items.find(i => i.id === pd.id);
    if (it && it.url && it.url.includes('vault_media/')) {
      try {
        await fetch('/api/trash', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ storedName: it.url.replace(/^\/?vault_media\//, '') })
        });
      } catch (e) {}
    }
    // Sub-board / Column / Sphere deleted: pop its cards safely back onto the parent board (never orphaned)
    if (it && (it.kind === 'folder' || it.kind === 'column' || it.kind === 'sphere')) {
      let offset = 0;
      vault.items.forEach(child => {
        if (child.id === it.id) return;
        const isFolderChild = it.kind === 'folder' && child.folderId === it.id;
        const isColumnChild = it.kind === 'column' && child.columnId === it.id;
        const isSphereChild = it.kind === 'sphere' && child.sphereId === it.id;
        if (!isFolderChild && !isColumnChild && !isSphereChild) return;
        if (isFolderChild) child.folderId = it.folderId || null;
        if (isColumnChild) delete child.columnId;
        if (isSphereChild) delete child.sphereId;
        child.wallX = (it.wallX || 264) + (offset % 3) * 288;
        child.wallY = (it.wallY || 144) + Math.floor(offset / 3) * 288;
        offset++;
      });
      if (state.activeFolderId === it.id) state.activeFolderId = it.folderId || null;
    }
    if (state.batchSelectedIds) state.batchSelectedIds.delete(pd.id);
    vault.items = vault.items.filter(i => i.id !== pd.id);
  } else if (pd.kind === 'batch_items') {
    const ids = Array.isArray(pd.id) ? pd.id : [];
    for (const delId of ids) {
      const projToTrash = vault.projects.find(p => p.id === delId);
      if (projToTrash) {
        const projItems = vault.items.filter(i => i.parentType === 'project' && i.parentId === delId);
        vault.projectsTrash = Array.isArray(vault.projectsTrash) ? vault.projectsTrash : [];
        vault.projectsTrash.push({
          project: JSON.parse(JSON.stringify(projToTrash)),
          items: JSON.parse(JSON.stringify(projItems)),
          deletedAt: new Date().toISOString()
        });
        for (const pi of projItems) {
          if (pi.url && pi.url.includes('vault_media/')) {
            try {
              await fetch('/api/trash', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ storedName: pi.url.replace(/^\/?vault_media\//, '') })
              });
            } catch (e) {}
          }
        }
        vault.projects = vault.projects.filter(p => p.id !== delId);
        vault.items = vault.items.filter(i => !(i.parentType === 'project' && i.parentId === delId));
        continue;
      }

      const it = vault.items.find(i => i.id === delId);
      if (!it) continue;
      if (it.url && it.url.includes('vault_media/')) {
        try {
          await fetch('/api/trash', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ storedName: it.url.replace(/^\/?vault_media\//, '') })
          });
        } catch (e) {}
      }
      if (it.kind === 'folder' || it.kind === 'column' || it.kind === 'sphere') {
        vault.items.forEach(child => {
          if (child.id === it.id) return;
          if (it.kind === 'folder' && child.folderId === it.id) child.folderId = it.folderId || null;
          if (it.kind === 'column' && child.columnId === it.id) delete child.columnId;
          if (it.kind === 'sphere' && child.sphereId === it.id) delete child.sphereId;
        });
        if (state.activeFolderId === it.id) state.activeFolderId = it.folderId || null;
      }
      vault.items = vault.items.filter(i => i.id !== delId);
    }
    if (state.batchSelectedIds) state.batchSelectedIds.clear();
  } else if (pd.kind === 'mf_lead') {
    if (vault.pitchEngine && Array.isArray(vault.pitchEngine.cards)) {
      const target = vault.pitchEngine.cards.find(c => c.id === pd.id);
      if (target) {
        vault.pitchEngine.trash = Array.isArray(vault.pitchEngine.trash) ? vault.pitchEngine.trash : [];
        vault.pitchEngine.trash.push({ ...target, deletedAt: new Date().toISOString() });
      }
      vault.pitchEngine.deletedIds = Array.isArray(vault.pitchEngine.deletedIds) ? vault.pitchEngine.deletedIds : [];
      if (!vault.pitchEngine.deletedIds.includes(pd.id)) {
        vault.pitchEngine.deletedIds.push(pd.id);
      }
      vault.pitchEngine.cards = vault.pitchEngine.cards.filter(c => c.id !== pd.id);
    }
    if (state.activeLeadId === pd.id) {
      state.activeLeadId = null;
    }
  } else if (pd.kind === 'showcase_rollout') {
    const target = (vault.showcaseRollouts || []).find(r => r.id === pd.id);
    if (target) {
      vault.showcaseRolloutsTrash = Array.isArray(vault.showcaseRolloutsTrash) ? vault.showcaseRolloutsTrash : [];
      vault.showcaseRolloutsTrash.push({ ...target, deletedAt: new Date().toISOString() });
    }
    vault.showcaseRollouts = (vault.showcaseRollouts || []).filter(r => r.id !== pd.id);
  } else if (pd.kind === 'mf_req') {
    if (vault.pitchEngine && Array.isArray(vault.pitchEngine.cards) && pd.id) {
      const target = vault.pitchEngine.cards.find(c => c.id === pd.id.leadId);
      if (target && Array.isArray(target.requirementsList) && typeof pd.id.reqIdx === 'number') {
        target.requirementsList.splice(pd.id.reqIdx, 1);
      }
    }
  }

  state.pendingDelete = null;
  document.getElementById('confirmDeleteDialog')?.close();
  document.getElementById('itemDialog')?.close();
  document.getElementById('projectDialog')?.close();
  document.getElementById('toolDockDialog')?.close();

  // Sync selectedCompareAssets & open #compareDialog if any compared item was trashed
  if (Array.isArray(state.selectedCompareAssets) && state.selectedCompareAssets.length > 0) {
    const validIds = new Set((vault.items || []).map(i => i.id));
    state.selectedCompareAssets = state.selectedCompareAssets.filter(a => validIds.has(a.vaultItemId || a.id));
  }
  renderCompareFloatingBar();

  const cmpDlg = document.getElementById('compareDialog');
  if (cmpDlg && cmpDlg.open) {
    const rem = state.selectedCompareAssets || [];
    if (rem.length > 0) {
      if (state.compareState.activeIndex >= rem.length) {
        state.compareState.activeIndex = Math.max(0, rem.length - 1);
      }
      state.compareState.visibleLayers = new Set(rem.map((_, idx) => idx));
      renderCompareModal();
    } else {
      cmpDlg.close();
    }
  }

  saveVault('MOVED TO TRASH');
  showStatusToast('Moved to Trash');
  announceLightboxPolite('Moved to Trash');
  renderAll();
}

/* --------------------------------------------------------------------------
   UTILITIES & INLINE RENAMING
   -------------------------------------------------------------------------- */
function promptInlineRename(targetEl, currentText, onCommit) {
  if (!targetEl || targetEl.querySelector('.inline-rename-field')) return;
  const draggableParent = targetEl.closest('[draggable="true"]') || targetEl.closest('.gdrive-sidebar-item');
  if (draggableParent) {
    draggableParent.setAttribute('draggable', 'false');
    draggableParent.classList.add('is-editing-rename');
  }

  const input = document.createElement('input');
  input.type = 'text';
  input.className = 'inline-rename-field';
  input.value = currentText || '';
  const origHtml = targetEl.innerHTML;
  targetEl.innerHTML = '';
  targetEl.appendChild(input);
  input.focus();
  input.select();

  let done = false;
  const finish = (save) => {
    if (done) return;
    done = true;
    if (draggableParent) {
      draggableParent.setAttribute('draggable', 'true');
      draggableParent.classList.remove('is-editing-rename');
    }
    const val = (input.value || '').trim();
    targetEl.innerHTML = origHtml;
    if (save && val) onCommit(val);
  };

  input.addEventListener('click', (e) => e.stopPropagation());
  input.addEventListener('dblclick', (e) => e.stopPropagation());
  input.addEventListener('pointerdown', (e) => e.stopPropagation());
  input.addEventListener('keyup', (e) => e.stopPropagation());
  input.addEventListener('keydown', (e) => {
    e.stopPropagation();
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === 'Enter') { e.preventDefault(); finish(true); }
    if (e.key === 'Escape') { e.preventDefault(); finish(false); }
  });
  input.addEventListener('blur', () => finish(true));
}

async function openUrlOrMacPath(raw) {
  if (!raw) return;
  const val = raw.trim();
  if (/^https?:\/\//i.test(val)) {
    window.open(val, '_blank', 'noopener');
    return;
  }
  if (/^[a-zA-Z0-9.-]+:\/\//i.test(val)) {
    window.location.href = val;
    return;
  }
  const isExplicitLocal = val.startsWith('~') ||
    val.startsWith('/') ||
    val.toLowerCase().endsWith('.app') ||
    val.toLowerCase().includes('.app/') ||
    val.toLowerCase().startsWith('app:');
  const isLikelyLocal = isExplicitLocal || !val.includes('.');
  if (isLikelyLocal) {
    try {
      const res = await fetch('/api/reveal', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ localPath: val })
      });
      const data = await res.json();
      if (data && data.ok) return;
      if (isExplicitLocal && data && data.error) {
        showStatusToast(data.error);
        return;
      }
    } catch (e) {}
  }
  const href = val.startsWith('http') ? val : 'https://' + val;
  window.open(href, '_blank', 'noopener');
}

function reorderArrayById(arr, fromId, toId) {
  const fromIdx = arr.findIndex(x => x.id === fromId);
  const toIdx = arr.findIndex(x => x.id === toId);
  if (fromIdx === -1 || toIdx === -1) return;
  const [moved] = arr.splice(fromIdx, 1);
  arr.splice(toIdx, 0, moved);
}

function formatBytes(bytes) {
  if (!bytes || bytes < 1024) return bytes + ' B';
  if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / 1048576).toFixed(1) + ' MB';
}

function uid(prefix = '') {
  const rnd = Math.random().toString(36).slice(2, 8);
  const ts = Date.now();
  if (prefix) return `${prefix}_${ts}_${rnd}`;
  return `${ts}_${rnd}`;
}

function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/* --------------------------------------------------------------------------
   BOOT & EVENT BINDINGS
   -------------------------------------------------------------------------- */
function initEvents() {
  // Cross-tab Tool Dock synchronization so background tabs never overwrite newly added staples/tools
  window.addEventListener('storage', (e) => {
    if (e.key === 'ideal_vault_v5' && e.newValue) {
      try {
        const updated = JSON.parse(e.newValue);
        if (updated && updated.toolDock && vault) {
          vault.toolDock = updated.toolDock;
          normalizeToolDockData(vault);
          if (state.viewType === 'space' && state.activeSpaceId === 'tool_dock') {
            renderWorkspace();
          }
        }
      } catch (err) {}
    }
  });

  // Sidebar collapse & restore controls
  document.getElementById('btnToggleSidebar')?.addEventListener('click', () => toggleSidebar(true));
  document.getElementById('btnRestoreSidebarEdge')?.addEventListener('click', () => toggleSidebar(true));
  document.getElementById('btnCloseSidebar')?.addEventListener('click', () => toggleSidebar(false));

  document.getElementById('brandHomeBtn')?.addEventListener('click', (e) => {
    if (e.target.closest('.inline-rename-field')) return;
    if (e.detail > 1) return;
    guardLeaveCustomize(() => {
      state.viewType = 'space';
      state.activeSpaceId = 'projects';
      state.activeProjectId = null;
      const nav = document.getElementById('sidebarNav');
      nav?.querySelectorAll('.sidebar-item-btn').forEach(b => {
        b.classList.toggle('active', b.dataset.spaceId === 'projects');
      });
      updateSidebarBoardJumpButton();
      renderHeaderAndToolbar();
      renderFilterActionRow();
      renderSectionDesignDrawer();
      renderWorkspace();
      renderCompareFloatingBar();
      saveNavState();
    });
  });

  document.getElementById('sidebarBrandName')?.addEventListener('dblclick', (e) => {
    e.stopPropagation();
    promptInlineRename(e.currentTarget, vault.brand?.title || 'IDEAL', (val) => {
      vault.brand = vault.brand || {};
      vault.brand.title = val;
      saveVault('RENAMED BRAND');
      renderSidebar();
    });
  });

  // Inline rename of tagline, kicker, and page title
  document.getElementById('sidebarTagline')?.addEventListener('dblclick', (e) => {
    promptInlineRename(e.currentTarget, vault.brand?.tagline || '', (val) => {
      vault.brand = vault.brand || {};
      vault.brand.tagline = val;
      saveVault();
      renderSidebar();
    });
  });

  document.getElementById('viewKicker')?.addEventListener('click', (e) => {
    const { type, obj } = getActiveContainer();
    const cur = type === 'project' ? (obj.status || '') : (obj.kicker || '');
    promptInlineRename(e.currentTarget, cur, (val) => {
      if (type === 'project') obj.status = val;
      else obj.kicker = val;
      saveVault();
      renderAll();
    });
  });

  document.getElementById('viewTitle')?.addEventListener('click', (e) => {
    const { type, obj } = getActiveContainer();
    if (type === 'space' && obj.id === 'lightbox') {
      return; // The Lightbox top bar is uneditable from clicking on it (customize via Customization panel)
    }
    if (type === 'space' && obj.id === 'gdrive_assets') {
      state.activeCategory = 'All';
      state.activeGDriveBatchId = null;
      state.activeGDriveEnclosingFolder = null;
      state.eagleFormatFilter = 'all';
      saveNavState();
      renderFilterActionRow();
      renderWorkspace();
      return;
    }
    if (state.activeFolderId) {
      const fItem = vault.items.find(i => i.id === state.activeFolderId);
      if (fItem) {
        promptInlineRename(e.currentTarget, fItem.title || 'Folder', (val) => {
          fItem.title = val;
          saveVault('RENAMED FOLDER');
          renderAll();
        });
        return;
      }
    }
    const cur = type === 'project' ? obj.title : getSpaceTopBarTitle(obj.id);
    promptInlineRename(e.currentTarget, cur, (val) => {
      if (type === 'project') {
        obj.title = val;
      } else {
        // Disconnected from sidebar: only update top bar title / heading
        setSpaceTopBarTitle(obj.id, val);
      }
      saveVault('RENAMED TOP BAR TITLE');
      renderAll();
    });
  });

  // Site-wide Back / Forward history buttons
  document.getElementById('btnNavBack')?.addEventListener('click', () => {
    navigateHistoryBack();
  });
  document.getElementById('btnNavForward')?.addEventListener('click', () => {
    navigateHistoryForward();
  });

  // Back to Projects / Parent Folder button
  document.getElementById('btnBackToProjects')?.addEventListener('click', () => {
    if (state.activeFolderId) {
      const curFolder = vault.items.find(i => i.id === state.activeFolderId);
      state.activeFolderId = curFolder?.folderId || null;
      renderAll();
      return;
    }
    guardLeaveCustomize(() => {
      state.viewType = 'space';
      state.activeSpaceId = 'projects';
      state.activeProjectId = null;
      state.activeFolderId = null;
      const sp = vault.spaces.find(s => s.id === 'projects');
      state.activeCategory = (sp?.categories && sp.categories[0]) || 'All';
      renderAll();
    });
  });

  // Top single-row toolbar controls
  document.getElementById('searchInput')?.addEventListener('input', (e) => {
    state.searchQuery = e.target.value.trim();
    renderWorkspace();
  });

  document.getElementById('sortSelect')?.addEventListener('change', (e) => {
    const { obj } = getActiveContainer();
    obj.ui = obj.ui || {};
    obj.ui.sortOrder = e.target.value;
    saveVault();
    renderWorkspace();
  });

  ['btnViewSphere', 'btnViewGiantWall', 'btnViewWall', 'btnViewList', 'btnViewKanban', 'btnViewMfVertical', 'btnViewMfHorizontal'].forEach(id => {
    document.getElementById(id)?.addEventListener('click', (e) => {
      const mode = e.currentTarget.dataset.mode;
      const { type, obj } = getActiveContainer();
      obj.ui = obj.ui || {};
      obj.ui.layoutMode = mode;
      state.activeLeadId = null;
      applyCustomizationToDOM();
      saveVault();
      renderHeaderAndToolbar();
      renderWorkspace();
    });
  });

  document.getElementById('sizeSlider')?.addEventListener('input', (e) => {
    const rawVal = parseInt(e.target.value, 10);
    const step = Math.max(1, Math.min(5, rawVal));
    const { type, obj } = getActiveContainer();
    if (!obj) return;
    obj.ui = obj.ui || {};
    obj.ui.scaleStep = step;
    obj.ui.scaleStepByMode = obj.ui.scaleStepByMode || {};
    const { key } = getContainerScaleContext(type, obj);
    obj.ui.scaleStepByMode[key] = step;
    applyContainerScale(type, obj, true);
    saveVault();
  });

  document.getElementById('btnSectionDesign')?.addEventListener('click', () => {
    state.sectionDrawerOpen = !state.sectionDrawerOpen;
    renderHeaderAndToolbar();
    renderSectionDesignDrawer();
  });

  document.getElementById('btnThemeToggle')?.addEventListener('click', () => {
    const cur = vault.customization.themePreset || 'warm_gallery';
    vault.customization.themePreset = cur.includes('dark') || cur.includes('oled') ? 'warm_gallery' : 'dark_studio';
    if (state.viewType === 'space' && state.activeSpaceId === 'customize') {
      applyCustomizationToDOM();
      updateCustomizerDirtyState();
      renderWorkspace();
    } else {
      saveVault();
      state.custSavedSnapshot = captureCustomizationSnapshot(vault);
      state.custDirty = false;
      renderAll();
    }
  });

  // Compact Board Switcher (⌘K) for 800+ Boards
  const boardSwitcherDlg = document.getElementById('boardSwitcherDialog');
  document.getElementById('btnOpenBoardSwitcher')?.addEventListener('click', () => openBoardSwitcherModal());
  document.getElementById('btnCloseBoardSwitcher')?.addEventListener('click', () => boardSwitcherDlg?.close());
  if (boardSwitcherDlg && !('closedBy' in HTMLDialogElement.prototype)) {
    const isOutsideDialog = (ev, dlgEl) => {
      const r = dlgEl.getBoundingClientRect();
      return ev.clientX < r.left || ev.clientX > r.right || ev.clientY < r.top || ev.clientY > r.bottom;
    };
    let pressedOutsideBs = false;
    boardSwitcherDlg.addEventListener('pointerdown', (ev) => {
      pressedOutsideBs = isOutsideDialog(ev, boardSwitcherDlg);
    });
    boardSwitcherDlg.addEventListener('pointerup', (ev) => {
      if (pressedOutsideBs && isOutsideDialog(ev, boardSwitcherDlg)) boardSwitcherDlg.close();
    });
  }
  document.getElementById('boardSwitcherInput')?.addEventListener('input', (e) => {
    state.boardSwitcherActiveIdx = 0;
    renderBoardSwitcherList(e.target.value);
  });
  document.getElementById('boardSwitcherInput')?.addEventListener('keydown', (e) => {
    const listEl = document.getElementById('boardSwitcherList');
    const rows = listEl ? Array.from(listEl.querySelectorAll('.board-switcher-row')) : [];
    if (!rows.length) return;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      state.boardSwitcherActiveIdx = ((state.boardSwitcherActiveIdx || 0) + 1) % rows.length;
      renderBoardSwitcherList(e.target.value);
      listEl.querySelector('.board-switcher-row.is-focused')?.scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      state.boardSwitcherActiveIdx = ((state.boardSwitcherActiveIdx || 0) - 1 + rows.length) % rows.length;
      renderBoardSwitcherList(e.target.value);
      listEl.querySelector('.board-switcher-row.is-focused')?.scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (e.isComposing || e.keyCode === 229) return;
      const activeRow = rows[state.boardSwitcherActiveIdx || 0] || rows[0];
      const pid = activeRow?.dataset.projId;
      if (pid) {
        boardSwitcherDlg?.close();
        openProjectBoard(pid);
      }
    }
  });
  document.getElementById('btnBoardSwitcherNew')?.addEventListener('click', () => {
    boardSwitcherDlg?.close();
    createAndOpenNewProjectBoard();
  });

  // Global keyboard shortcuts: Cmd/Ctrl + K (Board Switcher) & Cmd/Ctrl + =/-/0 (Spatial Zoom)
  window.addEventListener('keydown', (e) => {
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      openBoardSwitcherModal();
      return;
    }
    if (e.target.closest('input, textarea, [contenteditable="true"]')) return;
    const plane = document.getElementById('giantWallPlane');
    if (plane && (e.metaKey || e.ctrlKey)) {
      if (e.key === '=' || e.key === '+') {
        e.preventDefault();
        const cam = getActiveBoardCamera();
        cam.zoom = Math.min(3.5, +((cam.zoom || 1) * 1.18).toFixed(3));
        applyActiveBoardCameraTransform();
      } else if (e.key === '-' || e.key === '_') {
        e.preventDefault();
        const cam = getActiveBoardCamera();
        cam.zoom = Math.max(0.25, +((cam.zoom || 1) / 1.18).toFixed(3));
        applyActiveBoardCameraTransform();
      } else if (e.key === '0') {
        e.preventDefault();
        const cam = getActiveBoardCamera();
        cam.zoom = 1;
        cam.panX = 0;
        cam.panY = 0;
        applyActiveBoardCameraTransform();
      }
    }
  });

  // Initialize Milanote Tool Rail (Click-to-Add AND Drag-from-Rail to Board)
  initMilanoteToolRailEvents();

  // Sidebar footer & floating HUD quick actions
  document.getElementById('btnSidebarAddProject')?.addEventListener('click', () => createAndOpenNewProjectBoard());
  document.getElementById('btnSidebarUpload')?.addEventListener('click', () => {
    if (state.viewType === 'space' && state.activeSpaceId === 'lightbox') {
      chooseLightboxLocalFiles();
      return;
    }
    document.getElementById('globalFileInput')?.click();
  });
  document.getElementById('btnSidebarQuickNote')?.addEventListener('click', () => openQuickComposer('note'));
  document.getElementById('btnSidebarQuickLink')?.addEventListener('click', () => openQuickComposer('link'));

  document.getElementById('btnHudUpload')?.addEventListener('click', () => document.getElementById('globalFileInput')?.click());
  document.getElementById('btnHudNote')?.addEventListener('click', () => openQuickComposer('note'));
  document.getElementById('btnHudLink')?.addEventListener('click', () => openQuickComposer('link'));

  // IG Status Quick Filter Bar in Floating HUD
  document.querySelectorAll('#igStatusFilterBar .ig-filter-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      state.igStatusFilter = btn.dataset.igFilter || 'all';
      renderHeaderAndToolbar();
      if (state.viewType === 'space' && state.activeSpaceId === 'instagram') {
        renderFilterActionRow();
      }
      renderWorkspace();
    });
  });

  // Inspector IG Status Segmented Buttons
  document.querySelectorAll('#sheetIgStatusGroup .seg-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#sheetIgStatusGroup .seg-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    });
  });

  // Multi-Select Compare Floating Bar Controls
  document.getElementById('btnOpenCompareModal')?.addEventListener('click', () => openCompareDialog());
  document.getElementById('btnClearCompareSelection')?.addEventListener('click', () => {
    state.selectedCompareAssets = [];
    renderWorkspace();
    renderCompareFloatingBar();
  });
  document.getElementById('btnBatchSelectAll')?.addEventListener('click', () => {
    if (!(state.viewType === 'space' && state.activeSpaceId === 'lightbox')) return;
    const visibleCards = Array.from(document.querySelectorAll('#lightboxMainShell .lb-studio-card:not(.is-render-pile)[data-lb-item-id]'));
    const visibleIds = visibleCards.map(c => c.dataset.lbItemId).filter(Boolean);
    const pool = visibleIds.length > 0
      ? visibleIds.map(id => vault.items.find(i => i.id === id)).filter(Boolean)
      : getLightboxAssetsForActiveProject();
    if (!pool.length) return;
    const allAlreadySelected = pool.every(it => isAssetCompareSelected(it.id));
    if (allAlreadySelected) {
      state.selectedCompareAssets = [];
    } else {
      state.selectedCompareAssets = pool.map(it => ({
        id: it.id,
        title: it.title || 'Asset',
        url: it.url,
        kind: getLightboxMasterMediaKind(it),
        igStatus: it.igStatus || '',
        lightboxKeep: Boolean(it.lightboxKeep),
        vaultItemId: it.id,
        notes: it.notes || ''
      }));
    }
    renderWorkspace();
    renderCompareFloatingBar();
  });
  document.getElementById('btnBatchMarkKeep')?.addEventListener('click', () => {
    batchSetSelectedKeepStatus(true);
  });
  document.getElementById('btnBatchMarkQueued')?.addEventListener('click', () => {
    batchSetSelectedIgStatus('queued');
  });
  document.getElementById('btnBatchMarkPublished')?.addEventListener('click', () => {
    batchSetSelectedIgStatus('published');
  });
  document.getElementById('btnBatchMarkWebsite')?.addEventListener('click', () => {
    batchSetSelectedIgStatus('website');
  });
  document.getElementById('btnBatchTrashSelected')?.addEventListener('click', () => {
    const sel = state.selectedCompareAssets || [];
    if (!sel.length) return;
    const ids = sel.map(a => a.vaultItemId || a.id).filter(Boolean);
    const isLbNow = state.viewType === 'space' && state.activeSpaceId === 'lightbox';
    if (ids.length === 1) {
      const single = vault.items.find(i => i.id === ids[0]);
      requestDelete(isLbNow ? 'lb_item' : 'item', ids[0], single?.title || sel[0]?.title || 'Asset');
    } else {
      requestDelete(isLbNow ? 'lb_batch_items' : 'batch_items', ids, `${ids.length} selected files`);
    }
  });

  // Batch Move Popover Menu (Invoker command fallback + focusgroup fallback + viewport-clamped fallback)
  const batchMoveBtn = document.getElementById('btnBatchMoveProject');
  const batchMovePop = document.getElementById('lbBatchMovePopover');
  const batchMoveInner = document.getElementById('lbBatchMoveInner');
  if (batchMoveBtn && batchMovePop && batchMoveInner) {
    let movePointerPressed = false;
    batchMoveBtn.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      movePointerPressed = true;
    });
    if (!('commandForElement' in HTMLButtonElement.prototype)) {
      batchMoveBtn.addEventListener('click', (e) => {
        e.preventDefault();
        const isOpen = batchMovePop.matches(':popover-open') || batchMovePop.classList.contains(':popover-open');
        if (isOpen) {
          batchMoveBtn.focus({ focusVisible: !movePointerPressed });
          batchMovePop.hidePopover();
        } else {
          batchMovePop.dataset.kbOpen = movePointerPressed ? '0' : '1';
          try { batchMovePop.showPopover({ source: batchMoveBtn }); }
          catch (_) { batchMovePop.showPopover(); }
        }
        movePointerPressed = false;
      });
    } else {
      batchMoveBtn.addEventListener('click', (e) => {
        batchMovePop.dataset.kbOpen = (e.detail === 0 && !movePointerPressed) ? '1' : '0';
        movePointerPressed = false;
      });
    }
    batchMoveBtn.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        batchMovePop.dataset.kbOpen = '1';
        const isOpen = batchMovePop.matches(':popover-open') || batchMovePop.classList.contains(':popover-open');
        if (!isOpen) batchMoveBtn.click();
        else batchMoveInner.querySelector('button')?.focus({ preventScroll: true });
      }
    });
    batchMovePop.addEventListener('toggle', ({ newState }) => {
      const openNow = newState === 'open';
      batchMoveBtn.setAttribute('aria-expanded', openNow ? 'true' : 'false');
      if (!openNow) return;
      if (!CSS.supports('position-area', 'block-end')) {
        const t = batchMoveBtn.getBoundingClientRect();
        const m = batchMovePop.getBoundingClientRect();
        const above = t.top - m.height - 6 >= 8;
        batchMovePop.style.top = `${above ? t.top - m.height - 6 : Math.min(window.innerHeight - m.height - 8, t.bottom + 6)}px`;
        batchMovePop.style.left = `${Math.max(8, Math.min(t.left, window.innerWidth - m.width - 8))}px`;
      }
      if (batchMovePop.dataset.kbOpen === '1') {
        batchMoveInner.querySelector('button')?.focus({ preventScroll: true });
      }
    });
    batchMovePop.addEventListener('keydown', (e) => {
      if (e.key === 'Tab') {
        batchMovePop.hidePopover();
      } else if (e.key === 'Escape') {
        e.stopPropagation();
        batchMoveBtn.focus();
        batchMovePop.hidePopover();
      }
    });
    initMenuFocusgroupFallbackOnElement(batchMoveInner);
  }

  initLightboxSharedMenuEvents();

  // Lightbox Keyboard Shortcuts (Delete/Backspace to Trash, Cmd/Ctrl+A Select All, Esc Clear Selection)
  window.addEventListener('keydown', (e) => {
    if (!(state.viewType === 'space' && state.activeSpaceId === 'lightbox')) return;
    if (e.target && (['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName) || e.target.isContentEditable)) return;
    if (Array.from(document.querySelectorAll('dialog')).some(d => d.open)) return;
    if (document.querySelector('[popover]:popover-open')) return;

    const sel = state.selectedCompareAssets || [];
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z' && !e.shiftKey) {
      e.preventDefault();
      undoLightboxAction();
      return;
    }
    if ((e.metaKey || e.ctrlKey) && ((e.shiftKey && e.key.toLowerCase() === 'z') || e.key.toLowerCase() === 'y')) {
      e.preventDefault();
      redoLightboxAction();
      return;
    }
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'a') {
      e.preventDefault();
      document.getElementById('btnBatchSelectAll')?.click();
      return;
    }
    if ((e.key === 'Delete' || e.key === 'Backspace') && sel.length > 0) {
      e.preventDefault();
      document.getElementById('btnBatchTrashSelected')?.click();
      return;
    }
    if (e.key === 'Escape' && sel.length > 0) {
      e.preventDefault();
      state.selectedCompareAssets = [];
      renderWorkspace();
      renderCompareFloatingBar();
    }
  });

  // Spacebar High-Res Quick-Look Preview Modal
  const spaceDlg = document.getElementById('spacebarPreviewDialog');
  document.getElementById('btnCloseSpacebarPreview')?.addEventListener('click', () => spaceDlg?.close());
  if (spaceDlg && !('closedBy' in HTMLDialogElement.prototype)) {
    spaceDlg.addEventListener('click', (e) => {
      if (e.target === spaceDlg) spaceDlg.close();
    });
  }

  window.addEventListener('keydown', (e) => {
    if (e.target && ['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) return;
    if (e.target && e.target.isContentEditable) return;

    if (spaceDlg && spaceDlg.open) {
      if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
        const list = state.currentEagleAssetList || [];
        if (list.length > 1 && state.currentQuickLookAsset) {
          e.preventDefault();
          const curIdx = list.findIndex(x => x.id === state.currentQuickLookAsset.id || (x.localPath && x.localPath === state.currentQuickLookAsset.localPath));
          if (curIdx !== -1) {
            const nextIdx = (curIdx + (e.key === 'ArrowRight' ? 1 : -1) + list.length) % list.length;
            openSpacebarPreview(list[nextIdx]);
          } else if (list.length > 0) {
            openSpacebarPreview(list[0]);
          }
          return;
        }
      }
      if (e.key === ' ' || e.code === 'Space' || e.key === 'Escape') {
        e.preventDefault();
        spaceDlg.close();
        return;
      }
    }

    if (e.key !== ' ') return;
    if (e.target && ['BUTTON'].includes(e.target.tagName)) return;
    const anyDialogOpen = Array.from(document.querySelectorAll('dialog')).some(d => d.open && d.id !== 'spacebarPreviewDialog');
    if (anyDialogOpen) return;

    if (state.hoveredAssetForQuickLook) {
      e.preventDefault();
      openSpacebarPreview(state.hoveredAssetForQuickLook);
    }
  });

  // Contextual Asset Comparison Lightbox Modal Controls
  initCompareDialogEvents();
  initMfIntakeDialogEvents();

  document.getElementById('globalFileInput')?.addEventListener('change', (e) => {
    if (state.viewType === 'space' && state.activeSpaceId === 'lightbox') {
      handleLightboxLocalInputFiles(e.target.files, false);
      e.target.value = '';
      return;
    }
    handleFilesUpload(e.target.files);
    e.target.value = '';
  });
  document.getElementById('globalFolderInput')?.addEventListener('change', (e) => {
    if (state.viewType === 'space' && state.activeSpaceId === 'lightbox') {
      handleLightboxLocalInputFiles(e.target.files, true);
      e.target.value = '';
      return;
    }
    handleFilesUpload(e.target.files);
    e.target.value = '';
  });
  document.getElementById('lbLocalFileInput')?.addEventListener('change', (e) => {
    handleLightboxLocalInputFiles(e.target.files, false);
    e.target.value = '';
  });
  document.getElementById('lbLocalFolderInput')?.addEventListener('change', (e) => {
    handleLightboxLocalInputFiles(e.target.files, true);
    e.target.value = '';
  });

  // Global file & folder Drag & Drop + Clipboard Paste (Never gets stuck)
  const dropOverlay = document.getElementById('globalDropOverlay');
  let _dragWatchdogTimer = null;
  window.addEventListener('dragover', (e) => {
    if (state.viewType === 'space' && (state.activeSpaceId === 'gdrive_assets' || state.activeSpaceId === 'tool_dock')) return;
    if (e.dataTransfer && Array.from(e.dataTransfer.types || []).includes('Files')) {
      e.preventDefault();
      if (dropOverlay) {
        const isMf = (state.viewType === 'space' && ['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(state.activeSpaceId));
        const isLb = (state.viewType === 'space' && state.activeSpaceId === 'lightbox');
        const kicker = dropOverlay.querySelector('.kicker-mono');
        if (kicker) {
          kicker.textContent = isMf
            ? 'DROP OPPORTUNITY (AUTO-EXTRACT DETAILS & SAVE ORIGINAL)'
            : (isLb
                ? 'DROP LOCAL FILES OR FOLDERS TO LINK INSTANTLY (ZERO UPLOAD)'
                : 'DROP FILES OR FOLDERS (UNCOMPRESSED ORIGINAL QUALITY · RECURSIVE SUBFOLDERS)');
        }
        dropOverlay.hidden = false;
      }
      clearTimeout(_dragWatchdogTimer);
      _dragWatchdogTimer = setTimeout(() => {
        forceHideAllDropOverlays();
      }, 1800);
    }
  });
  window.addEventListener('dragleave', (e) => {
    if (e.relatedTarget === null) forceHideAllDropOverlays();
  });
  window.addEventListener('dragend', () => forceHideAllDropOverlays());
  window.addEventListener('blur', () => forceHideAllDropOverlays());
  window.addEventListener('mousedown', () => {
    if (dropOverlay && !dropOverlay.hidden) forceHideAllDropOverlays();
  });
  window.addEventListener('drop', (e) => {
    clearTimeout(_dragWatchdogTimer);
    forceHideAllDropOverlays();
    if (state.viewType === 'space' && (state.activeSpaceId === 'gdrive_assets' || state.activeSpaceId === 'tool_dock')) return;
    if (e.dataTransfer && ((e.dataTransfer.items && e.dataTransfer.items.length > 0) || (e.dataTransfer.files && e.dataTransfer.files.length > 0))) {
      e.preventDefault();
      const isMf = (state.viewType === 'space' && ['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(state.activeSpaceId));
      if (isMf && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
        runOpportunityIntake({ files: e.dataTransfer.files });
        return;
      }
      if (state.viewType === 'space' && state.activeSpaceId === 'lightbox') {
        handleLightboxLocalDrop(e.dataTransfer);
        return;
      }
      const captured = captureDropPayloadSynchronously(e.dataTransfer);
      handleFilesUpload(captured, {
        clientX: e.clientX,
        clientY: e.clientY
      });
    }
  });
  window.addEventListener('paste', (e) => {
    if (state.viewType === 'space' && (state.activeSpaceId === 'gdrive_assets' || state.activeSpaceId === 'tool_dock')) return;
    if (e.target && ['INPUT', 'TEXTAREA'].includes(e.target.tagName)) return;
    if (e.target && e.target.isContentEditable) return;
    const isMf = (state.viewType === 'space' && ['residencies', 'work_apps', 'dream_clients', 'opportunity_pool'].includes(state.activeSpaceId));
    if (e.clipboardData && e.clipboardData.files && e.clipboardData.files.length > 0) {
      e.preventDefault();
      if (isMf) {
        runOpportunityIntake({ files: e.clipboardData.files });
        return;
      }
      if (state.viewType === 'space' && state.activeSpaceId === 'lightbox') {
        handleLightboxLocalInputFiles(e.clipboardData.files, false);
        return;
      }
      handleFilesUpload(e.clipboardData.files);
      return;
    }
    if (isMf && e.clipboardData) {
      const text = e.clipboardData.getData('text/plain') || '';
      if (text && text.trim()) {
        e.preventDefault();
        runOpportunityIntake({ text: text.trim() });
      }
    }
  });

  // Inspector & Project Dialog bindings
  document.getElementById('btnCloseSheet')?.addEventListener('click', () => document.getElementById('itemDialog')?.close());
  document.getElementById('btnSheetSave')?.addEventListener('click', saveInspectorChanges);
  document.getElementById('btnSheetDelete')?.addEventListener('click', () => {
    const it = vault.items.find(i => i.id === state.editingItemId);
    if (it) {
      const isLbItem = it.parentType === 'space' && it.parentId === 'lightbox';
      requestDelete(isLbItem ? 'lb_item' : 'item', it.id, it.title);
    }
  });
  document.getElementById('btnSheetOpenLink')?.addEventListener('click', () => {
    const val = document.getElementById('sheetLinkInput')?.value;
    openUrlOrMacPath(val);
  });

  document.getElementById('btnCloseProjectDialog')?.addEventListener('click', () => document.getElementById('projectDialog')?.close());
  document.getElementById('btnProjDialogCancel')?.addEventListener('click', () => document.getElementById('projectDialog')?.close());
  document.getElementById('btnProjDialogSave')?.addEventListener('click', saveProjectModal);
  document.getElementById('btnProjDialogDelete')?.addEventListener('click', () => {
    const proj = vault.projects.find(p => p.id === state.editingProjectId);
    if (proj) requestDelete('project', proj.id, proj.title);
  });

  // Tool Dock & R&D Lab Dialog bindings
  const tdDlg = document.getElementById('toolDockDialog');
  tdDlg?.addEventListener('close', () => {
    const colorIn = document.getElementById('tdEditColor');
    if (colorIn) {
      const savedHex = state.tdSelectedColor || colorIn.value || '#181715';
      colorIn.type = 'text';
      colorIn.type = 'color';
      colorIn.value = savedHex;
    }
  });
  document.getElementById('btnCloseToolDockDialog')?.addEventListener('click', () => tdDlg?.close());
  document.getElementById('btnTdDialogCancel')?.addEventListener('click', () => tdDlg?.close());
  document.getElementById('btnTdModeLaunchpad')?.addEventListener('click', () => syncToolDockModalModeUI('launchpad'));
  document.getElementById('btnTdModeRd')?.addEventListener('click', () => syncToolDockModalModeUI('rd'));
  document.getElementById('btnTdModeLink')?.addEventListener('click', () => syncToolDockModalModeUI('link'));
  document.getElementById('btnTdTestUrl')?.addEventListener('click', () => {
    const val = document.getElementById('tdEditUrl')?.value;
    openUrlOrMacPath(val);
  });
  document.getElementById('btnTdDialogSave')?.addEventListener('click', saveToolDockModal);
  ['tdEditTitle', 'tdEditUrl', 'tdEditDesc', 'tdEditCluster', 'tdEditSub', 'tdEditIcon'].forEach(fieldId => {
    document.getElementById(fieldId)?.addEventListener('keydown', (e) => {
      if (e.isComposing || e.keyCode === 229) return;
      if (e.key === 'Enter') {
        e.preventDefault();
        saveToolDockModal();
      }
    });
  });
  document.getElementById('btnTdDialogTransfer')?.addEventListener('click', transferToolDockModalItem);
  document.getElementById('btnTdDialogDelete')?.addEventListener('click', () => {
    if (!state.tdModalId) return;
    const titleVal = (document.getElementById('tdEditTitle')?.value || '').trim() || 'Item';
    const delKind = state.tdModalMode === 'rd' ? 'tool_rd' : (state.tdModalMode === 'link' ? 'tool_link' : 'tool_launchpad');
    requestDelete(delKind, state.tdModalId, titleVal);
  });
  if (tdDlg && !('closedBy' in HTMLDialogElement.prototype)) {
    tdDlg.addEventListener('click', (e) => {
      if (e.target === tdDlg) tdDlg.close();
    });
  }

  document.getElementById('btnCancelDelete')?.addEventListener('click', () => document.getElementById('confirmDeleteDialog')?.close());
  document.getElementById('btnConfirmDeleteYes')?.addEventListener('click', executeConfirmedDelete);

  // Unsaved Customizations Guard Dialog & Save Template Dialog
  const unsavedDlg = document.getElementById('unsavedCustDialog');
  document.getElementById('btnUnsavedKeepEditing')?.addEventListener('click', () => {
    state.pendingLeaveAction = null;
    unsavedDlg?.close();
  });
  document.getElementById('btnUnsavedDiscardLeave')?.addEventListener('click', () => {
    const nextAction = state.pendingLeaveAction;
    state.pendingLeaveAction = null;
    unsavedDlg?.close();
    const defTpl = getWebsiteDefaultTemplate(vault);
    applyTemplateObjectToVault(defTpl, vault);
    applyCustomizationToDOM();
    state.custDirty = false;
    state.custMode = 'idle';
    state.custPreviewingTemplateId = null;
    state.custEditingTemplateId = null;
    state.custSavedSnapshot = captureCustomizationSnapshot(vault);
    if (typeof nextAction === 'function') nextAction();
  });
  document.getElementById('btnUnsavedSaveLeave')?.addEventListener('click', () => {
    const nextAction = state.pendingLeaveAction;
    state.pendingLeaveAction = null;
    unsavedDlg?.close();
    const isCreatingNew = (state.custMode === 'create' || !state.custEditingTemplateId);
    if (isCreatingNew) {
      openSaveTemplateModal(nextAction);
    } else {
      saveChangesToActiveTemplate();
      if (typeof nextAction === 'function') nextAction();
    }
  });

  const saveTplDlg = document.getElementById('saveTemplateDialog');
  document.getElementById('btnCancelSaveTemplate')?.addEventListener('click', () => {
    state.pendingSaveAfterCallback = null;
    saveTplDlg?.close();
  });
  document.getElementById('btnConfirmSaveTemplate')?.addEventListener('click', commitSaveTemplateFromModal);
  document.getElementById('saveTplNameInput')?.addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === 'Enter') {
      e.preventDefault();
      commitSaveTemplateFromModal();
    }
  });

  window.addEventListener('beforeunload', (e) => {
    if (state.viewType === 'space' && state.activeSpaceId === 'customize' && state.custDirty) {
      e.preventDefault();
      e.returnValue = '';
    }
  });
}

/* ==========================================================================
   MILANOTE TOOL RAIL: CLICK-TO-ADD OR DRAG-FROM-RAIL ONTO SPATIAL BOARD
   ========================================================================== */
function findNextOpenBoardSpot(overrideType = null, overrideId = null, overrideFolderId = undefined) {
  const cam = getActiveBoardCamera();
  const baseX = snapCoord(Math.round((264 - (cam.panX || 0)) / (cam.zoom || 1)));
  const baseY = snapCoord(Math.round((108 - (cam.panY || 0)) / (cam.zoom || 1)));
  const { type: curType, obj: curObj } = getActiveContainer();
  const type = overrideType || curType;
  const objId = overrideId || curObj?.id;
  const folderId = overrideFolderId !== undefined ? overrideFolderId : (state.activeFolderId || null);

  if (type === 'space' && objId === 'projects' && !folderId) {
    const lcFilter = state.projectsLifecycleFilter || 'active';
    const visibleProjs = (vault.projects || []).filter(p => {
      const pState = p.lifecycleState || 'active';
      return lcFilter === 'delivered' ? pState === 'delivered' : pState !== 'delivered';
    });
    const looseItems = (vault.items || []).filter(i => i.parentType === 'space' && i.parentId === 'projects' && !i.folderId && !i.columnId);
    for (let step = 0; step < 50; step++) {
      const candX = snapCoord(baseX + (step % 3) * 336);
      const candY = snapCoord(baseY + Math.floor(step / 3) * 288);
      const projHit = visibleProjs.some(p => Math.abs((p.boardX ?? 264) - candX) < 220 && Math.abs((p.boardY ?? 108) - candY) < 180);
      const itemHit = looseItems.some(it => Math.abs((it.wallX ?? 264) - candX) < 180 && Math.abs((it.wallY ?? 108) - candY) < 140);
      if (!projHit && !itemHit) return { x: candX, y: candY };
    }
  }

  const existing = vault.items.filter(i => i.parentType === type && i.parentId === objId && (i.folderId || null) === folderId);
  for (let step = 0; step < 40; step++) {
    const candX = snapCoord(baseX + (step % 3) * 288);
    const candY = snapCoord(baseY + Math.floor(step / 3) * 240);
    const collision = existing.some(it => Math.abs((it.wallX || 0) - candX) < 140 && Math.abs((it.wallY || 0) - candY) < 110);
    if (!collision) return { x: candX, y: candY };
  }
  return { x: baseX, y: baseY };
}

function getEffectiveLayoutMode(obj) {
  if (!obj) return 'giant_wall';
  if (obj.ui && obj.ui.layoutMode) return obj.ui.layoutMode;
  if (obj.id === 'projects' || obj.id === 'incubator') return 'giant_wall';
  return 'wall';
}

function createMilanoteElementAt(toolKind, canvasX, canvasY) {
  if (toolKind === 'image' || toolKind === 'upload' || toolKind === 'document' || toolKind === 'audio' || toolKind === 'video') {
    document.getElementById('globalFileInput')?.click();
    return;
  }

  const { type, obj } = getActiveContainer();
  const spot = (typeof canvasX === 'number' && typeof canvasY === 'number')
    ? { x: snapCoord(canvasX), y: snapCoord(canvasY) }
    : findNextOpenBoardSpot();

  let targetParentType = type;
  let targetParentId = obj.id;

  // In Sphere mode on 01 Studio Projects:
  // If viewing a project sphere (index > 0), target that specific project directly!
  if (type === 'space' && obj.id === 'projects') {
    const curMode = getEffectiveLayoutMode(obj);
    if (curMode === 'sphere' && state.sphereActiveIndex > 0) {
      const activeProj = (vault.projects || [])[state.sphereActiveIndex - 1];
      if (activeProj) {
        targetParentType = 'project';
        targetParentId = activeProj.id;
      }
    }
  }

  const defaultsByKind = {
    note: { title: 'Note', kind: 'note', section: 'Notes', notes: '', wallW: 264 },
    comment: { title: 'Comment', kind: 'comment', section: 'Notes', notes: '', wallW: 264 },
    link: { title: 'Web / Mac Link', kind: 'link', section: 'References', link: 'https://', notes: '', wallW: 264 },
    todo: { title: 'To-do List', kind: 'todo', section: 'Notes', notes: '[ ] First step\n[ ] Second step', wallW: 264 },
    line: { title: 'Connector', kind: 'line', section: 'Notes', notes: '', wallW: 336 },
    sphere: { title: 'Sphere Batch', kind: 'sphere', section: 'All', notes: '', wallW: 520, wallH: 520 },
    folder: { title: 'New Folder', kind: 'folder', section: 'All', notes: '', wallW: 280 },
    column: { title: 'Column', kind: 'column', section: 'All', notes: 'Vertical card stack', wallW: 288 },
    heading: { title: 'Section Heading', kind: 'heading', section: 'Notes', notes: '', wallW: 360 },
    color: { title: 'Accent Swatch', kind: 'color', section: 'References', notes: '#FF3B24', wallW: 192 },
    table: { title: 'Specs Table', kind: 'table', section: 'Notes', notes: 'Part | Status\nSculpt | Ready\nRender | WIP', wallW: 312 },
    sketch: { title: 'Sketch Pad', kind: 'sketch', section: 'WIP', notes: '', wallW: 264 },
    map: { title: 'Location Pin', kind: 'map', section: 'References', link: 'https://maps.google.com', notes: 'Venue / exhibition coordinates', wallW: 264 }
  };

  const spec = defaultsByKind[toolKind] || defaultsByKind.note;
  const isIgTarget = (targetParentType === 'space' && targetParentId === 'instagram');
  const activeCatOverride = (state.activeCategory && state.activeCategory !== 'All' && !state.activeCategory.startsWith('All '))
    ? state.activeCategory
    : spec.section;
  const newItem = {
    id: 'item_' + uid(),
    parentType: targetParentType,
    parentId: targetParentId,
    folderId: state.activeFolderId || null,
    title: spec.title,
    kind: spec.kind,
    section: activeCatOverride,
    status: 'Active',
    igStatus: isIgTarget
      ? ((state.igStatusFilter === 'published' || state.activeCategory === 'IG Live') ? 'published' : ((state.igStatusFilter === 'queued' || state.activeCategory === 'IG Ready') ? 'queued' : ''))
      : undefined,
    url: '',
    link: spec.link || '',
    notes: spec.notes || '',
    tags: [],
    wallX: spot.x,
    wallY: spot.y,
    wallW: spec.wallW || 264,
    wallH: spec.wallH || undefined,
    createdAt: Date.now()
  };

  if (spec.kind === 'sphere') {
    newItem.title = 'Sphere Batch';
    newItem.wallW = 520;
    newItem.wallH = 520;
  }

  if (spec.kind === 'line') {
    newItem.lineX1 = spot.x;
    newItem.lineY1 = spot.y + 40;
    newItem.lineX2 = spot.x + 220;
    newItem.lineY2 = spot.y + 40;
    newItem.wallX = spot.x;
    newItem.wallY = spot.y + 40;
    newItem.wallW = 220;
    newItem.title = '';
  }

  vault.items.unshift(newItem);
  saveVault(`ADDED ${spec.title.toUpperCase()}`);
  renderAll();
  showStatusToast(`+ Added ${spec.title} to Board`);

  // Auto-focus inline editable area if it's a note, heading, or folder
  requestAnimationFrame(() => {
    const pinEl = document.querySelector(`.wall-pin-item[data-item-id="${newItem.id}"]`);
    const editable = pinEl?.querySelector('.mn-note-editable, .mn-heading-editable, .mn-folder-title, .mn-column-title');
    if (editable) {
      editable.focus();
    }
  });
}

function initMilanoteToolRailEvents() {
  const rail = document.getElementById('milanoteToolRail');
  const moreBtn = document.getElementById('btnMilanoteMore');
  const morePop = document.getElementById('milanoteMorePopover');
  if (!rail) return;

  moreBtn?.addEventListener('click', (e) => {
    e.stopPropagation();
    if (!morePop) return;
    morePop.hidden = !morePop.hidden;
  });

  window.addEventListener('pointerdown', (e) => {
    if (morePop && !morePop.hidden && !e.target.closest('#milanoteMorePopover') && !e.target.closest('#btnMilanoteMore')) {
      morePop.hidden = true;
    }
  });

  const trashSlot = document.getElementById('milanoteTrashDropZone');
  trashSlot?.addEventListener('click', (e) => {
    e.stopPropagation();
    if (state.batchSelectedIds && state.batchSelectedIds.size > 0) {
      const ids = Array.from(state.batchSelectedIds);
      if (ids.length === 1) {
        deleteItemDirectly(ids[0]);
        return;
      }
      requestDelete('batch_items', ids, `${ids.length} selected items`);
    } else {
      showStatusToast('Drop any item or batch here to move to Trash');
    }
  });

  // Bind both Click-to-Add and Drag-from-Rail onto the Spatial Board for all tool buttons
  const toolButtons = document.querySelectorAll('#milanoteToolRail .mn-tool-btn[data-mn-tool], #milanoteMorePopover .mn-more-item[data-mn-tool]');
  toolButtons.forEach(btn => {
    const toolKind = btn.dataset.mnTool;
    if (!toolKind) return;

    let draggingTool = false;
    let movedTool = false;
    let startX = 0;
    let startY = 0;
    let ghostEl = null;
    let gestureCompleted = false;

    // Direct Click support — clicking ANY element in the sidebar immediately creates it!
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (morePop) morePop.hidden = true;
      if (gestureCompleted) {
        gestureCompleted = false;
        return;
      }
      createMilanoteElementAt(toolKind);
    });

    btn.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      draggingTool = true;
      movedTool = false;
      gestureCompleted = false;
      startX = e.clientX;
      startY = e.clientY;
      try { btn.setPointerCapture(e.pointerId); } catch (_) {}
    });

    btn.addEventListener('pointermove', (e) => {
      if (!draggingTool) return;
      // Require a decisive 14px drag away from the button before showing ghost
      if (Math.hypot(e.clientX - startX, e.clientY - startY) > 14) {
        if (!movedTool) {
          movedTool = true;
          if (morePop) morePop.hidden = true;
          ghostEl = document.createElement('div');
          ghostEl.className = 'mn-drag-ghost';
          const label = btn.querySelector('.mn-tool-label, .mn-more-name')?.textContent || toolKind;
          ghostEl.textContent = `+ ${label.trim()}`;
          document.body.appendChild(ghostEl);
        }
      }
      if (movedTool && ghostEl) {
        ghostEl.style.left = `${e.clientX + 14}px`;
        ghostEl.style.top = `${e.clientY + 14}px`;

        const stage = document.getElementById('giantWallStage');
        const snapPreview = document.getElementById('wallSnapPreview');
        if (stage && snapPreview) {
          const rect = stage.getBoundingClientRect();
          const cam = getActiveBoardCamera();
          const cx = snapCoord((e.clientX - rect.left - (cam.panX || 0)) / (cam.zoom || 1) - 110);
          const cy = snapCoord((e.clientY - rect.top - (cam.panY || 0)) / (cam.zoom || 1) - 40);
          snapPreview.hidden = false;
          snapPreview.style.left = `${cx}px`;
          snapPreview.style.top = `${cy}px`;
          snapPreview.style.width = `264px`;
          snapPreview.style.height = `144px`;
        }
      }
    });

    const finishToolGesture = (e) => {
      if (!draggingTool) return;
      draggingTool = false;
      if (ghostEl) {
        ghostEl.remove();
        ghostEl = null;
      }
      const snapPreview = document.getElementById('wallSnapPreview');
      if (snapPreview) snapPreview.hidden = true;
      if (morePop) morePop.hidden = true;

      try { btn.releasePointerCapture(e.pointerId); } catch (_) {}

      if (!movedTool) {
        // Plain click -> handled by click listener
        return;
      }

      gestureCompleted = true;
      setTimeout(() => { gestureCompleted = false; }, 200);

      // Dropped onto canvas -> compute exact snapped board coordinates if in Giant Wall, or create in active view
      const stage = document.getElementById('giantWallStage');
      if (stage && e) {
        const rect = stage.getBoundingClientRect();
        const cam = getActiveBoardCamera();
        const dropX = snapCoord((e.clientX - rect.left - (cam.panX || 0)) / (cam.zoom || 1) - 110);
        const dropY = snapCoord((e.clientY - rect.top - (cam.panY || 0)) / (cam.zoom || 1) - 40);
        createMilanoteElementAt(toolKind, dropX, dropY);
      } else {
        createMilanoteElementAt(toolKind);
      }
    };

    btn.addEventListener('pointerup', finishToolGesture);
    btn.addEventListener('pointercancel', finishToolGesture);
    btn.addEventListener('lostpointercapture', finishToolGesture);
  });
}

/* ==========================================================================
   MODULES 3 & 4: CONTEXTUAL ASSET COMPARISON MODAL (1:1 STACK & SPLIT VIEW)
   & ONE-CLICK PUBLISHING STATUS (IG READY / IG LIVE / ON WEBSITE)
   ========================================================================== */
function isAssetCompareSelected(id) {
  return (state.selectedCompareAssets || []).some(a => a.id === id);
}

function toggleCompareSelect(assetObj) {
  if (!assetObj || !assetObj.id) return;
  state.selectedCompareAssets = state.selectedCompareAssets || [];
  const idx = state.selectedCompareAssets.findIndex(a => a.id === assetObj.id);
  if (idx !== -1) {
    state.selectedCompareAssets.splice(idx, 1);
  } else {
    state.selectedCompareAssets.push(assetObj);
  }
  if (state.viewType === 'space' && state.activeSpaceId === 'lightbox') {
    document.querySelectorAll(`#lightboxMainShell [data-lb-item-id="${CSS.escape(assetObj.id)}"]`).forEach(el => {
      el.classList.toggle('is-compared', idx === -1);
    });
    const cnt = state.selectedCompareAssets.length;
    const selGroup = document.querySelector('#lightboxMainShell #lbSelActionsGroup');
    if (!selGroup) {
      renderWorkspace();
    } else {
      const cmpBtn = selGroup.querySelector('#btnLbCompareAllKept');
      const hideBtn = selGroup.querySelector('#btnLbHideSelected');
      const clrBtn = selGroup.querySelector('#btnLbClearSelection');
      if (cnt > 0) {
        if (hideBtn) { hideBtn.hidden = false; hideBtn.textContent = `Hide (${cnt})`; }
        if (clrBtn) clrBtn.hidden = false;
        if (cmpBtn) { cmpBtn.textContent = `Compare (${cnt})`; cmpBtn.classList.add('is-primary'); cmpBtn.classList.remove('is-ghost'); }
      } else {
        if (hideBtn) hideBtn.hidden = true;
        if (clrBtn) clrBtn.hidden = true;
        if (cmpBtn) { cmpBtn.textContent = 'Compare'; cmpBtn.classList.remove('is-primary'); cmpBtn.classList.add('is-ghost'); }
      }
    }
    return;
  }
  renderWorkspace();
  renderCompareFloatingBar();
}

function syncMenuRolesFallback(groupEl) {
  if (!groupEl || ('focusGroup' in HTMLElement.prototype)) return;
  groupEl.setAttribute('role', 'menu');
  groupEl.querySelectorAll('button:not([role]), a:not([role])').forEach(item => {
    item.setAttribute('role', 'menuitem');
  });
}

function initMenuFocusgroupFallbackOnElement(groupEl) {
  if (!groupEl || groupEl._menuFgBound) return;
  groupEl._menuFgBound = true;
  if (!('focusGroup' in HTMLElement.prototype)) {
    syncMenuRolesFallback(groupEl);
    groupEl.addEventListener('keydown', (event) => {
      if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
      const items = [...groupEl.querySelectorAll('button, a')]
        .filter(item => item.closest('[focusgroup]') === groupEl)
        .filter(item => !item.disabled && item.getAttribute('aria-disabled') !== 'true');
      if (!items.length) return;
      const current = items.indexOf(document.activeElement);
      const next = event.key === 'Home' ? 0
        : event.key === 'End' ? items.length - 1
        : current < 0 ? 0
        : (current + (event.key === 'ArrowUp' ? -1 : 1) + items.length) % items.length;
      event.preventDefault();
      event.stopImmediatePropagation();
      items[next].focus({ preventScroll: true });
    }, true);
  }
  groupEl.addEventListener('pointermove', (e) => {
    const item = e.target.closest('button, a');
    if (item && item.closest('[focusgroup]') === groupEl && document.activeElement !== item) {
      try { item.focus({ focusVisible: false, preventScroll: true }); }
      catch (_) { item.focus({ preventScroll: true }); }
    }
  });
}

const LB_LOCAL_MEDIA_EXT_RE = /\.(png|jpe?g|webp|gif|svg|avif|bmp|heic|heif|tif|tiff|mp4|mov|webm|m4v)$/i;
const LB_HANDLES_DB_NAME = 'ideal_lightbox_handles_v2';
const LB_HANDLES_STORE = 'handles';
const LB_PREVIEWS_STORE = 'previews';
const LB_DIRS_STORE = 'dirs';
const lightboxLiveObjectUrls = new Map();
const lightboxStoredHandles = new Map();
const lightboxNeedsPermissionIds = new Set();
const lightboxResolveAttemptedIds = new Set(); // searched once per session; Reconnect clears it
let _lbHandlesDbPromise = null;

function isLightboxPortfolioRouted(it) {
  return Boolean(it) && (it.igStatus === 'website' || it.lightboxRoute === 'portfolio');
}

function isLightboxInstagramRouted(it) {
  return Boolean(it) && (it.igStatus === 'queued' || it.igStatus === 'published' || it.lightboxRoute === 'instagram');
}

function getLightboxActiveRoom(filterVal = state.lightboxFilter) {
  if (filterVal === 'Instagram Board') return 'instagram';
  if (filterVal === 'Portfolio Staging') return 'website';
  return 'source';
}

function isLightboxHiddenInRoom(it, room) {
  if (!it) return false;
  if (Boolean(it.lbGlobalHidden)) return true; // Hidden from All = hidden everywhere
  if (room === 'instagram') return Boolean(it.lbIgHidden);
  if (room === 'website') return Boolean(it.lbWebHidden);
  return false;
}

function isLightboxKeptInRoom(it, room) {
  // Everything not hidden in a room is ready/kept for that room
  return Boolean(it) && !isLightboxHiddenInRoom(it, room);
}

function syncLightboxItemLegacyRouteFields(it) {
  if (!it) return;
  const igKept = isLightboxKeptInRoom(it, 'instagram');
  const webKept = isLightboxKeptInRoom(it, 'website');
  if (igKept && !webKept) {
    it.igStatus = it.igStatus === 'published' ? 'published' : 'queued';
    it.lightboxRoute = 'instagram';
    it.status = it.igStatus === 'published' ? '● IG Live' : '◈ IG Ready';
  } else if (webKept && !igKept) {
    it.igStatus = 'website';
    it.lightboxRoute = 'portfolio';
    it.status = '🌐 Website Ready';
  } else if (!igKept && !webKept) {
    it.igStatus = '';
    it.lightboxRoute = '';
    if (it.status === '● IG Live' || it.status === '◈ IG Ready' || it.status === '🌐 On Site' || it.status === '🌐 Website Ready') {
      it.status = '✨ WIP / Edit';
    }
  }
  (state.selectedCompareAssets || []).forEach(a => {
    if (a.id === it.id || a.vaultItemId === it.id) {
      a.igStatus = it.igStatus;
    }
  });
}

function toggleLightboxRoomKeep(itemId, room) {
  const it = vault.items.find(i => i.id === itemId);
  if (!it || (room !== 'instagram' && room !== 'website')) return;
  const field = room === 'instagram' ? 'lbIgKeep' : 'lbWebKeep';
  const prevVal = isLightboxKeptInRoom(it, room);
  const nextVal = !prevVal;
  it[field] = nextVal;
  if (nextVal) {
    // Keeping a file ensures it is visible in that room
    it[room === 'instagram' ? 'lbIgHidden' : 'lbWebHidden'] = false;
  }
  syncLightboxItemLegacyRouteFields(it);
  pushLightboxUndo({
    type: 'room_keep',
    desc: `${nextVal ? 'Kept' : 'Unkept'} "${it.title || 'asset'}" in ${room === 'instagram' ? 'Instagram' : 'Website'}`,
    itemId: it.id,
    room,
    prevVal,
    nextVal
  });
  saveVault(`${nextVal ? '★ KEPT' : 'UNKEPT'} IN ${room.toUpperCase()}`);
  renderAll();
}

function toggleLightboxRoomHide(itemId, room, forceHide = null) {
  const it = vault.items.find(i => i.id === itemId);
  if (!it || !['instagram', 'website', 'source'].includes(room)) return;
  const field = room === 'instagram' ? 'lbIgHidden' : (room === 'website' ? 'lbWebHidden' : 'lbGlobalHidden');
  const prevHidden = Boolean(it[field]);
  const nextHidden = forceHide !== null ? Boolean(forceHide) : !prevHidden;
  if (prevHidden === nextHidden) return;
  it[field] = nextHidden;
  // When unhiding from a specific room, also clear global hide if it was globally hidden
  if (!nextHidden && room !== 'source' && it.lbGlobalHidden) {
    it.lbGlobalHidden = false;
  }
  const roomLabel = room === 'instagram' ? 'Instagram' : (room === 'website' ? 'Website' : 'All');
  pushLightboxUndo({
    type: 'room_hide',
    desc: `${nextHidden ? 'Hid' : 'Unhid'} "${it.title || 'asset'}" in ${roomLabel}`,
    itemId: it.id,
    room,
    prevHidden,
    nextHidden
  });
  saveVault(`${nextHidden ? 'HIDDEN' : 'UNHIDDEN'} IN ${roomLabel.toUpperCase()}`);
  renderAll();
}

function unhideAllInLightboxRoom(room) {
  if (!['instagram', 'website', 'source'].includes(room)) return;
  const field = room === 'instagram' ? 'lbIgHidden' : (room === 'website' ? 'lbWebHidden' : 'lbGlobalHidden');
  const items = getLightboxAssetsForActiveProject().filter(it => Boolean(it[field]) || (room !== 'source' && Boolean(it.lbGlobalHidden)));
  if (!items.length) return;
  items.forEach(it => {
    it[field] = false;
    if (room === 'source') it.lbGlobalHidden = false;
  });
  const roomLabel = room === 'instagram' ? 'Instagram' : (room === 'website' ? 'Website' : 'All');
  pushLightboxUndo({
    type: 'room_unhide_all',
    desc: `Unhid ${items.length} files in ${roomLabel}`,
    itemIds: items.map(i => i.id),
    room
  });
  saveVault(`UNHID ${items.length} IN ${roomLabel.toUpperCase()}`);
  renderAll();
}

function getLightboxProjects(v = vault) {
  if (!v) return [];
  if (!Array.isArray(v.lightboxProjects)) {
    v.lightboxProjects = [];
  }
  return v.lightboxProjects;
}

function ensureLightboxCleanWorkspace(v = vault) {
  if (!v) return;
  v.items = Array.isArray(v.items) ? v.items : [];
  v.lightboxProjects = Array.isArray(v.lightboxProjects) ? v.lightboxProjects : [];

  // Remove stale dummy character passes so the user's workspace contains strictly their own real files
  v.items = v.items.filter(i => !i?.id?.startsWith('itm_lb_char_'));
  v.lightboxProjects = v.lightboxProjects.filter(p => p && p.id !== 'lbproj_character_lookdev');

  const st = (typeof window !== 'undefined' && window.state) ? window.state : (typeof state !== 'undefined' ? state : null);
  if (st) {
    // If state.lightboxProjectId was set to the dummy project or invalid, default to 'all' so all files show immediately
    if (v.lightboxProjects.length > 0) {
      const hasUnsortedItems = v.items.some(i => i && i.parentType === 'space' && i.parentId === 'lightbox' && !i.lightboxProjectId);
      if (!st.lightboxProjectId || st.lightboxProjectId === 'all' || st.lightboxProjectId === 'lbproj_character_lookdev' || (st.lightboxProjectId === 'unsorted' && !hasUnsortedItems) || (st.lightboxProjectId !== 'unsorted' && !v.lightboxProjects.some(p => p && p.id === st.lightboxProjectId))) {
        st.lightboxProjectId = v.lightboxProjects[0].id;
      }
    }
    // Default into Instagram room
    if (!['Instagram Board', 'Portfolio Staging'].includes(st.lightboxFilter)) {
      st.lightboxFilter = 'Instagram Board';
    }
  }
}

function openLbHandlesDb() {
  if (_lbHandlesDbPromise) return _lbHandlesDbPromise;
  _lbHandlesDbPromise = new Promise((resolve) => {
    if (typeof indexedDB === 'undefined') {
      resolve(null);
      return;
    }
    try {
      const req = indexedDB.open(LB_HANDLES_DB_NAME, 2);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(LB_HANDLES_STORE)) {
          db.createObjectStore(LB_HANDLES_STORE);
        }
        if (!db.objectStoreNames.contains(LB_PREVIEWS_STORE)) {
          db.createObjectStore(LB_PREVIEWS_STORE);
        }
        if (!db.objectStoreNames.contains(LB_DIRS_STORE)) {
          db.createObjectStore(LB_DIRS_STORE);
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
    } catch (_) {
      resolve(null);
    }
  });
  return _lbHandlesDbPromise;
}

async function saveLbFileHandle(itemId, handle) {
  if (!itemId || !handle) return;
  lightboxStoredHandles.set(itemId, handle);
  const db = await openLbHandlesDb();
  if (!db) return;
  return new Promise((resolve) => {
    try {
      const tx = db.transaction(LB_HANDLES_STORE, 'readwrite');
      tx.objectStore(LB_HANDLES_STORE).put(handle, itemId);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    } catch (_) {
      resolve(false);
    }
  });
}

async function deleteLbFileHandle(itemId) {
  if (!itemId) return;
  lightboxStoredHandles.delete(itemId);
  lightboxNeedsPermissionIds.delete(itemId);
  const db = await openLbHandlesDb();
  if (!db) return;
  return new Promise((resolve) => {
    try {
      const tx = db.transaction([LB_HANDLES_STORE, LB_PREVIEWS_STORE], 'readwrite');
      tx.objectStore(LB_HANDLES_STORE).delete(itemId);
      tx.objectStore(LB_PREVIEWS_STORE).delete(itemId);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    } catch (_) {
      resolve(false);
    }
  });
}

async function getAllLbFileHandles() {
  const map = new Map();
  const db = await openLbHandlesDb();
  if (!db) return map;
  return new Promise((resolve) => {
    try {
      const tx = db.transaction(LB_HANDLES_STORE, 'readonly');
      const store = tx.objectStore(LB_HANDLES_STORE);
      const req = store.openCursor();
      req.onsuccess = () => {
        const cursor = req.result;
        if (cursor) {
          map.set(String(cursor.key), cursor.value);
          cursor.continue();
        } else {
          resolve(map);
        }
      };
      req.onerror = () => resolve(map);
    } catch (_) {
      resolve(map);
    }
  });
}

async function saveLbPreviewBlob(itemId, blob) {
  if (!itemId || !blob) return;
  const db = await openLbHandlesDb();
  if (!db) return;
  return new Promise((resolve) => {
    try {
      const tx = db.transaction(LB_PREVIEWS_STORE, 'readwrite');
      tx.objectStore(LB_PREVIEWS_STORE).put(blob, itemId);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    } catch (_) {
      resolve(false);
    }
  });
}

